INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u4-C1','math',3,2,'u4',2,'묶어서 분수로 나타내기 — 여러 개를 똑같이 묶어 전체 묶음의 수를 분모, 부분 묶음의 수를 분자로 나타내기(낱개 수가 아니라 묶음 수)',ARRAY['4수01-11']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u4-C2','math',3,2,'u4',2,'전체 정하기와 묶는 방법 — 부분끼리가 아니라 전체와 견주어 분수로 나타내고, 묶는 방법이 달라지면 같은 수라도 분수가 달라짐을 알기',ARRAY['4수01-11']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u4-C3','math',3,2,'u4',3,'전체의 분수만큼(개수) — 전체를 분모만큼 똑같이 묶어 단위분수만큼을 구하고, 분자만큼의 묶음을 세어 분수만큼이 몇 개인지 구하기(분자만 보고 답하지 않기)',ARRAY['4수01-11']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u4-C4','math',3,2,'u4',4,'길이·시간의 분수만큼 — 길이·시간을 분모만큼 똑같이 나누어 단위분수만큼을 구하고 분자만큼 모으기(하루 24시간, 1시간 60분, m·cm·km)',ARRAY['4수01-11']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u4-C5','math',3,2,'u4',5,'진분수와 가분수 — 분자가 분모보다 작으면 진분수, 분자가 분모와 같거나 크면 가분수임을 알고 단위분수 개수가 분자임을 알기',ARRAY['4수01-11']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u4-C6','math',3,2,'u4',5,'자연수를 분수로 — 단위분수가 분모만큼 모이면 1(⟨3/3⟩ = 1)이고, 자연수를 분모가 같은 가분수로 나타내며 수직선에서 자리 찾기',ARRAY['4수01-11']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u4-C7','math',3,2,'u4',6,'대분수와 가분수 바꾸기 — 자연수와 진분수로 이루어진 대분수를 알고 읽으며, 대분수 → 가분수는 단위분수가 모두 몇 개인지, 가분수 → 대분수는 통째로 모을 수 있는 만큼을 자연수로 나타내기',ARRAY['4수01-11']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u4-C8','math',3,2,'u4',7,'분모가 같은 분수의 크기 비교 — 가분수끼리는 분자로, 대분수끼리는 자연수 부분부터, 가분수와 대분수는 한쪽으로 바꾸어 단위분수 개수로 견주기',ARRAY['4수01-11']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u4-C9','math',3,2,'u4',8,'1보다 큰 소수 — 4 cm 7 mm = 4.7 cm처럼 1보다 큰 소수를 쓰고 「사 점 칠」로 읽으며, 소수를 0.1이 몇 개인지로 세고 cm·mm로 바꾸기',ARRAY['4수01-11']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u4-C10','math',3,2,'u4',9,'소수의 크기 비교 — 자연수 부분부터 견주고 같으면 소수점 오른쪽 수를 견주며, 0.1의 개수·수직선으로 확인하고 생활 기록(걸린 시간)을 견주기',ARRAY['4수01-11']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u4-C11','math',3,2,'u4',10,'분수와 소수의 크기 비교 — 분모가 10인 분수 ↔ 소수로 한쪽으로 바꾸어 견주고, 크기 비교에 알맞은 수를 하나씩 넣어 찾기',ARRAY['4수01-11']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u4-X01','math',3,'u4',ARRAY['M3-2-u4-C1','M3-2-u4-C2']::text[],'부분 묶음을 나머지 묶음과 견주어 분모로 쓴다(검은 돌 3개·흰 돌 4개 → ⟨3/4⟩)','부분은 전체와 견주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u4-X02','math',3,'u4',ARRAY['M3-2-u4-C1','M3-2-u4-C2']::text[],'묶음 수 대신 낱개 수로 분수를 쓴다(12를 2씩 묶어 8은 → ⟨8/12⟩)','묶음이 몇 개인지 세기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u4-X03','math',3,'u4',ARRAY['M3-2-u4-C1','M3-2-u4-C5','M3-2-u4-C6','M3-2-u4-C7']::text[],'분모와 분자를 바꾸어 쓴다(6묶음 중 4묶음 → ⟨6/4⟩)','아래 분모·위 분자') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u4-X04','math',3,'u4',ARRAY['M3-2-u4-C3','M3-2-u4-C4']::text[],'분수만큼을 구할 때 분자만 보고 답한다(12의 ⟨3/4⟩ → 3)','분모만큼 묶고 분자만큼 세기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u4-X05','math',3,'u4',ARRAY['M3-2-u4-C3','M3-2-u4-C4']::text[],'단위분수만큼(한 묶음)에서 멈춘다(12의 ⟨2/3⟩ → 4)','분자만큼 모으기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u4-X06','math',3,'u4',ARRAY['M3-2-u4-C3','M3-2-u4-C4']::text[],'분수만큼에서 분모와 분자의 역할을 바꾼다(12의 ⟨3/4⟩ → 12를 3묶음으로 나눈 것 중 4묶음)','분모만큼 똑같이 나누기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u4-X07','math',3,'u4',ARRAY['M3-2-u4-C1','M3-2-u4-C3']::text[],'묶음 수와 한 묶음 안의 개수를 헷갈린다(몇 묶음인지 물었는데 한 묶음의 개수를 답한다)','묶음 수 ↔ 한 묶음 개수') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u4-X08','math',3,'u4',ARRAY['M3-2-u4-C5','M3-2-u4-C7']::text[],'진분수·가분수·대분수의 뜻을 헷갈린다(⟨4/4⟩을 진분수로, 분모가 큰 분수를 가분수로)','분자와 분모를 견주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u4-X09','math',3,'u4',ARRAY['M3-2-u4-C6']::text[],'자연수를 분수로 나타낼 때 자연수를 그대로 분자에 쓴다(2 = ⟨2/8⟩)','1 = ⟨8/8⟩, 2 = ⟨16/8⟩') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u4-X10','math',3,'u4',ARRAY['M3-2-u4-C6','M3-2-u4-C7']::text[],'대분수를 가분수로 바꿀 때 자연수 부분을 단위분수 개수로 바꾸지 않는다(⟨2 3/4⟩ → ⟨5/4⟩·⟨8/4⟩)','자연수 1 = 분모만큼') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u4-X11','math',3,'u4',ARRAY['M3-2-u4-C7']::text[],'가분수를 대분수로 바꿀 때 분수 부분을 가분수로 남긴다(⟨5/2⟩ → ⟨1 3/2⟩)','분수 부분은 진분수') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u4-X12','math',3,'u4',ARRAY['M3-2-u4-C7']::text[],'대분수의 자연수 부분(통째)을 빼먹거나 잘못 센다(⟨13/8⟩ → ⟨5/8⟩·⟨2 5/8⟩)','통째로 몇 번 모이는지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u4-X13','math',3,'u4',ARRAY['M3-2-u4-C8']::text[],'분모가 같은 분수에서 분자가 작을수록 크다고 하거나, 대분수를 분수 부분만 보고 견준다(⟨1 4/5⟩ > ⟨2 1/5⟩)','자연수 부분부터') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u4-X14','math',3,'u4',ARRAY['M3-2-u4-C8','M3-2-u4-C11']::text[],'가분수와 대분수(분수와 소수)를 바꾸지 않고 겉으로 보이는 수만 견준다(⟨32/15⟩은 32라서 크다)','한쪽으로 바꾸어 견주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u4-X15','math',3,'u4',ARRAY['M3-2-u4-C9','M3-2-u4-C10']::text[],'소수를 0.1의 개수로 셀 때 자연수 부분을 빼먹는다(2.9 → 0.1이 9개)','1 = 0.1이 10개') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u4-X16','math',3,'u4',ARRAY['M3-2-u4-C9','M3-2-u4-C11']::text[],'소수를 쓰거나 읽을 때 소수점 앞뒤를 바꾼다(⟨5 8/10⟩ → 8.5, 9.3 → 삼 점 구)','자연수 . 십분의 몇') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u4-X17','math',3,'u4',ARRAY['M3-2-u4-C9']::text[],'소수와 cm·mm·0.1 개수를 바꿀 때 자리를 잘못 쓴다(0.1이 35개 → 35·0.35, 4 cm 7 mm → 4.07 cm)','0.1이 10개 = 1') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u4-X18','math',3,'u4',ARRAY['M3-2-u4-C10','M3-2-u4-C11']::text[],'소수의 크기를 소수점 오른쪽 수만 보고 견준다(1.8 > 2.3)','자연수 부분부터') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u4-X19','math',3,'u4',ARRAY['M3-2-u4-C10']::text[],'기록(걸린 시간)은 짧을수록 빠른데 큰 수를 빠르다고 한다','걸린 시간이 짧을수록 빠름') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u4-X20','math',3,'u4',ARRAY['M3-2-u4-C1','M3-2-u4-C2','M3-2-u4-C3','M3-2-u4-C4','M3-2-u4-C5','M3-2-u4-C6','M3-2-u4-C7','M3-2-u4-C8','M3-2-u4-C9','M3-2-u4-C10','M3-2-u4-C11']::text[],'묻는 말을 거꾸로 읽는다 — 큰↔작은, 진분수↔가분수, 먹은↔남은, 색칠한↔색칠 안 한','물음의 핵심 말에 동그라미') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u4-X21','math',3,'u4',ARRAY['M3-2-u4-C1','M3-2-u4-C3','M3-2-u4-C4','M3-2-u4-C6','M3-2-u4-C7','M3-2-u4-C8','M3-2-u4-C10','M3-2-u4-C11']::text[],'개수를 세거나 셈하는 데서 하나 많거나 적게 답한다(경계의 수를 넣거나 빼기 포함)','하나씩 넣어 확인하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u4-X22','math',3,'u4',ARRAY['M3-2-u4-C2','M3-2-u4-C3','M3-2-u4-C8','M3-2-u4-C10','M3-2-u4-C11']::text[],'크기를 견줄 수 있는데도 「알 수 없다」·「같다」고 하거나 분수와 소수는 견줄 수 없다고 한다','단위분수·0.1 개수로 견주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L02_basic#1','math',3,2,'u4','L02','g3_2_math_u4_L02_basic','lesson_basic','M3-2-u4-C1',1,'mc','auto','사탕 6개를 똑같이 3묶음으로 나누었어요. 한 묶음은 전체의 얼마인가요?',ARRAY['M3-2-u4-X02','M3-2-u4-X07']::text[],true,'{"seq":1,"concept":"M3-2-u4-C1","difficulty":1,"kind":"mc","stem":"사탕 6개를 똑같이 3묶음으로 나누었어요. 한 묶음은 전체의 얼마인가요?","options":[{"t":"⟨1/3⟩","correct":true},{"t":"⟨1/6⟩","mis":"M3-2-u4-X02"},{"t":"⟨1/2⟩","mis":"M3-2-u4-X07"},{"t":"⟨3/6⟩","mis":"M3-2-u4-X07"}],"explanation":["전체를 똑같이 3묶음으로 나누었어요 — 분모 3.","한 묶음은 그중 1묶음이에요 — 분자 1.","한 묶음은 전체의 ⟨1/3⟩ — 낱개 6개가 아니라 묶음 수로 나타내요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[2.7,0],[3.7,0],[3.7,1],[2.7,1]]},{"p":[[3.7,0],[4.7,0],[4.7,1],[3.7,1]]},{"p":[[5.4,0],[6.4,0],[6.4,1],[5.4,1]]},{"p":[[6.4,0],[7.4,0],[7.4,1],[6.4,1]]}],"u":30},"variant_rule":{"alt":[{"stem":"쿠키 4개를 똑같이 2묶음으로 나누었어요. 한 묶음은 전체의 얼마인가요?","options":[{"t":"⟨1/2⟩","correct":true},{"t":"⟨1/4⟩","mis":"M3-2-u4-X02"},{"t":"⟨2/2⟩","mis":"M3-2-u4-X07"},{"t":"⟨1/3⟩","mis":"M3-2-u4-X21"}],"explanation":["전체를 똑같이 2묶음으로 나누었어요 — 분모 2.","한 묶음은 그중 1묶음이에요 — 분자 1.","한 묶음은 전체의 ⟨1/2⟩ — 낱개 4개가 아니라 묶음 수로 나타내요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[2.7,0],[3.7,0],[3.7,1],[2.7,1]]},{"p":[[3.7,0],[4.7,0],[4.7,1],[3.7,1]]}],"u":30}},{"stem":"귤 8개를 똑같이 4묶음으로 나누었어요. 한 묶음은 전체의 얼마인가요?","options":[{"t":"⟨1/4⟩","correct":true},{"t":"⟨1/8⟩","mis":"M3-2-u4-X02"},{"t":"⟨1/2⟩","mis":"M3-2-u4-X07"},{"t":"⟨4/8⟩","mis":"M3-2-u4-X07"}],"explanation":["전체를 똑같이 4묶음으로 나누었어요 — 분모 4.","한 묶음은 그중 1묶음이에요 — 분자 1.","한 묶음은 전체의 ⟨1/4⟩ — 낱개 8개가 아니라 묶음 수로 나타내요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[2.7,0],[3.7,0],[3.7,1],[2.7,1]]},{"p":[[3.7,0],[4.7,0],[4.7,1],[3.7,1]]},{"p":[[5.4,0],[6.4,0],[6.4,1],[5.4,1]]},{"p":[[6.4,0],[7.4,0],[7.4,1],[6.4,1]]},{"p":[[8.1,0],[9.1,0],[9.1,1],[8.1,1]]},{"p":[[9.1,0],[10.1,0],[10.1,1],[9.1,1]]}],"u":29}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L02_basic#2','math',3,2,'u4','L02','g3_2_math_u4_L02_basic','lesson_basic','M3-2-u4-C1',1,'sa','auto','18을 3씩 묶으면 모두 몇 묶음이 되나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u4-C1","difficulty":1,"kind":"sa","stem":"18을 3씩 묶으면 모두 몇 묶음이 되나요? 숫자로 쓰세요.","answer":["6"],"explanation":["18개를 3개씩 묶어요.","18 ÷ 3 = 6 — 나눗셈으로도 구할 수 있어요.","모두 6묶음이에요."],"variant_rule":{"alt":[{"stem":"16을 4씩 묶으면 모두 몇 묶음이 되나요? 숫자로 쓰세요.","answer":["4"],"explanation":["16개를 4개씩 묶어요.","16 ÷ 4 = 4 — 나눗셈으로도 구할 수 있어요.","모두 4묶음이에요."],"asset":null},{"stem":"15를 5씩 묶으면 모두 몇 묶음이 되나요? 숫자로 쓰세요.","answer":["3"],"explanation":["15개를 5개씩 묶어요.","15 ÷ 5 = 3 — 나눗셈으로도 구할 수 있어요.","모두 3묶음이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L02_basic#3','math',3,2,'u4','L02','g3_2_math_u4_L02_basic','lesson_basic','M3-2-u4-C1',1,'mc','auto','2개씩 묶었어요. 색칠한 부분은 전체의 얼마인가요?',ARRAY['M3-2-u4-X03','M3-2-u4-X02','M3-2-u4-X20']::text[],true,'{"seq":3,"concept":"M3-2-u4-C1","difficulty":1,"kind":"mc","stem":"2개씩 묶었어요. 색칠한 부분은 전체의 얼마인가요?","options":[{"t":"⟨3/4⟩","correct":true},{"t":"⟨4/3⟩","mis":"M3-2-u4-X03"},{"t":"⟨6/4⟩","mis":"M3-2-u4-X02"},{"t":"⟨1/4⟩","mis":"M3-2-u4-X20"}],"explanation":["2개씩 묶으니 모두 4묶음 — 분모 4.","색칠한 묶음은 3묶음 — 분자 3.","색칠한 부분은 전체의 ⟨3/4⟩이에요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[2.7,0],[3.7,0],[3.7,1],[2.7,1]],"hi":true},{"p":[[3.7,0],[4.7,0],[4.7,1],[3.7,1]],"hi":true},{"p":[[5.4,0],[6.4,0],[6.4,1],[5.4,1]],"hi":true},{"p":[[6.4,0],[7.4,0],[7.4,1],[6.4,1]],"hi":true},{"p":[[8.1,0],[9.1,0],[9.1,1],[8.1,1]]},{"p":[[9.1,0],[10.1,0],[10.1,1],[9.1,1]]}],"u":29},"variant_rule":{"alt":[{"stem":"3개씩 묶었어요. 색칠한 부분은 전체의 얼마인가요?","options":[{"t":"⟨1/5⟩","correct":true},{"t":"⟨1/4⟩","mis":"M3-2-u4-X01"},{"t":"⟨3/5⟩","mis":"M3-2-u4-X02"},{"t":"⟨4/5⟩","mis":"M3-2-u4-X20"}],"explanation":["3개씩 묶으니 모두 5묶음 — 분모 5.","색칠한 묶음은 1묶음 — 분자 1.","색칠한 부분은 전체의 ⟨1/5⟩이에요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[2,0],[3,0],[3,1],[2,1]],"hi":true},{"p":[[3.7,0],[4.7,0],[4.7,1],[3.7,1]]},{"p":[[4.7,0],[5.7,0],[5.7,1],[4.7,1]]},{"p":[[5.7,0],[6.7,0],[6.7,1],[5.7,1]]},{"p":[[7.4,0],[8.4,0],[8.4,1],[7.4,1]]},{"p":[[8.4,0],[9.4,0],[9.4,1],[8.4,1]]},{"p":[[9.4,0],[10.4,0],[10.4,1],[9.4,1]]},{"p":[[11.1,0],[12.1,0],[12.1,1],[11.1,1]]},{"p":[[12.1,0],[13.1,0],[13.1,1],[12.1,1]]},{"p":[[13.1,0],[14.1,0],[14.1,1],[13.1,1]]},{"p":[[14.8,0],[15.8,0],[15.8,1],[14.8,1]]},{"p":[[15.8,0],[16.8,0],[16.8,1],[15.8,1]]},{"p":[[16.8,0],[17.8,0],[17.8,1],[16.8,1]]}],"u":16}},{"stem":"이번에는 다른 문제예요. 2개씩 묶었어요. 색칠한 부분은 전체의 얼마인가요?","options":[{"t":"⟨2/5⟩","correct":true},{"t":"⟨2/3⟩","mis":"M3-2-u4-X01"},{"t":"⟨5/2⟩","mis":"M3-2-u4-X03"},{"t":"⟨4/5⟩","mis":"M3-2-u4-X02"}],"explanation":["2개씩 묶으니 모두 5묶음 — 분모 5.","색칠한 묶음은 2묶음 — 분자 2.","색칠한 부분은 전체의 ⟨2/5⟩예요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[2.7,0],[3.7,0],[3.7,1],[2.7,1]],"hi":true},{"p":[[3.7,0],[4.7,0],[4.7,1],[3.7,1]],"hi":true},{"p":[[5.4,0],[6.4,0],[6.4,1],[5.4,1]]},{"p":[[6.4,0],[7.4,0],[7.4,1],[6.4,1]]},{"p":[[8.1,0],[9.1,0],[9.1,1],[8.1,1]]},{"p":[[9.1,0],[10.1,0],[10.1,1],[9.1,1]]},{"p":[[10.8,0],[11.8,0],[11.8,1],[10.8,1]]},{"p":[[11.8,0],[12.8,0],[12.8,1],[11.8,1]]}],"u":23}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L02_basic#4','math',3,2,'u4','L02','g3_2_math_u4_L02_basic','lesson_basic','M3-2-u4-C1',1,'sa','auto','12를 2씩 묶었어요. 8은 몇 묶음인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-2-u4-C1","difficulty":1,"kind":"sa","stem":"12를 2씩 묶었어요. 8은 몇 묶음인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["2씩 묶으면 한 묶음에 2개예요.","8은 2가 4번 — 4묶음이에요.","8은 4묶음이에요."],"variant_rule":{"alt":[{"stem":"12를 3씩 묶었어요. 9는 몇 묶음인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["3씩 묶으면 한 묶음에 3개예요.","9는 3이 3번 — 3묶음이에요.","9는 3묶음이에요."],"asset":null},{"stem":"15를 3씩 묶었어요. 9는 몇 묶음인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["3씩 묶으면 한 묶음에 3개예요.","9는 3이 3번 — 3묶음이에요.","9는 3묶음이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L02_basic#5','math',3,2,'u4','L02','g3_2_math_u4_L02_basic','lesson_basic','M3-2-u4-C1',2,'mc','auto','12를 2씩 묶었어요. 2는 12의 얼마인가요?',ARRAY['M3-2-u4-X01','M3-2-u4-X07','M3-2-u4-X02']::text[],true,'{"seq":5,"concept":"M3-2-u4-C1","difficulty":2,"kind":"mc","stem":"12를 2씩 묶었어요. 2는 12의 얼마인가요?","options":[{"t":"⟨1/6⟩","correct":true},{"t":"⟨1/5⟩","mis":"M3-2-u4-X01"},{"t":"⟨2/6⟩","mis":"M3-2-u4-X07"},{"t":"⟨1/12⟩","mis":"M3-2-u4-X02"}],"explanation":["12를 2씩 묶으면 6묶음 — 분모 6.","2는 그중 1묶음 — 분자 1.","2는 12의 ⟨1/6⟩ — 낱개 수 2·12로 쓰지 않아요."],"variant_rule":{"alt":[{"stem":"12를 4씩 묶었어요. 8은 12의 얼마인가요?","options":[{"t":"⟨2/3⟩","correct":true},{"t":"⟨3/2⟩","mis":"M3-2-u4-X03"},{"t":"⟨2/12⟩","mis":"M3-2-u4-X02"},{"t":"⟨1/3⟩","mis":"M3-2-u4-X20"}],"explanation":["12를 4씩 묶으면 3묶음 — 분모 3.","8은 그중 2묶음 — 분자 2.","8은 12의 ⟨2/3⟩ — 낱개 수 8·12로 쓰지 않아요."],"asset":null},{"stem":"16을 4씩 묶었어요. 8은 16의 얼마인가요?","options":[{"t":"⟨2/4⟩","correct":true},{"t":"⟨4/2⟩","mis":"M3-2-u4-X03"},{"t":"⟨3/4⟩","mis":"M3-2-u4-X21"},{"t":"⟨2/16⟩","mis":"M3-2-u4-X02"}],"explanation":["16을 4씩 묶으면 4묶음 — 분모 4.","8은 그중 2묶음 — 분자 2.","8은 16의 ⟨2/4⟩ — 낱개 수 8·16으로 쓰지 않아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L02_basic#6','math',3,2,'u4','L02','g3_2_math_u4_L02_basic','lesson_basic','M3-2-u4-C2',2,'mc','auto','검은 돌 3개와 흰 돌 4개가 있어요. 검은 돌은 전체 돌의 얼마인가요?',ARRAY['M3-2-u4-X01','M3-2-u4-X20','M3-2-u4-X03']::text[],true,'{"seq":6,"concept":"M3-2-u4-C2","difficulty":2,"kind":"mc","stem":"검은 돌 3개와 흰 돌 4개가 있어요. 검은 돌은 전체 돌의 얼마인가요?","options":[{"t":"⟨3/7⟩","correct":true},{"t":"⟨3/4⟩","mis":"M3-2-u4-X01"},{"t":"⟨4/7⟩","mis":"M3-2-u4-X20"},{"t":"⟨7/3⟩","mis":"M3-2-u4-X03"}],"explanation":["먼저 전체를 정해요 — 돌은 모두 3 + 4 = 7개.","검은 돌은 흰 돌과 견주는 것이 아니라 전체 7개와 견주어요.","검은 돌은 전체의 ⟨3/7⟩이에요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[2,0],[3,0],[3,1],[2,1]],"hi":true},{"p":[[3,0],[4,0],[4,1],[3,1]]},{"p":[[4,0],[5,0],[5,1],[4,1]]},{"p":[[0,1],[1,1],[1,2],[0,2]]},{"p":[[1,1],[2,1],[2,2],[1,2]]}],"u":30},"variant_rule":{"alt":[{"stem":"검은 돌 5개와 흰 돌 3개가 있어요. 검은 돌은 전체 돌의 얼마인가요?","options":[{"t":"⟨5/8⟩","correct":true},{"t":"⟨5/3⟩","mis":"M3-2-u4-X01"},{"t":"⟨3/8⟩","mis":"M3-2-u4-X20"},{"t":"⟨8/5⟩","mis":"M3-2-u4-X03"}],"explanation":["먼저 전체를 정해요 — 돌은 모두 5 + 3 = 8개.","검은 돌은 흰 돌과 견주는 것이 아니라 전체 8개와 견주어요.","검은 돌은 전체의 ⟨5/8⟩예요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[2,0],[3,0],[3,1],[2,1]],"hi":true},{"p":[[3,0],[4,0],[4,1],[3,1]],"hi":true},{"p":[[4,0],[5,0],[5,1],[4,1]],"hi":true},{"p":[[0,1],[1,1],[1,2],[0,2]]},{"p":[[1,1],[2,1],[2,2],[1,2]]},{"p":[[2,1],[3,1],[3,2],[2,2]]}],"u":30}},{"stem":"검은 돌 3개와 흰 돌 5개가 있어요. 검은 돌은 전체 돌의 얼마인가요?","options":[{"t":"⟨3/8⟩","correct":true},{"t":"⟨3/5⟩","mis":"M3-2-u4-X01"},{"t":"⟨5/8⟩","mis":"M3-2-u4-X20"},{"t":"⟨8/3⟩","mis":"M3-2-u4-X03"}],"explanation":["먼저 전체를 정해요 — 돌은 모두 3 + 5 = 8개.","검은 돌은 흰 돌과 견주는 것이 아니라 전체 8개와 견주어요.","검은 돌은 전체의 ⟨3/8⟩이에요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[2,0],[3,0],[3,1],[2,1]],"hi":true},{"p":[[3,0],[4,0],[4,1],[3,1]]},{"p":[[4,0],[5,0],[5,1],[4,1]]},{"p":[[0,1],[1,1],[1,2],[0,2]]},{"p":[[1,1],[2,1],[2,2],[1,2]]},{"p":[[2,1],[3,1],[3,2],[2,2]]}],"u":30}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L02_basic#7','math',3,2,'u4','L02','g3_2_math_u4_L02_basic','lesson_basic','M3-2-u4-C2',2,'mc','auto','약과 6개를 ⟨2/3⟩만큼 색칠하려고 해요. 바르게 말한 것은 무엇인가요?',ARRAY['M3-2-u4-X04','M3-2-u4-X06','M3-2-u4-X02']::text[],true,'{"seq":7,"concept":"M3-2-u4-C2","difficulty":2,"kind":"mc","stem":"약과 6개를 ⟨2/3⟩만큼 색칠하려고 해요. 바르게 말한 것은 무엇인가요?","options":[{"t":"3묶음으로 똑같이 나눈 것 중 2묶음을 색칠한다","correct":true},{"t":"약과 2개를 색칠한다","mis":"M3-2-u4-X04"},{"t":"약과 3개를 색칠한다","mis":"M3-2-u4-X06"},{"t":"6묶음으로 똑같이 나눈 것 중 2묶음을 색칠한다","mis":"M3-2-u4-X02"}],"explanation":["분모 3은 전체를 똑같이 3묶음으로 나눈다는 뜻이에요.","분자 2는 그중 2묶음이라는 뜻이에요.","6개를 3묶음으로 나누면 한 묶음에 2개 — 4개를 색칠해요."],"variant_rule":{"alt":[{"stem":"와플 15개를 ⟨2/5⟩만큼 색칠하려고 해요. 바르게 말한 것은 무엇인가요?","options":[{"t":"5묶음으로 똑같이 나눈 것 중 2묶음을 색칠한다","correct":true},{"t":"와플 2개를 색칠한다","mis":"M3-2-u4-X04"},{"t":"와플 5개를 색칠한다","mis":"M3-2-u4-X06"},{"t":"15묶음으로 똑같이 나눈 것 중 2묶음을 색칠한다","mis":"M3-2-u4-X02"}],"explanation":["분모 5는 전체를 똑같이 5묶음으로 나눈다는 뜻이에요.","분자 2는 그중 2묶음이라는 뜻이에요.","15개를 5묶음으로 나누면 한 묶음에 3개 — 6개를 색칠해요."],"asset":null},{"stem":"풍선 9개를 ⟨1/3⟩만큼 색칠하려고 해요. 바르게 말한 것은 무엇인가요?","options":[{"t":"3묶음으로 똑같이 나눈 것 중 1묶음을 색칠한다","correct":true},{"t":"풍선 1개를 색칠한다","mis":"M3-2-u4-X04"},{"t":"풍선 3개를 색칠한다","mis":"M3-2-u4-X06"},{"t":"9묶음으로 똑같이 나눈 것 중 1묶음을 색칠한다","mis":"M3-2-u4-X02"}],"explanation":["분모 3은 전체를 똑같이 3묶음으로 나눈다는 뜻이에요.","분자 1은 그중 1묶음이라는 뜻이에요.","9개를 3묶음으로 나누면 한 묶음에 3개 — 3개를 색칠해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
