INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L02_basic#9','math',3,2,'u4','L02','g3_2_math_u4_L02_basic','lesson_basic','M3-2-u4-C1',2,'ox','auto','준우가 「12를 3씩 묶으면 3은 12의 ⟨1/3⟩이야.」라고 했어요. 바르게 말했어요.',ARRAY['M3-2-u4-X01']::text[],true,'{"seq":9,"concept":"M3-2-u4-C1","difficulty":2,"kind":"ox","stem":"준우가 「12를 3씩 묶으면 3은 12의 ⟨1/3⟩이야.」라고 했어요. 바르게 말했어요.","answer":"X","reason_options":[{"t":"3은 전체 4묶음 중 1묶음이라 ⟨1/4⟩이라서","correct":true},{"t":"⟨1/3⟩도 분수라서","mis":"M3-2-u4-X01"}],"mis":"M3-2-u4-X01","explanation":["3씩 묶으면 전체 4묶음 — 분모 4.","3은 그중 1묶음 — ⟨1/4⟩.","준우는 부분을 나머지 묶음과 견주었어요 — ×."],"variant_rule":{"alt":[{"stem":"건우가 「9를 3씩 묶으면 6은 9의 ⟨3/2⟩이야.」라고 했어요. 바르게 말했어요.","answer":"X","reason_options":[{"t":"6은 전체 3묶음 중 2묶음이라 ⟨2/3⟩이라서","correct":true},{"t":"⟨3/2⟩도 분수라서","mis":"M3-2-u4-X03"}],"explanation":["3씩 묶으면 전체 3묶음 — 분모 3.","6은 그중 2묶음 — ⟨2/3⟩.","건우는 분모와 분자를 바꾸었어요 — ×."],"asset":null},{"stem":"준우가 「10을 2씩 묶으면 2는 10의 ⟨1/5⟩이야.」라고 했어요. 바르게 말했어요.","answer":"O","reason_options":[{"t":"5묶음 중 1묶음이라서","correct":true},{"t":"낱개 10개 중 2개라서","mis":"M3-2-u4-X02"}],"explanation":["2씩 묶으면 5묶음이에요.","2는 그중 1묶음이에요.","⟨1/5⟩ — 바르게 말했어요 ○."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L02_basic#10','math',3,2,'u4','L02','g3_2_math_u4_L02_basic','lesson_basic','M3-2-u4-C2',3,'mc','auto','8을 2씩 묶으면 4는 8의 ⟨2/4⟩이고, 1씩 묶으면 ⟨4/8⟩예요. 같은 4인데 분수가 다르게 나온 까닭은 무엇인가요?',ARRAY['M3-2-u4-X02','M3-2-u4-X01','M3-2-u4-X22']::text[],true,'{"seq":10,"concept":"M3-2-u4-C2","difficulty":3,"kind":"mc","stem":"8을 2씩 묶으면 4는 8의 ⟨2/4⟩이고, 1씩 묶으면 ⟨4/8⟩예요. 같은 4인데 분수가 다르게 나온 까닭은 무엇인가요?","options":[{"t":"묶는 방법이 달라서","correct":true},{"t":"전체 개수가 달라져서","mis":"M3-2-u4-X02"},{"t":"2가 1보다 커서","mis":"M3-2-u4-X01"},{"t":"분수를 잘못 써서","mis":"M3-2-u4-X22"}],"explanation":["전체는 똑같이 8개예요.","2씩 묶으면 4묶음, 1씩 묶으면 8묶음 — 전체 묶음 수가 달라요.","묶는 방법이 달라지면 분수도 달라져요."],"variant_rule":{"alt":[{"stem":"18을 3씩 묶으면 6은 18의 ⟨2/6⟩이고, 2씩 묶으면 ⟨3/9⟩이에요. 같은 6인데 분수가 다르게 나온 까닭은 무엇인가요?","options":[{"t":"묶는 방법이 달라서","correct":true},{"t":"전체 개수가 달라져서","mis":"M3-2-u4-X02"},{"t":"3이 2보다 커서","mis":"M3-2-u4-X01"},{"t":"분수를 잘못 써서","mis":"M3-2-u4-X22"}],"explanation":["전체는 똑같이 18개예요.","3씩 묶으면 6묶음, 2씩 묶으면 9묶음 — 전체 묶음 수가 달라요.","묶는 방법이 달라지면 분수도 달라져요."],"asset":null},{"stem":"16을 2씩 묶으면 4는 16의 ⟨2/8⟩이고, 4씩 묶으면 ⟨1/4⟩이에요. 같은 4인데 분수가 다르게 나온 까닭은 무엇인가요?","options":[{"t":"묶는 방법이 달라서","correct":true},{"t":"전체 개수가 달라져서","mis":"M3-2-u4-X02"},{"t":"4가 2보다 커서","mis":"M3-2-u4-X01"},{"t":"분수를 잘못 써서","mis":"M3-2-u4-X22"}],"explanation":["전체는 똑같이 16개예요.","2씩 묶으면 8묶음, 4씩 묶으면 4묶음 — 전체 묶음 수가 달라요.","묶는 방법이 달라지면 분수도 달라져요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L02_challenge#1','math',3,2,'u4','L02','g3_2_math_u4_L02_challenge','lesson_challenge','M3-2-u4-C1',2,'mc','auto','28을 4씩 묶었어요. 16은 28의 얼마인가요?',ARRAY['M3-2-u4-X03','M3-2-u4-X01','M3-2-u4-X21']::text[],true,'{"seq":1,"concept":"M3-2-u4-C1","difficulty":2,"kind":"mc","stem":"28을 4씩 묶었어요. 16은 28의 얼마인가요?","options":[{"t":"⟨4/7⟩","correct":true},{"t":"⟨7/4⟩","mis":"M3-2-u4-X03"},{"t":"⟨4/3⟩","mis":"M3-2-u4-X01"},{"t":"⟨5/7⟩","mis":"M3-2-u4-X21"}],"explanation":["28을 4씩 묶으면 7묶음 — 분모 7.","16은 그중 4묶음 — 분자 4.","16은 28의 ⟨4/7⟩ — 낱개 수 16·28로 쓰지 않아요."],"variant_rule":{"alt":[{"stem":"25를 5씩 묶었어요. 20은 25의 얼마인가요?","options":[{"t":"⟨4/5⟩","correct":true},{"t":"⟨5/4⟩","mis":"M3-2-u4-X03"},{"t":"⟨4/25⟩","mis":"M3-2-u4-X02"},{"t":"⟨1/5⟩","mis":"M3-2-u4-X20"}],"explanation":["25를 5씩 묶으면 5묶음 — 분모 5.","20은 그중 4묶음 — 분자 4.","20은 25의 ⟨4/5⟩ — 낱개 수 20·25로 쓰지 않아요."],"asset":null},{"stem":"24를 4씩 묶었어요. 12는 24의 얼마인가요?","options":[{"t":"⟨3/6⟩","correct":true},{"t":"⟨6/3⟩","mis":"M3-2-u4-X03"},{"t":"⟨4/6⟩","mis":"M3-2-u4-X07"},{"t":"⟨3/24⟩","mis":"M3-2-u4-X02"}],"explanation":["24를 4씩 묶으면 6묶음 — 분모 6.","12는 그중 3묶음 — 분자 3.","12는 24의 ⟨3/6⟩ — 낱개 수 12·24로 쓰지 않아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L02_challenge#2','math',3,2,'u4','L02','g3_2_math_u4_L02_challenge','lesson_challenge','M3-2-u4-C2',2,'mc','auto','검은 돌 3개와 흰 돌 4개가 있어요. 흰 돌은 전체 돌의 얼마인가요?',ARRAY['M3-2-u4-X01','M3-2-u4-X20','M3-2-u4-X03']::text[],true,'{"seq":2,"concept":"M3-2-u4-C2","difficulty":2,"kind":"mc","stem":"검은 돌 3개와 흰 돌 4개가 있어요. 흰 돌은 전체 돌의 얼마인가요?","options":[{"t":"⟨4/7⟩","correct":true},{"t":"⟨4/3⟩","mis":"M3-2-u4-X01"},{"t":"⟨3/7⟩","mis":"M3-2-u4-X20"},{"t":"⟨7/4⟩","mis":"M3-2-u4-X03"}],"explanation":["먼저 전체를 정해요 — 돌은 모두 3 + 4 = 7개.","흰 돌은 검은 돌과 견주는 것이 아니라 전체 7개와 견주어요.","흰 돌은 전체의 ⟨4/7⟩예요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[2,0],[3,0],[3,1],[2,1]],"hi":true},{"p":[[3,0],[4,0],[4,1],[3,1]]},{"p":[[4,0],[5,0],[5,1],[4,1]]},{"p":[[0,1],[1,1],[1,2],[0,2]]},{"p":[[1,1],[2,1],[2,2],[1,2]]}],"u":30},"variant_rule":{"alt":[{"stem":"검은 돌 4개와 흰 돌 5개가 있어요. 흰 돌은 전체 돌의 얼마인가요?","options":[{"t":"⟨5/9⟩","correct":true},{"t":"⟨5/4⟩","mis":"M3-2-u4-X01"},{"t":"⟨4/9⟩","mis":"M3-2-u4-X20"},{"t":"⟨9/5⟩","mis":"M3-2-u4-X03"}],"explanation":["먼저 전체를 정해요 — 돌은 모두 4 + 5 = 9개.","흰 돌은 검은 돌과 견주는 것이 아니라 전체 9개와 견주어요.","흰 돌은 전체의 ⟨5/9⟩예요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[2,0],[3,0],[3,1],[2,1]],"hi":true},{"p":[[3,0],[4,0],[4,1],[3,1]],"hi":true},{"p":[[4,0],[5,0],[5,1],[4,1]]},{"p":[[0,1],[1,1],[1,2],[0,2]]},{"p":[[1,1],[2,1],[2,2],[1,2]]},{"p":[[2,1],[3,1],[3,2],[2,2]]},{"p":[[3,1],[4,1],[4,2],[3,2]]}],"u":30}},{"stem":"검은 돌 5개와 흰 돌 3개가 있어요. 흰 돌은 전체 돌의 얼마인가요?","options":[{"t":"⟨3/8⟩","correct":true},{"t":"⟨3/5⟩","mis":"M3-2-u4-X01"},{"t":"⟨5/8⟩","mis":"M3-2-u4-X20"},{"t":"⟨8/3⟩","mis":"M3-2-u4-X03"}],"explanation":["먼저 전체를 정해요 — 돌은 모두 5 + 3 = 8개.","흰 돌은 검은 돌과 견주는 것이 아니라 전체 8개와 견주어요.","흰 돌은 전체의 ⟨3/8⟩이에요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[2,0],[3,0],[3,1],[2,1]],"hi":true},{"p":[[3,0],[4,0],[4,1],[3,1]],"hi":true},{"p":[[4,0],[5,0],[5,1],[4,1]],"hi":true},{"p":[[0,1],[1,1],[1,2],[0,2]]},{"p":[[1,1],[2,1],[2,2],[1,2]]},{"p":[[2,1],[3,1],[3,2],[2,2]]}],"u":30}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L02_challenge#3','math',3,2,'u4','L02','g3_2_math_u4_L02_challenge','lesson_challenge','M3-2-u4-C1',3,'error','auto','12를 2씩 묶은 것을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u4-X03','M3-2-u4-X20']::text[],true,'{"seq":3,"concept":"M3-2-u4-C1","difficulty":3,"kind":"error","stem":"12를 2씩 묶은 것을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서윤 — 「8은 12의 ⟨6/4⟩이야」","correct":true,"mis_target":"M3-2-u4-X03"},{"t":"민서 — 「12를 2씩 묶으면 6묶음이야」","mis":"M3-2-u4-X20"},{"t":"서준 — 「8은 4묶음이야」","mis":"M3-2-u4-X20"}],"explanation":["2씩 묶으면 6묶음 — 분모 6.","8은 4묶음 — 분자 4, 곧 ⟨4/6⟩.","서윤의 말이 틀렸어요."],"variant_rule":{"alt":[{"stem":"21을 3씩 묶은 것을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"채원 — 「9는 21의 ⟨9/7⟩야」","correct":true,"mis_target":"M3-2-u4-X02"},{"t":"서윤 — 「21을 3씩 묶으면 7묶음이야」","mis":"M3-2-u4-X20"},{"t":"은비 — 「9는 3묶음이야」","mis":"M3-2-u4-X20"}],"explanation":["3씩 묶으면 7묶음 — 분모 7.","9는 3묶음 — 분자 3, 곧 ⟨3/7⟩.","채원의 말이 틀렸어요."],"asset":null},{"stem":"14를 2씩 묶은 것을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"채원 — 「8은 14의 ⟨4/3⟩야」","correct":true,"mis_target":"M3-2-u4-X01"},{"t":"서윤 — 「14를 2씩 묶으면 7묶음이야」","mis":"M3-2-u4-X20"},{"t":"은비 — 「8은 4묶음이야」","mis":"M3-2-u4-X20"}],"explanation":["2씩 묶으면 7묶음 — 분모 7.","8은 4묶음 — 분자 4, 곧 ⟨4/7⟩.","채원의 말이 틀렸어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L02_challenge#4','math',3,2,'u4','L02','g3_2_math_u4_L02_challenge','lesson_challenge','M3-2-u4-C2',3,'mc','auto','16을 2씩 묶으면 4는 16의 ⟨2/8⟩이고, 4씩 묶으면 ⟨1/4⟩이에요. 같은 4인데 분수가 다르게 나온 까닭은 무엇인가요?',ARRAY['M3-2-u4-X02','M3-2-u4-X01','M3-2-u4-X22']::text[],true,'{"seq":4,"concept":"M3-2-u4-C2","difficulty":3,"kind":"mc","stem":"16을 2씩 묶으면 4는 16의 ⟨2/8⟩이고, 4씩 묶으면 ⟨1/4⟩이에요. 같은 4인데 분수가 다르게 나온 까닭은 무엇인가요?","options":[{"t":"묶는 방법이 달라서","correct":true},{"t":"전체 개수가 달라져서","mis":"M3-2-u4-X02"},{"t":"4가 2보다 커서","mis":"M3-2-u4-X01"},{"t":"분수를 잘못 써서","mis":"M3-2-u4-X22"}],"explanation":["전체는 똑같이 16개예요.","2씩 묶으면 8묶음, 4씩 묶으면 4묶음 — 전체 묶음 수가 달라요.","묶는 방법이 달라지면 분수도 달라져요."],"variant_rule":{"alt":[{"stem":"8을 2씩 묶으면 4는 8의 ⟨2/4⟩이고, 4씩 묶으면 ⟨1/2⟩이에요. 같은 4인데 분수가 다르게 나온 까닭은 무엇인가요?","options":[{"t":"묶는 방법이 달라서","correct":true},{"t":"전체 개수가 달라져서","mis":"M3-2-u4-X02"},{"t":"4가 2보다 커서","mis":"M3-2-u4-X01"},{"t":"분수를 잘못 써서","mis":"M3-2-u4-X22"}],"explanation":["전체는 똑같이 8개예요.","2씩 묶으면 4묶음, 4씩 묶으면 2묶음 — 전체 묶음 수가 달라요.","묶는 방법이 달라지면 분수도 달라져요."],"asset":null},{"stem":"24를 2씩 묶으면 4는 24의 ⟨2/12⟩이고, 4씩 묶으면 ⟨1/6⟩이에요. 같은 4인데 분수가 다르게 나온 까닭은 무엇인가요?","options":[{"t":"묶는 방법이 달라서","correct":true},{"t":"전체 개수가 달라져서","mis":"M3-2-u4-X02"},{"t":"4가 2보다 커서","mis":"M3-2-u4-X01"},{"t":"분수를 잘못 써서","mis":"M3-2-u4-X22"}],"explanation":["전체는 똑같이 24개예요.","2씩 묶으면 12묶음, 4씩 묶으면 6묶음 — 전체 묶음 수가 달라요.","묶는 방법이 달라지면 분수도 달라져요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L02_challenge#5','math',3,2,'u4','L02','g3_2_math_u4_L02_challenge','lesson_challenge','M3-2-u4-C2',3,'mc','auto','약과 8개를 ⟨3/4⟩만큼 색칠하려고 해요. 바르게 말한 것은 무엇인가요?',ARRAY['M3-2-u4-X04','M3-2-u4-X06','M3-2-u4-X02']::text[],true,'{"seq":5,"concept":"M3-2-u4-C2","difficulty":3,"kind":"mc","stem":"약과 8개를 ⟨3/4⟩만큼 색칠하려고 해요. 바르게 말한 것은 무엇인가요?","options":[{"t":"4묶음으로 똑같이 나눈 것 중 3묶음을 색칠한다","correct":true},{"t":"약과 3개를 색칠한다","mis":"M3-2-u4-X04"},{"t":"약과 4개를 색칠한다","mis":"M3-2-u4-X06"},{"t":"8묶음으로 똑같이 나눈 것 중 3묶음을 색칠한다","mis":"M3-2-u4-X02"}],"explanation":["분모 4는 전체를 똑같이 4묶음으로 나눈다는 뜻이에요.","분자 3은 그중 3묶음이라는 뜻이에요.","8개를 4묶음으로 나누면 한 묶음에 2개 — 6개를 색칠해요."],"variant_rule":{"alt":[{"stem":"와플 10개를 ⟨1/5⟩만큼 색칠하려고 해요. 바르게 말한 것은 무엇인가요?","options":[{"t":"5묶음으로 똑같이 나눈 것 중 1묶음을 색칠한다","correct":true},{"t":"와플 1개를 색칠한다","mis":"M3-2-u4-X04"},{"t":"와플 5개를 색칠한다","mis":"M3-2-u4-X06"},{"t":"10묶음으로 똑같이 나눈 것 중 1묶음을 색칠한다","mis":"M3-2-u4-X02"}],"explanation":["분모 5는 전체를 똑같이 5묶음으로 나눈다는 뜻이에요.","분자 1은 그중 1묶음이라는 뜻이에요.","10개를 5묶음으로 나누면 한 묶음에 2개 — 2개를 색칠해요."],"asset":null},{"stem":"풍선 18개를 ⟨5/6⟩만큼 색칠하려고 해요. 바르게 말한 것은 무엇인가요?","options":[{"t":"6묶음으로 똑같이 나눈 것 중 5묶음을 색칠한다","correct":true},{"t":"풍선 5개를 색칠한다","mis":"M3-2-u4-X04"},{"t":"풍선 6개를 색칠한다","mis":"M3-2-u4-X06"},{"t":"18묶음으로 똑같이 나눈 것 중 5묶음을 색칠한다","mis":"M3-2-u4-X02"}],"explanation":["분모 6은 전체를 똑같이 6묶음으로 나눈다는 뜻이에요.","분자 5는 그중 5묶음이라는 뜻이에요.","18개를 6묶음으로 나누면 한 묶음에 3개 — 15개를 색칠해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L02_challenge#6','math',3,2,'u4','L02','g3_2_math_u4_L02_challenge','lesson_challenge','M3-2-u4-C1',3,'sa','auto','어떤 수를 3씩 묶었더니 6은 전체의 ⟨2/5⟩였어요. 어떤 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M3-2-u4-C1","difficulty":3,"kind":"sa","stem":"어떤 수를 3씩 묶었더니 6은 전체의 ⟨2/5⟩였어요. 어떤 수는 얼마인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["6은 3씩 2묶음이에요 — 분자 2.","분모 5 — 전체는 5묶음이에요.","3씩 5묶음 = 3 × 5 = 15."],"variant_rule":{"alt":[{"stem":"어떤 수를 2씩 묶었더니 4는 전체의 ⟨2/3⟩였어요. 어떤 수는 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["4는 2씩 2묶음이에요 — 분자 2.","분모 3 — 전체는 3묶음이에요.","2씩 3묶음 = 2 × 3 = 6."],"asset":null},{"stem":"어떤 수를 5씩 묶었더니 10은 전체의 ⟨2/4⟩였어요. 어떤 수는 얼마인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["10은 5씩 2묶음이에요 — 분자 2.","분모 4 — 전체는 4묶음이에요.","5씩 4묶음 = 5 × 4 = 20."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L02_challenge#7','math',3,2,'u4','L02','g3_2_math_u4_L02_challenge','lesson_challenge','M3-2-u4-C1',3,'sa','auto','24를 몇씩 묶었더니 6은 24의 ⟨2/8⟩였어요. 몇씩 묶었나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M3-2-u4-C1","difficulty":3,"kind":"sa","stem":"24를 몇씩 묶었더니 6은 24의 ⟨2/8⟩였어요. 몇씩 묶었나요? 숫자로 쓰세요.","answer":["3"],"explanation":["분모 8 — 24를 8묶음으로 나누었어요.","한 묶음은 24 ÷ 8 = 3이에요.","6은 3씩 2묶음 — 맞아요. 3씩 묶었어요."],"variant_rule":{"alt":[{"stem":"12를 몇씩 묶었더니 6은 12의 ⟨3/6⟩이었어요. 몇씩 묶었나요? 숫자로 쓰세요.","answer":["2"],"explanation":["분모 6 — 12를 6묶음으로 나누었어요.","한 묶음은 12 ÷ 6 = 2예요.","6은 2씩 3묶음 — 맞아요. 2씩 묶었어요."],"asset":null},{"stem":"14를 몇씩 묶었더니 2는 14의 ⟨1/7⟩이었어요. 몇씩 묶었나요? 숫자로 쓰세요.","answer":["2"],"explanation":["분모 7 — 14를 7묶음으로 나누었어요.","한 묶음은 14 ÷ 7 = 2예요.","2는 2씩 1묶음 — 맞아요. 2씩 묶었어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L02_challenge#8','math',3,2,'u4','L02','g3_2_math_u4_L02_challenge','lesson_challenge','M3-2-u4-C2',4,'essay','teacher','검은 돌 3개와 흰 돌 4개가 있어요. 은비는 「검은 돌은 흰 돌의 ⟨3/4⟩이야.」라고 했어요. 검은 돌은 전체 돌의 얼마인지 쓰고, 은비의 생각에서 무엇이 잘못되었는지 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-2-u4-C2","difficulty":4,"kind":"essay","stem":"검은 돌 3개와 흰 돌 4개가 있어요. 은비는 「검은 돌은 흰 돌의 ⟨3/4⟩이야.」라고 했어요. 검은 돌은 전체 돌의 얼마인지 쓰고, 은비의 생각에서 무엇이 잘못되었는지 설명해 보세요.","answer_guide":{"answer":"예: 검은 돌은 전체 7개 중 3개이므로 전체의 ⟨3/7⟩이다. 은비는 전체가 아니라 흰 돌과 견주었다. 분수로 나타낼 때는 먼저 전체를 정하고 부분을 전체와 견주어야 한다.","scoring_points":["⟨3/7⟩이라고 답했는가","흰 돌과 견준 것이 잘못이라고 썼는가","전체를 먼저 정해 전체와 견주어야 한다고 썼는가"]},"explanation":["돌은 모두 7개.","검은 돌 3개 → ⟨3/7⟩.","부분끼리 견주지 않아요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[2,0],[3,0],[3,1],[2,1]],"hi":true},{"p":[[3,0],[4,0],[4,1],[3,1]]},{"p":[[4,0],[5,0],[5,1],[4,1]]},{"p":[[0,1],[1,1],[1,2],[0,2]]},{"p":[[1,1],[2,1],[2,2],[1,2]]}],"u":30}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L02_challenge#9','math',3,2,'u4','L02','g3_2_math_u4_L02_challenge','lesson_challenge','M3-2-u4-C2',4,'essay','teacher','와플 8개를 2개씩 묶을 때와 4개씩 묶을 때, 와플 4개는 각각 전체의 얼마인지 분수로 쓰고 왜 분수가 다르게 나오는지 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-2-u4-C2","difficulty":4,"kind":"essay","stem":"와플 8개를 2개씩 묶을 때와 4개씩 묶을 때, 와플 4개는 각각 전체의 얼마인지 분수로 쓰고 왜 분수가 다르게 나오는지 설명해 보세요.","answer_guide":{"answer":"예: 2개씩 묶으면 4묶음 중 2묶음이라 ⟨2/4⟩, 4개씩 묶으면 2묶음 중 1묶음이라 ⟨1/2⟩이다. 같은 4개라도 묶는 방법이 달라지면 전체 묶음 수(분모)와 부분 묶음 수(분자)가 달라져서 분수가 다르게 나온다.","scoring_points":["2개씩 묶을 때 ⟨2/4⟩를 썼는가","4개씩 묶을 때 ⟨1/2⟩을 썼는가","묶는 방법에 따라 묶음 수가 달라진다고 설명했는가"]},"explanation":["2개씩 → 4묶음 중 2묶음.","4개씩 → 2묶음 중 1묶음.","묶는 방법이 다르면 분수도 달라요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[2.7,0],[3.7,0],[3.7,1],[2.7,1]],"hi":true},{"p":[[3.7,0],[4.7,0],[4.7,1],[3.7,1]],"hi":true},{"p":[[5.4,0],[6.4,0],[6.4,1],[5.4,1]]},{"p":[[6.4,0],[7.4,0],[7.4,1],[6.4,1]]},{"p":[[8.1,0],[9.1,0],[9.1,1],[8.1,1]]},{"p":[[9.1,0],[10.1,0],[10.1,1],[9.1,1]]}],"u":29}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L02_challenge#10','math',3,2,'u4','L02','g3_2_math_u4_L02_challenge','lesson_challenge','M3-2-u4-C1',4,'sa','auto','15를 몇씩 묶었더니 5는 15의 ⟨1/3⟩이었어요. 몇씩 묶었나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M3-2-u4-C1","difficulty":4,"kind":"sa","stem":"15를 몇씩 묶었더니 5는 15의 ⟨1/3⟩이었어요. 몇씩 묶었나요? 숫자로 쓰세요.","answer":["5"],"explanation":["분모 3 — 15를 3묶음으로 나누었어요.","한 묶음은 15 ÷ 3 = 5예요.","5는 5씩 1묶음 — 맞아요. 5씩 묶었어요."],"variant_rule":{"alt":[{"stem":"16을 몇씩 묶었더니 2는 16의 ⟨1/8⟩이었어요. 몇씩 묶었나요? 숫자로 쓰세요.","answer":["2"],"explanation":["분모 8 — 16을 8묶음으로 나누었어요.","한 묶음은 16 ÷ 8 = 2예요.","2는 2씩 1묶음 — 맞아요. 2씩 묶었어요."],"asset":null},{"stem":"12를 몇씩 묶었더니 3은 12의 ⟨1/4⟩이었어요. 몇씩 묶었나요? 숫자로 쓰세요.","answer":["3"],"explanation":["분모 4 — 12를 4묶음으로 나누었어요.","한 묶음은 12 ÷ 4 = 3이에요.","3은 3씩 1묶음 — 맞아요. 3씩 묶었어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L03_basic#1','math',3,2,'u4','L03','g3_2_math_u4_L03_basic','lesson_basic','M3-2-u4-C3',1,'sa','auto','풍선 8개의 ⟨1/2⟩은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M3-2-u4-C3","difficulty":1,"kind":"sa","stem":"풍선 8개의 ⟨1/2⟩은 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["8을 분모만큼 똑같이 2묶음으로 나누면 한 묶음에 4개예요 — 8의 ⟨1/2⟩은 4.","⟨1/2⟩은 그중 1묶음이에요.","8의 ⟨1/2⟩은 4 — 8 ÷ 2와 같아요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[0,1],[1,1],[1,2],[0,2]],"hi":true},{"p":[[1,1],[2,1],[2,2],[1,2]],"hi":true},{"p":[[2.7,0],[3.7,0],[3.7,1],[2.7,1]]},{"p":[[3.7,0],[4.7,0],[4.7,1],[3.7,1]]},{"p":[[2.7,1],[3.7,1],[3.7,2],[2.7,2]]},{"p":[[3.7,1],[4.7,1],[4.7,2],[3.7,2]]}],"u":30},"variant_rule":{"alt":[{"stem":"구슬 6개의 ⟨1/3⟩은 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["6을 분모만큼 똑같이 3묶음으로 나누면 한 묶음에 2개예요 — 6의 ⟨1/3⟩은 2.","⟨1/3⟩은 그중 1묶음이에요.","6의 ⟨1/3⟩은 2 — 6 ÷ 3과 같아요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[2.7,0],[3.7,0],[3.7,1],[2.7,1]]},{"p":[[3.7,0],[4.7,0],[4.7,1],[3.7,1]]},{"p":[[5.4,0],[6.4,0],[6.4,1],[5.4,1]]},{"p":[[6.4,0],[7.4,0],[7.4,1],[6.4,1]]}],"u":30}},{"stem":"딸기 8개의 ⟨2/4⟩는 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["8을 분모만큼 똑같이 4묶음으로 나누면 한 묶음에 2개예요 — 8의 ⟨1/4⟩은 2.","⟨2/4⟩는 ⟨1/4⟩이 2개 — 2묶음이에요.","8의 ⟨2/4⟩는 2 × 2 = 4 — 분자만 보고 답하지 않아요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[2.7,0],[3.7,0],[3.7,1],[2.7,1]],"hi":true},{"p":[[3.7,0],[4.7,0],[4.7,1],[3.7,1]],"hi":true},{"p":[[5.4,0],[6.4,0],[6.4,1],[5.4,1]]},{"p":[[6.4,0],[7.4,0],[7.4,1],[6.4,1]]},{"p":[[8.1,0],[9.1,0],[9.1,1],[8.1,1]]},{"p":[[9.1,0],[10.1,0],[10.1,1],[9.1,1]]}],"u":29}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L03_basic#2','math',3,2,'u4','L03','g3_2_math_u4_L03_basic','lesson_basic','M3-2-u4-C3',1,'sa','auto','9의 ⟨1/3⟩은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u4-C3","difficulty":1,"kind":"sa","stem":"9의 ⟨1/3⟩은 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["9를 분모만큼 똑같이 3묶음으로 나누면 한 묶음에 3개예요 — 9의 ⟨1/3⟩은 3.","⟨1/3⟩은 그중 1묶음이에요.","9의 ⟨1/3⟩은 3 — 9 ÷ 3과 같아요."],"variant_rule":{"alt":[{"stem":"36의 ⟨1/6⟩은 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["36을 분모만큼 똑같이 6묶음으로 나누면 한 묶음에 6개예요 — 36의 ⟨1/6⟩은 6.","⟨1/6⟩은 그중 1묶음이에요.","36의 ⟨1/6⟩은 6 — 36 ÷ 6과 같아요."],"asset":null},{"stem":"12의 ⟨1/6⟩은 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["12를 분모만큼 똑같이 6묶음으로 나누면 한 묶음에 2개예요 — 12의 ⟨1/6⟩은 2.","⟨1/6⟩은 그중 1묶음이에요.","12의 ⟨1/6⟩은 2 — 12 ÷ 6과 같아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L03_basic#3','math',3,2,'u4','L03','g3_2_math_u4_L03_basic','lesson_basic','M3-2-u4-C3',1,'sa','auto','12의 ⟨1/6⟩은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-2-u4-C3","difficulty":1,"kind":"sa","stem":"12의 ⟨1/6⟩은 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["12를 분모만큼 똑같이 6묶음으로 나누면 한 묶음에 2개예요 — 12의 ⟨1/6⟩은 2.","⟨1/6⟩은 그중 1묶음이에요.","12의 ⟨1/6⟩은 2 — 12 ÷ 6과 같아요."],"variant_rule":{"alt":[{"stem":"21의 ⟨1/7⟩은 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["21을 분모만큼 똑같이 7묶음으로 나누면 한 묶음에 3개예요 — 21의 ⟨1/7⟩은 3.","⟨1/7⟩은 그중 1묶음이에요.","21의 ⟨1/7⟩은 3 — 21 ÷ 7과 같아요."],"asset":null},{"stem":"24의 ⟨1/6⟩은 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["24를 분모만큼 똑같이 6묶음으로 나누면 한 묶음에 4개예요 — 24의 ⟨1/6⟩은 4.","⟨1/6⟩은 그중 1묶음이에요.","24의 ⟨1/6⟩은 4 — 24 ÷ 6과 같아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L03_basic#4','math',3,2,'u4','L03','g3_2_math_u4_L03_basic','lesson_basic','M3-2-u4-C3',1,'sa','auto','12의 ⟨3/4⟩은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-2-u4-C3","difficulty":1,"kind":"sa","stem":"12의 ⟨3/4⟩은 얼마인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["12를 분모만큼 똑같이 4묶음으로 나누면 한 묶음에 3개예요 — 12의 ⟨1/4⟩은 3.","⟨3/4⟩은 ⟨1/4⟩이 3개 — 3묶음이에요.","12의 ⟨3/4⟩은 3 × 3 = 9 — 분자만 보고 답하지 않아요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[2,0],[3,0],[3,1],[2,1]],"hi":true},{"p":[[3.7,0],[4.7,0],[4.7,1],[3.7,1]],"hi":true},{"p":[[4.7,0],[5.7,0],[5.7,1],[4.7,1]],"hi":true},{"p":[[5.7,0],[6.7,0],[6.7,1],[5.7,1]],"hi":true},{"p":[[7.4,0],[8.4,0],[8.4,1],[7.4,1]],"hi":true},{"p":[[8.4,0],[9.4,0],[9.4,1],[8.4,1]],"hi":true},{"p":[[9.4,0],[10.4,0],[10.4,1],[9.4,1]],"hi":true},{"p":[[11.1,0],[12.1,0],[12.1,1],[11.1,1]]},{"p":[[12.1,0],[13.1,0],[13.1,1],[12.1,1]]},{"p":[[13.1,0],[14.1,0],[14.1,1],[13.1,1]]}],"u":21},"variant_rule":{"alt":[{"stem":"8의 ⟨3/4⟩은 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["8을 분모만큼 똑같이 4묶음으로 나누면 한 묶음에 2개예요 — 8의 ⟨1/4⟩은 2.","⟨3/4⟩은 ⟨1/4⟩이 3개 — 3묶음이에요.","8의 ⟨3/4⟩은 2 × 3 = 6 — 분자만 보고 답하지 않아요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[2.7,0],[3.7,0],[3.7,1],[2.7,1]],"hi":true},{"p":[[3.7,0],[4.7,0],[4.7,1],[3.7,1]],"hi":true},{"p":[[5.4,0],[6.4,0],[6.4,1],[5.4,1]],"hi":true},{"p":[[6.4,0],[7.4,0],[7.4,1],[6.4,1]],"hi":true},{"p":[[8.1,0],[9.1,0],[9.1,1],[8.1,1]]},{"p":[[9.1,0],[10.1,0],[10.1,1],[9.1,1]]}],"u":29}},{"stem":"16의 ⟨3/4⟩은 얼마인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["16을 분모만큼 똑같이 4묶음으로 나누면 한 묶음에 4개예요 — 16의 ⟨1/4⟩은 4.","⟨3/4⟩은 ⟨1/4⟩이 3개 — 3묶음이에요.","16의 ⟨3/4⟩은 4 × 3 = 12 — 분자만 보고 답하지 않아요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[0,1],[1,1],[1,2],[0,2]],"hi":true},{"p":[[1,1],[2,1],[2,2],[1,2]],"hi":true},{"p":[[2.7,0],[3.7,0],[3.7,1],[2.7,1]],"hi":true},{"p":[[3.7,0],[4.7,0],[4.7,1],[3.7,1]],"hi":true},{"p":[[2.7,1],[3.7,1],[3.7,2],[2.7,2]],"hi":true},{"p":[[3.7,1],[4.7,1],[4.7,2],[3.7,2]],"hi":true},{"p":[[5.4,0],[6.4,0],[6.4,1],[5.4,1]],"hi":true},{"p":[[6.4,0],[7.4,0],[7.4,1],[6.4,1]],"hi":true},{"p":[[5.4,1],[6.4,1],[6.4,2],[5.4,2]],"hi":true},{"p":[[6.4,1],[7.4,1],[7.4,2],[6.4,2]],"hi":true},{"p":[[8.1,0],[9.1,0],[9.1,1],[8.1,1]]},{"p":[[9.1,0],[10.1,0],[10.1,1],[9.1,1]]},{"p":[[8.1,1],[9.1,1],[9.1,2],[8.1,2]]},{"p":[[9.1,1],[10.1,1],[10.1,2],[9.1,2]]}],"u":29}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L03_basic#5','math',3,2,'u4','L03','g3_2_math_u4_L03_basic','lesson_basic','M3-2-u4-C3',2,'mc','auto','사탕 12개의 ⟨3/4⟩은 몇 개인가요?',ARRAY['M3-2-u4-X04','M3-2-u4-X06','M3-2-u4-X21']::text[],true,'{"seq":5,"concept":"M3-2-u4-C3","difficulty":2,"kind":"mc","stem":"사탕 12개의 ⟨3/4⟩은 몇 개인가요?","options":[{"t":"9개","correct":true},{"t":"3개","mis":"M3-2-u4-X04"},{"t":"16개","mis":"M3-2-u4-X06"},{"t":"12개","mis":"M3-2-u4-X21"}],"explanation":["12를 분모만큼 똑같이 4묶음으로 나누면 한 묶음에 3개예요 — 12의 ⟨1/4⟩은 3.","⟨3/4⟩은 ⟨1/4⟩이 3개 — 3묶음이에요.","12의 ⟨3/4⟩은 3 × 3 = 9 — 분자만 보고 답하지 않아요."],"variant_rule":{"alt":[{"stem":"쿠키 15개의 ⟨2/3⟩는 몇 개인가요?","options":[{"t":"10개","correct":true},{"t":"2개","mis":"M3-2-u4-X04"},{"t":"5개","mis":"M3-2-u4-X05"},{"t":"15개","mis":"M3-2-u4-X21"}],"explanation":["15를 분모만큼 똑같이 3묶음으로 나누면 한 묶음에 5개예요 — 15의 ⟨1/3⟩은 5.","⟨2/3⟩는 ⟨1/3⟩이 2개 — 2묶음이에요.","15의 ⟨2/3⟩는 5 × 2 = 10 — 분자만 보고 답하지 않아요."],"asset":null},{"stem":"귤 8개의 ⟨3/4⟩은 몇 개인가요?","options":[{"t":"6개","correct":true},{"t":"3개","mis":"M3-2-u4-X04"},{"t":"2개","mis":"M3-2-u4-X05"},{"t":"8개","mis":"M3-2-u4-X21"}],"explanation":["8을 분모만큼 똑같이 4묶음으로 나누면 한 묶음에 2개예요 — 8의 ⟨1/4⟩은 2.","⟨3/4⟩은 ⟨1/4⟩이 3개 — 3묶음이에요.","8의 ⟨3/4⟩은 2 × 3 = 6 — 분자만 보고 답하지 않아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L03_basic#6','math',3,2,'u4','L03','g3_2_math_u4_L03_basic','lesson_basic','M3-2-u4-C3',2,'mc','auto','12의 ⟨2/3⟩를 구하는 방법으로 알맞은 것은 무엇인가요?',ARRAY['M3-2-u4-X06','M3-2-u4-X05','M3-2-u4-X04']::text[],true,'{"seq":6,"concept":"M3-2-u4-C3","difficulty":2,"kind":"mc","stem":"12의 ⟨2/3⟩를 구하는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"12를 똑같이 3묶음으로 나눈 것 중 2묶음","correct":true},{"t":"12를 똑같이 2묶음으로 나눈 것 중 3묶음","mis":"M3-2-u4-X06"},{"t":"12를 똑같이 3묶음으로 나눈 것 중 1묶음","mis":"M3-2-u4-X05"},{"t":"12에서 2를 뺀다","mis":"M3-2-u4-X04"}],"explanation":["분모 3 — 3묶음으로 똑같이 나눠요.","분자 2 — 그중 2묶음을 모아요.","12의 ⟨2/3⟩는 8."],"variant_rule":{"alt":[{"stem":"12의 ⟨2/4⟩를 구하는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"12를 똑같이 4묶음으로 나눈 것 중 2묶음","correct":true},{"t":"12를 똑같이 2묶음으로 나눈 것 중 4묶음","mis":"M3-2-u4-X06"},{"t":"12를 똑같이 4묶음으로 나눈 것 중 1묶음","mis":"M3-2-u4-X05"},{"t":"12에서 2를 뺀다","mis":"M3-2-u4-X04"}],"explanation":["분모 4 — 4묶음으로 똑같이 나눠요.","분자 2 — 그중 2묶음을 모아요.","12의 ⟨2/4⟩는 6."],"asset":null},{"stem":"8의 ⟨2/4⟩를 구하는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"8을 똑같이 4묶음으로 나눈 것 중 2묶음","correct":true},{"t":"8을 똑같이 2묶음으로 나눈 것 중 4묶음","mis":"M3-2-u4-X06"},{"t":"8을 똑같이 4묶음으로 나눈 것 중 1묶음","mis":"M3-2-u4-X05"},{"t":"8에서 2를 뺀다","mis":"M3-2-u4-X04"}],"explanation":["분모 4 — 4묶음으로 똑같이 나눠요.","분자 2 — 그중 2묶음을 모아요.","8의 ⟨2/4⟩는 4."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L03_basic#7','math',3,2,'u4','L03','g3_2_math_u4_L03_basic','lesson_basic','M3-2-u4-C3',2,'sa','auto','사탕 12개 중 채원은 ⟨1/4⟩을, 서준은 ⟨2/4⟩를 먹었어요. 남은 사탕은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M3-2-u4-C3","difficulty":2,"kind":"sa","stem":"사탕 12개 중 채원은 ⟨1/4⟩을, 서준은 ⟨2/4⟩를 먹었어요. 남은 사탕은 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["12의 ⟨1/4⟩은 3개예요.","채원은 3개, 서준은 6개 — 모두 9개를 먹었어요.","남은 것은 12 − 9 = 3개."],"variant_rule":{"alt":[{"stem":"귤 10개 중 채원은 ⟨1/5⟩을, 서준은 ⟨2/5⟩를 먹었어요. 남은 귤은 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["10의 ⟨1/5⟩은 2개예요.","채원은 2개, 서준은 4개 — 모두 6개를 먹었어요.","남은 것은 10 − 6 = 4개."],"asset":null},{"stem":"약과 20개 중 준우는 ⟨3/5⟩을, 도연은 ⟨1/5⟩을 먹었어요. 남은 약과는 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["20의 ⟨1/5⟩은 4개예요.","준우는 12개, 도연은 4개 — 모두 16개를 먹었어요.","남은 것은 20 − 16 = 4개."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L03_basic#8','math',3,2,'u4','L03','g3_2_math_u4_L03_basic','lesson_basic','M3-2-u4-C3',2,'ox','auto','도연이 「12의 ⟨3/4⟩은 3이야.」라고 했어요. 바르게 말했어요.',ARRAY['M3-2-u4-X04']::text[],true,'{"seq":8,"concept":"M3-2-u4-C3","difficulty":2,"kind":"ox","stem":"도연이 「12의 ⟨3/4⟩은 3이야.」라고 했어요. 바르게 말했어요.","answer":"X","reason_options":[{"t":"4묶음으로 나눈 것 중 3묶음은 9이라서","correct":true},{"t":"분자가 3이라서","mis":"M3-2-u4-X04"}],"mis":"M3-2-u4-X04","explanation":["12를 분모만큼 똑같이 4묶음으로 나누면 한 묶음에 3개예요 — 12의 ⟨1/4⟩은 3.","⟨3/4⟩은 ⟨1/4⟩이 3개 — 3묶음이에요.","12의 ⟨3/4⟩은 3 × 3 = 9 — 분자만 보고 답하지 않아요."],"variant_rule":{"alt":[{"stem":"하윤이 「18의 ⟨4/6⟩는 4야.」라고 했어요. 바르게 말했어요.","answer":"X","reason_options":[{"t":"6묶음으로 나눈 것 중 4묶음은 12이라서","correct":true},{"t":"분자가 4이라서","mis":"M3-2-u4-X04"}],"explanation":["18을 분모만큼 똑같이 6묶음으로 나누면 한 묶음에 3개예요 — 18의 ⟨1/6⟩은 3.","⟨4/6⟩는 ⟨1/6⟩이 4개 — 4묶음이에요.","18의 ⟨4/6⟩는 3 × 4 = 12 — 분자만 보고 답하지 않아요."],"asset":null},{"stem":"채원이 「36의 ⟨2/6⟩는 12야.」라고 했어요. 바르게 말했어요.","answer":"O","reason_options":[{"t":"6묶음으로 나눈 것 중 2묶음이 12이라서","correct":true},{"t":"분자가 2이라서","mis":"M3-2-u4-X04"}],"explanation":["36을 분모만큼 똑같이 6묶음으로 나누면 한 묶음에 6개예요 — 36의 ⟨1/6⟩은 6.","⟨2/6⟩는 ⟨1/6⟩이 2개 — 2묶음이에요.","36의 ⟨2/6⟩는 6 × 2 = 12 — 분자만 보고 답하지 않아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L03_basic#9','math',3,2,'u4','L03','g3_2_math_u4_L03_basic','lesson_basic','M3-2-u4-C3',2,'sa','auto','18의 ⟨2/3⟩는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M3-2-u4-C3","difficulty":2,"kind":"sa","stem":"18의 ⟨2/3⟩는 얼마인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["18을 분모만큼 똑같이 3묶음으로 나누면 한 묶음에 6개예요 — 18의 ⟨1/3⟩은 6.","⟨2/3⟩는 ⟨1/3⟩이 2개 — 2묶음이에요.","18의 ⟨2/3⟩는 6 × 2 = 12 — 분자만 보고 답하지 않아요."],"variant_rule":{"alt":[{"stem":"10의 ⟨4/5⟩는 얼마인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["10을 분모만큼 똑같이 5묶음으로 나누면 한 묶음에 2개예요 — 10의 ⟨1/5⟩은 2.","⟨4/5⟩는 ⟨1/5⟩이 4개 — 4묶음이에요.","10의 ⟨4/5⟩는 2 × 4 = 8 — 분자만 보고 답하지 않아요."],"asset":null},{"stem":"9의 ⟨2/3⟩는 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["9를 분모만큼 똑같이 3묶음으로 나누면 한 묶음에 3개예요 — 9의 ⟨1/3⟩은 3.","⟨2/3⟩는 ⟨1/3⟩이 2개 — 2묶음이에요.","9의 ⟨2/3⟩는 3 × 2 = 6 — 분자만 보고 답하지 않아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L03_basic#10','math',3,2,'u4','L03','g3_2_math_u4_L03_basic','lesson_basic','M3-2-u4-C3',3,'mc','auto','쿠키 10개 중 도연은 ⟨1/2⟩을, 지훈은 ⟨4/10⟩를 먹었어요. 누가 더 많이 먹었나요?',ARRAY['M3-2-u4-X04','M3-2-u4-X22']::text[],true,'{"seq":10,"concept":"M3-2-u4-C3","difficulty":3,"kind":"mc","stem":"쿠키 10개 중 도연은 ⟨1/2⟩을, 지훈은 ⟨4/10⟩를 먹었어요. 누가 더 많이 먹었나요?","options":[{"t":"도연","correct":true},{"t":"지훈","mis":"M3-2-u4-X04"},{"t":"두 사람이 같아요","mis":"M3-2-u4-X22"},{"t":"알 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["10의 ⟨1/2⟩은 5개예요.","10의 ⟨4/10⟩는 4개예요.","개수로 바꾸어 견주면 도연이 더 많이 먹었어요."],"variant_rule":{"alt":[{"stem":"과자 18개 중 서준은 ⟨1/2⟩을, 하윤은 ⟨2/3⟩를 먹었어요. 누가 더 많이 먹었나요?","options":[{"t":"하윤","correct":true},{"t":"서준","mis":"M3-2-u4-X04"},{"t":"두 사람이 같아요","mis":"M3-2-u4-X22"},{"t":"알 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["18의 ⟨1/2⟩은 9개예요.","18의 ⟨2/3⟩는 12개예요.","개수로 바꾸어 견주면 하윤이 더 많이 먹었어요."],"asset":null},{"stem":"딸기 24개 중 건우는 ⟨4/8⟩를, 서윤은 ⟨1/6⟩을 먹었어요. 누가 더 많이 먹었나요?","options":[{"t":"건우","correct":true},{"t":"서윤","mis":"M3-2-u4-X04"},{"t":"두 사람이 같아요","mis":"M3-2-u4-X22"},{"t":"알 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["24의 ⟨4/8⟩는 12개예요.","24의 ⟨1/6⟩은 4개예요.","개수로 바꾸어 견주면 건우가 더 많이 먹었어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L03_challenge#1','math',3,2,'u4','L03','g3_2_math_u4_L03_challenge','lesson_challenge','M3-2-u4-C3',2,'mc','auto','귤 35개의 ⟨6/7⟩은 몇 개인가요?',ARRAY['M3-2-u4-X04','M3-2-u4-X05','M3-2-u4-X21']::text[],true,'{"seq":1,"concept":"M3-2-u4-C3","difficulty":2,"kind":"mc","stem":"귤 35개의 ⟨6/7⟩은 몇 개인가요?","options":[{"t":"30개","correct":true},{"t":"6개","mis":"M3-2-u4-X04"},{"t":"5개","mis":"M3-2-u4-X05"},{"t":"35개","mis":"M3-2-u4-X21"}],"explanation":["35를 분모만큼 똑같이 7묶음으로 나누면 한 묶음에 5개예요 — 35의 ⟨1/7⟩은 5.","⟨6/7⟩은 ⟨1/7⟩이 6개 — 6묶음이에요.","35의 ⟨6/7⟩은 5 × 6 = 30 — 분자만 보고 답하지 않아요."],"variant_rule":{"alt":[{"stem":"약과 20개의 ⟨3/4⟩은 몇 개인가요?","options":[{"t":"15개","correct":true},{"t":"3개","mis":"M3-2-u4-X04"},{"t":"5개","mis":"M3-2-u4-X05"},{"t":"20개","mis":"M3-2-u4-X21"}],"explanation":["20을 분모만큼 똑같이 4묶음으로 나누면 한 묶음에 5개예요 — 20의 ⟨1/4⟩은 5.","⟨3/4⟩은 ⟨1/4⟩이 3개 — 3묶음이에요.","20의 ⟨3/4⟩은 5 × 3 = 15 — 분자만 보고 답하지 않아요."],"asset":null},{"stem":"와플 30개의 ⟨4/5⟩는 몇 개인가요?","options":[{"t":"24개","correct":true},{"t":"4개","mis":"M3-2-u4-X04"},{"t":"6개","mis":"M3-2-u4-X05"},{"t":"30개","mis":"M3-2-u4-X21"}],"explanation":["30을 분모만큼 똑같이 5묶음으로 나누면 한 묶음에 6개예요 — 30의 ⟨1/5⟩은 6.","⟨4/5⟩는 ⟨1/5⟩이 4개 — 4묶음이에요.","30의 ⟨4/5⟩는 6 × 4 = 24 — 분자만 보고 답하지 않아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L03_challenge#2','math',3,2,'u4','L03','g3_2_math_u4_L03_challenge','lesson_challenge','M3-2-u4-C3',2,'sa','auto','쿠키 32개 중 민서는 ⟨5/8⟩를, 하윤은 ⟨1/8⟩을 먹었어요. 남은 쿠키는 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u4-C3","difficulty":2,"kind":"sa","stem":"쿠키 32개 중 민서는 ⟨5/8⟩를, 하윤은 ⟨1/8⟩을 먹었어요. 남은 쿠키는 몇 개인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["32의 ⟨1/8⟩은 4개예요.","민서는 20개, 하윤은 4개 — 모두 24개를 먹었어요.","남은 것은 32 − 24 = 8개."],"variant_rule":{"alt":[{"stem":"사탕 24개 중 지훈은 ⟨5/8⟩를, 은비는 ⟨1/8⟩을 먹었어요. 남은 사탕은 몇 개인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["24의 ⟨1/8⟩은 3개예요.","지훈은 15개, 은비는 3개 — 모두 18개를 먹었어요.","남은 것은 24 − 18 = 6개."],"asset":null},{"stem":"귤 10개 중 채원은 ⟨1/5⟩을, 은비는 ⟨3/5⟩을 먹었어요. 남은 귤은 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["10의 ⟨1/5⟩은 2개예요.","채원은 2개, 은비는 6개 — 모두 8개를 먹었어요.","남은 것은 10 − 8 = 2개."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L03_challenge#3','math',3,2,'u4','L03','g3_2_math_u4_L03_challenge','lesson_challenge','M3-2-u4-C3',3,'mc','auto','과자 30개 중 도연은 ⟨1/3⟩을, 하윤은 ⟨1/2⟩을 먹었어요. 누가 더 많이 먹었나요?',ARRAY['M3-2-u4-X04','M3-2-u4-X22']::text[],true,'{"seq":3,"concept":"M3-2-u4-C3","difficulty":3,"kind":"mc","stem":"과자 30개 중 도연은 ⟨1/3⟩을, 하윤은 ⟨1/2⟩을 먹었어요. 누가 더 많이 먹었나요?","options":[{"t":"하윤","correct":true},{"t":"도연","mis":"M3-2-u4-X04"},{"t":"두 사람이 같아요","mis":"M3-2-u4-X22"},{"t":"알 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["30의 ⟨1/3⟩은 10개예요.","30의 ⟨1/2⟩은 15개예요.","개수로 바꾸어 견주면 하윤이 더 많이 먹었어요."],"variant_rule":{"alt":[{"stem":"딸기 20개 중 서윤은 ⟨1/4⟩을, 지훈은 ⟨1/2⟩을 먹었어요. 누가 더 많이 먹었나요?","options":[{"t":"지훈","correct":true},{"t":"서윤","mis":"M3-2-u4-X04"},{"t":"두 사람이 같아요","mis":"M3-2-u4-X22"},{"t":"알 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["20의 ⟨1/4⟩은 5개예요.","20의 ⟨1/2⟩은 10개예요.","개수로 바꾸어 견주면 지훈이 더 많이 먹었어요."],"asset":null},{"stem":"사탕 18개 중 채원은 ⟨3/6⟩을, 하윤은 ⟨1/2⟩을 먹었어요. 누가 더 많이 먹었나요?","options":[{"t":"두 사람이 같아요","correct":true},{"t":"채원","mis":"M3-2-u4-X22"},{"t":"하윤","mis":"M3-2-u4-X22"},{"t":"알 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["18의 ⟨3/6⟩은 9개예요.","18의 ⟨1/2⟩은 9개예요.","개수로 바꾸어 견주면 같아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L03_challenge#4','math',3,2,'u4','L03','g3_2_math_u4_L03_challenge','lesson_challenge','M3-2-u4-C3',3,'sa','auto','어떤 수의 ⟨1/3⟩이 4예요. 어떤 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-2-u4-C3","difficulty":3,"kind":"sa","stem":"어떤 수의 ⟨1/3⟩이 4예요. 어떤 수는 얼마인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["⟨1/3⟩이 4예요.","한 묶음이 4예요.","전체는 3묶음 — 4 × 3 = 12."],"variant_rule":{"alt":[{"stem":"어떤 수의 ⟨1/4⟩이 8이에요. 어떤 수는 얼마인가요? 숫자로 쓰세요.","answer":["32"],"explanation":["⟨1/4⟩이 8이에요.","한 묶음이 8이에요.","전체는 4묶음 — 8 × 4 = 32."],"asset":null},{"stem":"어떤 수의 ⟨2/3⟩가 16이에요. 어떤 수는 얼마인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["⟨2/3⟩는 ⟨1/3⟩이 2개예요.","⟨1/3⟩만큼은 16 ÷ 2 = 8이에요.","전체는 3묶음 — 8 × 3 = 24."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L03_challenge#5','math',3,2,'u4','L03','g3_2_math_u4_L03_challenge','lesson_challenge','M3-2-u4-C3',3,'sa','auto','어떤 수의 ⟨3/6⟩이 6이에요. 어떤 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-2-u4-C3","difficulty":3,"kind":"sa","stem":"어떤 수의 ⟨3/6⟩이 6이에요. 어떤 수는 얼마인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["⟨3/6⟩은 ⟨1/6⟩이 3개예요.","⟨1/6⟩만큼은 6 ÷ 3 = 2예요.","전체는 6묶음 — 2 × 6 = 12."],"variant_rule":{"alt":[{"stem":"어떤 수의 ⟨3/4⟩이 18이에요. 어떤 수는 얼마인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["⟨3/4⟩은 ⟨1/4⟩이 3개예요.","⟨1/4⟩만큼은 18 ÷ 3 = 6이에요.","전체는 4묶음 — 6 × 4 = 24."],"asset":null},{"stem":"어떤 수의 ⟨5/6⟩가 40이에요. 어떤 수는 얼마인가요? 숫자로 쓰세요.","answer":["48"],"explanation":["⟨5/6⟩는 ⟨1/6⟩이 5개예요.","⟨1/6⟩만큼은 40 ÷ 5 = 8이에요.","전체는 6묶음 — 8 × 6 = 48."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L03_challenge#6','math',3,2,'u4','L03','g3_2_math_u4_L03_challenge','lesson_challenge','M3-2-u4-C3',3,'mc','auto','20의 ⟨1/4⟩과 20의 ⟨1/5⟩ 중 더 큰 것은 무엇인가요?',ARRAY['M3-2-u4-X04','M3-2-u4-X22']::text[],true,'{"seq":6,"concept":"M3-2-u4-C3","difficulty":3,"kind":"mc","stem":"20의 ⟨1/4⟩과 20의 ⟨1/5⟩ 중 더 큰 것은 무엇인가요?","options":[{"t":"20의 ⟨1/4⟩","correct":true},{"t":"20의 ⟨1/5⟩","mis":"M3-2-u4-X04"},{"t":"두 수가 같아요","mis":"M3-2-u4-X22"},{"t":"알 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["20의 ⟨1/4⟩ = 5예요.","20의 ⟨1/5⟩ = 4예요.","5 > 4 — 20의 ⟨1/4⟩이 더 커요."],"variant_rule":{"alt":[{"stem":"25의 ⟨3/5⟩과 15의 ⟨3/5⟩ 중 더 큰 것은 무엇인가요?","options":[{"t":"25의 ⟨3/5⟩","correct":true},{"t":"15의 ⟨3/5⟩","mis":"M3-2-u4-X04"},{"t":"두 수가 같아요","mis":"M3-2-u4-X22"},{"t":"알 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["25의 ⟨3/5⟩ = 15예요.","15의 ⟨3/5⟩ = 9예요.","15 > 9 — 25의 ⟨3/5⟩이 더 커요."],"asset":null},{"stem":"20의 ⟨2/5⟩와 18의 ⟨2/6⟩ 중 더 큰 것은 무엇인가요?","options":[{"t":"20의 ⟨2/5⟩","correct":true},{"t":"18의 ⟨2/6⟩","mis":"M3-2-u4-X04"},{"t":"두 수가 같아요","mis":"M3-2-u4-X22"},{"t":"알 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["20의 ⟨2/5⟩ = 8이에요.","18의 ⟨2/6⟩ = 6이에요.","8 > 6 — 20의 ⟨2/5⟩가 더 커요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L03_challenge#7','math',3,2,'u4','L03','g3_2_math_u4_L03_challenge','lesson_challenge','M3-2-u4-C3',3,'ox','auto','채원이 「12의 ⟨3/4⟩은 9야.」라고 했어요. 바르게 말했어요.',ARRAY['M3-2-u4-X04']::text[],true,'{"seq":7,"concept":"M3-2-u4-C3","difficulty":3,"kind":"ox","stem":"채원이 「12의 ⟨3/4⟩은 9야.」라고 했어요. 바르게 말했어요.","answer":"O","reason_options":[{"t":"4묶음으로 나눈 것 중 3묶음이 9이라서","correct":true},{"t":"분자가 3이라서","mis":"M3-2-u4-X04"}],"mis":"M3-2-u4-X04","explanation":["12를 분모만큼 똑같이 4묶음으로 나누면 한 묶음에 3개예요 — 12의 ⟨1/4⟩은 3.","⟨3/4⟩은 ⟨1/4⟩이 3개 — 3묶음이에요.","12의 ⟨3/4⟩은 3 × 3 = 9 — 분자만 보고 답하지 않아요."],"variant_rule":{"alt":[{"stem":"채원이 「30의 ⟨5/6⟩는 5야.」라고 했어요. 바르게 말했어요.","answer":"X","reason_options":[{"t":"6묶음으로 나눈 것 중 5묶음은 25이라서","correct":true},{"t":"6묶음으로 나눈 한 묶음이 5이라서","mis":"M3-2-u4-X05"}],"explanation":["30을 분모만큼 똑같이 6묶음으로 나누면 한 묶음에 5개예요 — 30의 ⟨1/6⟩은 5.","⟨5/6⟩는 ⟨1/6⟩이 5개 — 5묶음이에요.","30의 ⟨5/6⟩는 5 × 5 = 25 — 분자만 보고 답하지 않아요."],"asset":null},{"stem":"건우가 「25의 ⟨4/5⟩는 4야.」라고 했어요. 바르게 말했어요.","answer":"X","reason_options":[{"t":"5묶음으로 나눈 것 중 4묶음은 20이라서","correct":true},{"t":"분자가 4이라서","mis":"M3-2-u4-X04"}],"explanation":["25를 분모만큼 똑같이 5묶음으로 나누면 한 묶음에 5개예요 — 25의 ⟨1/5⟩은 5.","⟨4/5⟩는 ⟨1/5⟩이 4개 — 4묶음이에요.","25의 ⟨4/5⟩는 5 × 4 = 20 — 분자만 보고 답하지 않아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L03_challenge#8','math',3,2,'u4','L03','g3_2_math_u4_L03_challenge','lesson_challenge','M3-2-u4-C3',4,'essay','teacher','사탕 12개의 ⟨3/4⟩을 건우는 「3개」라고 답했어요. 건우의 답이 맞는지 판단하고, 12의 ⟨3/4⟩을 구하는 방법을 묶음으로 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-2-u4-C3","difficulty":4,"kind":"essay","stem":"사탕 12개의 ⟨3/4⟩을 건우는 「3개」라고 답했어요. 건우의 답이 맞는지 판단하고, 12의 ⟨3/4⟩을 구하는 방법을 묶음으로 설명해 보세요.","answer_guide":{"answer":"예: 틀렸다. 12를 분모 4만큼 똑같이 4묶음으로 나누면 한 묶음에 3개이고, 12의 ⟨1/4⟩은 3이다. ⟨3/4⟩은 그런 묶음 3개이므로 3 × 3 = 9개이다. 건우는 분자만 보고 답했다.","scoring_points":["틀렸다고 판단했는가","4묶음으로 나누어 한 묶음이 3개라고 썼는가","9개라고 바르게 구했는가"]},"explanation":["12 ÷ 4 = 3 — 한 묶음 3개.","3묶음 = 9개.","분자만 보고 답하지 않아요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[2,0],[3,0],[3,1],[2,1]],"hi":true},{"p":[[3.7,0],[4.7,0],[4.7,1],[3.7,1]],"hi":true},{"p":[[4.7,0],[5.7,0],[5.7,1],[4.7,1]],"hi":true},{"p":[[5.7,0],[6.7,0],[6.7,1],[5.7,1]],"hi":true},{"p":[[7.4,0],[8.4,0],[8.4,1],[7.4,1]],"hi":true},{"p":[[8.4,0],[9.4,0],[9.4,1],[8.4,1]],"hi":true},{"p":[[9.4,0],[10.4,0],[10.4,1],[9.4,1]],"hi":true},{"p":[[11.1,0],[12.1,0],[12.1,1],[11.1,1]]},{"p":[[12.1,0],[13.1,0],[13.1,1],[12.1,1]]},{"p":[[13.1,0],[14.1,0],[14.1,1],[13.1,1]]}],"u":21}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L03_challenge#9','math',3,2,'u4','L03','g3_2_math_u4_L03_challenge','lesson_challenge','M3-2-u4-C3',4,'essay','teacher','과자 10개 중 서윤이는 ⟨1/2⟩을, 건우는 ⟨4/10⟩를 먹었어요. 누가 더 많이 먹었는지 개수를 구해 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-2-u4-C3","difficulty":4,"kind":"essay","stem":"과자 10개 중 서윤이는 ⟨1/2⟩을, 건우는 ⟨4/10⟩를 먹었어요. 누가 더 많이 먹었는지 개수를 구해 설명해 보세요.","answer_guide":{"answer":"예: 10의 ⟨1/2⟩은 10을 2묶음으로 나눈 것 중 1묶음이라 5개이다. 10의 ⟨4/10⟩는 10을 10묶음으로 나눈 것 중 4묶음이라 4개이다. 5개가 4개보다 많으므로 서윤이가 더 많이 먹었다.","scoring_points":["서윤이 5개를 구했는가","건우 4개를 구했는가","서윤이가 더 많이 먹었다고 답했는가"]},"explanation":["10의 ⟨1/2⟩ = 5.","10의 ⟨4/10⟩ = 4.","서윤이가 더 많이 먹었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L03_challenge#10','math',3,2,'u4','L03','g3_2_math_u4_L03_challenge','lesson_challenge','M3-2-u4-C3',4,'sa','auto','어떤 수의 ⟨4/5⟩가 28이에요. 어떤 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M3-2-u4-C3","difficulty":4,"kind":"sa","stem":"어떤 수의 ⟨4/5⟩가 28이에요. 어떤 수는 얼마인가요? 숫자로 쓰세요.","answer":["35"],"explanation":["⟨4/5⟩는 ⟨1/5⟩이 4개예요.","⟨1/5⟩만큼은 28 ÷ 4 = 7이에요.","전체는 5묶음 — 7 × 5 = 35."],"variant_rule":{"alt":[{"stem":"어떤 수의 ⟨4/6⟩가 28이에요. 어떤 수는 얼마인가요? 숫자로 쓰세요.","answer":["42"],"explanation":["⟨4/6⟩는 ⟨1/6⟩이 4개예요.","⟨1/6⟩만큼은 28 ÷ 4 = 7이에요.","전체는 6묶음 — 7 × 6 = 42."],"asset":null},{"stem":"어떤 수의 ⟨5/7⟩가 40이에요. 어떤 수는 얼마인가요? 숫자로 쓰세요.","answer":["56"],"explanation":["⟨5/7⟩는 ⟨1/7⟩이 5개예요.","⟨1/7⟩만큼은 40 ÷ 5 = 8이에요.","전체는 7묶음 — 8 × 7 = 56."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L04_basic#1','math',3,2,'u4','L04','g3_2_math_u4_L04_basic','lesson_basic','M3-2-u4-C4',1,'sa','auto','색 테이프 8 m의 ⟨1/2⟩은 몇 m인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M3-2-u4-C4","difficulty":1,"kind":"sa","stem":"색 테이프 8 m의 ⟨1/2⟩은 몇 m인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["8 m를 분모만큼 똑같이 2부분으로 나누면 한 부분이 4 m예요.","⟨1/2⟩은 한 부분이에요.","8 m의 ⟨1/2⟩은 4 m — 나눈 부분의 길이는 모두 같아야 해요."],"asset":{"type":"fbar","bars":[{"den":2,"num":1,"grp":1,"label":"색 테이프 8 m"}]},"variant_rule":{"alt":[{"stem":"리본 16 m의 ⟨2/4⟩는 몇 m인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["16 m를 분모만큼 똑같이 4부분으로 나누면 한 부분이 4 m예요.","⟨2/4⟩는 그런 부분 2개예요.","16 m의 ⟨2/4⟩는 8 m — 나눈 부분의 길이는 모두 같아야 해요."],"asset":{"type":"fbar","bars":[{"den":4,"num":2,"grp":1,"label":"리본 16 m"}]}},{"stem":"끈 15 m의 ⟨1/3⟩은 몇 m인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["15 m를 분모만큼 똑같이 3부분으로 나누면 한 부분이 5 m예요.","⟨1/3⟩은 한 부분이에요.","15 m의 ⟨1/3⟩은 5 m — 나눈 부분의 길이는 모두 같아야 해요."],"asset":{"type":"fbar","bars":[{"den":3,"num":1,"grp":1,"label":"끈 15 m"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L04_basic#2','math',3,2,'u4','L04','g3_2_math_u4_L04_basic','lesson_basic','M3-2-u4-C4',1,'sa','auto','철사 10 cm의 ⟨2/5⟩는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u4-C4","difficulty":1,"kind":"sa","stem":"철사 10 cm의 ⟨2/5⟩는 몇 cm인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["10 cm를 분모만큼 똑같이 5부분으로 나누면 한 부분이 2 cm예요.","⟨2/5⟩는 그런 부분 2개예요.","10 cm의 ⟨2/5⟩는 4 cm — 나눈 부분의 길이는 모두 같아야 해요."],"asset":{"type":"fbar","bars":[{"den":5,"num":2,"grp":1,"label":"철사 10 cm"}]},"variant_rule":{"alt":[{"stem":"색 테이프 6 cm의 ⟨1/2⟩은 몇 cm인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["6 cm를 분모만큼 똑같이 2부분으로 나누면 한 부분이 3 cm예요.","⟨1/2⟩은 한 부분이에요.","6 cm의 ⟨1/2⟩은 3 cm — 나눈 부분의 길이는 모두 같아야 해요."],"asset":{"type":"fbar","bars":[{"den":2,"num":1,"grp":1,"label":"색 테이프 6 cm"}]}},{"stem":"리본 15 m의 ⟨3/5⟩은 몇 m인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["15 m를 분모만큼 똑같이 5부분으로 나누면 한 부분이 3 m예요.","⟨3/5⟩은 그런 부분 3개예요.","15 m의 ⟨3/5⟩은 9 m — 나눈 부분의 길이는 모두 같아야 해요."],"asset":{"type":"fbar","bars":[{"den":5,"num":3,"grp":1,"label":"리본 15 m"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L04_basic#3','math',3,2,'u4','L04','g3_2_math_u4_L04_basic','lesson_basic','M3-2-u4-C4',1,'sa','auto','준우가 하루의 ⟨6/24⟩ 동안 학교에 있는 시간은 몇 시간인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-2-u4-C4","difficulty":1,"kind":"sa","stem":"준우가 하루의 ⟨6/24⟩ 동안 학교에 있는 시간은 몇 시간인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["하루는 24시간이에요.","24를 똑같이 24부분으로 나누면 한 부분이 1시간이에요.","하루의 ⟨6/24⟩은 1 × 6 = 6시간."],"variant_rule":{"alt":[{"stem":"지훈이 하루의 ⟨2/6⟩ 동안 잠을 잔 시간은 몇 시간인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["하루는 24시간이에요.","24를 똑같이 6부분으로 나누면 한 부분이 4시간이에요.","하루의 ⟨2/6⟩는 4 × 2 = 8시간."],"asset":null},{"stem":"채원이 하루의 ⟨3/24⟩ 동안 책을 읽은 시간은 몇 시간인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["하루는 24시간이에요.","24를 똑같이 24부분으로 나누면 한 부분이 1시간이에요.","하루의 ⟨3/24⟩은 1 × 3 = 3시간."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L04_basic#4','math',3,2,'u4','L04','g3_2_math_u4_L04_basic','lesson_basic','M3-2-u4-C4',1,'sa','auto','1시간의 ⟨1/4⟩은 몇 분인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-2-u4-C4","difficulty":1,"kind":"sa","stem":"1시간의 ⟨1/4⟩은 몇 분인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["1시간은 60분이에요.","60을 똑같이 4부분으로 나누면 한 부분이 15분이에요.","1시간의 ⟨1/4⟩은 15 × 1 = 15분."],"variant_rule":{"alt":[{"stem":"1시간의 ⟨1/2⟩은 몇 분인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["1시간은 60분이에요.","60을 똑같이 2부분으로 나누면 한 부분이 30분이에요.","1시간의 ⟨1/2⟩은 30 × 1 = 30분."],"asset":null},{"stem":"1시간의 ⟨3/5⟩은 몇 분인가요? 숫자로 쓰세요.","answer":["36"],"explanation":["1시간은 60분이에요.","60을 똑같이 5부분으로 나누면 한 부분이 12분이에요.","1시간의 ⟨3/5⟩은 12 × 3 = 36분."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L04_basic#5','math',3,2,'u4','L04','g3_2_math_u4_L04_basic','lesson_basic','M3-2-u4-C4',2,'mc','auto','80 cm의 ⟨3/4⟩을 구하는 방법으로 알맞은 것은 무엇인가요?',ARRAY['M3-2-u4-X06','M3-2-u4-X04']::text[],true,'{"seq":5,"concept":"M3-2-u4-C4","difficulty":2,"kind":"mc","stem":"80 cm의 ⟨3/4⟩을 구하는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"80 cm를 똑같이 4부분으로 나눈 것 중 3부분","correct":true},{"t":"80 cm를 똑같이 3부분으로 나눈 것 중 4부분","mis":"M3-2-u4-X06"},{"t":"80에서 3을 뺀다","mis":"M3-2-u4-X04"},{"t":"80을 3으로 나눈다","mis":"M3-2-u4-X06"}],"explanation":["분모 4 — 4부분으로 똑같이 나눠요.","분자 3 — 그중 3부분을 모아요.","80 cm의 ⟨3/4⟩은 60 cm."],"variant_rule":{"alt":[{"stem":"50 cm의 ⟨1/2⟩을 구하는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"50 cm를 똑같이 2부분으로 나눈 것 중 1부분","correct":true},{"t":"50 cm를 똑같이 1부분으로 나눈 것 중 2부분","mis":"M3-2-u4-X06"},{"t":"50에서 1을 뺀다","mis":"M3-2-u4-X04"},{"t":"50을 1로 나눈다","mis":"M3-2-u4-X06"}],"explanation":["분모 2 — 2부분으로 똑같이 나눠요.","분자 1 — 그중 1부분을 모아요.","50 cm의 ⟨1/2⟩은 25 cm."],"asset":null},{"stem":"18 cm의 ⟨1/3⟩을 구하는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"18 cm를 똑같이 3부분으로 나눈 것 중 1부분","correct":true},{"t":"18 cm를 똑같이 1부분으로 나눈 것 중 3부분","mis":"M3-2-u4-X06"},{"t":"18에서 1을 뺀다","mis":"M3-2-u4-X04"},{"t":"18을 1로 나눈다","mis":"M3-2-u4-X06"}],"explanation":["분모 3 — 3부분으로 똑같이 나눠요.","분자 1 — 그중 1부분을 모아요.","18 cm의 ⟨1/3⟩은 6 cm."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L04_basic#6','math',3,2,'u4','L04','g3_2_math_u4_L04_basic','lesson_basic','M3-2-u4-C4',2,'mc','auto','50 cm의 ⟨1/2⟩은 몇 cm인가요?',ARRAY['M3-2-u4-X04','M3-2-u4-X21']::text[],true,'{"seq":6,"concept":"M3-2-u4-C4","difficulty":2,"kind":"mc","stem":"50 cm의 ⟨1/2⟩은 몇 cm인가요?","options":[{"t":"25 cm","correct":true},{"t":"1 cm","mis":"M3-2-u4-X04"},{"t":"50 cm","mis":"M3-2-u4-X21"},{"t":"49 cm","mis":"M3-2-u4-X04"}],"explanation":["50 cm를 분모만큼 똑같이 2부분으로 나누면 한 부분이 25 cm예요.","⟨1/2⟩은 한 부분이에요.","50 cm의 ⟨1/2⟩은 25 cm — 나눈 부분의 길이는 모두 같아야 해요."],"variant_rule":{"alt":[{"stem":"36 m의 ⟨4/6⟩는 몇 m인가요?","options":[{"t":"24 m","correct":true},{"t":"4 m","mis":"M3-2-u4-X04"},{"t":"6 m","mis":"M3-2-u4-X05"},{"t":"54 m","mis":"M3-2-u4-X06"}],"explanation":["36 m를 분모만큼 똑같이 6부분으로 나누면 한 부분이 6 m예요.","⟨4/6⟩는 그런 부분 4개예요.","36 m의 ⟨4/6⟩는 24 m — 나눈 부분의 길이는 모두 같아야 해요."],"asset":null},{"stem":"8 m의 ⟨1/2⟩은 몇 m인가요?","options":[{"t":"4 m","correct":true},{"t":"1 m","mis":"M3-2-u4-X04"},{"t":"8 m","mis":"M3-2-u4-X21"},{"t":"7 m","mis":"M3-2-u4-X04"}],"explanation":["8 m를 분모만큼 똑같이 2부분으로 나누면 한 부분이 4 m예요.","⟨1/2⟩은 한 부분이에요.","8 m의 ⟨1/2⟩은 4 m — 나눈 부분의 길이는 모두 같아야 해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L04_basic#7','math',3,2,'u4','L04','g3_2_math_u4_L04_basic','lesson_basic','M3-2-u4-C4',2,'sa','auto','400 m 중 ⟨1/2⟩은 걷고 ⟨1/4⟩은 달렸어요. 모두 몇 m를 갔나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M3-2-u4-C4","difficulty":2,"kind":"sa","stem":"400 m 중 ⟨1/2⟩은 걷고 ⟨1/4⟩은 달렸어요. 모두 몇 m를 갔나요? 숫자로 쓰세요.","answer":["300"],"explanation":["400 m의 ⟨1/2⟩은 200 m예요.","400 m의 ⟨1/4⟩은 100 m예요.","모두 200 + 100 = 300 m."],"variant_rule":{"alt":[{"stem":"200 m 중 ⟨2/5⟩는 걷고 ⟨2/10⟩는 달렸어요. 모두 몇 m를 갔나요? 숫자로 쓰세요.","answer":["120"],"explanation":["200 m의 ⟨2/5⟩는 80 m예요.","200 m의 ⟨2/10⟩는 40 m예요.","모두 80 + 40 = 120 m."],"asset":null},{"stem":"600 m 중 ⟨3/5⟩은 걷고 ⟨1/3⟩은 달렸어요. 모두 몇 m를 갔나요? 숫자로 쓰세요.","answer":["560"],"explanation":["600 m의 ⟨3/5⟩은 360 m예요.","600 m의 ⟨1/3⟩은 200 m예요.","모두 360 + 200 = 560 m."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L04_basic#8','math',3,2,'u4','L04','g3_2_math_u4_L04_basic','lesson_basic','M3-2-u4-C4',2,'sa','auto','리본 6 cm 중 ⟨1/2⟩을 썼어요. 남은 리본은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M3-2-u4-C4","difficulty":2,"kind":"sa","stem":"리본 6 cm 중 ⟨1/2⟩을 썼어요. 남은 리본은 몇 cm인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["6 cm의 ⟨1/2⟩은 3 cm예요.","쓴 길이는 ⟨1/2⟩ — 3 cm.","남은 길이 6 − 3 = 3 cm — 남은 부분 ⟨1/2⟩과 같아요."],"variant_rule":{"alt":[{"stem":"끈 150 cm 중 ⟨2/5⟩를 썼어요. 남은 끈은 몇 cm인가요? 숫자로 쓰세요.","answer":["90"],"explanation":["150 cm의 ⟨1/5⟩은 30 cm예요.","쓴 길이는 ⟨2/5⟩ — 60 cm.","남은 길이 150 − 60 = 90 cm — 남은 부분 ⟨3/5⟩과 같아요."],"asset":null},{"stem":"색 테이프 70 cm 중 ⟨1/2⟩을 썼어요. 남은 색 테이프는 몇 cm인가요? 숫자로 쓰세요.","answer":["35"],"explanation":["70 cm의 ⟨1/2⟩은 35 cm예요.","쓴 길이는 ⟨1/2⟩ — 35 cm.","남은 길이 70 − 35 = 35 cm — 남은 부분 ⟨1/2⟩과 같아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L04_basic#9','math',3,2,'u4','L04','g3_2_math_u4_L04_basic','lesson_basic','M3-2-u4-C4',2,'mc','auto','1시간의 ⟨1/2⟩은 몇 분인가요?',ARRAY['M3-2-u4-X04','M3-2-u4-X06','M3-2-u4-X21']::text[],true,'{"seq":9,"concept":"M3-2-u4-C4","difficulty":2,"kind":"mc","stem":"1시간의 ⟨1/2⟩은 몇 분인가요?","options":[{"t":"30분","correct":true},{"t":"1분","mis":"M3-2-u4-X04"},{"t":"50분","mis":"M3-2-u4-X06"},{"t":"60분","mis":"M3-2-u4-X21"}],"explanation":["1시간은 60분이에요.","60을 똑같이 2부분으로 나누면 한 부분이 30분이에요.","1시간의 ⟨1/2⟩은 30 × 1 = 30분."],"variant_rule":{"alt":[{"stem":"1시간의 ⟨1/4⟩은 몇 분인가요?","options":[{"t":"15분","correct":true},{"t":"1분","mis":"M3-2-u4-X04"},{"t":"25분","mis":"M3-2-u4-X06"},{"t":"45분","mis":"M3-2-u4-X20"}],"explanation":["1시간은 60분이에요.","60을 똑같이 4부분으로 나누면 한 부분이 15분이에요.","1시간의 ⟨1/4⟩은 15 × 1 = 15분."],"asset":null},{"stem":"1시간의 ⟨2/4⟩는 몇 분인가요?","options":[{"t":"30분","correct":true},{"t":"2분","mis":"M3-2-u4-X04"},{"t":"15분","mis":"M3-2-u4-X05"},{"t":"50분","mis":"M3-2-u4-X06"}],"explanation":["1시간은 60분이에요.","60을 똑같이 4부분으로 나누면 한 부분이 15분이에요.","1시간의 ⟨2/4⟩는 15 × 2 = 30분."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L04_basic#10','math',3,2,'u4','L04','g3_2_math_u4_L04_basic','lesson_basic','M3-2-u4-C4',3,'mc','auto','같은 30 m 끈에서 건우는 ⟨1/3⟩을, 하윤은 ⟨3/6⟩을 잘랐어요. 누가 더 길게 잘랐나요?',ARRAY['M3-2-u4-X04','M3-2-u4-X22']::text[],true,'{"seq":10,"concept":"M3-2-u4-C4","difficulty":3,"kind":"mc","stem":"같은 30 m 끈에서 건우는 ⟨1/3⟩을, 하윤은 ⟨3/6⟩을 잘랐어요. 누가 더 길게 잘랐나요?","options":[{"t":"하윤","correct":true},{"t":"건우","mis":"M3-2-u4-X04"},{"t":"두 사람이 같아요","mis":"M3-2-u4-X22"},{"t":"알 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["건우는 10 m를 잘랐어요.","하윤은 15 m를 잘랐어요.","하윤이 더 길게 잘랐어요."],"variant_rule":{"alt":[{"stem":"같은 12 m 끈에서 채원은 ⟨1/2⟩을, 건우는 ⟨1/6⟩을 잘랐어요. 누가 더 길게 잘랐나요?","options":[{"t":"채원","correct":true},{"t":"건우","mis":"M3-2-u4-X04"},{"t":"두 사람이 같아요","mis":"M3-2-u4-X22"},{"t":"알 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["채원은 6 m를 잘랐어요.","건우는 2 m를 잘랐어요.","채원이 더 길게 잘랐어요."],"asset":null},{"stem":"같은 36 cm 끈에서 지훈은 ⟨6/12⟩을, 서윤은 ⟨8/9⟩을 잘랐어요. 누가 더 길게 잘랐나요?","options":[{"t":"서윤","correct":true},{"t":"지훈","mis":"M3-2-u4-X04"},{"t":"두 사람이 같아요","mis":"M3-2-u4-X22"},{"t":"알 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["지훈은 18 cm를 잘랐어요.","서윤은 32 cm를 잘랐어요.","서윤이 더 길게 잘랐어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L04_challenge#1','math',3,2,'u4','L04','g3_2_math_u4_L04_challenge','lesson_challenge','M3-2-u4-C4',2,'mc','auto','12 m의 ⟨1/2⟩은 몇 m인가요?',ARRAY['M3-2-u4-X04','M3-2-u4-X21']::text[],true,'{"seq":1,"concept":"M3-2-u4-C4","difficulty":2,"kind":"mc","stem":"12 m의 ⟨1/2⟩은 몇 m인가요?","options":[{"t":"6 m","correct":true},{"t":"1 m","mis":"M3-2-u4-X04"},{"t":"12 m","mis":"M3-2-u4-X21"},{"t":"11 m","mis":"M3-2-u4-X04"}],"explanation":["12 m를 분모만큼 똑같이 2부분으로 나누면 한 부분이 6 m예요.","⟨1/2⟩은 한 부분이에요.","12 m의 ⟨1/2⟩은 6 m — 나눈 부분의 길이는 모두 같아야 해요."],"variant_rule":{"alt":[{"stem":"16 m의 ⟨6/8⟩은 몇 m인가요?","options":[{"t":"12 m","correct":true},{"t":"6 m","mis":"M3-2-u4-X04"},{"t":"2 m","mis":"M3-2-u4-X05"},{"t":"4 m","mis":"M3-2-u4-X20"}],"explanation":["16 m를 분모만큼 똑같이 8부분으로 나누면 한 부분이 2 m예요.","⟨6/8⟩은 그런 부분 6개예요.","16 m의 ⟨6/8⟩은 12 m — 나눈 부분의 길이는 모두 같아야 해요."],"asset":null},{"stem":"8 m의 ⟨1/2⟩은 몇 m인가요?","options":[{"t":"4 m","correct":true},{"t":"1 m","mis":"M3-2-u4-X04"},{"t":"8 m","mis":"M3-2-u4-X21"},{"t":"7 m","mis":"M3-2-u4-X04"}],"explanation":["8 m를 분모만큼 똑같이 2부분으로 나누면 한 부분이 4 m예요.","⟨1/2⟩은 한 부분이에요.","8 m의 ⟨1/2⟩은 4 m — 나눈 부분의 길이는 모두 같아야 해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L04_challenge#2','math',3,2,'u4','L04','g3_2_math_u4_L04_challenge','lesson_challenge','M3-2-u4-C4',2,'ox','auto','서준이 「48 cm의 ⟨2/6⟩를 구하려면 48 cm를 똑같이 2부분으로 나누어야 해.」라고 했어요. 바르게 말했어요.',ARRAY['M3-2-u4-X06']::text[],true,'{"seq":2,"concept":"M3-2-u4-C4","difficulty":2,"kind":"ox","stem":"서준이 「48 cm의 ⟨2/6⟩를 구하려면 48 cm를 똑같이 2부분으로 나누어야 해.」라고 했어요. 바르게 말했어요.","answer":"X","reason_options":[{"t":"분모 6만큼 6부분으로 나누어야 해서","correct":true},{"t":"분자가 2이라서","mis":"M3-2-u4-X06"}],"mis":"M3-2-u4-X06","explanation":["48 cm를 분모만큼 똑같이 6부분으로 나누면 한 부분이 8 cm예요.","⟨2/6⟩는 그런 부분 2개예요.","48 cm의 ⟨2/6⟩는 16 cm — 나눈 부분의 길이는 모두 같아야 해요."],"variant_rule":{"alt":[{"stem":"채원이 「36 m의 ⟨2/4⟩를 구하려면 36 m를 똑같이 2부분으로 나누어야 해.」라고 했어요. 바르게 말했어요.","answer":"X","reason_options":[{"t":"분모 4만큼 4부분으로 나누어야 해서","correct":true},{"t":"분자가 2이라서","mis":"M3-2-u4-X06"}],"explanation":["36 m를 분모만큼 똑같이 4부분으로 나누면 한 부분이 9 m예요.","⟨2/4⟩는 그런 부분 2개예요.","36 m의 ⟨2/4⟩는 18 m — 나눈 부분의 길이는 모두 같아야 해요."],"asset":null},{"stem":"도연이 「12 m의 ⟨2/6⟩를 구하려면 12 m를 똑같이 2부분으로 나누어야 해.」라고 했어요. 바르게 말했어요.","answer":"X","reason_options":[{"t":"분모 6만큼 6부분으로 나누어야 해서","correct":true},{"t":"분자가 2이라서","mis":"M3-2-u4-X06"}],"explanation":["12 m를 분모만큼 똑같이 6부분으로 나누면 한 부분이 2 m예요.","⟨2/6⟩는 그런 부분 2개예요.","12 m의 ⟨2/6⟩는 4 m — 나눈 부분의 길이는 모두 같아야 해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L04_challenge#3','math',3,2,'u4','L04','g3_2_math_u4_L04_challenge','lesson_challenge','M3-2-u4-C4',3,'sa','auto','200 m 중 ⟨1/2⟩은 걷고 ⟨1/4⟩은 달렸어요. 모두 몇 m를 갔나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-2-u4-C4","difficulty":3,"kind":"sa","stem":"200 m 중 ⟨1/2⟩은 걷고 ⟨1/4⟩은 달렸어요. 모두 몇 m를 갔나요? 숫자로 쓰세요.","answer":["150"],"explanation":["200 m의 ⟨1/2⟩은 100 m예요.","200 m의 ⟨1/4⟩은 50 m예요.","모두 100 + 50 = 150 m."],"variant_rule":{"alt":[{"stem":"200 m 중 ⟨1/5⟩은 걷고 ⟨3/10⟩은 달렸어요. 모두 몇 m를 갔나요? 숫자로 쓰세요.","answer":["100"],"explanation":["200 m의 ⟨1/5⟩은 40 m예요.","200 m의 ⟨3/10⟩은 60 m예요.","모두 40 + 60 = 100 m."],"asset":null},{"stem":"600 m 중 ⟨1/5⟩은 걷고 ⟨1/2⟩은 달렸어요. 모두 몇 m를 갔나요? 숫자로 쓰세요.","answer":["420"],"explanation":["600 m의 ⟨1/5⟩은 120 m예요.","600 m의 ⟨1/2⟩은 300 m예요.","모두 120 + 300 = 420 m."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L04_challenge#4','math',3,2,'u4','L04','g3_2_math_u4_L04_challenge','lesson_challenge','M3-2-u4-C4',3,'sa','auto','끈 전체의 ⟨3/5⟩이 12 cm예요. 끈 전체의 길이는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-2-u4-C4","difficulty":3,"kind":"sa","stem":"끈 전체의 ⟨3/5⟩이 12 cm예요. 끈 전체의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["⟨3/5⟩은 ⟨1/5⟩이 3개예요.","⟨1/5⟩만큼은 12 ÷ 3 = 4 cm.","전체는 5부분 — 4 × 5 = 20 cm."],"variant_rule":{"alt":[{"stem":"색 테이프 전체의 ⟨2/3⟩가 16 m예요. 색 테이프 전체의 길이는 몇 m인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["⟨2/3⟩는 ⟨1/3⟩이 2개예요.","⟨1/3⟩만큼은 16 ÷ 2 = 8 m.","전체는 3부분 — 8 × 3 = 24 m."],"asset":null},{"stem":"리본 전체의 ⟨5/8⟩가 45 cm예요. 리본 전체의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["72"],"explanation":["⟨5/8⟩는 ⟨1/8⟩이 5개예요.","⟨1/8⟩만큼은 45 ÷ 5 = 9 cm.","전체는 8부분 — 9 × 8 = 72 cm."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L04_challenge#5','math',3,2,'u4','L04','g3_2_math_u4_L04_challenge','lesson_challenge','M3-2-u4-C4',3,'mc','auto','같은 24 cm 끈에서 준우는 ⟨2/3⟩를, 서윤은 ⟨2/4⟩를 잘랐어요. 누가 더 길게 잘랐나요?',ARRAY['M3-2-u4-X04','M3-2-u4-X22']::text[],true,'{"seq":5,"concept":"M3-2-u4-C4","difficulty":3,"kind":"mc","stem":"같은 24 cm 끈에서 준우는 ⟨2/3⟩를, 서윤은 ⟨2/4⟩를 잘랐어요. 누가 더 길게 잘랐나요?","options":[{"t":"준우","correct":true},{"t":"서윤","mis":"M3-2-u4-X04"},{"t":"두 사람이 같아요","mis":"M3-2-u4-X22"},{"t":"알 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["준우는 16 cm를 잘랐어요.","서윤은 12 cm를 잘랐어요.","준우가 더 길게 잘랐어요."],"variant_rule":{"alt":[{"stem":"같은 36 m 끈에서 은비는 ⟨1/12⟩을, 민서는 ⟨2/3⟩를 잘랐어요. 누가 더 길게 잘랐나요?","options":[{"t":"민서","correct":true},{"t":"은비","mis":"M3-2-u4-X04"},{"t":"두 사람이 같아요","mis":"M3-2-u4-X22"},{"t":"알 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["은비는 3 m를 잘랐어요.","민서는 24 m를 잘랐어요.","민서가 더 길게 잘랐어요."],"asset":null},{"stem":"같은 36 cm 끈에서 도연은 ⟨6/9⟩을, 지훈은 ⟨2/6⟩를 잘랐어요. 누가 더 길게 잘랐나요?","options":[{"t":"도연","correct":true},{"t":"지훈","mis":"M3-2-u4-X04"},{"t":"두 사람이 같아요","mis":"M3-2-u4-X22"},{"t":"알 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["도연은 24 cm를 잘랐어요.","지훈은 12 cm를 잘랐어요.","도연이 더 길게 잘랐어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L04_challenge#6','math',3,2,'u4','L04','g3_2_math_u4_L04_challenge','lesson_challenge','M3-2-u4-C4',3,'sa','auto','도연이 하루의 ⟨7/8⟩ 동안 잠을 잔 시간은 몇 시간인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M3-2-u4-C4","difficulty":3,"kind":"sa","stem":"도연이 하루의 ⟨7/8⟩ 동안 잠을 잔 시간은 몇 시간인가요? 숫자로 쓰세요.","answer":["21"],"explanation":["하루는 24시간이에요.","24를 똑같이 8부분으로 나누면 한 부분이 3시간이에요.","하루의 ⟨7/8⟩은 3 × 7 = 21시간."],"variant_rule":{"alt":[{"stem":"도연이 하루의 ⟨4/8⟩ 동안 학교에 있는 시간은 몇 시간인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["하루는 24시간이에요.","24를 똑같이 8부분으로 나누면 한 부분이 3시간이에요.","하루의 ⟨4/8⟩는 3 × 4 = 12시간."],"asset":null},{"stem":"은비가 하루의 ⟨2/12⟩ 동안 놀이를 한 시간은 몇 시간인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["하루는 24시간이에요.","24를 똑같이 12부분으로 나누면 한 부분이 2시간이에요.","하루의 ⟨2/12⟩는 2 × 2 = 4시간."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L04_challenge#7','math',3,2,'u4','L04','g3_2_math_u4_L04_challenge','lesson_challenge','M3-2-u4-C4',3,'sa','auto','등산로 24 km 중 ⟨1/2⟩을 걸었어요. 남은 거리는 몇 km인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M3-2-u4-C4","difficulty":3,"kind":"sa","stem":"등산로 24 km 중 ⟨1/2⟩을 걸었어요. 남은 거리는 몇 km인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["24 km의 ⟨1/2⟩은 12 km예요.","쓴 길이는 ⟨1/2⟩ — 12 km.","남은 길이 24 − 12 = 12 km — 남은 부분 ⟨1/2⟩과 같아요."],"variant_rule":{"alt":[{"stem":"산책길 42 km 중 ⟨1/6⟩을 걸었어요. 남은 거리는 몇 km인가요? 숫자로 쓰세요.","answer":["35"],"explanation":["42 km의 ⟨1/6⟩은 7 km예요.","쓴 길이는 ⟨1/6⟩ — 7 km.","남은 길이 42 − 7 = 35 km — 남은 부분 ⟨5/6⟩와 같아요."],"asset":null},{"stem":"자전거 길 28 km 중 ⟨5/7⟩를 걸었어요. 남은 거리는 몇 km인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["28 km의 ⟨1/7⟩은 4 km예요.","쓴 길이는 ⟨5/7⟩ — 20 km.","남은 길이 28 − 20 = 8 km — 남은 부분 ⟨2/7⟩와 같아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L04_challenge#8','math',3,2,'u4','L04','g3_2_math_u4_L04_challenge','lesson_challenge','M3-2-u4-C4',4,'essay','teacher','채원이는 하루의 ⟨1/3⟩은 잠을 자고, ⟨6/24⟩은 학교에 있어요. 잠을 자는 시간과 학교에 있는 시간은 각각 몇 시간인지 구하고, 어느 쪽이 몇 시간 더 긴지 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-2-u4-C4","difficulty":4,"kind":"essay","stem":"채원이는 하루의 ⟨1/3⟩은 잠을 자고, ⟨6/24⟩은 학교에 있어요. 잠을 자는 시간과 학교에 있는 시간은 각각 몇 시간인지 구하고, 어느 쪽이 몇 시간 더 긴지 설명해 보세요.","answer_guide":{"answer":"예: 하루는 24시간이다. 24의 ⟨1/3⟩은 24를 3부분으로 나눈 것 중 1부분이라 8시간, 24의 ⟨6/24⟩은 24를 24부분으로 나눈 것 중 6부분이라 6시간이다. 잠을 자는 시간이 8 − 6 = 2시간 더 길다.","scoring_points":["8시간을 구했는가","6시간을 구했는가","잠자는 시간이 2시간 더 길다고 답했는가"]},"explanation":["24 ÷ 3 = 8시간.","24의 ⟨6/24⟩ = 6시간.","8 − 6 = 2시간 더 길어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L04_challenge#9','math',3,2,'u4','L04','g3_2_math_u4_L04_challenge','lesson_challenge','M3-2-u4-C4',4,'essay','teacher','80 cm의 ⟨3/4⟩을 구하는 방법을 띠 그림을 이용해 설명하고, 몇 cm인지 구해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-2-u4-C4","difficulty":4,"kind":"essay","stem":"80 cm의 ⟨3/4⟩을 구하는 방법을 띠 그림을 이용해 설명하고, 몇 cm인지 구해 보세요.","answer_guide":{"answer":"예: 80 cm 띠를 분모 4만큼 똑같은 길이 4부분으로 나누면 한 부분이 20 cm이다. ⟨3/4⟩은 그런 부분 3개이므로 20 × 3 = 60 cm이다. 나눈 부분의 길이는 모두 같아야 한다.","scoring_points":["똑같은 길이 4부분으로 나누었는가","한 부분 20 cm를 구했는가","60 cm라고 답했는가"]},"explanation":["80 ÷ 4 = 20 cm.","20 × 3 = 60 cm.","나눈 부분은 길이가 같아야 해요."],"asset":{"type":"fbar","bars":[{"den":4,"num":3,"grp":1,"label":"80 cm"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L04_challenge#10','math',3,2,'u4','L04','g3_2_math_u4_L04_challenge','lesson_challenge','M3-2-u4-C4',4,'sa','auto','리본 전체의 ⟨5/6⟩가 150 cm예요. 리본 전체의 길이는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M3-2-u4-C4","difficulty":4,"kind":"sa","stem":"리본 전체의 ⟨5/6⟩가 150 cm예요. 리본 전체의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["180"],"explanation":["⟨5/6⟩는 ⟨1/6⟩이 5개예요.","⟨1/6⟩만큼은 150 ÷ 5 = 30 cm.","전체는 6부분 — 30 × 6 = 180 cm."],"variant_rule":{"alt":[{"stem":"끈 전체의 ⟨1/3⟩이 5 m예요. 끈 전체의 길이는 몇 m인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["⟨1/3⟩이 5 m예요.","한 부분이 5 m예요.","전체는 3부분 — 5 × 3 = 15 m."],"asset":null},{"stem":"색 테이프 전체의 ⟨6/7⟩이 30 cm예요. 색 테이프 전체의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["35"],"explanation":["⟨6/7⟩은 ⟨1/7⟩이 6개예요.","⟨1/7⟩만큼은 30 ÷ 6 = 5 cm.","전체는 7부분 — 5 × 7 = 35 cm."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L05_basic#1','math',3,2,'u4','L05','g3_2_math_u4_L05_basic','lesson_basic','M3-2-u4-C5',1,'mc','auto','건우는 책갈피 1개를 만드는 데 색 도화지 ⟨1/2⟩ 장가 필요해요. 책갈피 3개를 만들려면 색 도화지가 모두 몇 장 필요한가요?',ARRAY['M3-2-u4-X03','M3-2-u4-X07']::text[],true,'{"seq":1,"concept":"M3-2-u4-C5","difficulty":1,"kind":"mc","stem":"건우는 책갈피 1개를 만드는 데 색 도화지 ⟨1/2⟩ 장가 필요해요. 책갈피 3개를 만들려면 색 도화지가 모두 몇 장 필요한가요?","options":[{"t":"⟨3/2⟩","correct":true},{"t":"⟨2/3⟩","mis":"M3-2-u4-X03"},{"t":"⟨1/6⟩","mis":"M3-2-u4-X07"},{"t":"⟨1/5⟩","mis":"M3-2-u4-X07"}],"explanation":["⟨1/2⟩이 3개 모이면 분자가 3 — 분모 2는 그대로예요.","그래서 ⟨3/2⟩개 필요해요.","분자 3이 분모 2보다 커서 — 가분수예요."],"variant_rule":{"alt":[{"stem":"건우는 바람개비 1개를 만드는 데 수수깡 ⟨1/3⟩ 개가 필요해요. 바람개비 5개를 만들려면 수수깡이 모두 몇 개 필요한가요?","options":[{"t":"⟨5/3⟩","correct":true},{"t":"⟨3/5⟩","mis":"M3-2-u4-X03"},{"t":"⟨1/15⟩","mis":"M3-2-u4-X07"},{"t":"⟨1/8⟩","mis":"M3-2-u4-X07"}],"explanation":["⟨1/3⟩이 5개 모이면 분자가 5 — 분모 3은 그대로예요.","그래서 ⟨5/3⟩개 필요해요.","분자 5가 분모 3보다 커서 — 가분수예요."],"asset":null},{"stem":"채원은 리본 꽃 1개를 만드는 데 색 테이프 ⟨1/3⟩ m가 필요해요. 리본 꽃 6개를 만들려면 색 테이프가 모두 몇 m 필요한가요?","options":[{"t":"⟨6/3⟩","correct":true},{"t":"⟨3/6⟩","mis":"M3-2-u4-X03"},{"t":"⟨1/18⟩","mis":"M3-2-u4-X07"},{"t":"⟨1/9⟩","mis":"M3-2-u4-X07"}],"explanation":["⟨1/3⟩이 6개 모이면 분자가 6 — 분모 3은 그대로예요.","그래서 ⟨6/3⟩개 필요해요.","분자 6이 분모 3보다 커서 — 가분수예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L05_basic#2','math',3,2,'u4','L05','g3_2_math_u4_L05_basic','lesson_basic','M3-2-u4-C6',1,'sa','auto','1을 분모가 6인 분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u4-C6","difficulty":1,"kind":"sa","stem":"1을 분모가 6인 분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["⟨1/6⟩이 6개면 1이에요 — 1 = ⟨6/6⟩.","그래서 1 = ⟨6/6⟩.","1 = ⟨6/6⟩ — 분자는 6."],"variant_rule":{"alt":[{"stem":"1을 분모가 7인 분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["⟨1/7⟩이 7개면 1이에요 — 1 = ⟨7/7⟩.","그래서 1 = ⟨7/7⟩.","1 = ⟨7/7⟩ — 분자는 7."],"asset":null},{"stem":"1을 분모가 9인 분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["⟨1/9⟩이 9개면 1이에요 — 1 = ⟨9/9⟩.","그래서 1 = ⟨9/9⟩.","1 = ⟨9/9⟩ — 분자는 9."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L05_basic#3','math',3,2,'u4','L05','g3_2_math_u4_L05_basic','lesson_basic','M3-2-u4-C5',1,'mc','auto','분수 ⟨5/5⟩는 무엇인가요?',ARRAY['M3-2-u4-X08','M3-2-u4-X09']::text[],true,'{"seq":3,"concept":"M3-2-u4-C5","difficulty":1,"kind":"mc","stem":"분수 ⟨5/5⟩는 무엇인가요?","options":[{"t":"가분수","correct":true},{"t":"진분수","mis":"M3-2-u4-X08"},{"t":"대분수","mis":"M3-2-u4-X08"},{"t":"자연수","mis":"M3-2-u4-X09"}],"explanation":["분자 5, 분모 5를 견주어요.","분자가 분모보다 같아요.","⟨5/5⟩는 가분수 — 분자가 분모와 같거나 큰 분수."],"variant_rule":{"alt":[{"stem":"분수 ⟨6/5⟩은 무엇인가요?","options":[{"t":"가분수","correct":true},{"t":"진분수","mis":"M3-2-u4-X08"},{"t":"대분수","mis":"M3-2-u4-X08"},{"t":"자연수","mis":"M3-2-u4-X08"}],"explanation":["분자 6, 분모 5를 견주어요.","분자가 분모보다 커요.","⟨6/5⟩은 가분수 — 분자가 분모와 같거나 큰 분수."],"asset":null},{"stem":"분수 ⟨2/6⟩는 무엇인가요?","options":[{"t":"진분수","correct":true},{"t":"가분수","mis":"M3-2-u4-X08"},{"t":"대분수","mis":"M3-2-u4-X08"},{"t":"자연수","mis":"M3-2-u4-X08"}],"explanation":["분자 2, 분모 6을 견주어요.","분자가 분모보다 작아요.","⟨2/6⟩는 진분수 — 분자가 분모보다 작은 분수."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L05_basic#4','math',3,2,'u4','L05','g3_2_math_u4_L05_basic','lesson_basic','M3-2-u4-C5',1,'mc','auto','가분수를 바르게 설명한 것은 무엇인가요?',ARRAY['M3-2-u4-X08']::text[],true,'{"seq":4,"concept":"M3-2-u4-C5","difficulty":1,"kind":"mc","stem":"가분수를 바르게 설명한 것은 무엇인가요?","options":[{"t":"분자가 분모와 같거나 분모보다 큰 분수","correct":true},{"t":"분자가 분모보다 작은 분수","mis":"M3-2-u4-X08"},{"t":"분자가 1인 분수","mis":"M3-2-u4-X08"},{"t":"자연수와 진분수로 이루어진 분수","mis":"M3-2-u4-X08"}],"explanation":["분자가 분모보다 작으면 진분수예요.","분자가 분모와 같거나 크면 가분수예요.","분자가 1이면 단위분수, 자연수와 진분수면 대분수예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 가분수를 바르게 설명한 것은 무엇인가요?","options":[{"t":"⟨4/4⟩, ⟨7/4⟩처럼 분자가 분모와 같거나 큰 분수","correct":true},{"t":"분자가 분모보다 작은 분수","mis":"M3-2-u4-X08"},{"t":"분자가 1인 분수","mis":"M3-2-u4-X08"},{"t":"자연수와 진분수로 이루어진 분수","mis":"M3-2-u4-X08"}],"explanation":["분자가 분모보다 작으면 진분수예요.","분자가 분모와 같거나 크면 가분수예요.","분자가 1이면 단위분수, 자연수와 진분수면 대분수예요."],"asset":null},{"stem":"이번에는 다른 문제예요. 가분수를 바르게 설명한 것은 무엇인가요?","options":[{"t":"분자가 분모보다 작지 않은 분수","correct":true},{"t":"분자가 분모보다 작은 분수","mis":"M3-2-u4-X08"},{"t":"분자가 1인 분수","mis":"M3-2-u4-X08"},{"t":"자연수와 진분수로 이루어진 분수","mis":"M3-2-u4-X08"}],"explanation":["분자가 분모보다 작으면 진분수예요.","분자가 분모와 같거나 크면 가분수예요.","분자가 1이면 단위분수, 자연수와 진분수면 대분수예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L05_basic#5','math',3,2,'u4','L05','g3_2_math_u4_L05_basic','lesson_basic','M3-2-u4-C6',2,'sa','auto','2를 분모가 8인 분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-2-u4-C6","difficulty":2,"kind":"sa","stem":"2를 분모가 8인 분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["⟨1/8⟩이 8개면 1이에요 — 1 = ⟨8/8⟩.","2는 1이 2개 — ⟨1/8⟩이 8 × 2 = 16개.","2 = ⟨16/8⟩ — 분자는 16."],"variant_rule":{"alt":[{"stem":"2를 분모가 9인 분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["⟨1/9⟩이 9개면 1이에요 — 1 = ⟨9/9⟩.","2는 1이 2개 — ⟨1/9⟩이 9 × 2 = 18개.","2 = ⟨18/9⟩ — 분자는 18."],"asset":null},{"stem":"3을 분모가 6인 분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["⟨1/6⟩이 6개면 1이에요 — 1 = ⟨6/6⟩.","3은 1이 3개 — ⟨1/6⟩이 6 × 3 = 18개.","3 = ⟨18/6⟩ — 분자는 18."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L05_basic#6','math',3,2,'u4','L05','g3_2_math_u4_L05_basic','lesson_basic','M3-2-u4-C5',2,'sa','auto','⟨22/11⟩, ⟨16/8⟩, ⟨17/10⟩, ⟨1/2⟩, ⟨7/7⟩, ⟨7/4⟩ 중에서 가분수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M3-2-u4-C5","difficulty":2,"kind":"sa","stem":"⟨22/11⟩, ⟨16/8⟩, ⟨17/10⟩, ⟨1/2⟩, ⟨7/7⟩, ⟨7/4⟩ 중에서 가분수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["분자와 분모를 견주어요.","가분수: ⟨22/11⟩, ⟨16/8⟩, ⟨17/10⟩, ⟨7/7⟩, ⟨7/4⟩.","가분수는 5개 — 분자가 분모와 같은 것도 가분수예요 잊지 않아요."],"variant_rule":{"alt":[{"stem":"⟨8/8⟩, ⟨7/5⟩, ⟨6/3⟩, ⟨3/4⟩, ⟨20/11⟩, ⟨1/10⟩ 중에서 가분수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["분자와 분모를 견주어요.","가분수: ⟨8/8⟩, ⟨7/5⟩, ⟨6/3⟩, ⟨20/11⟩.","가분수는 4개 — 분자가 분모와 같은 것도 가분수예요 잊지 않아요."],"asset":null},{"stem":"⟨1/3⟩, ⟨2/2⟩, ⟨3/4⟩, ⟨4/8⟩, ⟨4/6⟩, ⟨3/2⟩ 중에서 가분수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["분자와 분모를 견주어요.","가분수: ⟨2/2⟩, ⟨3/2⟩.","가분수는 2개 — 분자가 분모와 같은 것도 가분수예요 잊지 않아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
