INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L05_basic#10','math',3,2,'u4','L05','g3_2_math_u4_L05_basic','lesson_basic','M3-2-u4-C5',3,'sa','auto','분모가 6인 가분수 중에서 분자가 12보다 작은 것은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M3-2-u4-C5","difficulty":3,"kind":"sa","stem":"분모가 6인 가분수 중에서 분자가 12보다 작은 것은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["가분수는 분자가 분모 6과 같거나 커요 — 분자는 6부터.","12보다 작은 분자: 6, 7, 8, 9, 10, 11.","모두 6개 — ⟨6/6⟩처럼 분자와 분모가 같은 것도 넣어요."],"variant_rule":{"alt":[{"stem":"분모가 7인 가분수 중에서 분자가 10보다 작은 것은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["가분수는 분자가 분모 7과 같거나 커요 — 분자는 7부터.","10보다 작은 분자: 7, 8, 9.","모두 3개 — ⟨7/7⟩처럼 분자와 분모가 같은 것도 넣어요."],"asset":null},{"stem":"분모가 5인 가분수 중에서 분자가 11보다 작은 것은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["가분수는 분자가 분모 5와 같거나 커요 — 분자는 5부터.","11보다 작은 분자: 5, 6, 7, 8, 9, 10.","모두 6개 — ⟨5/5⟩처럼 분자와 분모가 같은 것도 넣어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
