INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L05_challenge#5','math',3,2,'u4','L05','g3_2_math_u4_L05_challenge','lesson_challenge','M3-2-u4-C5',3,'sa','auto','주사위를 던져 처음 나온 4를 분모로 정했어요. 두 번째로 나온 수를 분자로 할 때, 가분수가 되는 경우는 모두 몇 가지인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-2-u4-C5","difficulty":3,"kind":"sa","stem":"주사위를 던져 처음 나온 4를 분모로 정했어요. 두 번째로 나온 수를 분자로 할 때, 가분수가 되는 경우는 모두 몇 가지인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["주사위의 수는 1부터 6까지예요.","가분수: 분자가 4와 같거나 커야 해요 — 4, 5, 6.","모두 3가지예요."],"variant_rule":{"alt":[{"stem":"주사위를 던져 처음 나온 5를 분모로 정했어요. 두 번째로 나온 수를 분자로 할 때, 가분수가 되는 경우는 모두 몇 가지인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["주사위의 수는 1부터 6까지예요.","가분수: 분자가 5와 같거나 커야 해요 — 5, 6.","모두 2가지예요."],"asset":null},{"stem":"주사위를 던져 처음 나온 3을 분모로 정했어요. 두 번째로 나온 수를 분자로 할 때, 가분수가 되는 경우는 모두 몇 가지인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["주사위의 수는 1부터 6까지예요.","가분수: 분자가 3과 같거나 커야 해요 — 3, 4, 5, 6.","모두 4가지예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L05_challenge#6','math',3,2,'u4','L05','g3_2_math_u4_L05_challenge','lesson_challenge','M3-2-u4-C5',3,'error','auto','분수를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u4-X09','M3-2-u4-X20']::text[],true,'{"seq":6,"concept":"M3-2-u4-C5","difficulty":3,"kind":"error","stem":"분수를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준우 — 「2 = ⟨2/8⟩야」","correct":true,"mis_target":"M3-2-u4-X09"},{"t":"도연 — 「1 = ⟨8/8⟩이야」","mis":"M3-2-u4-X20"},{"t":"서준 — 「⟨3/8⟩은 진분수야」","mis":"M3-2-u4-X20"}],"explanation":["분자가 분모보다 작으면 진분수, 같거나 크면 가분수예요.","1 = ⟨8/8⟩, 2 = ⟨16/8⟩이에요.","준우의 말이 틀렸어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 분수를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지훈 — 「⟨5/13⟩는 가분수야」","correct":true,"mis_target":"M3-2-u4-X08"},{"t":"채원 — 「1 = ⟨8/8⟩이야」","mis":"M3-2-u4-X20"},{"t":"은비 — 「⟨1/8⟩이 9개면 ⟨9/8⟩야」","mis":"M3-2-u4-X20"}],"explanation":["분자가 분모보다 작으면 진분수, 같거나 크면 가분수예요.","1 = ⟨8/8⟩, 2 = ⟨16/8⟩이에요.","지훈의 말이 틀렸어요."],"asset":null},{"stem":"이번에는 다른 문제예요. 분수를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서윤 — 「⟨6/6⟩은 진분수야」","correct":true,"mis_target":"M3-2-u4-X08"},{"t":"채원 — 「⟨1/6⟩이 7개면 ⟨7/6⟩이야」","mis":"M3-2-u4-X20"},{"t":"건우 — 「⟨11/6⟩은 가분수야」","mis":"M3-2-u4-X20"}],"explanation":["분자가 분모보다 작으면 진분수, 같거나 크면 가분수예요.","1 = ⟨6/6⟩, 2 = ⟨12/6⟩예요.","서윤의 말이 틀렸어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L05_challenge#7','math',3,2,'u4','L05','g3_2_math_u4_L05_challenge','lesson_challenge','M3-2-u4-C5',3,'mc','auto','서윤은 샌드위치 1개를 만드는 데 식빵 ⟨1/5⟩ 장가 필요해요. 샌드위치 7개를 만들려면 식빵이 모두 몇 장 필요한가요?',ARRAY['M3-2-u4-X03','M3-2-u4-X07']::text[],true,'{"seq":7,"concept":"M3-2-u4-C5","difficulty":3,"kind":"mc","stem":"서윤은 샌드위치 1개를 만드는 데 식빵 ⟨1/5⟩ 장가 필요해요. 샌드위치 7개를 만들려면 식빵이 모두 몇 장 필요한가요?","options":[{"t":"⟨7/5⟩","correct":true},{"t":"⟨5/7⟩","mis":"M3-2-u4-X03"},{"t":"⟨1/35⟩","mis":"M3-2-u4-X07"},{"t":"⟨1/12⟩","mis":"M3-2-u4-X07"}],"explanation":["⟨1/5⟩이 7개 모이면 분자가 7 — 분모 5는 그대로예요.","그래서 ⟨7/5⟩개 필요해요.","분자 7이 분모 5보다 커서 — 가분수예요."],"variant_rule":{"alt":[{"stem":"도연은 책갈피 1개를 만드는 데 색 도화지 ⟨1/3⟩ 장가 필요해요. 책갈피 8개를 만들려면 색 도화지가 모두 몇 장 필요한가요?","options":[{"t":"⟨8/3⟩","correct":true},{"t":"⟨3/8⟩","mis":"M3-2-u4-X03"},{"t":"⟨1/24⟩","mis":"M3-2-u4-X07"},{"t":"⟨1/11⟩","mis":"M3-2-u4-X07"}],"explanation":["⟨1/3⟩이 8개 모이면 분자가 8 — 분모 3은 그대로예요.","그래서 ⟨8/3⟩개 필요해요.","분자 8이 분모 3보다 커서 — 가분수예요."],"asset":null},{"stem":"민서는 바람개비 1개를 만드는 데 수수깡 ⟨1/2⟩ 개가 필요해요. 바람개비 3개를 만들려면 수수깡이 모두 몇 개 필요한가요?","options":[{"t":"⟨3/2⟩","correct":true},{"t":"⟨2/3⟩","mis":"M3-2-u4-X03"},{"t":"⟨1/6⟩","mis":"M3-2-u4-X07"},{"t":"⟨1/5⟩","mis":"M3-2-u4-X07"}],"explanation":["⟨1/2⟩이 3개 모이면 분자가 3 — 분모 2는 그대로예요.","그래서 ⟨3/2⟩개 필요해요.","분자 3이 분모 2보다 커서 — 가분수예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L05_challenge#8','math',3,2,'u4','L05','g3_2_math_u4_L05_challenge','lesson_challenge','M3-2-u4-C5',4,'essay','teacher','바람개비 1개를 만드는 데 수수깡 ⟨1/3⟩개가 필요해요. 바람개비 4개를 만들 때 필요한 수수깡을 분수로 쓰고, 이 분수가 진분수인지 가분수인지 까닭과 함께 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-2-u4-C5","difficulty":4,"kind":"essay","stem":"바람개비 1개를 만드는 데 수수깡 ⟨1/3⟩개가 필요해요. 바람개비 4개를 만들 때 필요한 수수깡을 분수로 쓰고, 이 분수가 진분수인지 가분수인지 까닭과 함께 설명해 보세요.","answer_guide":{"answer":"예: ⟨1/3⟩이 4개이므로 ⟨4/3⟩개가 필요하다. 분자 4가 분모 3보다 크므로 가분수이다. 분자가 분모와 같거나 크면 가분수, 작으면 진분수이다.","scoring_points":["⟨4/3⟩를 구했는가","가분수라고 답했는가","분자와 분모를 견주어 까닭을 썼는가"]},"explanation":["⟨1/3⟩ × 4개 = ⟨4/3⟩.","분자 4 > 분모 3.","가분수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L05_challenge#9','math',3,2,'u4','L05','g3_2_math_u4_L05_challenge','lesson_challenge','M3-2-u4-C6',4,'essay','teacher','2를 분모가 4인 분수로 나타내고, 그렇게 나타낼 수 있는 까닭을 단위분수와 수직선을 이용해 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-2-u4-C6","difficulty":4,"kind":"essay","stem":"2를 분모가 4인 분수로 나타내고, 그렇게 나타낼 수 있는 까닭을 단위분수와 수직선을 이용해 설명해 보세요.","answer_guide":{"answer":"예: 2 = ⟨8/4⟩이다. ⟨1/4⟩이 4개 모이면 ⟨4/4⟩ = 1이고, 2는 1이 2개이므로 ⟨1/4⟩이 8개이다. 분모가 4인 수직선에서 ⟨4/4⟩는 1의 자리, ⟨8/4⟩은 2의 자리에 있다.","scoring_points":["⟨8/4⟩이라고 썼는가","⟨1/4⟩이 4개면 1이라고 썼는가","⟨1/4⟩이 8개면 2라고 설명했는가"]},"explanation":["⟨4/4⟩ = 1.","2 = ⟨1/4⟩ × 8개.","2 = ⟨8/4⟩."],"asset":{"type":"number_line","cells":["0","⟨2/4⟩","1","⟨6/4⟩","?"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L05_challenge#10','math',3,2,'u4','L05','g3_2_math_u4_L05_challenge','lesson_challenge','M3-2-u4-C5',4,'sa','auto','주사위를 던져 처음 나온 5를 분모로 정했어요. 두 번째로 나온 수를 분자로 할 때, 가분수가 되는 경우는 모두 몇 가지인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M3-2-u4-C5","difficulty":4,"kind":"sa","stem":"주사위를 던져 처음 나온 5를 분모로 정했어요. 두 번째로 나온 수를 분자로 할 때, 가분수가 되는 경우는 모두 몇 가지인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["주사위의 수는 1부터 6까지예요.","가분수: 분자가 5와 같거나 커야 해요 — 5, 6.","모두 2가지예요."],"variant_rule":{"alt":[{"stem":"주사위를 던져 처음 나온 3을 분모로 정했어요. 두 번째로 나온 수를 분자로 할 때, 가분수가 되는 경우는 모두 몇 가지인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["주사위의 수는 1부터 6까지예요.","가분수: 분자가 3과 같거나 커야 해요 — 3, 4, 5, 6.","모두 4가지예요."],"asset":null},{"stem":"주사위를 던져 처음 나온 6을 분모로 정했어요. 두 번째로 나온 수를 분자로 할 때, 가분수가 되는 경우는 모두 몇 가지인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["주사위의 수는 1부터 6까지예요.","가분수: 분자가 6과 같거나 커야 해요 — 6.","모두 1가지예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L06_basic#1','math',3,2,'u4','L06','g3_2_math_u4_L06_basic','lesson_basic','M3-2-u4-C7',1,'mc','auto','똑같은 띠 2개에 색칠했어요. 색칠한 부분을 대분수로 나타내면 무엇인가요?',ARRAY['M3-2-u4-X12','M3-2-u4-X21']::text[],true,'{"seq":1,"concept":"M3-2-u4-C7","difficulty":1,"kind":"mc","stem":"똑같은 띠 2개에 색칠했어요. 색칠한 부분을 대분수로 나타내면 무엇인가요?","options":[{"t":"⟨1 1/2⟩","correct":true},{"t":"⟨1/2⟩","mis":"M3-2-u4-X12"},{"t":"⟨2 1/2⟩","mis":"M3-2-u4-X21"},{"t":"⟨1 1/3⟩","mis":"M3-2-u4-X21"}],"explanation":["통째로 색칠한 띠가 1개 — 자연수 부분 1.","남은 띠는 2칸 중 1칸 — 진분수 ⟨1/2⟩.","색칠한 부분은 ⟨1 1/2⟩이에요."],"asset":{"type":"fbar","bars":[{"den":2,"num":2},{"den":2,"num":1}]},"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 똑같은 띠 2개에 색칠했어요. 색칠한 부분을 대분수로 나타내면 무엇인가요?","options":[{"t":"⟨1 5/6⟩","correct":true},{"t":"⟨5/6⟩","mis":"M3-2-u4-X12"},{"t":"⟨2 5/6⟩","mis":"M3-2-u4-X21"},{"t":"⟨1 1/6⟩","mis":"M3-2-u4-X20"}],"explanation":["통째로 색칠한 띠가 1개 — 자연수 부분 1.","남은 띠는 6칸 중 5칸 — 진분수 ⟨5/6⟩.","색칠한 부분은 ⟨1 5/6⟩예요."],"asset":{"type":"fbar","bars":[{"den":6,"num":6},{"den":6,"num":5}]}},{"stem":"똑같은 띠 3개에 색칠했어요. 색칠한 부분을 대분수로 나타내면 무엇인가요?","options":[{"t":"⟨2 1/2⟩","correct":true},{"t":"⟨1/2⟩","mis":"M3-2-u4-X12"},{"t":"⟨3 1/2⟩","mis":"M3-2-u4-X21"},{"t":"⟨1 1/2⟩","mis":"M3-2-u4-X12"}],"explanation":["통째로 색칠한 띠가 2개 — 자연수 부분 2.","남은 띠는 2칸 중 1칸 — 진분수 ⟨1/2⟩.","색칠한 부분은 ⟨2 1/2⟩이에요."],"asset":{"type":"fbar","bars":[{"den":2,"num":2},{"den":2,"num":2},{"den":2,"num":1}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L06_basic#2','math',3,2,'u4','L06','g3_2_math_u4_L06_basic','lesson_basic','M3-2-u4-C7',1,'sa','auto','⟨2 1/4⟩을 가분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u4-C7","difficulty":1,"kind":"sa","stem":"⟨2 1/4⟩을 가분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["자연수 1은 ⟨1/4⟩이 4개예요 — 2는 2 × 4 = 8개.","⟨1/4⟩은 1개 — 모두 8 + 1 = 9개예요.","⟨2 1/4⟩ = ⟨9/4⟩ — 분모는 그대로 두어요."],"variant_rule":{"alt":[{"stem":"⟨2 1/5⟩을 가분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["자연수 1은 ⟨1/5⟩이 5개예요 — 2는 2 × 5 = 10개.","⟨1/5⟩은 1개 — 모두 10 + 1 = 11개예요.","⟨2 1/5⟩ = ⟨11/5⟩ — 분모는 그대로 두어요."],"asset":null},{"stem":"⟨3 1/5⟩을 가분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["자연수 1은 ⟨1/5⟩이 5개예요 — 3은 3 × 5 = 15개.","⟨1/5⟩은 1개 — 모두 15 + 1 = 16개예요.","⟨3 1/5⟩ = ⟨16/5⟩ — 분모는 그대로 두어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L06_basic#3','math',3,2,'u4','L06','g3_2_math_u4_L06_basic','lesson_basic','M3-2-u4-C7',1,'sa','auto','⟨13/8⟩을 대분수로 나타내면 분수 부분의 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-2-u4-C7","difficulty":1,"kind":"sa","stem":"⟨13/8⟩을 대분수로 나타내면 분수 부분의 분자는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["⟨13/8⟩은 ⟨1/8⟩이 13개예요.","8개씩 모으면 1 — 13 ÷ 8 = 1 … 5, 통째로 1이고 ⟨1/8⟩이 5개 남아요.","⟨13/8⟩ = ⟨1 5/8⟩ — 분수 부분은 진분수예요."],"variant_rule":{"alt":[{"stem":"⟨7/6⟩을 대분수로 나타내면 분수 부분의 분자는 얼마인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["⟨7/6⟩은 ⟨1/6⟩이 7개예요.","6개씩 모으면 1 — 7 ÷ 6 = 1 … 1, 통째로 1이고 ⟨1/6⟩이 1개 남아요.","⟨7/6⟩ = ⟨1 1/6⟩ — 분수 부분은 진분수예요."],"asset":null},{"stem":"⟨12/8⟩를 대분수로 나타내면 분수 부분의 분자는 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["⟨12/8⟩는 ⟨1/8⟩이 12개예요.","8개씩 모으면 1 — 12 ÷ 8 = 1 … 4, 통째로 1이고 ⟨1/8⟩이 4개 남아요.","⟨12/8⟩ = ⟨1 4/8⟩ — 분수 부분은 진분수예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L06_basic#4','math',3,2,'u4','L06','g3_2_math_u4_L06_basic','lesson_basic','M3-2-u4-C7',1,'mc','auto','⟨1 1/5⟩을 바르게 읽은 것은 무엇인가요?',ARRAY['M3-2-u4-X03','M3-2-u4-X16','M3-2-u4-X10']::text[],true,'{"seq":4,"concept":"M3-2-u4-C7","difficulty":1,"kind":"mc","stem":"⟨1 1/5⟩을 바르게 읽은 것은 무엇인가요?","options":[{"t":"일과 오분의 일","correct":true},{"t":"일과 일분의 오","mis":"M3-2-u4-X03"},{"t":"일 점 일오","mis":"M3-2-u4-X16"},{"t":"오분의 육","mis":"M3-2-u4-X10"}],"explanation":["대분수는 자연수 부분을 먼저 읽고 「과(와)」를 붙여요.","분수 부분은 분모부터 「○분의 △」로 읽어요.","⟨1 1/5⟩은 「일과 오분의 일」."],"variant_rule":{"alt":[{"stem":"⟨3 1/4⟩을 바르게 읽은 것은 무엇인가요?","options":[{"t":"삼과 사분의 일","correct":true},{"t":"삼과 일분의 사","mis":"M3-2-u4-X03"},{"t":"삼 점 일사","mis":"M3-2-u4-X16"},{"t":"사분의 십삼","mis":"M3-2-u4-X10"}],"explanation":["대분수는 자연수 부분을 먼저 읽고 「과(와)」를 붙여요.","분수 부분은 분모부터 「○분의 △」로 읽어요.","⟨3 1/4⟩은 「삼과 사분의 일」."],"asset":null},{"stem":"⟨4 1/3⟩을 바르게 읽은 것은 무엇인가요?","options":[{"t":"사와 삼분의 일","correct":true},{"t":"사와 일분의 삼","mis":"M3-2-u4-X03"},{"t":"사 점 일삼","mis":"M3-2-u4-X16"},{"t":"삼분의 십삼","mis":"M3-2-u4-X10"}],"explanation":["대분수는 자연수 부분을 먼저 읽고 「과(와)」를 붙여요.","분수 부분은 분모부터 「○분의 △」로 읽어요.","⟨4 1/3⟩은 「사와 삼분의 일」."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L06_basic#5','math',3,2,'u4','L06','g3_2_math_u4_L06_basic','lesson_basic','M3-2-u4-C7',2,'sa','auto','⟨17/5⟩을 대분수로 나타내면 자연수 부분은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-2-u4-C7","difficulty":2,"kind":"sa","stem":"⟨17/5⟩을 대분수로 나타내면 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["⟨17/5⟩은 ⟨1/5⟩이 17개예요.","5개씩 모으면 1 — 17 ÷ 5 = 3 … 2, 통째로 3이고 ⟨1/5⟩이 2개 남아요.","⟨17/5⟩ = ⟨3 2/5⟩ — 분수 부분은 진분수예요."],"variant_rule":{"alt":[{"stem":"⟨5/2⟩를 대분수로 나타내면 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["⟨5/2⟩는 ⟨1/2⟩이 5개예요.","2개씩 모으면 1 — 5 ÷ 2 = 2 … 1, 통째로 2이고 ⟨1/2⟩이 1개 남아요.","⟨5/2⟩ = ⟨2 1/2⟩ — 분수 부분은 진분수예요."],"asset":null},{"stem":"⟨13/4⟩을 대분수로 나타내면 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["⟨13/4⟩은 ⟨1/4⟩이 13개예요.","4개씩 모으면 1 — 13 ÷ 4 = 3 … 1, 통째로 3이고 ⟨1/4⟩이 1개 남아요.","⟨13/4⟩ = ⟨3 1/4⟩ — 분수 부분은 진분수예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
