INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L06_basic#7','math',3,2,'u4','L06','g3_2_math_u4_L06_basic','lesson_basic','M3-2-u4-C7',2,'mc','auto','대분수는 어느 것인가요?',ARRAY['M3-2-u4-X11','M3-2-u4-X08']::text[],true,'{"seq":7,"concept":"M3-2-u4-C7","difficulty":2,"kind":"mc","stem":"대분수는 어느 것인가요?","options":[{"t":"⟨2 2/6⟩","correct":true},{"t":"⟨2 8/6⟩","mis":"M3-2-u4-X11"},{"t":"⟨2/6⟩","mis":"M3-2-u4-X08"},{"t":"⟨6/2⟩","mis":"M3-2-u4-X08"}],"explanation":["대분수는 자연수와 진분수로 이루어진 분수예요.","⟨2 2/6⟩는 자연수 2와 진분수 ⟨2/6⟩ — 대분수예요.","분수 부분이 가분수이면 대분수가 아니에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 대분수는 어느 것인가요?","options":[{"t":"⟨1 2/8⟩","correct":true},{"t":"⟨1 10/8⟩","mis":"M3-2-u4-X11"},{"t":"⟨2/8⟩","mis":"M3-2-u4-X08"},{"t":"⟨8/2⟩","mis":"M3-2-u4-X08"}],"explanation":["대분수는 자연수와 진분수로 이루어진 분수예요.","⟨1 2/8⟩는 자연수 1과 진분수 ⟨2/8⟩ — 대분수예요.","분수 부분이 가분수이면 대분수가 아니에요."],"asset":null},{"stem":"이번에는 다른 문제예요. 대분수는 어느 것인가요?","options":[{"t":"⟨1 5/8⟩","correct":true},{"t":"⟨1 13/8⟩","mis":"M3-2-u4-X11"},{"t":"⟨5/8⟩","mis":"M3-2-u4-X08"},{"t":"⟨8/5⟩","mis":"M3-2-u4-X08"}],"explanation":["대분수는 자연수와 진분수로 이루어진 분수예요.","⟨1 5/8⟩는 자연수 1과 진분수 ⟨5/8⟩ — 대분수예요.","분수 부분이 가분수이면 대분수가 아니에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L06_basic#8','math',3,2,'u4','L06','g3_2_math_u4_L06_basic','lesson_basic','M3-2-u4-C7',2,'ox','auto','지훈이 ⟨5/2⟩를 대분수로 ⟨1 3/2⟩라고 나타냈어요. 바르게 나타냈어요.',ARRAY['M3-2-u4-X11']::text[],true,'{"seq":8,"concept":"M3-2-u4-C7","difficulty":2,"kind":"ox","stem":"지훈이 ⟨5/2⟩를 대분수로 ⟨1 3/2⟩라고 나타냈어요. 바르게 나타냈어요.","answer":"X","reason_options":[{"t":"분수 부분 ⟨3/2⟩이 가분수라서","correct":true},{"t":"⟨1/2⟩이 5개는 그대로 맞아서","mis":"M3-2-u4-X11"}],"mis":"M3-2-u4-X11","explanation":["대분수의 분수 부분은 반드시 진분수예요.","⟨3/2⟩은 아직 1을 더 모을 수 있어요.","⟨5/2⟩ = ⟨2 1/2⟩ — ×."],"variant_rule":{"alt":[{"stem":"채원이 ⟨17/5⟩을 대분수로 ⟨2 7/5⟩라고 나타냈어요. 바르게 나타냈어요.","answer":"X","reason_options":[{"t":"분수 부분 ⟨7/5⟩이 가분수라서","correct":true},{"t":"⟨1/5⟩이 17개는 그대로 맞아서","mis":"M3-2-u4-X11"}],"explanation":["대분수의 분수 부분은 반드시 진분수예요.","⟨7/5⟩은 아직 1을 더 모을 수 있어요.","⟨17/5⟩ = ⟨3 2/5⟩ — ×."],"asset":null},{"stem":"도연이 ⟨25/6⟩를 대분수로 ⟨3 7/6⟩라고 나타냈어요. 바르게 나타냈어요.","answer":"X","reason_options":[{"t":"분수 부분 ⟨7/6⟩이 가분수라서","correct":true},{"t":"⟨1/6⟩이 25개는 그대로 맞아서","mis":"M3-2-u4-X11"}],"explanation":["대분수의 분수 부분은 반드시 진분수예요.","⟨7/6⟩은 아직 1을 더 모을 수 있어요.","⟨25/6⟩ = ⟨4 1/6⟩ — ×."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L06_basic#9','math',3,2,'u4','L06','g3_2_math_u4_L06_basic','lesson_basic','M3-2-u4-C7',2,'sa','auto','우유 ⟨1 5/7⟩ 컵을 ⟨1/7⟩ 컵씩 덜어 쓰려고 해요. 모두 몇 번 덜 수 있나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M3-2-u4-C7","difficulty":2,"kind":"sa","stem":"우유 ⟨1 5/7⟩ 컵을 ⟨1/7⟩ 컵씩 덜어 쓰려고 해요. 모두 몇 번 덜 수 있나요? 숫자로 쓰세요.","answer":["12"],"explanation":["⟨1/7⟩ 컵이 7번이면 1 컵이에요.","⟨1 5/7⟩ = ⟨1/7⟩이 7 + 5 = 12개 — 가분수 ⟨12/7⟩.","12번 덜 수 있어요."],"variant_rule":{"alt":[{"stem":"밀가루 ⟨2 3/8⟩ 컵을 ⟨1/8⟩ 컵씩 덜어 쓰려고 해요. 모두 몇 번 덜 수 있나요? 숫자로 쓰세요.","answer":["19"],"explanation":["⟨1/8⟩ 컵이 8번이면 1 컵이에요.","⟨2 3/8⟩ = ⟨1/8⟩이 16 + 3 = 19개 — 가분수 ⟨19/8⟩.","19번 덜 수 있어요."],"asset":null},{"stem":"주스 ⟨1 2/7⟩ 병을 ⟨1/7⟩ 병씩 덜어 쓰려고 해요. 모두 몇 번 덜 수 있나요? 숫자로 쓰세요.","answer":["9"],"explanation":["⟨1/7⟩ 병이 7번이면 1 병이에요.","⟨1 2/7⟩ = ⟨1/7⟩이 7 + 2 = 9개 — 가분수 ⟨9/7⟩.","9번 덜 수 있어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L06_basic#10','math',3,2,'u4','L06','g3_2_math_u4_L06_basic','lesson_basic','M3-2-u4-C7',3,'sa','auto','6보다 크고 7보다 작은 대분수예요. 분모는 3이고 분자는 홀수예요. 이 수를 가분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M3-2-u4-C7","difficulty":3,"kind":"sa","stem":"6보다 크고 7보다 작은 대분수예요. 분모는 3이고 분자는 홀수예요. 이 수를 가분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.","answer":["19"],"explanation":["6보다 크고 7보다 작으니 자연수 부분은 6이에요.","분모 3인 진분수 중 분자가 홀수인 것은 ⟨1/3⟩ — 대분수 ⟨6 1/3⟩.","6 × 3 + 1 = 19 — 가분수 ⟨19/3⟩."],"variant_rule":{"alt":[{"stem":"7보다 크고 8보다 작은 대분수예요. 분모는 3이고 분자는 짝수예요. 이 수를 가분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.","answer":["23"],"explanation":["7보다 크고 8보다 작으니 자연수 부분은 7이에요.","분모 3인 진분수 중 분자가 짝수인 것은 ⟨2/3⟩ — 대분수 ⟨7 2/3⟩.","7 × 3 + 2 = 23 — 가분수 ⟨23/3⟩."],"asset":null},{"stem":"2보다 크고 3보다 작은 대분수예요. 분모는 3이고 분자는 홀수예요. 이 수를 가분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["2보다 크고 3보다 작으니 자연수 부분은 2예요.","분모 3인 진분수 중 분자가 홀수인 것은 ⟨1/3⟩ — 대분수 ⟨2 1/3⟩.","2 × 3 + 1 = 7 — 가분수 ⟨7/3⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L06_challenge#1','math',3,2,'u4','L06','g3_2_math_u4_L06_challenge','lesson_challenge','M3-2-u4-C7',2,'mc','auto','⟨4 2/3⟩를 가분수로 나타낸 것은 무엇인가요?',ARRAY['M3-2-u4-X10']::text[],true,'{"seq":1,"concept":"M3-2-u4-C7","difficulty":2,"kind":"mc","stem":"⟨4 2/3⟩를 가분수로 나타낸 것은 무엇인가요?","options":[{"t":"⟨14/3⟩","correct":true},{"t":"⟨6/3⟩","mis":"M3-2-u4-X10"},{"t":"⟨12/3⟩","mis":"M3-2-u4-X10"},{"t":"⟨11/3⟩","mis":"M3-2-u4-X10"}],"explanation":["자연수 1은 ⟨1/3⟩이 3개예요 — 4는 4 × 3 = 12개.","⟨2/3⟩는 2개 — 모두 12 + 2 = 14개예요.","⟨4 2/3⟩ = ⟨14/3⟩ — 분모는 그대로 두어요."],"variant_rule":{"alt":[{"stem":"⟨3 6/8⟩을 가분수로 나타낸 것은 무엇인가요?","options":[{"t":"⟨30/8⟩","correct":true},{"t":"⟨9/8⟩","mis":"M3-2-u4-X10"},{"t":"⟨24/8⟩","mis":"M3-2-u4-X10"},{"t":"⟨26/8⟩","mis":"M3-2-u4-X10"}],"explanation":["자연수 1은 ⟨1/8⟩이 8개예요 — 3은 3 × 8 = 24개.","⟨6/8⟩은 6개 — 모두 24 + 6 = 30개예요.","⟨3 6/8⟩ = ⟨30/8⟩ — 분모는 그대로 두어요."],"asset":null},{"stem":"⟨1 1/3⟩을 가분수로 나타낸 것은 무엇인가요?","options":[{"t":"⟨4/3⟩","correct":true},{"t":"⟨2/3⟩","mis":"M3-2-u4-X10"},{"t":"⟨3/3⟩","mis":"M3-2-u4-X10"},{"t":"⟨5/3⟩","mis":"M3-2-u4-X21"}],"explanation":["자연수 1은 ⟨1/3⟩이 3개예요.","⟨1/3⟩은 1개 — 모두 3 + 1 = 4개예요.","⟨1 1/3⟩ = ⟨4/3⟩ — 분모는 그대로 두어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L06_challenge#2','math',3,2,'u4','L06','g3_2_math_u4_L06_challenge','lesson_challenge','M3-2-u4-C7',2,'match','auto','대분수와 크기가 같은 가분수를 알맞게 이으세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u4-C7","difficulty":2,"kind":"match","stem":"대분수와 크기가 같은 가분수를 알맞게 이으세요.","pairs":[{"l":"⟨2 2/6⟩","r":"⟨14/6⟩"},{"l":"⟨3 5/6⟩","r":"⟨23/6⟩"},{"l":"⟨3 1/4⟩","r":"⟨13/4⟩"}],"mis":"M3-2-u4-X10","explanation":["자연수 1은 분모만큼의 단위분수예요.","⟨2 2/6⟩ = ⟨14/6⟩, ⟨3 5/6⟩ = ⟨23/6⟩, ⟨3 1/4⟩ = ⟨13/4⟩.","분모는 그대로, 분자는 단위분수의 개수."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 대분수와 크기가 같은 가분수를 알맞게 이으세요.","pairs":[{"l":"⟨2 5/7⟩","r":"⟨19/7⟩"},{"l":"⟨1 1/3⟩","r":"⟨4/3⟩"},{"l":"⟨1 6/7⟩","r":"⟨13/7⟩"}],"explanation":["자연수 1은 분모만큼의 단위분수예요.","⟨2 5/7⟩ = ⟨19/7⟩, ⟨1 1/3⟩ = ⟨4/3⟩, ⟨1 6/7⟩ = ⟨13/7⟩.","분모는 그대로, 분자는 단위분수의 개수."],"asset":null},{"stem":"이번에는 다른 문제예요. 대분수와 크기가 같은 가분수를 알맞게 이으세요.","pairs":[{"l":"⟨3 1/2⟩","r":"⟨7/2⟩"},{"l":"⟨1 4/6⟩","r":"⟨10/6⟩"},{"l":"⟨3 3/5⟩","r":"⟨18/5⟩"}],"explanation":["자연수 1은 분모만큼의 단위분수예요.","⟨3 1/2⟩ = ⟨7/2⟩, ⟨1 4/6⟩ = ⟨10/6⟩, ⟨3 3/5⟩ = ⟨18/5⟩.","분모는 그대로, 분자는 단위분수의 개수."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L06_challenge#3','math',3,2,'u4','L06','g3_2_math_u4_L06_challenge','lesson_challenge','M3-2-u4-C7',3,'mc','auto','⟨18/7⟩을 대분수로 바르게 나타낸 것은 무엇인가요?',ARRAY['M3-2-u4-X12','M3-2-u4-X21']::text[],true,'{"seq":3,"concept":"M3-2-u4-C7","difficulty":3,"kind":"mc","stem":"⟨18/7⟩을 대분수로 바르게 나타낸 것은 무엇인가요?","options":[{"t":"⟨2 4/7⟩","correct":true},{"t":"⟨4 2/7⟩","mis":"M3-2-u4-X12"},{"t":"⟨3 4/7⟩","mis":"M3-2-u4-X21"},{"t":"⟨2 5/7⟩","mis":"M3-2-u4-X21"}],"explanation":["⟨18/7⟩은 ⟨1/7⟩이 18개예요.","7개씩 모으면 1 — 18 ÷ 7 = 2 … 4, 통째로 2이고 ⟨1/7⟩이 4개 남아요.","⟨18/7⟩ = ⟨2 4/7⟩ — 분수 부분은 진분수예요."],"variant_rule":{"alt":[{"stem":"⟨11/4⟩을 대분수로 바르게 나타낸 것은 무엇인가요?","options":[{"t":"⟨2 3/4⟩","correct":true},{"t":"⟨3 2/4⟩","mis":"M3-2-u4-X12"},{"t":"⟨3 3/4⟩","mis":"M3-2-u4-X21"},{"t":"⟨3/4⟩","mis":"M3-2-u4-X12"}],"explanation":["⟨11/4⟩은 ⟨1/4⟩이 11개예요.","4개씩 모으면 1 — 11 ÷ 4 = 2 … 3, 통째로 2이고 ⟨1/4⟩이 3개 남아요.","⟨11/4⟩ = ⟨2 3/4⟩ — 분수 부분은 진분수예요."],"asset":null},{"stem":"⟨8/3⟩을 대분수로 바르게 나타낸 것은 무엇인가요?","options":[{"t":"⟨2 2/3⟩","correct":true},{"t":"⟨3 2/3⟩","mis":"M3-2-u4-X21"},{"t":"⟨2/3⟩","mis":"M3-2-u4-X12"},{"t":"⟨2 1/3⟩","mis":"M3-2-u4-X12"}],"explanation":["⟨8/3⟩은 ⟨1/3⟩이 8개예요.","3개씩 모으면 1 — 8 ÷ 3 = 2 … 2, 통째로 2이고 ⟨1/3⟩이 2개 남아요.","⟨8/3⟩ = ⟨2 2/3⟩ — 분수 부분은 진분수예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L06_challenge#4','math',3,2,'u4','L06','g3_2_math_u4_L06_challenge','lesson_challenge','M3-2-u4-C7',3,'error','auto','대분수를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u4-X10','M3-2-u4-X20']::text[],true,'{"seq":4,"concept":"M3-2-u4-C7","difficulty":3,"kind":"error","stem":"대분수를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서윤 — 「⟨2 3/4⟩ = ⟨5/4⟩야」","correct":true,"mis_target":"M3-2-u4-X10"},{"t":"채원 — 「대분수의 분수 부분은 진분수야」","mis":"M3-2-u4-X20"},{"t":"민서 — 「⟨2 3/4⟩ = ⟨11/4⟩이야」","mis":"M3-2-u4-X20"}],"explanation":["⟨2 3/4⟩은 ⟨1/4⟩이 11개예요.","그래서 ⟨2 3/4⟩ = ⟨11/4⟩이고 분수 부분은 진분수 ⟨3/4⟩이에요.","서윤의 말이 틀렸어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 대분수를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은비 — 「⟨16/7⟩ = ⟨1 9/7⟩야」","correct":true,"mis_target":"M3-2-u4-X11"},{"t":"지훈 — 「대분수의 분수 부분은 진분수야」","mis":"M3-2-u4-X20"},{"t":"준우 — 「⟨2 2/7⟩는 이와 칠분의 이라고 읽어」","mis":"M3-2-u4-X20"}],"explanation":["⟨2 2/7⟩는 ⟨1/7⟩이 16개예요.","그래서 ⟨2 2/7⟩ = ⟨16/7⟩이고 분수 부분은 진분수 ⟨2/7⟩예요.","은비의 말이 틀렸어요."],"asset":null},{"stem":"이번에는 다른 문제예요. 대분수를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은비 — 「⟨34/7⟩ = ⟨3 13/7⟩이야」","correct":true,"mis_target":"M3-2-u4-X11"},{"t":"지훈 — 「대분수의 분수 부분은 진분수야」","mis":"M3-2-u4-X20"},{"t":"준우 — 「⟨4 6/7⟩은 사와 칠분의 육이라고 읽어」","mis":"M3-2-u4-X20"}],"explanation":["⟨4 6/7⟩은 ⟨1/7⟩이 34개예요.","그래서 ⟨4 6/7⟩ = ⟨34/7⟩이고 분수 부분은 진분수 ⟨6/7⟩이에요.","은비의 말이 틀렸어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L06_challenge#5','math',3,2,'u4','L06','g3_2_math_u4_L06_challenge','lesson_challenge','M3-2-u4-C7',3,'sa','auto','3보다 크고 4보다 작은 대분수예요. 분모는 4이고 분자는 짝수예요. 이 수를 가분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-2-u4-C7","difficulty":3,"kind":"sa","stem":"3보다 크고 4보다 작은 대분수예요. 분모는 4이고 분자는 짝수예요. 이 수를 가분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["3보다 크고 4보다 작으니 자연수 부분은 3이에요.","분모 4인 진분수 중 분자가 짝수인 것은 ⟨2/4⟩ — 대분수 ⟨3 2/4⟩.","3 × 4 + 2 = 14 — 가분수 ⟨14/4⟩."],"variant_rule":{"alt":[{"stem":"7보다 크고 8보다 작은 대분수예요. 분모는 4이고 분자는 짝수예요. 이 수를 가분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["7보다 크고 8보다 작으니 자연수 부분은 7이에요.","분모 4인 진분수 중 분자가 짝수인 것은 ⟨2/4⟩ — 대분수 ⟨7 2/4⟩.","7 × 4 + 2 = 30 — 가분수 ⟨30/4⟩."],"asset":null},{"stem":"3보다 크고 4보다 작은 대분수예요. 분모는 3이고 분자는 짝수예요. 이 수를 가분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["3보다 크고 4보다 작으니 자연수 부분은 3이에요.","분모 3인 진분수 중 분자가 짝수인 것은 ⟨2/3⟩ — 대분수 ⟨3 2/3⟩.","3 × 3 + 2 = 11 — 가분수 ⟨11/3⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L06_challenge#6','math',3,2,'u4','L06','g3_2_math_u4_L06_challenge','lesson_challenge','M3-2-u4-C7',3,'mc','auto','똑같은 띠 2개에 색칠했어요. 색칠한 부분을 대분수로 나타내면 무엇인가요?',ARRAY['M3-2-u4-X12','M3-2-u4-X21','M3-2-u4-X20']::text[],true,'{"seq":6,"concept":"M3-2-u4-C7","difficulty":3,"kind":"mc","stem":"똑같은 띠 2개에 색칠했어요. 색칠한 부분을 대분수로 나타내면 무엇인가요?","options":[{"t":"⟨1 1/3⟩","correct":true},{"t":"⟨1/3⟩","mis":"M3-2-u4-X12"},{"t":"⟨2 1/3⟩","mis":"M3-2-u4-X21"},{"t":"⟨1 2/3⟩","mis":"M3-2-u4-X20"}],"explanation":["통째로 색칠한 띠가 1개 — 자연수 부분 1.","남은 띠는 3칸 중 1칸 — 진분수 ⟨1/3⟩.","색칠한 부분은 ⟨1 1/3⟩이에요."],"asset":{"type":"fbar","bars":[{"den":3,"num":3},{"den":3,"num":1}]},"variant_rule":{"alt":[{"stem":"똑같은 띠 3개에 색칠했어요. 색칠한 부분을 대분수로 나타내면 무엇인가요?","options":[{"t":"⟨2 2/3⟩","correct":true},{"t":"⟨2/3⟩","mis":"M3-2-u4-X12"},{"t":"⟨3 2/3⟩","mis":"M3-2-u4-X21"},{"t":"⟨2 1/3⟩","mis":"M3-2-u4-X20"}],"explanation":["통째로 색칠한 띠가 2개 — 자연수 부분 2.","남은 띠는 3칸 중 2칸 — 진분수 ⟨2/3⟩.","색칠한 부분은 ⟨2 2/3⟩예요."],"asset":{"type":"fbar","bars":[{"den":3,"num":3},{"den":3,"num":3},{"den":3,"num":2}]}},{"stem":"이번에는 다른 문제예요. 똑같은 띠 2개에 색칠했어요. 색칠한 부분을 대분수로 나타내면 무엇인가요?","options":[{"t":"⟨1 2/8⟩","correct":true},{"t":"⟨2/8⟩","mis":"M3-2-u4-X12"},{"t":"⟨2 2/8⟩","mis":"M3-2-u4-X21"},{"t":"⟨1 6/8⟩","mis":"M3-2-u4-X20"}],"explanation":["통째로 색칠한 띠가 1개 — 자연수 부분 1.","남은 띠는 8칸 중 2칸 — 진분수 ⟨2/8⟩.","색칠한 부분은 ⟨1 2/8⟩예요."],"asset":{"type":"fbar","bars":[{"den":8,"num":8},{"den":8,"num":2}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L06_challenge#7','math',3,2,'u4','L06','g3_2_math_u4_L06_challenge','lesson_challenge','M3-2-u4-C7',3,'sa','auto','우유 ⟨3 2/4⟩ 컵을 ⟨1/4⟩ 컵씩 덜어 쓰려고 해요. 모두 몇 번 덜 수 있나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M3-2-u4-C7","difficulty":3,"kind":"sa","stem":"우유 ⟨3 2/4⟩ 컵을 ⟨1/4⟩ 컵씩 덜어 쓰려고 해요. 모두 몇 번 덜 수 있나요? 숫자로 쓰세요.","answer":["14"],"explanation":["⟨1/4⟩ 컵이 4번이면 1 컵이에요.","⟨3 2/4⟩ = ⟨1/4⟩이 12 + 2 = 14개 — 가분수 ⟨14/4⟩.","14번 덜 수 있어요."],"variant_rule":{"alt":[{"stem":"밀가루 ⟨2 1/3⟩ 컵을 ⟨1/3⟩ 컵씩 덜어 쓰려고 해요. 모두 몇 번 덜 수 있나요? 숫자로 쓰세요.","answer":["7"],"explanation":["⟨1/3⟩ 컵이 3번이면 1 컵이에요.","⟨2 1/3⟩ = ⟨1/3⟩이 6 + 1 = 7개 — 가분수 ⟨7/3⟩.","7번 덜 수 있어요."],"asset":null},{"stem":"주스 ⟨3 2/3⟩ 병을 ⟨1/3⟩ 병씩 덜어 쓰려고 해요. 모두 몇 번 덜 수 있나요? 숫자로 쓰세요.","answer":["11"],"explanation":["⟨1/3⟩ 병이 3번이면 1 병이에요.","⟨3 2/3⟩ = ⟨1/3⟩이 9 + 2 = 11개 — 가분수 ⟨11/3⟩.","11번 덜 수 있어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L06_challenge#8','math',3,2,'u4','L06','g3_2_math_u4_L06_challenge','lesson_challenge','M3-2-u4-C7',4,'essay','teacher','⟨2 3/4⟩을 가분수로 나타내고, 그 방법을 단위분수의 개수로 설명해 보세요. 또 「⟨2 3/4⟩ = ⟨5/4⟩」라고 한 친구의 잘못을 고쳐 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-2-u4-C7","difficulty":4,"kind":"essay","stem":"⟨2 3/4⟩을 가분수로 나타내고, 그 방법을 단위분수의 개수로 설명해 보세요. 또 「⟨2 3/4⟩ = ⟨5/4⟩」라고 한 친구의 잘못을 고쳐 보세요.","answer_guide":{"answer":"예: 2는 ⟨1/4⟩이 8개, ⟨3/4⟩은 ⟨1/4⟩이 3개이므로 모두 11개, 곧 ⟨11/4⟩이다. ⟨5/4⟩는 자연수 2를 ⟨1/4⟩ 8개로 바꾸지 않고 2와 3을 더한 것이라 틀렸다.","scoring_points":["⟨11/4⟩을 구했는가","2 = ⟨1/4⟩ 8개라고 설명했는가","자연수를 단위분수로 바꾸지 않은 잘못을 짚었는가"]},"explanation":["2 = ⟨8/4⟩.","⟨8/4⟩ + ⟨3/4⟩ = ⟨11/4⟩.","2를 바꾸지 않으면 틀려요."],"asset":{"type":"fbar","bars":[{"den":4,"num":4},{"den":4,"num":4},{"den":4,"num":3}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L06_challenge#9','math',3,2,'u4','L06','g3_2_math_u4_L06_challenge','lesson_challenge','M3-2-u4-C7',4,'essay','teacher','⟨5/2⟩를 대분수로 나타내고, 「⟨5/2⟩ = ⟨1 3/2⟩」가 왜 대분수가 아닌지 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-2-u4-C7","difficulty":4,"kind":"essay","stem":"⟨5/2⟩를 대분수로 나타내고, 「⟨5/2⟩ = ⟨1 3/2⟩」가 왜 대분수가 아닌지 설명해 보세요.","answer_guide":{"answer":"예: ⟨5/2⟩는 ⟨1/2⟩이 5개이고 2개씩 모으면 1이 2번 되고 ⟨1/2⟩이 남으므로 ⟨2 1/2⟩이다. ⟨1 3/2⟩은 분수 부분 ⟨3/2⟩이 가분수라서 대분수가 아니다. 대분수의 분수 부분은 반드시 진분수여야 한다.","scoring_points":["⟨2 1/2⟩을 구했는가","분수 부분 ⟨3/2⟩이 가분수라고 썼는가","대분수의 분수 부분은 진분수라고 썼는가"]},"explanation":["⟨5/2⟩ = ⟨1/2⟩ × 5개.","1이 2번 + ⟨1/2⟩.","⟨2 1/2⟩ — 분수 부분은 진분수."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L06_challenge#10','math',3,2,'u4','L06','g3_2_math_u4_L06_challenge','lesson_challenge','M3-2-u4-C7',4,'sa','auto','수 카드 1, 9, 5를 한 번씩 모두 써서 만들 수 있는 대분수 중 가장 큰 수를 가분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M3-2-u4-C7","difficulty":4,"kind":"sa","stem":"수 카드 1, 9, 5를 한 번씩 모두 써서 만들 수 있는 대분수 중 가장 큰 수를 가분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.","answer":["46"],"explanation":["가장 큰 대분수는 자연수 부분에 가장 큰 수 9를 놓아요.","남은 1, 5로 진분수 ⟨1/5⟩을 만들어요 — ⟨9 1/5⟩.","9 × 5 + 1 = 46 — 가분수 ⟨46/5⟩."],"variant_rule":{"alt":[{"stem":"수 카드 8, 4, 1을 한 번씩 모두 써서 만들 수 있는 대분수 중 가장 큰 수를 가분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.","answer":["33"],"explanation":["가장 큰 대분수는 자연수 부분에 가장 큰 수 8을 놓아요.","남은 1, 4로 진분수 ⟨1/4⟩을 만들어요 — ⟨8 1/4⟩.","8 × 4 + 1 = 33 — 가분수 ⟨33/4⟩."],"asset":null},{"stem":"수 카드 8, 7, 5를 한 번씩 모두 써서 만들 수 있는 대분수 중 가장 큰 수를 가분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.","answer":["61"],"explanation":["가장 큰 대분수는 자연수 부분에 가장 큰 수 8을 놓아요.","남은 5, 7로 진분수 ⟨5/7⟩를 만들어요 — ⟨8 5/7⟩.","8 × 7 + 5 = 61 — 가분수 ⟨61/7⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L07_basic#1','math',3,2,'u4','L07','g3_2_math_u4_L07_basic','lesson_basic','M3-2-u4-C8',1,'mc','auto','두 수의 크기를 바르게 견준 것은 무엇인가요?',ARRAY['M3-2-u4-X13','M3-2-u4-X22']::text[],true,'{"seq":1,"concept":"M3-2-u4-C8","difficulty":1,"kind":"mc","stem":"두 수의 크기를 바르게 견준 것은 무엇인가요?","options":[{"t":"⟨9/5⟩ > ⟨7/5⟩","correct":true},{"t":"⟨9/5⟩ < ⟨7/5⟩","mis":"M3-2-u4-X13"},{"t":"⟨9/5⟩ = ⟨7/5⟩","mis":"M3-2-u4-X22"},{"t":"견줄 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["분모가 5로 같아요.","⟨9/5⟩는 ⟨1/5⟩이 9개, ⟨7/5⟩은 7개예요.","분자가 큰 쪽이 커요 — ⟨9/5⟩ > ⟨7/5⟩."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 두 수의 크기를 바르게 견준 것은 무엇인가요?","options":[{"t":"⟨8/7⟩ < ⟨11/7⟩","correct":true},{"t":"⟨8/7⟩ > ⟨11/7⟩","mis":"M3-2-u4-X13"},{"t":"⟨8/7⟩ = ⟨11/7⟩","mis":"M3-2-u4-X22"},{"t":"견줄 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["분모가 7로 같아요.","⟨8/7⟩은 ⟨1/7⟩이 8개, ⟨11/7⟩은 11개예요.","분자가 큰 쪽이 커요 — ⟨8/7⟩ < ⟨11/7⟩."],"asset":null},{"stem":"이번에는 다른 문제예요. 두 수의 크기를 바르게 견준 것은 무엇인가요?","options":[{"t":"⟨9/3⟩ > ⟨5/3⟩","correct":true},{"t":"⟨9/3⟩ < ⟨5/3⟩","mis":"M3-2-u4-X13"},{"t":"⟨9/3⟩ = ⟨5/3⟩","mis":"M3-2-u4-X22"},{"t":"견줄 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["분모가 3으로 같아요.","⟨9/3⟩는 ⟨1/3⟩이 9개, ⟨5/3⟩는 5개예요.","분자가 큰 쪽이 커요 — ⟨9/3⟩ > ⟨5/3⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
