INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L07_basic#4','math',3,2,'u4','L07','g3_2_math_u4_L07_basic','lesson_basic','M3-2-u4-C8',1,'sa','auto','⟨5/3⟩는 ⟨1/3⟩이 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-2-u4-C8","difficulty":1,"kind":"sa","stem":"⟨5/3⟩는 ⟨1/3⟩이 몇 개인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["분자는 단위분수의 개수예요.","⟨5/3⟩는 ⟨1/3⟩이 5개예요.","분모가 같으면 이 개수로 크기를 견주어요."],"variant_rule":{"alt":[{"stem":"⟨11/4⟩은 ⟨1/4⟩이 몇 개인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["분자는 단위분수의 개수예요.","⟨11/4⟩은 ⟨1/4⟩이 11개예요.","분모가 같으면 이 개수로 크기를 견주어요."],"asset":null},{"stem":"⟨6/5⟩은 ⟨1/5⟩이 몇 개인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["분자는 단위분수의 개수예요.","⟨6/5⟩은 ⟨1/5⟩이 6개예요.","분모가 같으면 이 개수로 크기를 견주어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L07_basic#5','math',3,2,'u4','L07','g3_2_math_u4_L07_basic','lesson_basic','M3-2-u4-C8',2,'mc','auto','두 수의 크기를 바르게 견준 것은 무엇인가요?',ARRAY['M3-2-u4-X14','M3-2-u4-X22']::text[],true,'{"seq":5,"concept":"M3-2-u4-C8","difficulty":2,"kind":"mc","stem":"두 수의 크기를 바르게 견준 것은 무엇인가요?","options":[{"t":"⟨8/3⟩ > ⟨2 1/3⟩","correct":true},{"t":"⟨8/3⟩ < ⟨2 1/3⟩","mis":"M3-2-u4-X14"},{"t":"⟨8/3⟩ = ⟨2 1/3⟩","mis":"M3-2-u4-X22"},{"t":"견줄 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["한쪽으로 바꾸어 견주어요.","⟨2 1/3⟩ = ⟨7/3⟩이에요.","⟨8/3⟩과 ⟨7/3⟩ — ⟨8/3⟩ > ⟨2 1/3⟩ (⟨8/3⟩ = ⟨2 2/3⟩로 바꾸어도 같아요)."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 두 수의 크기를 바르게 견준 것은 무엇인가요?","options":[{"t":"⟨44/9⟩ > ⟨1 7/9⟩","correct":true},{"t":"⟨44/9⟩ < ⟨1 7/9⟩","mis":"M3-2-u4-X14"},{"t":"⟨44/9⟩ = ⟨1 7/9⟩","mis":"M3-2-u4-X22"},{"t":"견줄 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["한쪽으로 바꾸어 견주어요.","⟨1 7/9⟩ = ⟨16/9⟩이에요.","⟨44/9⟩와 ⟨16/9⟩ — ⟨44/9⟩ > ⟨1 7/9⟩ (⟨44/9⟩ = ⟨4 8/9⟩로 바꾸어도 같아요)."],"asset":null},{"stem":"이번에는 다른 문제예요. 두 수의 크기를 바르게 견준 것은 무엇인가요?","options":[{"t":"⟨3/2⟩ < ⟨3 1/2⟩","correct":true},{"t":"⟨3/2⟩ > ⟨3 1/2⟩","mis":"M3-2-u4-X14"},{"t":"⟨3/2⟩ = ⟨3 1/2⟩","mis":"M3-2-u4-X22"},{"t":"견줄 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["한쪽으로 바꾸어 견주어요.","⟨3 1/2⟩ = ⟨7/2⟩이에요.","⟨3/2⟩과 ⟨7/2⟩ — ⟨3/2⟩ < ⟨3 1/2⟩ (⟨3/2⟩ = ⟨1 1/2⟩로 바꾸어도 같아요)."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L07_basic#6','math',3,2,'u4','L07','g3_2_math_u4_L07_basic','lesson_basic','M3-2-u4-C8',2,'mc','auto','천이 ⟨7/4⟩ m와 ⟨6/4⟩ m 있어요. 어느 것이 더 긴가요?',ARRAY['M3-2-u4-X13','M3-2-u4-X22']::text[],true,'{"seq":6,"concept":"M3-2-u4-C8","difficulty":2,"kind":"mc","stem":"천이 ⟨7/4⟩ m와 ⟨6/4⟩ m 있어요. 어느 것이 더 긴가요?","options":[{"t":"⟨7/4⟩ m","correct":true},{"t":"⟨6/4⟩ m","mis":"M3-2-u4-X13"},{"t":"두 길이가 같아요","mis":"M3-2-u4-X22"},{"t":"알 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["분모가 같으면 한 조각의 길이가 같아요.","⟨1/4⟩이 7개와 6개를 견주어요.","조각이 많은 ⟨7/4⟩ m가 더 길어요."],"variant_rule":{"alt":[{"stem":"리본이 ⟨25/9⟩ m와 ⟨18/9⟩ m 있어요. 어느 것이 더 긴가요?","options":[{"t":"⟨25/9⟩ m","correct":true},{"t":"⟨18/9⟩ m","mis":"M3-2-u4-X13"},{"t":"두 길이가 같아요","mis":"M3-2-u4-X22"},{"t":"알 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["분모가 같으면 한 조각의 길이가 같아요.","⟨1/9⟩이 25개와 18개를 견주어요.","조각이 많은 ⟨25/9⟩ m가 더 길어요."],"asset":null},{"stem":"끈이 ⟨10/5⟩ m와 ⟨12/5⟩ m 있어요. 어느 것이 더 긴가요?","options":[{"t":"⟨12/5⟩ m","correct":true},{"t":"⟨10/5⟩ m","mis":"M3-2-u4-X13"},{"t":"두 길이가 같아요","mis":"M3-2-u4-X22"},{"t":"알 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["분모가 같으면 한 조각의 길이가 같아요.","⟨1/5⟩이 10개와 12개를 견주어요.","조각이 많은 ⟨12/5⟩ m가 더 길어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L07_basic#7','math',3,2,'u4','L07','g3_2_math_u4_L07_basic','lesson_basic','M3-2-u4-C8',2,'mc','auto','은비는 물을 ⟨8/3⟩ 컵, 지훈은 ⟨1 1/3⟩ 컵 마셨어요. 누가 더 많이 마셨나요?',ARRAY['M3-2-u4-X14','M3-2-u4-X22']::text[],true,'{"seq":7,"concept":"M3-2-u4-C8","difficulty":2,"kind":"mc","stem":"은비는 물을 ⟨8/3⟩ 컵, 지훈은 ⟨1 1/3⟩ 컵 마셨어요. 누가 더 많이 마셨나요?","options":[{"t":"은비","correct":true},{"t":"지훈","mis":"M3-2-u4-X14"},{"t":"두 사람이 같아요","mis":"M3-2-u4-X22"},{"t":"알 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["⟨1 1/3⟩ = ⟨4/3⟩로 바꾸어요.","⟨8/3⟩과 ⟨4/3⟩의 분자 8, 4를 견주어요.","은비가 더 많이 마셨어요."],"variant_rule":{"alt":[{"stem":"하윤은 보리차를 ⟨26/9⟩ 컵, 지훈은 ⟨2 6/9⟩ 컵 마셨어요. 누가 더 많이 마셨나요?","options":[{"t":"하윤","correct":true},{"t":"지훈","mis":"M3-2-u4-X14"},{"t":"두 사람이 같아요","mis":"M3-2-u4-X22"},{"t":"알 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["⟨2 6/9⟩ = ⟨24/9⟩로 바꾸어요.","⟨26/9⟩과 ⟨24/9⟩의 분자 26, 24를 견주어요.","하윤이 더 많이 마셨어요."],"asset":null},{"stem":"건우는 우유를 ⟨21/5⟩ 컵, 서윤은 ⟨1 2/5⟩ 컵 마셨어요. 누가 더 많이 마셨나요?","options":[{"t":"건우","correct":true},{"t":"서윤","mis":"M3-2-u4-X14"},{"t":"두 사람이 같아요","mis":"M3-2-u4-X22"},{"t":"알 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["⟨1 2/5⟩ = ⟨7/5⟩로 바꾸어요.","⟨21/5⟩과 ⟨7/5⟩의 분자 21, 7을 견주어요.","건우가 더 많이 마셨어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L07_basic#8','math',3,2,'u4','L07','g3_2_math_u4_L07_basic','lesson_basic','M3-2-u4-C8',2,'sa','auto','⟨3 1/2⟩은 ⟨1/2⟩이 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M3-2-u4-C8","difficulty":2,"kind":"sa","stem":"⟨3 1/2⟩은 ⟨1/2⟩이 몇 개인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["1은 ⟨1/2⟩이 2개예요.","3은 6개, ⟨1/2⟩은 1개 — 모두 7개.","⟨3 1/2⟩ = ⟨7/2⟩."],"variant_rule":{"alt":[{"stem":"⟨1 1/2⟩은 ⟨1/2⟩이 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["1은 ⟨1/2⟩이 2개예요.","1은 2개, ⟨1/2⟩은 1개 — 모두 3개.","⟨1 1/2⟩ = ⟨3/2⟩."],"asset":null},{"stem":"⟨3 1/8⟩은 ⟨1/8⟩이 몇 개인가요? 숫자로 쓰세요.","answer":["25"],"explanation":["1은 ⟨1/8⟩이 8개예요.","3은 24개, ⟨1/8⟩은 1개 — 모두 25개.","⟨3 1/8⟩ = ⟨25/8⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L07_basic#9','math',3,2,'u4','L07','g3_2_math_u4_L07_basic','lesson_basic','M3-2-u4-C8',2,'ox','auto','채원이 「⟨2 2/4⟩의 분수 부분이 더 크니까 ⟨3 1/4⟩보다 커.」라고 했어요. 바르게 말했어요.',ARRAY['M3-2-u4-X13']::text[],true,'{"seq":9,"concept":"M3-2-u4-C8","difficulty":2,"kind":"ox","stem":"채원이 「⟨2 2/4⟩의 분수 부분이 더 크니까 ⟨3 1/4⟩보다 커.」라고 했어요. 바르게 말했어요.","answer":"X","reason_options":[{"t":"자연수 부분 3이 2보다 커서 ⟨3 1/4⟩이 더 크니까","correct":true},{"t":"분수 부분 ⟨2/4⟩가 더 커서","mis":"M3-2-u4-X13"}],"mis":"M3-2-u4-X13","explanation":["대분수는 자연수 부분부터 견주어요.","3 > 2예요.","⟨3 1/4⟩ > ⟨2 2/4⟩ — ×."],"variant_rule":{"alt":[{"stem":"준우가 「⟨3 4/5⟩의 분수 부분이 더 크니까 ⟨5 3/5⟩보다 커.」라고 했어요. 바르게 말했어요.","answer":"X","reason_options":[{"t":"자연수 부분 5가 3보다 커서 ⟨5 3/5⟩이 더 크니까","correct":true},{"t":"분수 부분 ⟨4/5⟩가 더 커서","mis":"M3-2-u4-X13"}],"explanation":["대분수는 자연수 부분부터 견주어요.","5 > 3이에요.","⟨5 3/5⟩ > ⟨3 4/5⟩ — ×."],"asset":null},{"stem":"하윤이 「⟨3 6/7⟩의 분수 부분이 더 크니까 ⟨4 3/7⟩보다 커.」라고 했어요. 바르게 말했어요.","answer":"X","reason_options":[{"t":"자연수 부분 4가 3보다 커서 ⟨4 3/7⟩이 더 크니까","correct":true},{"t":"분수 부분 ⟨6/7⟩이 더 커서","mis":"M3-2-u4-X13"}],"explanation":["대분수는 자연수 부분부터 견주어요.","4 > 3이에요.","⟨4 3/7⟩ > ⟨3 6/7⟩ — ×."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
