INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L07_challenge#5','math',3,2,'u4','L07','g3_2_math_u4_L07_challenge','lesson_challenge','M3-2-u4-C8',3,'sa','auto','□⟨2/7⟩ < ⟨30/7⟩에서 □ 안에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-2-u4-C8","difficulty":3,"kind":"sa","stem":"□⟨2/7⟩ < ⟨30/7⟩에서 □ 안에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["⟨30/7⟩ = ⟨4 2/7⟩ — 자연수 부분을 찾아요.","□가 3이면 ⟨23/7⟩으로 작고, 4이면 ⟨30/7⟩으로 같거나 커요.","□는 1부터 3까지 — 모두 3개."],"variant_rule":{"alt":[{"stem":"□⟨3/8⟩ < ⟨30/8⟩에서 □ 안에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["⟨30/8⟩ = ⟨3 6/8⟩ — 자연수 부분을 찾아요.","□가 3이면 ⟨27/8⟩로 작고, 4이면 ⟨35/8⟩로 같거나 커요.","□는 1부터 3까지 — 모두 3개."],"asset":null},{"stem":"□⟨1/3⟩ < ⟨18/3⟩에서 □ 안에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["⟨18/3⟩ = 6 — 자연수 부분을 찾아요.","□가 5이면 ⟨16/3⟩으로 작고, 6이면 ⟨19/3⟩로 같거나 커요.","□는 1부터 5까지 — 모두 5개."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
