INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L07_challenge#7','math',3,2,'u4','L07','g3_2_math_u4_L07_challenge','lesson_challenge','M3-2-u4-C8',3,'mc','auto','두 수의 크기를 바르게 견준 것은 무엇인가요?',ARRAY['M3-2-u4-X13','M3-2-u4-X22']::text[],true,'{"seq":7,"concept":"M3-2-u4-C8","difficulty":3,"kind":"mc","stem":"두 수의 크기를 바르게 견준 것은 무엇인가요?","options":[{"t":"⟨3 3/6⟩ > ⟨1 4/6⟩","correct":true},{"t":"⟨3 3/6⟩ < ⟨1 4/6⟩","mis":"M3-2-u4-X13"},{"t":"⟨3 3/6⟩ = ⟨1 4/6⟩","mis":"M3-2-u4-X22"},{"t":"견줄 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["대분수는 자연수 부분부터 견주어요.","3 > 1 — 자연수 부분이 큰 쪽이 커요.","분수 부분은 1보다 작아서 뒤집지 못해요 — ⟨3 3/6⟩ > ⟨1 4/6⟩."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 두 수의 크기를 바르게 견준 것은 무엇인가요?","options":[{"t":"⟨5 3/7⟩ > ⟨4 4/7⟩","correct":true},{"t":"⟨5 3/7⟩ < ⟨4 4/7⟩","mis":"M3-2-u4-X13"},{"t":"⟨5 3/7⟩ = ⟨4 4/7⟩","mis":"M3-2-u4-X22"},{"t":"견줄 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["대분수는 자연수 부분부터 견주어요.","5 > 4 — 자연수 부분이 큰 쪽이 커요.","분수 부분은 1보다 작아서 뒤집지 못해요 — ⟨5 3/7⟩ > ⟨4 4/7⟩."],"asset":null},{"stem":"이번에는 다른 문제예요. 두 수의 크기를 바르게 견준 것은 무엇인가요?","options":[{"t":"⟨2 2/8⟩ > ⟨1 2/8⟩","correct":true},{"t":"⟨2 2/8⟩ < ⟨1 2/8⟩","mis":"M3-2-u4-X13"},{"t":"⟨2 2/8⟩ = ⟨1 2/8⟩","mis":"M3-2-u4-X22"},{"t":"견줄 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["대분수는 자연수 부분부터 견주어요.","2 > 1 — 자연수 부분이 큰 쪽이 커요.","분수 부분은 1보다 작아서 뒤집지 못해요 — ⟨2 2/8⟩ > ⟨1 2/8⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L07_challenge#8','math',3,2,'u4','L07','g3_2_math_u4_L07_challenge','lesson_challenge','M3-2-u4-C8',4,'essay','teacher','⟨3 2/6⟩와 ⟨16/6⟩ 중 어느 수가 더 큰지 쓰고, 두 가지 방법(가분수로 바꾸기, 대분수로 바꾸기)으로 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-2-u4-C8","difficulty":4,"kind":"essay","stem":"⟨3 2/6⟩와 ⟨16/6⟩ 중 어느 수가 더 큰지 쓰고, 두 가지 방법(가분수로 바꾸기, 대분수로 바꾸기)으로 설명해 보세요.","answer_guide":{"answer":"예: ⟨3 2/6⟩가 더 크다. ① ⟨3 2/6⟩ = ⟨20/6⟩이고 20 > 16이므로 ⟨3 2/6⟩가 크다. ② ⟨16/6⟩ = ⟨2 4/6⟩이고 자연수 부분 3 > 2이므로 ⟨3 2/6⟩가 크다.","scoring_points":["⟨3 2/6⟩가 크다고 답했는가","가분수로 바꾸어 견주었는가","대분수로 바꾸어 견주었는가"]},"explanation":["⟨3 2/6⟩ = ⟨20/6⟩ > ⟨16/6⟩.","⟨16/6⟩ = ⟨2 4/6⟩ < ⟨3 2/6⟩.","⟨3 2/6⟩가 더 커요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L07_challenge#9','math',3,2,'u4','L07','g3_2_math_u4_L07_challenge','lesson_challenge','M3-2-u4-C8',4,'essay','teacher','도연이가 「⟨1 4/5⟩는 분수 부분 ⟨4/5⟩가 ⟨1/5⟩보다 크니까 ⟨2 1/5⟩보다 커.」라고 했어요. 도연이의 말이 맞는지 판단하고 까닭을 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-2-u4-C8","difficulty":4,"kind":"essay","stem":"도연이가 「⟨1 4/5⟩는 분수 부분 ⟨4/5⟩가 ⟨1/5⟩보다 크니까 ⟨2 1/5⟩보다 커.」라고 했어요. 도연이의 말이 맞는지 판단하고 까닭을 써 보세요.","answer_guide":{"answer":"예: 틀렸다. 대분수는 자연수 부분부터 견준다. 자연수 부분이 2 > 1이므로 ⟨2 1/5⟩이 더 크다. 분수 부분은 1보다 작아서 자연수 부분의 차이를 뒤집지 못한다.","scoring_points":["틀렸다고 판단했는가","자연수 부분부터 견주어야 한다고 썼는가","⟨2 1/5⟩이 더 크다고 답했는가"]},"explanation":["자연수 부분 2 > 1.","분수 부분은 1보다 작아요.","⟨2 1/5⟩ > ⟨1 4/5⟩."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L07_challenge#10','math',3,2,'u4','L07','g3_2_math_u4_L07_challenge','lesson_challenge','M3-2-u4-C8',4,'sa','auto','□⟨3/9⟩ < ⟨46/9⟩에서 □ 안에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M3-2-u4-C8","difficulty":4,"kind":"sa","stem":"□⟨3/9⟩ < ⟨46/9⟩에서 □ 안에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["⟨46/9⟩ = ⟨5 1/9⟩ — 자연수 부분을 찾아요.","□가 4이면 ⟨39/9⟩로 작고, 5이면 ⟨48/9⟩로 같거나 커요.","□는 1부터 4까지 — 모두 4개."],"variant_rule":{"alt":[{"stem":"□⟨3/4⟩ < ⟨12/4⟩에서 □ 안에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["⟨12/4⟩ = 3 — 자연수 부분을 찾아요.","□가 2이면 ⟨11/4⟩로 작고, 3이면 ⟨15/4⟩로 같거나 커요.","□는 1부터 2까지 — 모두 2개."],"asset":null},{"stem":"□⟨2/3⟩ < ⟨18/3⟩에서 □ 안에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["⟨18/3⟩ = 6 — 자연수 부분을 찾아요.","□가 5이면 ⟨17/3⟩로 작고, 6이면 ⟨20/3⟩으로 같거나 커요.","□는 1부터 5까지 — 모두 5개."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L08_basic#1','math',3,2,'u4','L08','g3_2_math_u4_L08_basic','lesson_basic','M3-2-u4-C9',1,'sa','auto','2.9는 0.1이 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M3-2-u4-C9","difficulty":1,"kind":"sa","stem":"2.9는 0.1이 몇 개인가요? 숫자로 쓰세요.","answer":["29"],"explanation":["1은 0.1이 10개예요 — 2는 0.1이 20개.","0.9는 0.1이 9개예요.","2.9는 0.1이 20 + 9 = 29개."],"variant_rule":{"alt":[{"stem":"3.8은 0.1이 몇 개인가요? 숫자로 쓰세요.","answer":["38"],"explanation":["1은 0.1이 10개예요 — 3은 0.1이 30개.","0.8은 0.1이 8개예요.","3.8은 0.1이 30 + 8 = 38개."],"asset":null},{"stem":"1.5는 0.1이 몇 개인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["1은 0.1이 10개예요 — 1은 0.1이 10개.","0.5는 0.1이 5개예요.","1.5는 0.1이 10 + 5 = 15개."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L08_basic#2','math',3,2,'u4','L08','g3_2_math_u4_L08_basic','lesson_basic','M3-2-u4-C9',1,'mc','auto','0.1이 35개인 수는 무엇인가요?',ARRAY['M3-2-u4-X17','M3-2-u4-X16']::text[],true,'{"seq":2,"concept":"M3-2-u4-C9","difficulty":1,"kind":"mc","stem":"0.1이 35개인 수는 무엇인가요?","options":[{"t":"3.5","correct":true},{"t":"35","mis":"M3-2-u4-X17"},{"t":"0.35","mis":"M3-2-u4-X17"},{"t":"5.3","mis":"M3-2-u4-X16"}],"explanation":["0.1이 10개면 1이에요.","0.1이 35개 = 1이 3개와 0.1이 5개.","그래서 3.5예요."],"variant_rule":{"alt":[{"stem":"0.1이 81개인 수는 무엇인가요?","options":[{"t":"8.1","correct":true},{"t":"81","mis":"M3-2-u4-X17"},{"t":"0.81","mis":"M3-2-u4-X17"},{"t":"1.8","mis":"M3-2-u4-X16"}],"explanation":["0.1이 10개면 1이에요.","0.1이 81개 = 1이 8개와 0.1이 1개.","그래서 8.1이에요."],"asset":null},{"stem":"0.1이 34개인 수는 무엇인가요?","options":[{"t":"3.4","correct":true},{"t":"34","mis":"M3-2-u4-X17"},{"t":"0.34","mis":"M3-2-u4-X17"},{"t":"4.3","mis":"M3-2-u4-X16"}],"explanation":["0.1이 10개면 1이에요.","0.1이 34개 = 1이 3개와 0.1이 4개.","그래서 3.4예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L08_basic#3','math',3,2,'u4','L08','g3_2_math_u4_L08_basic','lesson_basic','M3-2-u4-C9',1,'sa','auto','4.6 cm는 몇 mm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-2-u4-C9","difficulty":1,"kind":"sa","stem":"4.6 cm는 몇 mm인가요? 숫자로 쓰세요.","answer":["46"],"explanation":["1 cm = 10 mm, 0.1 cm = 1 mm예요.","4.6 cm = 4 cm 6 mm예요.","4 cm 6 mm = 46 mm."],"variant_rule":{"alt":[{"stem":"4.9 cm는 몇 mm인가요? 숫자로 쓰세요.","answer":["49"],"explanation":["1 cm = 10 mm, 0.1 cm = 1 mm예요.","4.9 cm = 4 cm 9 mm예요.","4 cm 9 mm = 49 mm."],"asset":null},{"stem":"9.4 cm는 몇 mm인가요? 숫자로 쓰세요.","answer":["94"],"explanation":["1 cm = 10 mm, 0.1 cm = 1 mm예요.","9.4 cm = 9 cm 4 mm예요.","9 cm 4 mm = 94 mm."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L08_basic#4','math',3,2,'u4','L08','g3_2_math_u4_L08_basic','lesson_basic','M3-2-u4-C9',1,'mc','auto','2와 0.4만큼인 수는 무엇인가요?',ARRAY['M3-2-u4-X16','M3-2-u4-X17']::text[],true,'{"seq":4,"concept":"M3-2-u4-C9","difficulty":1,"kind":"mc","stem":"2와 0.4만큼인 수는 무엇인가요?","options":[{"t":"2.4","correct":true},{"t":"4.2","mis":"M3-2-u4-X16"},{"t":"24","mis":"M3-2-u4-X17"},{"t":"2.04","mis":"M3-2-u4-X17"}],"explanation":["자연수 2는 소수점 앞에 써요.","0.4는 소수점 뒤 자리 4예요.","2와 0.4만큼은 2.4 — 「이 점 사」."],"variant_rule":{"alt":[{"stem":"6과 0.7만큼인 수는 무엇인가요?","options":[{"t":"6.7","correct":true},{"t":"7.6","mis":"M3-2-u4-X16"},{"t":"67","mis":"M3-2-u4-X17"},{"t":"6.07","mis":"M3-2-u4-X17"}],"explanation":["자연수 6은 소수점 앞에 써요.","0.7은 소수점 뒤 자리 7이에요.","6과 0.7만큼은 6.7 — 「육 점 칠」."],"asset":null},{"stem":"3과 0.6만큼인 수는 무엇인가요?","options":[{"t":"3.6","correct":true},{"t":"6.3","mis":"M3-2-u4-X16"},{"t":"36","mis":"M3-2-u4-X17"},{"t":"3.06","mis":"M3-2-u4-X17"}],"explanation":["자연수 3은 소수점 앞에 써요.","0.6은 소수점 뒤 자리 6이에요.","3과 0.6만큼은 3.6 — 「삼 점 육」."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L08_basic#5','math',3,2,'u4','L08','g3_2_math_u4_L08_basic','lesson_basic','M3-2-u4-C9',2,'mc','auto','종이 빨대의 길이는 4 cm 7 mm예요. 몇 cm인지 소수로 나타내면 얼마인가요?',ARRAY['M3-2-u4-X17','M3-2-u4-X16']::text[],true,'{"seq":5,"concept":"M3-2-u4-C9","difficulty":2,"kind":"mc","stem":"종이 빨대의 길이는 4 cm 7 mm예요. 몇 cm인지 소수로 나타내면 얼마인가요?","options":[{"t":"4.7 cm","correct":true},{"t":"4.07 cm","mis":"M3-2-u4-X17"},{"t":"47 cm","mis":"M3-2-u4-X17"},{"t":"7.4 cm","mis":"M3-2-u4-X16"}],"explanation":["1 mm = ⟨1/10⟩ cm = 0.1 cm예요.","7 mm는 0.7 cm — 4 cm 7 mm = ⟨4 7/10⟩ cm.","⟨4 7/10⟩ cm = 4.7 cm."],"asset":{"type":"mmruler","len":47,"label":"종이 빨대"},"variant_rule":{"alt":[{"stem":"애벌레의 길이는 6 cm 4 mm예요. 몇 cm인지 소수로 나타내면 얼마인가요?","options":[{"t":"6.4 cm","correct":true},{"t":"6.04 cm","mis":"M3-2-u4-X17"},{"t":"64 cm","mis":"M3-2-u4-X17"},{"t":"4.6 cm","mis":"M3-2-u4-X16"}],"explanation":["1 mm = ⟨1/10⟩ cm = 0.1 cm예요.","4 mm는 0.4 cm — 6 cm 4 mm = ⟨6 4/10⟩ cm.","⟨6 4/10⟩ cm = 6.4 cm."],"asset":{"type":"mmruler","len":64,"label":"애벌레"}},{"stem":"지우개의 길이는 6 cm 7 mm예요. 몇 cm인지 소수로 나타내면 얼마인가요?","options":[{"t":"6.7 cm","correct":true},{"t":"6.07 cm","mis":"M3-2-u4-X17"},{"t":"67 cm","mis":"M3-2-u4-X17"},{"t":"7.6 cm","mis":"M3-2-u4-X16"}],"explanation":["1 mm = ⟨1/10⟩ cm = 0.1 cm예요.","7 mm는 0.7 cm — 6 cm 7 mm = ⟨6 7/10⟩ cm.","⟨6 7/10⟩ cm = 6.7 cm."],"asset":{"type":"mmruler","len":67,"label":"지우개"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L08_basic#6','math',3,2,'u4','L08','g3_2_math_u4_L08_basic','lesson_basic','M3-2-u4-C9',2,'mc','auto','수직선의 한 칸은 0.1이에요. ?가 나타내는 소수는 무엇인가요?',ARRAY['M3-2-u4-X21','M3-2-u4-X16']::text[],true,'{"seq":6,"concept":"M3-2-u4-C9","difficulty":2,"kind":"mc","stem":"수직선의 한 칸은 0.1이에요. ?가 나타내는 소수는 무엇인가요?","options":[{"t":"1.9","correct":true},{"t":"2","mis":"M3-2-u4-X21"},{"t":"1.8","mis":"M3-2-u4-X21"},{"t":"9.1","mis":"M3-2-u4-X16"}],"explanation":["오른쪽으로 한 칸 갈 때마다 0.1씩 커져요.","앞뒤의 수를 보면 1.8 다음 자리예요.","?는 1.9예요."],"asset":{"type":"number_line","cells":["1.6","1.7","1.8","?","2"]},"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 수직선의 한 칸은 0.1이에요. ?가 나타내는 소수는 무엇인가요?","options":[{"t":"5.7","correct":true},{"t":"5.8","mis":"M3-2-u4-X21"},{"t":"5.6","mis":"M3-2-u4-X21"},{"t":"7.5","mis":"M3-2-u4-X16"}],"explanation":["오른쪽으로 한 칸 갈 때마다 0.1씩 커져요.","앞뒤의 수를 보면 5.6 다음 자리예요.","?는 5.7이에요."],"asset":{"type":"number_line","cells":["5.3","5.4","5.5","5.6","?"]}},{"stem":"이번에는 다른 문제예요. 수직선의 한 칸은 0.1이에요. ?가 나타내는 소수는 무엇인가요?","options":[{"t":"4.3","correct":true},{"t":"4.4","mis":"M3-2-u4-X21"},{"t":"4.2","mis":"M3-2-u4-X21"},{"t":"3.4","mis":"M3-2-u4-X16"}],"explanation":["오른쪽으로 한 칸 갈 때마다 0.1씩 커져요.","앞뒤의 수를 보면 4.2 다음 자리예요.","?는 4.3이에요."],"asset":{"type":"number_line","cells":["4","4.1","4.2","?","4.4"]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L08_basic#7','math',3,2,'u4','L08','g3_2_math_u4_L08_basic','lesson_basic','M3-2-u4-C9',2,'mc','auto','9.3을 바르게 읽은 것은 무엇인가요?',ARRAY['M3-2-u4-X16','M3-2-u4-X15']::text[],true,'{"seq":7,"concept":"M3-2-u4-C9","difficulty":2,"kind":"mc","stem":"9.3을 바르게 읽은 것은 무엇인가요?","options":[{"t":"구 점 삼","correct":true},{"t":"삼 점 구","mis":"M3-2-u4-X16"},{"t":"구십삼","mis":"M3-2-u4-X15"},{"t":"구 점 삼십","mis":"M3-2-u4-X16"}],"explanation":["소수점 앞의 자연수를 먼저 읽어요 — 구.","소수점은 「점」, 소수점 뒤 숫자는 하나씩 읽어요 — 삼.","9.3은 「구 점 삼」."],"variant_rule":{"alt":[{"stem":"5.1을 바르게 읽은 것은 무엇인가요?","options":[{"t":"오 점 일","correct":true},{"t":"일 점 오","mis":"M3-2-u4-X16"},{"t":"오십일","mis":"M3-2-u4-X15"},{"t":"오 점 일십","mis":"M3-2-u4-X16"}],"explanation":["소수점 앞의 자연수를 먼저 읽어요 — 오.","소수점은 「점」, 소수점 뒤 숫자는 하나씩 읽어요 — 일.","5.1은 「오 점 일」."],"asset":null},{"stem":"3.8을 바르게 읽은 것은 무엇인가요?","options":[{"t":"삼 점 팔","correct":true},{"t":"팔 점 삼","mis":"M3-2-u4-X16"},{"t":"삼십팔","mis":"M3-2-u4-X15"},{"t":"삼 점 팔십","mis":"M3-2-u4-X16"}],"explanation":["소수점 앞의 자연수를 먼저 읽어요 — 삼.","소수점은 「점」, 소수점 뒤 숫자는 하나씩 읽어요 — 팔.","3.8은 「삼 점 팔」."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L08_basic#8','math',3,2,'u4','L08','g3_2_math_u4_L08_basic','lesson_basic','M3-2-u4-C9',2,'sa','auto','머리핀의 길이는 2 cm 8 mm예요. 0.1 cm가 몇 개인 길이인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M3-2-u4-C9","difficulty":2,"kind":"sa","stem":"머리핀의 길이는 2 cm 8 mm예요. 0.1 cm가 몇 개인 길이인가요? 숫자로 쓰세요.","answer":["28"],"explanation":["1 cm = 0.1 cm가 10개 — 2 cm는 20개.","8 mm = 0.1 cm가 8개.","모두 28개 — 2.8 cm."],"asset":{"type":"mmruler","len":28,"label":"머리핀"},"variant_rule":{"alt":[{"stem":"크레파스의 길이는 8 cm 3 mm예요. 0.1 cm가 몇 개인 길이인가요? 숫자로 쓰세요.","answer":["83"],"explanation":["1 cm = 0.1 cm가 10개 — 8 cm는 80개.","3 mm = 0.1 cm가 3개.","모두 83개 — 8.3 cm."],"asset":{"type":"mmruler","len":83,"label":"크레파스"}},{"stem":"나뭇잎의 길이는 7 cm 8 mm예요. 0.1 cm가 몇 개인 길이인가요? 숫자로 쓰세요.","answer":["78"],"explanation":["1 cm = 0.1 cm가 10개 — 7 cm는 70개.","8 mm = 0.1 cm가 8개.","모두 78개 — 7.8 cm."],"asset":{"type":"mmruler","len":78,"label":"나뭇잎"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L08_basic#9','math',3,2,'u4','L08','g3_2_math_u4_L08_basic','lesson_basic','M3-2-u4-C9',2,'mc','auto','⟨5 8/10⟩을 소수로 나타낸 것은 무엇인가요?',ARRAY['M3-2-u4-X16','M3-2-u4-X17']::text[],true,'{"seq":9,"concept":"M3-2-u4-C9","difficulty":2,"kind":"mc","stem":"⟨5 8/10⟩을 소수로 나타낸 것은 무엇인가요?","options":[{"t":"5.8","correct":true},{"t":"8.5","mis":"M3-2-u4-X16"},{"t":"58","mis":"M3-2-u4-X17"},{"t":"5.08","mis":"M3-2-u4-X17"}],"explanation":["⟨5 8/10⟩은 5와 ⟨8/10⟩이에요.","⟨8/10⟩ = 0.8이에요.","⟨5 8/10⟩ = 5.8."],"variant_rule":{"alt":[{"stem":"⟨9 9/10⟩를 소수로 나타낸 것은 무엇인가요?","options":[{"t":"9.9","correct":true},{"t":"99","mis":"M3-2-u4-X17"},{"t":"9.09","mis":"M3-2-u4-X17"},{"t":"9.1","mis":"M3-2-u4-X17"}],"explanation":["⟨9 9/10⟩는 9와 ⟨9/10⟩예요.","⟨9/10⟩ = 0.9예요.","⟨9 9/10⟩ = 9.9."],"asset":null},{"stem":"⟨6 5/10⟩를 소수로 나타낸 것은 무엇인가요?","options":[{"t":"6.5","correct":true},{"t":"5.6","mis":"M3-2-u4-X16"},{"t":"65","mis":"M3-2-u4-X17"},{"t":"6.05","mis":"M3-2-u4-X17"}],"explanation":["⟨6 5/10⟩는 6과 ⟨5/10⟩예요.","⟨5/10⟩ = 0.5예요.","⟨6 5/10⟩ = 6.5."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L08_basic#10','math',3,2,'u4','L08','g3_2_math_u4_L08_basic','lesson_basic','M3-2-u4-C9',3,'error','auto','소수를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u4-X16','M3-2-u4-X20']::text[],true,'{"seq":10,"concept":"M3-2-u4-C9","difficulty":3,"kind":"error","stem":"소수를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서준 — 「⟨8 6/10⟩ = 6.8이야」","correct":true,"mis_target":"M3-2-u4-X16"},{"t":"도연 — 「8 cm 6 mm = 8.6 cm야」","mis":"M3-2-u4-X20"},{"t":"건우 — 「8.6은 팔 점 육이라고 읽어」","mis":"M3-2-u4-X20"}],"explanation":["8.6 = ⟨8 6/10⟩, 0.1이 86개예요.","1 mm = 0.1 cm예요.","서준의 말이 틀렸어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 소수를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하윤 — 「⟨8 5/10⟩ = 5.8이야」","correct":true,"mis_target":"M3-2-u4-X16"},{"t":"서준 — 「8.5는 0.1이 85개야」","mis":"M3-2-u4-X20"},{"t":"건우 — 「8.5는 팔 점 오라고 읽어」","mis":"M3-2-u4-X20"}],"explanation":["8.5 = ⟨8 5/10⟩, 0.1이 85개예요.","1 mm = 0.1 cm예요.","하윤의 말이 틀렸어요."],"asset":null},{"stem":"이번에는 다른 문제예요. 소수를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도연 — 「4.7은 0.1이 7개야」","correct":true,"mis_target":"M3-2-u4-X15"},{"t":"하윤 — 「4.7은 사 점 칠이라고 읽어」","mis":"M3-2-u4-X20"},{"t":"민서 — 「4.7은 0.1이 47개야」","mis":"M3-2-u4-X20"}],"explanation":["4.7 = ⟨4 7/10⟩, 0.1이 47개예요.","1 mm = 0.1 cm예요.","도연의 말이 틀렸어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L08_challenge#1','math',3,2,'u4','L08','g3_2_math_u4_L08_challenge','lesson_challenge','M3-2-u4-C9',2,'mc','auto','3.3은 0.1이 몇 개인가요?',ARRAY['M3-2-u4-X15','M3-2-u4-X17','M3-2-u4-X21']::text[],true,'{"seq":1,"concept":"M3-2-u4-C9","difficulty":2,"kind":"mc","stem":"3.3은 0.1이 몇 개인가요?","options":[{"t":"33개","correct":true},{"t":"3개","mis":"M3-2-u4-X15"},{"t":"6개","mis":"M3-2-u4-X17"},{"t":"43개","mis":"M3-2-u4-X21"}],"explanation":["1은 0.1이 10개예요 — 3은 0.1이 30개.","0.3은 0.1이 3개예요.","3.3은 0.1이 30 + 3 = 33개."],"variant_rule":{"alt":[{"stem":"9.6은 0.1이 몇 개인가요?","options":[{"t":"96개","correct":true},{"t":"6개","mis":"M3-2-u4-X15"},{"t":"15개","mis":"M3-2-u4-X17"},{"t":"106개","mis":"M3-2-u4-X21"}],"explanation":["1은 0.1이 10개예요 — 9는 0.1이 90개.","0.6은 0.1이 6개예요.","9.6은 0.1이 90 + 6 = 96개."],"asset":null},{"stem":"5.5는 0.1이 몇 개인가요?","options":[{"t":"55개","correct":true},{"t":"5개","mis":"M3-2-u4-X15"},{"t":"10개","mis":"M3-2-u4-X17"},{"t":"65개","mis":"M3-2-u4-X21"}],"explanation":["1은 0.1이 10개예요 — 5는 0.1이 50개.","0.5는 0.1이 5개예요.","5.5는 0.1이 50 + 5 = 55개."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L08_challenge#2','math',3,2,'u4','L08','g3_2_math_u4_L08_challenge','lesson_challenge','M3-2-u4-C9',2,'match','auto','같은 수끼리 알맞게 이으세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u4-C9","difficulty":2,"kind":"match","stem":"같은 수끼리 알맞게 이으세요.","pairs":[{"l":"⟨6 7/10⟩","r":"6.7"},{"l":"⟨4 1/10⟩","r":"4.1"},{"l":"⟨1 7/10⟩","r":"1.7"}],"mis":"M3-2-u4-X16","explanation":["⟨△/10⟩ = 0.△이에요.","⟨6 7/10⟩ = 6.7, ⟨4 1/10⟩ = 4.1, ⟨1 7/10⟩ = 1.7.","자연수는 소수점 앞, 십분의 몇은 소수점 뒤."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 같은 수끼리 알맞게 이으세요.","pairs":[{"l":"⟨7 3/10⟩","r":"7.3"},{"l":"⟨6 6/10⟩","r":"6.6"},{"l":"⟨5 7/10⟩","r":"5.7"}],"explanation":["⟨△/10⟩ = 0.△이에요.","⟨7 3/10⟩ = 7.3, ⟨6 6/10⟩ = 6.6, ⟨5 7/10⟩ = 5.7.","자연수는 소수점 앞, 십분의 몇은 소수점 뒤."],"asset":null},{"stem":"이번에는 다른 문제예요. 같은 수끼리 알맞게 이으세요.","pairs":[{"l":"⟨7 8/10⟩","r":"7.8"},{"l":"⟨2 8/10⟩","r":"2.8"},{"l":"⟨3 9/10⟩","r":"3.9"}],"explanation":["⟨△/10⟩ = 0.△이에요.","⟨7 8/10⟩ = 7.8, ⟨2 8/10⟩ = 2.8, ⟨3 9/10⟩ = 3.9.","자연수는 소수점 앞, 십분의 몇은 소수점 뒤."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L08_challenge#3','math',3,2,'u4','L08','g3_2_math_u4_L08_challenge','lesson_challenge','M3-2-u4-C9',3,'ox','auto','서윤이 「4 cm 7 mm는 4.07 cm야.」라고 했어요. 바르게 말했어요.',ARRAY['M3-2-u4-X17']::text[],true,'{"seq":3,"concept":"M3-2-u4-C9","difficulty":3,"kind":"ox","stem":"서윤이 「4 cm 7 mm는 4.07 cm야.」라고 했어요. 바르게 말했어요.","answer":"X","reason_options":[{"t":"7 mm는 0.7 cm라서 4.7 cm니까","correct":true},{"t":"mm는 소수 둘째 자리라서","mis":"M3-2-u4-X17"}],"mis":"M3-2-u4-X17","explanation":["1 mm = 0.1 cm예요.","7 mm = 0.7 cm예요.","4 cm 7 mm = 4.7 cm — ×."],"variant_rule":{"alt":[{"stem":"서윤이 「5.1은 0.1이 1개야.」라고 했어요. 바르게 말했어요.","answer":"X","reason_options":[{"t":"5도 0.1이 50개라서 모두 51개니까","correct":true},{"t":"소수점 뒤 숫자만 0.1의 개수라서","mis":"M3-2-u4-X15"}],"explanation":["1은 0.1이 10개예요 — 5는 0.1이 50개.","0.1은 0.1이 1개예요.","5.1은 0.1이 50 + 1 = 51개."],"asset":null},{"stem":"건우가 「7.6은 0.1이 6개야.」라고 했어요. 바르게 말했어요.","answer":"X","reason_options":[{"t":"7도 0.1이 70개라서 모두 76개니까","correct":true},{"t":"소수점 뒤 숫자만 0.1의 개수라서","mis":"M3-2-u4-X15"}],"explanation":["1은 0.1이 10개예요 — 7은 0.1이 70개.","0.6은 0.1이 6개예요.","7.6은 0.1이 70 + 6 = 76개."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L08_challenge#4','math',3,2,'u4','L08','g3_2_math_u4_L08_challenge','lesson_challenge','M3-2-u4-C9',3,'mc','auto','수직선의 한 칸은 0.1이에요. ?가 나타내는 소수는 무엇인가요?',ARRAY['M3-2-u4-X21','M3-2-u4-X16']::text[],true,'{"seq":4,"concept":"M3-2-u4-C9","difficulty":3,"kind":"mc","stem":"수직선의 한 칸은 0.1이에요. ?가 나타내는 소수는 무엇인가요?","options":[{"t":"8.5","correct":true},{"t":"8.6","mis":"M3-2-u4-X21"},{"t":"8.4","mis":"M3-2-u4-X21"},{"t":"5.8","mis":"M3-2-u4-X16"}],"explanation":["오른쪽으로 한 칸 갈 때마다 0.1씩 커져요.","앞뒤의 수를 보면 8.4 다음 자리예요.","?는 8.5예요."],"asset":{"type":"number_line","cells":["8.3","8.4","?","8.6","8.7"]},"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 수직선의 한 칸은 0.1이에요. ?가 나타내는 소수는 무엇인가요?","options":[{"t":"6.6","correct":true},{"t":"6.7","mis":"M3-2-u4-X21"},{"t":"6.5","mis":"M3-2-u4-X21"},{"t":"0.6","mis":"M3-2-u4-X15"}],"explanation":["오른쪽으로 한 칸 갈 때마다 0.1씩 커져요.","앞뒤의 수를 보면 6.5 다음 자리예요.","?는 6.6이에요."],"asset":{"type":"number_line","cells":["6.2","6.3","6.4","6.5","?"]}},{"stem":"이번에는 다른 문제예요. 수직선의 한 칸은 0.1이에요. ?가 나타내는 소수는 무엇인가요?","options":[{"t":"6.9","correct":true},{"t":"7","mis":"M3-2-u4-X21"},{"t":"6.8","mis":"M3-2-u4-X21"},{"t":"9.6","mis":"M3-2-u4-X16"}],"explanation":["오른쪽으로 한 칸 갈 때마다 0.1씩 커져요.","앞뒤의 수를 보면 6.8 다음 자리예요.","?는 6.9예요."],"asset":{"type":"number_line","cells":["6.8","?","7","7.1","7.2"]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L08_challenge#5','math',3,2,'u4','L08','g3_2_math_u4_L08_challenge','lesson_challenge','M3-2-u4-C9',3,'error','auto','소수를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u4-X15','M3-2-u4-X20']::text[],true,'{"seq":5,"concept":"M3-2-u4-C9","difficulty":3,"kind":"error","stem":"소수를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지훈 — 「2.9는 0.1이 9개야」","correct":true,"mis_target":"M3-2-u4-X15"},{"t":"민서 — 「2.9는 0.1이 29개야」","mis":"M3-2-u4-X20"},{"t":"준우 — 「2.9는 이 점 구라고 읽어」","mis":"M3-2-u4-X20"}],"explanation":["2.9 = ⟨2 9/10⟩, 0.1이 29개예요.","1 mm = 0.1 cm예요.","지훈의 말이 틀렸어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 소수를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"건우 — 「⟨3 2/10⟩ = 2.3이야」","correct":true,"mis_target":"M3-2-u4-X16"},{"t":"민서 — 「3 cm 2 mm = 3.2 cm야」","mis":"M3-2-u4-X20"},{"t":"서윤 — 「3.2는 삼 점 이라고 읽어」","mis":"M3-2-u4-X20"}],"explanation":["3.2 = ⟨3 2/10⟩, 0.1이 32개예요.","1 mm = 0.1 cm예요.","건우의 말이 틀렸어요."],"asset":null},{"stem":"이번에는 다른 문제예요. 소수를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준우 — 「6 cm 9 mm = 6.09 cm야」","correct":true,"mis_target":"M3-2-u4-X17"},{"t":"도연 — 「6 cm 9 mm = 6.9 cm야」","mis":"M3-2-u4-X20"},{"t":"은비 — 「0.1이 10개면 1이야」","mis":"M3-2-u4-X20"}],"explanation":["6.9 = ⟨6 9/10⟩, 0.1이 69개예요.","1 mm = 0.1 cm예요.","준우의 말이 틀렸어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L08_challenge#6','math',3,2,'u4','L08','g3_2_math_u4_L08_challenge','lesson_challenge','M3-2-u4-C9',3,'mc','auto','종이 빨대의 길이는 2 cm 9 mm예요. 몇 cm인지 소수로 나타내면 얼마인가요?',ARRAY['M3-2-u4-X17','M3-2-u4-X16']::text[],true,'{"seq":6,"concept":"M3-2-u4-C9","difficulty":3,"kind":"mc","stem":"종이 빨대의 길이는 2 cm 9 mm예요. 몇 cm인지 소수로 나타내면 얼마인가요?","options":[{"t":"2.9 cm","correct":true},{"t":"2.09 cm","mis":"M3-2-u4-X17"},{"t":"29 cm","mis":"M3-2-u4-X17"},{"t":"9.2 cm","mis":"M3-2-u4-X16"}],"explanation":["1 mm = ⟨1/10⟩ cm = 0.1 cm예요.","9 mm는 0.9 cm — 2 cm 9 mm = ⟨2 9/10⟩ cm.","⟨2 9/10⟩ cm = 2.9 cm."],"variant_rule":{"alt":[{"stem":"애벌레의 길이는 6 cm 2 mm예요. 몇 cm인지 소수로 나타내면 얼마인가요?","options":[{"t":"6.2 cm","correct":true},{"t":"6.02 cm","mis":"M3-2-u4-X17"},{"t":"62 cm","mis":"M3-2-u4-X17"},{"t":"2.6 cm","mis":"M3-2-u4-X16"}],"explanation":["1 mm = ⟨1/10⟩ cm = 0.1 cm예요.","2 mm는 0.2 cm — 6 cm 2 mm = ⟨6 2/10⟩ cm.","⟨6 2/10⟩ cm = 6.2 cm."],"asset":null},{"stem":"지우개의 길이는 8 cm 7 mm예요. 몇 cm인지 소수로 나타내면 얼마인가요?","options":[{"t":"8.7 cm","correct":true},{"t":"8.07 cm","mis":"M3-2-u4-X17"},{"t":"87 cm","mis":"M3-2-u4-X17"},{"t":"7.8 cm","mis":"M3-2-u4-X16"}],"explanation":["1 mm = ⟨1/10⟩ cm = 0.1 cm예요.","7 mm는 0.7 cm — 8 cm 7 mm = ⟨8 7/10⟩ cm.","⟨8 7/10⟩ cm = 8.7 cm."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L08_challenge#7','math',3,2,'u4','L08','g3_2_math_u4_L08_challenge','lesson_challenge','M3-2-u4-C9',3,'mc','auto','⟨7 9/10⟩를 소수로 나타낸 것은 무엇인가요?',ARRAY['M3-2-u4-X16','M3-2-u4-X17']::text[],true,'{"seq":7,"concept":"M3-2-u4-C9","difficulty":3,"kind":"mc","stem":"⟨7 9/10⟩를 소수로 나타낸 것은 무엇인가요?","options":[{"t":"7.9","correct":true},{"t":"9.7","mis":"M3-2-u4-X16"},{"t":"79","mis":"M3-2-u4-X17"},{"t":"7.09","mis":"M3-2-u4-X17"}],"explanation":["⟨7 9/10⟩는 7과 ⟨9/10⟩예요.","⟨9/10⟩ = 0.9예요.","⟨7 9/10⟩ = 7.9."],"variant_rule":{"alt":[{"stem":"⟨9 1/10⟩을 소수로 나타낸 것은 무엇인가요?","options":[{"t":"9.1","correct":true},{"t":"1.9","mis":"M3-2-u4-X16"},{"t":"91","mis":"M3-2-u4-X17"},{"t":"9.01","mis":"M3-2-u4-X17"}],"explanation":["⟨9 1/10⟩은 9와 ⟨1/10⟩이에요.","⟨1/10⟩ = 0.1이에요.","⟨9 1/10⟩ = 9.1."],"asset":null},{"stem":"⟨9 2/10⟩를 소수로 나타낸 것은 무엇인가요?","options":[{"t":"9.2","correct":true},{"t":"2.9","mis":"M3-2-u4-X16"},{"t":"92","mis":"M3-2-u4-X17"},{"t":"9.02","mis":"M3-2-u4-X17"}],"explanation":["⟨9 2/10⟩는 9와 ⟨2/10⟩예요.","⟨2/10⟩ = 0.2예요.","⟨9 2/10⟩ = 9.2."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L08_challenge#8','math',3,2,'u4','L08','g3_2_math_u4_L08_challenge','lesson_challenge','M3-2-u4-C9',4,'essay','teacher','종이 빨대의 길이는 4 cm 7 mm예요. 이 길이를 cm로만 나타내면 몇 cm인지 소수로 쓰고, 그 까닭을 1 mm와 0.1 cm를 이용해 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-2-u4-C9","difficulty":4,"kind":"essay","stem":"종이 빨대의 길이는 4 cm 7 mm예요. 이 길이를 cm로만 나타내면 몇 cm인지 소수로 쓰고, 그 까닭을 1 mm와 0.1 cm를 이용해 설명해 보세요.","answer_guide":{"answer":"예: 1 cm를 똑같이 10칸으로 나눈 한 칸이 1 mm이므로 1 mm = ⟨1/10⟩ cm = 0.1 cm이다. 7 mm는 0.1 cm가 7개라서 0.7 cm이고, 4 cm 7 mm = 4.7 cm(사 점 칠 센티미터)이다.","scoring_points":["1 mm = 0.1 cm임을 썼는가","7 mm = 0.7 cm라고 썼는가","4.7 cm라고 답했는가"]},"explanation":["1 mm = 0.1 cm.","7 mm = 0.7 cm.","4 cm 7 mm = 4.7 cm."],"asset":{"type":"mmruler","len":47,"label":"종이 빨대"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L08_challenge#9','math',3,2,'u4','L08','g3_2_math_u4_L08_challenge','lesson_challenge','M3-2-u4-C9',4,'essay','teacher','하윤이가 「2.9는 0.1이 9개야.」라고 했어요. 하윤이의 말이 맞는지 판단하고, 2.9는 0.1이 몇 개인지 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-2-u4-C9","difficulty":4,"kind":"essay","stem":"하윤이가 「2.9는 0.1이 9개야.」라고 했어요. 하윤이의 말이 맞는지 판단하고, 2.9는 0.1이 몇 개인지 설명해 보세요.","answer_guide":{"answer":"예: 틀렸다. 1은 0.1이 10개이므로 2는 0.1이 20개이다. 0.9는 0.1이 9개이므로 2.9는 0.1이 20 + 9 = 29개이다. 하윤이는 자연수 부분을 빼먹었다.","scoring_points":["틀렸다고 판단했는가","2 = 0.1이 20개라고 썼는가","29개라고 답했는가"]},"explanation":["1 = 0.1 × 10개.","2 = 20개, 0.9 = 9개.","2.9 = 29개."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L08_challenge#10','math',3,2,'u4','L08','g3_2_math_u4_L08_challenge','lesson_challenge','M3-2-u4-C9',4,'ox','auto','서준이 「6.3은 육 점 삼이라고 읽어.」라고 했어요. 바르게 말했어요.',ARRAY['M3-2-u4-X16']::text[],true,'{"seq":10,"concept":"M3-2-u4-C9","difficulty":4,"kind":"ox","stem":"서준이 「6.3은 육 점 삼이라고 읽어.」라고 했어요. 바르게 말했어요.","answer":"O","reason_options":[{"t":"자연수를 먼저, 「점」 뒤 숫자를 하나씩 읽어서","correct":true},{"t":"소수점 뒤 숫자를 먼저 읽어서","mis":"M3-2-u4-X16"}],"mis":"M3-2-u4-X16","explanation":["자연수 육, 「점」, 소수점 뒤 삼.","6.3 = 「육 점 삼」.","바르게 읽었어요 — ○."],"variant_rule":{"alt":[{"stem":"준우가 「2.3은 이 점 삼이라고 읽어.」라고 했어요. 바르게 말했어요.","answer":"O","reason_options":[{"t":"자연수를 먼저, 「점」 뒤 숫자를 하나씩 읽어서","correct":true},{"t":"소수점 뒤 숫자를 먼저 읽어서","mis":"M3-2-u4-X16"}],"explanation":["자연수 이, 「점」, 소수점 뒤 삼.","2.3 = 「이 점 삼」.","바르게 읽었어요 — ○."],"asset":null},{"stem":"하윤이 「2.3은 0.1이 3개야.」라고 했어요. 바르게 말했어요.","answer":"X","reason_options":[{"t":"2도 0.1이 20개라서 모두 23개니까","correct":true},{"t":"소수점 뒤 숫자만 0.1의 개수라서","mis":"M3-2-u4-X15"}],"explanation":["1은 0.1이 10개예요 — 2는 0.1이 20개.","0.3은 0.1이 3개예요.","2.3은 0.1이 20 + 3 = 23개."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L09_basic#1','math',3,2,'u4','L09','g3_2_math_u4_L09_basic','lesson_basic','M3-2-u4-C10',1,'mc','auto','두 수의 크기를 바르게 견준 것은 무엇인가요?',ARRAY['M3-2-u4-X13','M3-2-u4-X22']::text[],true,'{"seq":1,"concept":"M3-2-u4-C10","difficulty":1,"kind":"mc","stem":"두 수의 크기를 바르게 견준 것은 무엇인가요?","options":[{"t":"1.2 < 1.6","correct":true},{"t":"1.2 > 1.6","mis":"M3-2-u4-X13"},{"t":"1.2 = 1.6","mis":"M3-2-u4-X22"},{"t":"견줄 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["자연수 부분이 1로 같아요.","소수점 오른쪽 수 2와 6을 견주어요.","1.2 < 1.6."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 두 수의 크기를 바르게 견준 것은 무엇인가요?","options":[{"t":"7.5 < 7.9","correct":true},{"t":"7.5 > 7.9","mis":"M3-2-u4-X13"},{"t":"7.5 = 7.9","mis":"M3-2-u4-X22"},{"t":"견줄 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["자연수 부분이 7로 같아요.","소수점 오른쪽 수 5와 9를 견주어요.","7.5 < 7.9."],"asset":null},{"stem":"이번에는 다른 문제예요. 두 수의 크기를 바르게 견준 것은 무엇인가요?","options":[{"t":"5.7 > 5.2","correct":true},{"t":"5.7 < 5.2","mis":"M3-2-u4-X13"},{"t":"5.7 = 5.2","mis":"M3-2-u4-X22"},{"t":"견줄 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["자연수 부분이 5로 같아요.","소수점 오른쪽 수 7과 2를 견주어요.","5.7 > 5.2."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L09_basic#2','math',3,2,'u4','L09','g3_2_math_u4_L09_basic','lesson_basic','M3-2-u4-C10',1,'sa','auto','2.1은 0.1이 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u4-C10","difficulty":1,"kind":"sa","stem":"2.1은 0.1이 몇 개인가요? 숫자로 쓰세요.","answer":["21"],"explanation":["1은 0.1이 10개예요 — 2는 0.1이 20개.","0.1은 0.1이 1개예요.","2.1은 0.1이 20 + 1 = 21개."],"variant_rule":{"alt":[{"stem":"5.1은 0.1이 몇 개인가요? 숫자로 쓰세요.","answer":["51"],"explanation":["1은 0.1이 10개예요 — 5는 0.1이 50개.","0.1은 0.1이 1개예요.","5.1은 0.1이 50 + 1 = 51개."],"asset":null},{"stem":"9.3은 0.1이 몇 개인가요? 숫자로 쓰세요.","answer":["93"],"explanation":["1은 0.1이 10개예요 — 9는 0.1이 90개.","0.3은 0.1이 3개예요.","9.3은 0.1이 90 + 3 = 93개."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L09_basic#3','math',3,2,'u4','L09','g3_2_math_u4_L09_basic','lesson_basic','M3-2-u4-C10',1,'mc','auto','두 수의 크기를 바르게 견준 것은 무엇인가요?',ARRAY['M3-2-u4-X18','M3-2-u4-X22']::text[],true,'{"seq":3,"concept":"M3-2-u4-C10","difficulty":1,"kind":"mc","stem":"두 수의 크기를 바르게 견준 것은 무엇인가요?","options":[{"t":"6.3 > 4.5","correct":true},{"t":"6.3 < 4.5","mis":"M3-2-u4-X18"},{"t":"6.3 = 4.5","mis":"M3-2-u4-X22"},{"t":"견줄 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["자연수 부분부터 견주어요 — 6과 4.","자연수 부분이 큰 소수가 더 커요.","6.3 > 4.5 — 0.1이 63개와 45개로 견주어도 같아요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 두 수의 크기를 바르게 견준 것은 무엇인가요?","options":[{"t":"3.3 < 6.9","correct":true},{"t":"3.3 > 6.9","mis":"M3-2-u4-X18"},{"t":"3.3 = 6.9","mis":"M3-2-u4-X22"},{"t":"견줄 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["자연수 부분부터 견주어요 — 3과 6.","자연수 부분이 큰 소수가 더 커요.","3.3 < 6.9 — 0.1이 33개와 69개로 견주어도 같아요."],"asset":null},{"stem":"이번에는 다른 문제예요. 두 수의 크기를 바르게 견준 것은 무엇인가요?","options":[{"t":"7.8 > 1.4","correct":true},{"t":"7.8 < 1.4","mis":"M3-2-u4-X18"},{"t":"7.8 = 1.4","mis":"M3-2-u4-X22"},{"t":"견줄 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["자연수 부분부터 견주어요 — 7과 1.","자연수 부분이 큰 소수가 더 커요.","7.8 > 1.4 — 0.1이 78개와 14개로 견주어도 같아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L09_basic#4','math',3,2,'u4','L09','g3_2_math_u4_L09_basic','lesson_basic','M3-2-u4-C10',1,'mc','auto','두 수의 크기를 바르게 견준 것은 무엇인가요?',ARRAY['M3-2-u4-X13','M3-2-u4-X22']::text[],true,'{"seq":4,"concept":"M3-2-u4-C10","difficulty":1,"kind":"mc","stem":"두 수의 크기를 바르게 견준 것은 무엇인가요?","options":[{"t":"8.3 < 8.7","correct":true},{"t":"8.3 > 8.7","mis":"M3-2-u4-X13"},{"t":"8.3 = 8.7","mis":"M3-2-u4-X22"},{"t":"견줄 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["자연수 부분이 8로 같아요.","소수점 오른쪽 수 3과 7을 견주어요.","8.3 < 8.7."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 두 수의 크기를 바르게 견준 것은 무엇인가요?","options":[{"t":"2.9 > 2.1","correct":true},{"t":"2.9 < 2.1","mis":"M3-2-u4-X13"},{"t":"2.9 = 2.1","mis":"M3-2-u4-X22"},{"t":"견줄 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["자연수 부분이 2로 같아요.","소수점 오른쪽 수 9와 1을 견주어요.","2.9 > 2.1."],"asset":null},{"stem":"이번에는 다른 문제예요. 두 수의 크기를 바르게 견준 것은 무엇인가요?","options":[{"t":"9.1 < 9.4","correct":true},{"t":"9.1 > 9.4","mis":"M3-2-u4-X13"},{"t":"9.1 = 9.4","mis":"M3-2-u4-X22"},{"t":"견줄 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["자연수 부분이 9로 같아요.","소수점 오른쪽 수 1과 4를 견주어요.","9.1 < 9.4."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L09_basic#5','math',3,2,'u4','L09','g3_2_math_u4_L09_basic','lesson_basic','M3-2-u4-C10',2,'mc','auto','철사가 1.8 m와 2.3 m 있어요. 더 긴 것은 몇 m인가요?',ARRAY['M3-2-u4-X18','M3-2-u4-X22']::text[],true,'{"seq":5,"concept":"M3-2-u4-C10","difficulty":2,"kind":"mc","stem":"철사가 1.8 m와 2.3 m 있어요. 더 긴 것은 몇 m인가요?","options":[{"t":"2.3 m","correct":true},{"t":"1.8 m","mis":"M3-2-u4-X18"},{"t":"두 길이가 같아요","mis":"M3-2-u4-X22"},{"t":"알 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["자연수 부분부터 견주어요 — 1과 2.","자연수 부분이 큰 소수가 더 커요.","1.8 < 2.3 — 0.1이 18개와 23개로 견주어도 같아요."],"variant_rule":{"alt":[{"stem":"리본이 2.8 m와 6.7 m 있어요. 더 긴 것은 몇 m인가요?","options":[{"t":"6.7 m","correct":true},{"t":"2.8 m","mis":"M3-2-u4-X18"},{"t":"두 길이가 같아요","mis":"M3-2-u4-X22"},{"t":"알 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["자연수 부분부터 견주어요 — 2와 6.","자연수 부분이 큰 소수가 더 커요.","2.8 < 6.7 — 0.1이 28개와 67개로 견주어도 같아요."],"asset":null},{"stem":"끈이 1.9 m와 3.8 m 있어요. 더 긴 것은 몇 m인가요?","options":[{"t":"3.8 m","correct":true},{"t":"1.9 m","mis":"M3-2-u4-X18"},{"t":"두 길이가 같아요","mis":"M3-2-u4-X22"},{"t":"알 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["자연수 부분부터 견주어요 — 1과 3.","자연수 부분이 큰 소수가 더 커요.","1.9 < 3.8 — 0.1이 19개와 38개로 견주어도 같아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L09_basic#6','math',3,2,'u4','L09','g3_2_math_u4_L09_basic','lesson_basic','M3-2-u4-C10',2,'mc','auto','줄넘기 30번 기록이에요. 서준 9.8초, 하윤 10.1초, 채원 10.4초. 가장 빠른 사람은 누구인가요?',ARRAY['M3-2-u4-X19','M3-2-u4-X18','M3-2-u4-X22']::text[],true,'{"seq":6,"concept":"M3-2-u4-C10","difficulty":2,"kind":"mc","stem":"줄넘기 30번 기록이에요. 서준 9.8초, 하윤 10.1초, 채원 10.4초. 가장 빠른 사람은 누구인가요?","options":[{"t":"서준","correct":true},{"t":"채원","mis":"M3-2-u4-X19"},{"t":"하윤","mis":"M3-2-u4-X18"},{"t":"모두 같아요","mis":"M3-2-u4-X22"}],"explanation":["걸린 시간이 짧을수록 빨라요.","9.8, 10.1, 10.4 중 가장 작은 수는 9.8이에요.","가장 빠른 사람은 서준이에요."],"variant_rule":{"alt":[{"stem":"100 m 수영 기록이에요. 도연 11.4초, 서윤 12.9초, 하윤 11.2초. 가장 빠른 사람은 누구인가요?","options":[{"t":"하윤","correct":true},{"t":"서윤","mis":"M3-2-u4-X19"},{"t":"도연","mis":"M3-2-u4-X18"},{"t":"모두 같아요","mis":"M3-2-u4-X22"}],"explanation":["걸린 시간이 짧을수록 빨라요.","11.4, 12.9, 11.2 중 가장 작은 수는 11.2예요.","가장 빠른 사람은 하윤이에요."],"asset":null},{"stem":"50 m 달리기 기록이에요. 민서 9.5초, 도연 9.3초, 지훈 8.5초. 가장 빠른 사람은 누구인가요?","options":[{"t":"지훈","correct":true},{"t":"민서","mis":"M3-2-u4-X19"},{"t":"도연","mis":"M3-2-u4-X18"},{"t":"모두 같아요","mis":"M3-2-u4-X22"}],"explanation":["걸린 시간이 짧을수록 빨라요.","9.5, 9.3, 8.5 중 가장 작은 수는 8.5예요.","가장 빠른 사람은 지훈이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L09_basic#7','math',3,2,'u4','L09','g3_2_math_u4_L09_basic','lesson_basic','M3-2-u4-C10',2,'mc','auto','수직선을 보고 두 수의 크기를 바르게 견준 것은 무엇인가요?',ARRAY['M3-2-u4-X18','M3-2-u4-X22']::text[],true,'{"seq":7,"concept":"M3-2-u4-C10","difficulty":2,"kind":"mc","stem":"수직선을 보고 두 수의 크기를 바르게 견준 것은 무엇인가요?","options":[{"t":"7.1 < 7.2","correct":true},{"t":"7.1 > 7.2","mis":"M3-2-u4-X18"},{"t":"7.1 = 7.2","mis":"M3-2-u4-X22"},{"t":"견줄 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["수직선에서는 오른쪽에 있는 수가 더 커요.","7.2가 더 오른쪽에 있어요.","7.1 < 7.2."],"asset":{"type":"number_line","cells":["7","7.1","7.2","7.3","7.4"]},"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 수직선을 보고 두 수의 크기를 바르게 견준 것은 무엇인가요?","options":[{"t":"8.6 > 8.5","correct":true},{"t":"8.6 < 8.5","mis":"M3-2-u4-X18"},{"t":"8.6 = 8.5","mis":"M3-2-u4-X22"},{"t":"견줄 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["수직선에서는 오른쪽에 있는 수가 더 커요.","8.6이 더 오른쪽에 있어요.","8.6 > 8.5."],"asset":{"type":"number_line","cells":["8.4","8.5","8.6","8.7","8.8"]}},{"stem":"이번에는 다른 문제예요. 수직선을 보고 두 수의 크기를 바르게 견준 것은 무엇인가요?","options":[{"t":"8.9 > 8.7","correct":true},{"t":"8.9 < 8.7","mis":"M3-2-u4-X18"},{"t":"8.9 = 8.7","mis":"M3-2-u4-X22"},{"t":"견줄 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["수직선에서는 오른쪽에 있는 수가 더 커요.","8.9가 더 오른쪽에 있어요.","8.9 > 8.7."],"asset":{"type":"number_line","cells":["8.6","8.7","8.8","8.9","9"]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L09_basic#8','math',3,2,'u4','L09','g3_2_math_u4_L09_basic','lesson_basic','M3-2-u4-C10',2,'ox','auto','건우가 「2.6은 3.1보다 커. 6이 1보다 크니까.」라고 했어요. 바르게 말했어요.',ARRAY['M3-2-u4-X18']::text[],true,'{"seq":8,"concept":"M3-2-u4-C10","difficulty":2,"kind":"ox","stem":"건우가 「2.6은 3.1보다 커. 6이 1보다 크니까.」라고 했어요. 바르게 말했어요.","answer":"X","reason_options":[{"t":"자연수 부분 3이 더 커서 3.1이 크니까","correct":true},{"t":"소수점 오른쪽 수 6이 더 커서","mis":"M3-2-u4-X18"}],"mis":"M3-2-u4-X18","explanation":["자연수 부분부터 견주어요 — 3과 2.","자연수 부분이 큰 소수가 더 커요.","3.1 > 2.6 — 0.1이 31개와 26개로 견주어도 같아요."],"variant_rule":{"alt":[{"stem":"도연이 「1.7은 7.2보다 커. 7이 2보다 크니까.」라고 했어요. 바르게 말했어요.","answer":"X","reason_options":[{"t":"자연수 부분 7이 더 커서 7.2가 크니까","correct":true},{"t":"소수점 오른쪽 수 7이 더 커서","mis":"M3-2-u4-X18"}],"explanation":["자연수 부분부터 견주어요 — 7과 1.","자연수 부분이 큰 소수가 더 커요.","7.2 > 1.7 — 0.1이 72개와 17개로 견주어도 같아요."],"asset":null},{"stem":"하윤이 「2.8은 5.7보다 커. 8이 7보다 크니까.」라고 했어요. 바르게 말했어요.","answer":"X","reason_options":[{"t":"자연수 부분 5가 더 커서 5.7이 크니까","correct":true},{"t":"소수점 오른쪽 수 8이 더 커서","mis":"M3-2-u4-X18"}],"explanation":["자연수 부분부터 견주어요 — 5와 2.","자연수 부분이 큰 소수가 더 커요.","5.7 > 2.8 — 0.1이 57개와 28개로 견주어도 같아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L09_basic#9','math',3,2,'u4','L09','g3_2_math_u4_L09_basic','lesson_basic','M3-2-u4-C10',2,'sa','auto','수 카드 1, 4 중 2장으로 □.□를 만들 때, 가장 큰 소수는 0.1이 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M3-2-u4-C10","difficulty":2,"kind":"sa","stem":"수 카드 1, 4 중 2장으로 □.□를 만들 때, 가장 큰 소수는 0.1이 몇 개인가요? 숫자로 쓰세요.","answer":["41"],"explanation":["자연수 자리에 가장 큰 수 4를 놓아요.","소수점 뒤에 그다음 큰 수 1 — 4.1.","4.1은 0.1이 41개."],"variant_rule":{"alt":[{"stem":"수 카드 7, 4 중 2장으로 □.□를 만들 때, 가장 큰 소수는 0.1이 몇 개인가요? 숫자로 쓰세요.","answer":["74"],"explanation":["자연수 자리에 가장 큰 수 7을 놓아요.","소수점 뒤에 그다음 큰 수 4 — 7.4.","7.4는 0.1이 74개."],"asset":null},{"stem":"수 카드 7, 3 중 2장으로 □.□를 만들 때, 가장 큰 소수는 0.1이 몇 개인가요? 숫자로 쓰세요.","answer":["73"],"explanation":["자연수 자리에 가장 큰 수 7을 놓아요.","소수점 뒤에 그다음 큰 수 3 — 7.3.","7.3은 0.1이 73개."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L09_basic#10','math',3,2,'u4','L09','g3_2_math_u4_L09_basic','lesson_basic','M3-2-u4-C10',3,'mc','auto','네 수 중에서 가장 큰 수는 무엇인가요? 1.5, 2.4, 1.6, 2.6',ARRAY['M3-2-u4-X20','M3-2-u4-X18']::text[],true,'{"seq":10,"concept":"M3-2-u4-C10","difficulty":3,"kind":"mc","stem":"네 수 중에서 가장 큰 수는 무엇인가요? 1.5, 2.4, 1.6, 2.6","options":[{"t":"2.6","correct":true},{"t":"1.5","mis":"M3-2-u4-X20"},{"t":"2.4","mis":"M3-2-u4-X18"},{"t":"1.6","mis":"M3-2-u4-X18"}],"explanation":["자연수 부분부터 견주어요 — 1, 2, 1, 2.","같으면 소수점 오른쪽 수를 견주어요.","가장 큰 수는 2.6이에요."],"variant_rule":{"alt":[{"stem":"네 수 중에서 가장 큰 수는 무엇인가요? 4.3, 5.5, 4.8, 5.6","options":[{"t":"5.6","correct":true},{"t":"4.3","mis":"M3-2-u4-X20"},{"t":"5.5","mis":"M3-2-u4-X18"},{"t":"4.8","mis":"M3-2-u4-X18"}],"explanation":["자연수 부분부터 견주어요 — 4, 5, 4, 5.","같으면 소수점 오른쪽 수를 견주어요.","가장 큰 수는 5.6이에요."],"asset":null},{"stem":"네 수 중에서 가장 큰 수는 무엇인가요? 6.6, 6.2, 7.8, 7.6","options":[{"t":"7.8","correct":true},{"t":"6.6","mis":"M3-2-u4-X18"},{"t":"6.2","mis":"M3-2-u4-X20"},{"t":"7.6","mis":"M3-2-u4-X18"}],"explanation":["자연수 부분부터 견주어요 — 6, 6, 7, 7.","같으면 소수점 오른쪽 수를 견주어요.","가장 큰 수는 7.8이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L09_challenge#1','math',3,2,'u4','L09','g3_2_math_u4_L09_challenge','lesson_challenge','M3-2-u4-C10',2,'mc','auto','두 수의 크기를 바르게 견준 것은 무엇인가요?',ARRAY['M3-2-u4-X18','M3-2-u4-X22']::text[],true,'{"seq":1,"concept":"M3-2-u4-C10","difficulty":2,"kind":"mc","stem":"두 수의 크기를 바르게 견준 것은 무엇인가요?","options":[{"t":"2.7 < 3.5","correct":true},{"t":"2.7 > 3.5","mis":"M3-2-u4-X18"},{"t":"2.7 = 3.5","mis":"M3-2-u4-X22"},{"t":"견줄 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["자연수 부분부터 견주어요 — 2와 3.","자연수 부분이 큰 소수가 더 커요.","2.7 < 3.5 — 0.1이 27개와 35개로 견주어도 같아요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 두 수의 크기를 바르게 견준 것은 무엇인가요?","options":[{"t":"7.5 < 8.2","correct":true},{"t":"7.5 > 8.2","mis":"M3-2-u4-X18"},{"t":"7.5 = 8.2","mis":"M3-2-u4-X22"},{"t":"견줄 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["자연수 부분부터 견주어요 — 7과 8.","자연수 부분이 큰 소수가 더 커요.","7.5 < 8.2 — 0.1이 75개와 82개로 견주어도 같아요."],"asset":null},{"stem":"이번에는 다른 문제예요. 두 수의 크기를 바르게 견준 것은 무엇인가요?","options":[{"t":"7.4 > 1.7","correct":true},{"t":"7.4 < 1.7","mis":"M3-2-u4-X18"},{"t":"7.4 = 1.7","mis":"M3-2-u4-X22"},{"t":"견줄 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["자연수 부분부터 견주어요 — 7과 1.","자연수 부분이 큰 소수가 더 커요.","7.4 > 1.7 — 0.1이 74개와 17개로 견주어도 같아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L09_challenge#2','math',3,2,'u4','L09','g3_2_math_u4_L09_challenge','lesson_challenge','M3-2-u4-C10',2,'mc','auto','철사가 2.9 m와 9.5 m 있어요. 더 짧은 것은 몇 m인가요?',ARRAY['M3-2-u4-X20','M3-2-u4-X22']::text[],true,'{"seq":2,"concept":"M3-2-u4-C10","difficulty":2,"kind":"mc","stem":"철사가 2.9 m와 9.5 m 있어요. 더 짧은 것은 몇 m인가요?","options":[{"t":"2.9 m","correct":true},{"t":"9.5 m","mis":"M3-2-u4-X20"},{"t":"두 길이가 같아요","mis":"M3-2-u4-X22"},{"t":"알 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["자연수 부분부터 견주어요 — 2와 9.","자연수 부분이 큰 소수가 더 커요.","2.9 < 9.5 — 0.1이 29개와 95개로 견주어도 같아요."],"variant_rule":{"alt":[{"stem":"리본이 8.6 m와 1.7 m 있어요. 더 짧은 것은 몇 m인가요?","options":[{"t":"1.7 m","correct":true},{"t":"8.6 m","mis":"M3-2-u4-X20"},{"t":"두 길이가 같아요","mis":"M3-2-u4-X22"},{"t":"알 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["자연수 부분부터 견주어요 — 8과 1.","자연수 부분이 큰 소수가 더 커요.","8.6 > 1.7 — 0.1이 86개와 17개로 견주어도 같아요."],"asset":null},{"stem":"끈이 7.7 m와 5.7 m 있어요. 더 짧은 것은 몇 m인가요?","options":[{"t":"5.7 m","correct":true},{"t":"7.7 m","mis":"M3-2-u4-X20"},{"t":"두 길이가 같아요","mis":"M3-2-u4-X22"},{"t":"알 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["자연수 부분부터 견주어요 — 7과 5.","자연수 부분이 큰 소수가 더 커요.","7.7 > 5.7 — 0.1이 77개와 57개로 견주어도 같아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L09_challenge#3','math',3,2,'u4','L09','g3_2_math_u4_L09_challenge','lesson_challenge','M3-2-u4-C10',3,'mc','auto','줄넘기 30번 기록이에요. 서준 10.4초, 서윤 9.9초, 하윤 9.7초. 가장 빠른 사람은 누구인가요?',ARRAY['M3-2-u4-X19','M3-2-u4-X18','M3-2-u4-X22']::text[],true,'{"seq":3,"concept":"M3-2-u4-C10","difficulty":3,"kind":"mc","stem":"줄넘기 30번 기록이에요. 서준 10.4초, 서윤 9.9초, 하윤 9.7초. 가장 빠른 사람은 누구인가요?","options":[{"t":"하윤","correct":true},{"t":"서준","mis":"M3-2-u4-X19"},{"t":"서윤","mis":"M3-2-u4-X18"},{"t":"모두 같아요","mis":"M3-2-u4-X22"}],"explanation":["걸린 시간이 짧을수록 빨라요.","10.4, 9.9, 9.7 중 가장 작은 수는 9.7이에요.","가장 빠른 사람은 하윤이에요."],"variant_rule":{"alt":[{"stem":"100 m 수영 기록이에요. 하윤 8.6초, 준우 9.8초, 건우 8.5초. 가장 빠른 사람은 누구인가요?","options":[{"t":"건우","correct":true},{"t":"준우","mis":"M3-2-u4-X19"},{"t":"하윤","mis":"M3-2-u4-X18"},{"t":"모두 같아요","mis":"M3-2-u4-X22"}],"explanation":["걸린 시간이 짧을수록 빨라요.","8.6, 9.8, 8.5 중 가장 작은 수는 8.5예요.","가장 빠른 사람은 건우예요."],"asset":null},{"stem":"50 m 달리기 기록이에요. 서준 12.1초, 서윤 12.8초, 지훈 13.6초. 가장 빠른 사람은 누구인가요?","options":[{"t":"서준","correct":true},{"t":"지훈","mis":"M3-2-u4-X19"},{"t":"서윤","mis":"M3-2-u4-X18"},{"t":"모두 같아요","mis":"M3-2-u4-X22"}],"explanation":["걸린 시간이 짧을수록 빨라요.","12.1, 12.8, 13.6 중 가장 작은 수는 12.1이에요.","가장 빠른 사람은 서준이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
