INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L09_challenge#5','math',3,2,'u4','L09','g3_2_math_u4_L09_challenge','lesson_challenge','M3-2-u4-C10',3,'sa','auto','수 카드 6, 1, 2 중 2장으로 □.□를 만들 때, 가장 큰 소수는 0.1이 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-2-u4-C10","difficulty":3,"kind":"sa","stem":"수 카드 6, 1, 2 중 2장으로 □.□를 만들 때, 가장 큰 소수는 0.1이 몇 개인가요? 숫자로 쓰세요.","answer":["62"],"explanation":["자연수 자리에 가장 큰 수 6을 놓아요.","소수점 뒤에 그다음 큰 수 2 — 6.2.","6.2는 0.1이 62개."],"variant_rule":{"alt":[{"stem":"수 카드 6, 4, 3 중 2장으로 □.□를 만들 때, 가장 큰 소수는 0.1이 몇 개인가요? 숫자로 쓰세요.","answer":["64"],"explanation":["자연수 자리에 가장 큰 수 6을 놓아요.","소수점 뒤에 그다음 큰 수 4 — 6.4.","6.4는 0.1이 64개."],"asset":null},{"stem":"수 카드 5, 2, 7 중 2장으로 □.□를 만들 때, 가장 큰 소수는 0.1이 몇 개인가요? 숫자로 쓰세요.","answer":["75"],"explanation":["자연수 자리에 가장 큰 수 7을 놓아요.","소수점 뒤에 그다음 큰 수 5 — 7.5.","7.5는 0.1이 75개."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L09_challenge#6','math',3,2,'u4','L09','g3_2_math_u4_L09_challenge','lesson_challenge','M3-2-u4-C10',3,'sa','auto','6.5보다 크고 6.9보다 작은 소수 중에서 6.□ 꼴인 수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M3-2-u4-C10","difficulty":3,"kind":"sa","stem":"6.5보다 크고 6.9보다 작은 소수 중에서 6.□ 꼴인 수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["6.5는 0.1이 65개, 6.9는 0.1이 69개예요.","그 사이는 0.1이 66개부터 68개까지예요.","모두 3개 — 끝의 두 수는 넣지 않아요."],"variant_rule":{"alt":[{"stem":"7.3보다 크고 7.7보다 작은 소수 중에서 7.□ 꼴인 수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["7.3은 0.1이 73개, 7.7은 0.1이 77개예요.","그 사이는 0.1이 74개부터 76개까지예요.","모두 3개 — 끝의 두 수는 넣지 않아요."],"asset":null},{"stem":"4.4보다 크고 4.9보다 작은 소수 중에서 4.□ 꼴인 수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["4.4는 0.1이 44개, 4.9는 0.1이 49개예요.","그 사이는 0.1이 45개부터 48개까지예요.","모두 4개 — 끝의 두 수는 넣지 않아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L09_challenge#7','math',3,2,'u4','L09','g3_2_math_u4_L09_challenge','lesson_challenge','M3-2-u4-C10',3,'mc','auto','네 수 중에서 가장 작은 수는 무엇인가요? 1.4, 2.9, 1.2, 2.5',ARRAY['M3-2-u4-X18','M3-2-u4-X20']::text[],true,'{"seq":7,"concept":"M3-2-u4-C10","difficulty":3,"kind":"mc","stem":"네 수 중에서 가장 작은 수는 무엇인가요? 1.4, 2.9, 1.2, 2.5","options":[{"t":"1.2","correct":true},{"t":"1.4","mis":"M3-2-u4-X18"},{"t":"2.9","mis":"M3-2-u4-X20"},{"t":"2.5","mis":"M3-2-u4-X18"}],"explanation":["자연수 부분부터 견주어요 — 1, 2, 1, 2.","같으면 소수점 오른쪽 수를 견주어요.","가장 작은 수는 1.2예요."],"variant_rule":{"alt":[{"stem":"네 수 중에서 가장 작은 수는 무엇인가요? 5.2, 5.1, 5.8, 6.8","options":[{"t":"5.1","correct":true},{"t":"5.2","mis":"M3-2-u4-X18"},{"t":"5.8","mis":"M3-2-u4-X18"},{"t":"6.8","mis":"M3-2-u4-X20"}],"explanation":["자연수 부분부터 견주어요 — 5, 5, 5, 6.","같으면 소수점 오른쪽 수를 견주어요.","가장 작은 수는 5.1이에요."],"asset":null},{"stem":"네 수 중에서 가장 작은 수는 무엇인가요? 4.3, 5.4, 5.8, 5.7","options":[{"t":"4.3","correct":true},{"t":"5.4","mis":"M3-2-u4-X18"},{"t":"5.8","mis":"M3-2-u4-X20"},{"t":"5.7","mis":"M3-2-u4-X18"}],"explanation":["자연수 부분부터 견주어요 — 4, 5, 5, 5.","같으면 소수점 오른쪽 수를 견주어요.","가장 작은 수는 4.3이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L09_challenge#8','math',3,2,'u4','L09','g3_2_math_u4_L09_challenge','lesson_challenge','M3-2-u4-C10',4,'essay','teacher','리본이 1.8 m와 2.3 m 있어요. 지훈이는 「8이 3보다 크니까 1.8 m가 더 길어.」라고 했어요. 어느 리본이 더 긴지 두 가지 방법(자연수 부분부터 견주기, 0.1의 개수)으로 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-2-u4-C10","difficulty":4,"kind":"essay","stem":"리본이 1.8 m와 2.3 m 있어요. 지훈이는 「8이 3보다 크니까 1.8 m가 더 길어.」라고 했어요. 어느 리본이 더 긴지 두 가지 방법(자연수 부분부터 견주기, 0.1의 개수)으로 설명해 보세요.","answer_guide":{"answer":"예: 2.3 m가 더 길다. ① 자연수 부분 2가 1보다 크므로 2.3이 크다. ② 1.8은 0.1이 18개, 2.3은 0.1이 23개라서 2.3이 크다. 지훈이는 소수점 오른쪽 수만 보고 견주었다.","scoring_points":["2.3 m가 더 길다고 답했는가","자연수 부분부터 견주었는가","0.1의 개수로 견주었는가"]},"explanation":["2 > 1.","0.1이 23개 > 18개.","2.3 m가 더 길어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L09_challenge#9','math',3,2,'u4','L09','g3_2_math_u4_L09_challenge','lesson_challenge','M3-2-u4-C10',4,'essay','teacher','50 m 달리기에서 준우는 9.8초, 지훈이는 10.1초가 걸렸어요. 누가 더 빠른지 쓰고, 기록의 크기와 빠르기를 이어서 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-2-u4-C10","difficulty":4,"kind":"essay","stem":"50 m 달리기에서 준우는 9.8초, 지훈이는 10.1초가 걸렸어요. 누가 더 빠른지 쓰고, 기록의 크기와 빠르기를 이어서 설명해 보세요.","answer_guide":{"answer":"예: 준우가 더 빠르다. 9.8은 자연수 부분 9가 10보다 작으므로 10.1보다 작다. 달리기 기록은 걸린 시간이라 짧을수록 빠르므로 9.8초가 걸린 준우가 더 빠르다.","scoring_points":["준우가 더 빠르다고 답했는가","9.8 < 10.1을 바르게 견주었는가","걸린 시간이 짧을수록 빠르다고 썼는가"]},"explanation":["9.8 < 10.1.","걸린 시간이 짧을수록 빨라요.","준우가 더 빨라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L09_challenge#10','math',3,2,'u4','L09','g3_2_math_u4_L09_challenge','lesson_challenge','M3-2-u4-C10',4,'sa','auto','1.1보다 크고 1.9보다 작은 소수 중에서 1.□ 꼴인 수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M3-2-u4-C10","difficulty":4,"kind":"sa","stem":"1.1보다 크고 1.9보다 작은 소수 중에서 1.□ 꼴인 수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["1.1은 0.1이 11개, 1.9는 0.1이 19개예요.","그 사이는 0.1이 12개부터 18개까지예요.","모두 7개 — 끝의 두 수는 넣지 않아요."],"variant_rule":{"alt":[{"stem":"5.5보다 크고 5.9보다 작은 소수 중에서 5.□ 꼴인 수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["5.5는 0.1이 55개, 5.9는 0.1이 59개예요.","그 사이는 0.1이 56개부터 58개까지예요.","모두 3개 — 끝의 두 수는 넣지 않아요."],"asset":null},{"stem":"5.4보다 크고 5.8보다 작은 소수 중에서 5.□ 꼴인 수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["5.4는 0.1이 54개, 5.8은 0.1이 58개예요.","그 사이는 0.1이 55개부터 57개까지예요.","모두 3개 — 끝의 두 수는 넣지 않아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L10_basic#1','math',3,2,'u4','L10','g3_2_math_u4_L10_basic','lesson_basic','M3-2-u4-C11',1,'mc','auto','두 수의 크기를 바르게 견준 것은 무엇인가요?',ARRAY['M3-2-u4-X14','M3-2-u4-X22']::text[],true,'{"seq":1,"concept":"M3-2-u4-C11","difficulty":1,"kind":"mc","stem":"두 수의 크기를 바르게 견준 것은 무엇인가요?","options":[{"t":"⟨83/10⟩ < ⟨8 5/10⟩","correct":true},{"t":"⟨83/10⟩ > ⟨8 5/10⟩","mis":"M3-2-u4-X14"},{"t":"⟨83/10⟩ = ⟨8 5/10⟩","mis":"M3-2-u4-X22"},{"t":"견줄 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["분모가 10인 분수는 소수로 바꿀 수 있어요 — ⟨83/10⟩ = 8.3, ⟨8 5/10⟩ = 8.5.","소수로 견주어요 — 자연수 부분부터, 같으면 소수점 오른쪽 수.","⟨83/10⟩ < ⟨8 5/10⟩."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 두 수의 크기를 바르게 견준 것은 무엇인가요?","options":[{"t":"⟨24/10⟩ < ⟨3 3/10⟩","correct":true},{"t":"⟨24/10⟩ > ⟨3 3/10⟩","mis":"M3-2-u4-X14"},{"t":"⟨24/10⟩ = ⟨3 3/10⟩","mis":"M3-2-u4-X22"},{"t":"견줄 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["분모가 10인 분수는 소수로 바꿀 수 있어요 — ⟨24/10⟩ = 2.4, ⟨3 3/10⟩ = 3.3.","소수로 견주어요 — 자연수 부분부터, 같으면 소수점 오른쪽 수.","⟨24/10⟩ < ⟨3 3/10⟩."],"asset":null},{"stem":"이번에는 다른 문제예요. 두 수의 크기를 바르게 견준 것은 무엇인가요?","options":[{"t":"⟨6 8/10⟩ > ⟨59/10⟩","correct":true},{"t":"⟨6 8/10⟩ < ⟨59/10⟩","mis":"M3-2-u4-X14"},{"t":"⟨6 8/10⟩ = ⟨59/10⟩","mis":"M3-2-u4-X22"},{"t":"견줄 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["분모가 10인 분수는 소수로 바꿀 수 있어요 — ⟨6 8/10⟩ = 6.8, ⟨59/10⟩ = 5.9.","소수로 견주어요 — 자연수 부분부터, 같으면 소수점 오른쪽 수.","⟨6 8/10⟩ > ⟨59/10⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
