INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L10_basic#3','math',3,2,'u4','L10','g3_2_math_u4_L10_basic','lesson_basic','M3-2-u4-C11',1,'sa','auto','⟨8 5/10⟩를 소수로 나타내면 0.1이 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-2-u4-C11","difficulty":1,"kind":"sa","stem":"⟨8 5/10⟩를 소수로 나타내면 0.1이 몇 개인가요? 숫자로 쓰세요.","answer":["85"],"explanation":["⟨8 5/10⟩ = 8.5예요.","8은 0.1이 80개, 0.5는 5개예요.","모두 85개."],"variant_rule":{"alt":[{"stem":"⟨1 6/10⟩을 소수로 나타내면 0.1이 몇 개인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["⟨1 6/10⟩ = 1.6이에요.","1은 0.1이 10개, 0.6은 6개예요.","모두 16개."],"asset":null},{"stem":"⟨4 9/10⟩를 소수로 나타내면 0.1이 몇 개인가요? 숫자로 쓰세요.","answer":["49"],"explanation":["⟨4 9/10⟩ = 4.9예요.","4는 0.1이 40개, 0.9는 9개예요.","모두 49개."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
