INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L10_basic#5','math',3,2,'u4','L10','g3_2_math_u4_L10_basic','lesson_basic','M3-2-u4-C11',2,'mc','auto','⟨1 □/10⟩가 ⟨1 7/10⟩보다 클 때, □ 안에 들어갈 수 있는 수를 모두 고른 것은 무엇인가요?',ARRAY['M3-2-u4-X21','M3-2-u4-X20']::text[],true,'{"seq":5,"concept":"M3-2-u4-C11","difficulty":2,"kind":"mc","stem":"⟨1 □/10⟩가 ⟨1 7/10⟩보다 클 때, □ 안에 들어갈 수 있는 수를 모두 고른 것은 무엇인가요?","options":[{"t":"8, 9","correct":true},{"t":"7, 8, 9","mis":"M3-2-u4-X21"},{"t":"1, 2, 3, 4, 5, 6","mis":"M3-2-u4-X20"},{"t":"8","mis":"M3-2-u4-X21"}],"explanation":["자연수 부분이 1로 같아요.","분수 부분의 분자 □가 7보다 커야 해요.","□ = 8, 9 — 7은 같아서 넣지 않아요."],"variant_rule":{"alt":[{"stem":"⟨9 □/10⟩가 ⟨9 6/10⟩보다 클 때, □ 안에 들어갈 수 있는 수를 모두 고른 것은 무엇인가요?","options":[{"t":"7, 8, 9","correct":true},{"t":"6, 7, 8, 9","mis":"M3-2-u4-X21"},{"t":"1, 2, 3, 4, 5","mis":"M3-2-u4-X20"},{"t":"7","mis":"M3-2-u4-X21"}],"explanation":["자연수 부분이 9로 같아요.","분수 부분의 분자 □가 6보다 커야 해요.","□ = 7, 8, 9 — 6은 같아서 넣지 않아요."],"asset":null},{"stem":"⟨8 □/10⟩가 ⟨8 3/10⟩보다 클 때, □ 안에 들어갈 수 있는 수를 모두 고른 것은 무엇인가요?","options":[{"t":"4, 5, 6, 7, 8, 9","correct":true},{"t":"3, 4, 5, 6, 7, 8, 9","mis":"M3-2-u4-X21"},{"t":"1, 2","mis":"M3-2-u4-X20"},{"t":"4","mis":"M3-2-u4-X21"}],"explanation":["자연수 부분이 8로 같아요.","분수 부분의 분자 □가 3보다 커야 해요.","□ = 4, 5, 6, 7, 8, 9 — 3은 같아서 넣지 않아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L10_basic#6','math',3,2,'u4','L10','g3_2_math_u4_L10_basic','lesson_basic','M3-2-u4-C11',2,'sa','auto','1.6 < 1.□일 때, □ 안에 들어갈 수 있는 수는 모두 몇 개인가요? (□는 0부터 9까지의 수) 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M3-2-u4-C11","difficulty":2,"kind":"sa","stem":"1.6 < 1.□일 때, □ 안에 들어갈 수 있는 수는 모두 몇 개인가요? (□는 0부터 9까지의 수) 숫자로 쓰세요.","answer":["3"],"explanation":["자연수 부분이 1로 같아요.","□는 6보다 커야 해요 — 7, 8, 9.","모두 3개 — 6은 같아서 빼요."],"variant_rule":{"alt":[{"stem":"8.7 < 8.□일 때, □ 안에 들어갈 수 있는 수는 모두 몇 개인가요? (□는 0부터 9까지의 수) 숫자로 쓰세요.","answer":["2"],"explanation":["자연수 부분이 8로 같아요.","□는 7보다 커야 해요 — 8, 9.","모두 2개 — 7은 같아서 빼요."],"asset":null},{"stem":"5.2 < 5.□일 때, □ 안에 들어갈 수 있는 수는 모두 몇 개인가요? (□는 0부터 9까지의 수) 숫자로 쓰세요.","answer":["7"],"explanation":["자연수 부분이 5로 같아요.","□는 2보다 커야 해요 — 3, 4, 5, 6, 7, 8, 9.","모두 7개 — 2는 같아서 빼요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L10_basic#7','math',3,2,'u4','L10','g3_2_math_u4_L10_basic','lesson_basic','M3-2-u4-C11',2,'mc','auto','네 수 중에서 가장 큰 수는 무엇인가요? ⟨7 9/10⟩, 6.8, ⟨74/10⟩, 7.7',ARRAY['M3-2-u4-X20','M3-2-u4-X14']::text[],true,'{"seq":7,"concept":"M3-2-u4-C11","difficulty":2,"kind":"mc","stem":"네 수 중에서 가장 큰 수는 무엇인가요? ⟨7 9/10⟩, 6.8, ⟨74/10⟩, 7.7","options":[{"t":"⟨7 9/10⟩","correct":true},{"t":"6.8","mis":"M3-2-u4-X20"},{"t":"⟨74/10⟩","mis":"M3-2-u4-X14"},{"t":"7.7","mis":"M3-2-u4-X14"}],"explanation":["분수는 소수로 바꾸어요 — 7.9, 6.8, 7.4, 7.7.","자연수 부분부터, 같으면 소수점 오른쪽 수를 견주어요.","가장 큰 수는 ⟨7 9/10⟩예요."],"variant_rule":{"alt":[{"stem":"네 수 중에서 가장 큰 수는 무엇인가요? 6.4, 6.5, ⟨7 1/10⟩, ⟨6 8/10⟩","options":[{"t":"⟨7 1/10⟩","correct":true},{"t":"6.4","mis":"M3-2-u4-X20"},{"t":"6.5","mis":"M3-2-u4-X14"},{"t":"⟨6 8/10⟩","mis":"M3-2-u4-X14"}],"explanation":["분수는 소수로 바꾸어요 — 6.4, 6.5, 7.1, 6.8.","자연수 부분부터, 같으면 소수점 오른쪽 수를 견주어요.","가장 큰 수는 ⟨7 1/10⟩이에요."],"asset":null},{"stem":"네 수 중에서 가장 큰 수는 무엇인가요? 7.1, ⟨7 2/10⟩, 8.7, ⟨8 3/10⟩","options":[{"t":"8.7","correct":true},{"t":"7.1","mis":"M3-2-u4-X20"},{"t":"⟨7 2/10⟩","mis":"M3-2-u4-X14"},{"t":"⟨8 3/10⟩","mis":"M3-2-u4-X14"}],"explanation":["분수는 소수로 바꾸어요 — 7.1, 7.2, 8.7, 8.3.","자연수 부분부터, 같으면 소수점 오른쪽 수를 견주어요.","가장 큰 수는 8.7이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L10_basic#8','math',3,2,'u4','L10','g3_2_math_u4_L10_basic','lesson_basic','M3-2-u4-C11',2,'mc','auto','사마귀 수컷은 ⟨5 3/10⟩ cm, 암컷은 ⟨44/10⟩ cm예요. 어느 쪽이 더 긴가요?',ARRAY['M3-2-u4-X14','M3-2-u4-X22']::text[],true,'{"seq":8,"concept":"M3-2-u4-C11","difficulty":2,"kind":"mc","stem":"사마귀 수컷은 ⟨5 3/10⟩ cm, 암컷은 ⟨44/10⟩ cm예요. 어느 쪽이 더 긴가요?","options":[{"t":"수컷","correct":true},{"t":"암컷","mis":"M3-2-u4-X14"},{"t":"두 길이가 같아요","mis":"M3-2-u4-X22"},{"t":"알 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["⟨5 3/10⟩ = 5.3, ⟨44/10⟩ = 4.4로 바꾸어요.","5.3 > 4.4예요.","수컷이 더 길어요."],"variant_rule":{"alt":[{"stem":"사슴벌레 수컷은 ⟨3 7/10⟩ cm, 암컷은 ⟨65/10⟩ cm예요. 어느 쪽이 더 긴가요?","options":[{"t":"암컷","correct":true},{"t":"수컷","mis":"M3-2-u4-X14"},{"t":"두 길이가 같아요","mis":"M3-2-u4-X22"},{"t":"알 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["⟨3 7/10⟩ = 3.7, ⟨65/10⟩ = 6.5로 바꾸어요.","3.7 < 6.5예요.","암컷이 더 길어요."],"asset":null},{"stem":"장수풍뎅이 수컷은 ⟨6 2/10⟩ cm, 암컷은 ⟨32/10⟩ cm예요. 어느 쪽이 더 긴가요?","options":[{"t":"수컷","correct":true},{"t":"암컷","mis":"M3-2-u4-X14"},{"t":"두 길이가 같아요","mis":"M3-2-u4-X22"},{"t":"알 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["⟨6 2/10⟩ = 6.2, ⟨32/10⟩ = 3.2로 바꾸어요.","6.2 > 3.2예요.","수컷이 더 길어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L10_basic#9','math',3,2,'u4','L10','g3_2_math_u4_L10_basic','lesson_basic','M3-2-u4-C11',2,'ox','auto','민서가 「⟨4 6/10⟩과 3.7은 분수와 소수라서 크기를 견줄 수 없어.」라고 했어요. 바르게 말했어요.',ARRAY['M3-2-u4-X22']::text[],true,'{"seq":9,"concept":"M3-2-u4-C11","difficulty":2,"kind":"ox","stem":"민서가 「⟨4 6/10⟩과 3.7은 분수와 소수라서 크기를 견줄 수 없어.」라고 했어요. 바르게 말했어요.","answer":"X","reason_options":[{"t":"⟨4 6/10⟩ = 4.6으로 바꾸면 견줄 수 있어서","correct":true},{"t":"분수와 소수는 다른 수라서","mis":"M3-2-u4-X22"}],"mis":"M3-2-u4-X22","explanation":["분모가 10인 분수는 소수로 바꿀 수 있어요.","⟨4 6/10⟩ = 4.6이에요.","4.6 > 3.7 — 견줄 수 있어요 ×."],"variant_rule":{"alt":[{"stem":"준우가 「⟨4 8/10⟩과 5.4는 분수와 소수라서 크기를 견줄 수 없어.」라고 했어요. 바르게 말했어요.","answer":"X","reason_options":[{"t":"⟨4 8/10⟩ = 4.8로 바꾸면 견줄 수 있어서","correct":true},{"t":"분수와 소수는 다른 수라서","mis":"M3-2-u4-X22"}],"explanation":["분모가 10인 분수는 소수로 바꿀 수 있어요.","⟨4 8/10⟩ = 4.8이에요.","4.8 < 5.4 — 견줄 수 있어요 ×."],"asset":null},{"stem":"준우가 「⟨5 9/10⟩와 3.1은 분수와 소수라서 크기를 견줄 수 없어.」라고 했어요. 바르게 말했어요.","answer":"X","reason_options":[{"t":"⟨5 9/10⟩ = 5.9로 바꾸면 견줄 수 있어서","correct":true},{"t":"분수와 소수는 다른 수라서","mis":"M3-2-u4-X22"}],"explanation":["분모가 10인 분수는 소수로 바꿀 수 있어요.","⟨5 9/10⟩ = 5.9예요.","5.9 > 3.1 — 견줄 수 있어요 ×."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L10_basic#10','math',3,2,'u4','L10','g3_2_math_u4_L10_basic','lesson_basic','M3-2-u4-C11',3,'mc','auto','네 수 중에서 가장 작은 수는 무엇인가요? 6.4, 6.6, ⟨69/10⟩, ⟨6 2/10⟩',ARRAY['M3-2-u4-X14','M3-2-u4-X20']::text[],true,'{"seq":10,"concept":"M3-2-u4-C11","difficulty":3,"kind":"mc","stem":"네 수 중에서 가장 작은 수는 무엇인가요? 6.4, 6.6, ⟨69/10⟩, ⟨6 2/10⟩","options":[{"t":"⟨6 2/10⟩","correct":true},{"t":"6.4","mis":"M3-2-u4-X14"},{"t":"6.6","mis":"M3-2-u4-X14"},{"t":"⟨69/10⟩","mis":"M3-2-u4-X20"}],"explanation":["분수는 소수로 바꾸어요 — 6.4, 6.6, 6.9, 6.2.","자연수 부분부터, 같으면 소수점 오른쪽 수를 견주어요.","가장 작은 수는 ⟨6 2/10⟩예요."],"variant_rule":{"alt":[{"stem":"네 수 중에서 가장 작은 수는 무엇인가요? ⟨1 9/10⟩, ⟨1 7/10⟩, 2.6, 1.8","options":[{"t":"⟨1 7/10⟩","correct":true},{"t":"⟨1 9/10⟩","mis":"M3-2-u4-X14"},{"t":"2.6","mis":"M3-2-u4-X20"},{"t":"1.8","mis":"M3-2-u4-X14"}],"explanation":["분수는 소수로 바꾸어요 — 1.9, 1.7, 2.6, 1.8.","자연수 부분부터, 같으면 소수점 오른쪽 수를 견주어요.","가장 작은 수는 ⟨1 7/10⟩이에요."],"asset":null},{"stem":"네 수 중에서 가장 작은 수는 무엇인가요? 5.2, ⟨5 4/10⟩, ⟨5 9/10⟩, 4.3","options":[{"t":"4.3","correct":true},{"t":"5.2","mis":"M3-2-u4-X14"},{"t":"⟨5 4/10⟩","mis":"M3-2-u4-X14"},{"t":"⟨5 9/10⟩","mis":"M3-2-u4-X20"}],"explanation":["분수는 소수로 바꾸어요 — 5.2, 5.4, 5.9, 4.3.","자연수 부분부터, 같으면 소수점 오른쪽 수를 견주어요.","가장 작은 수는 4.3이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L10_challenge#1','math',3,2,'u4','L10','g3_2_math_u4_L10_challenge','lesson_challenge','M3-2-u4-C11',2,'mc','auto','두 수의 크기를 바르게 견준 것은 무엇인가요?',ARRAY['M3-2-u4-X14','M3-2-u4-X22']::text[],true,'{"seq":1,"concept":"M3-2-u4-C11","difficulty":2,"kind":"mc","stem":"두 수의 크기를 바르게 견준 것은 무엇인가요?","options":[{"t":"⟨12/10⟩ < 1.5","correct":true},{"t":"⟨12/10⟩ > 1.5","mis":"M3-2-u4-X14"},{"t":"⟨12/10⟩ = 1.5","mis":"M3-2-u4-X22"},{"t":"견줄 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["분모가 10인 분수는 소수로 바꿀 수 있어요 — ⟨12/10⟩ = 1.2.","소수로 견주어요 — 자연수 부분부터, 같으면 소수점 오른쪽 수.","⟨12/10⟩ < 1.5."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 두 수의 크기를 바르게 견준 것은 무엇인가요?","options":[{"t":"8.6 > ⟨74/10⟩","correct":true},{"t":"8.6 < ⟨74/10⟩","mis":"M3-2-u4-X14"},{"t":"8.6 = ⟨74/10⟩","mis":"M3-2-u4-X22"},{"t":"견줄 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["분모가 10인 분수는 소수로 바꿀 수 있어요 — ⟨74/10⟩ = 7.4.","소수로 견주어요 — 자연수 부분부터, 같으면 소수점 오른쪽 수.","8.6 > ⟨74/10⟩."],"asset":null},{"stem":"이번에는 다른 문제예요. 두 수의 크기를 바르게 견준 것은 무엇인가요?","options":[{"t":"⟨34/10⟩ > 3.3","correct":true},{"t":"⟨34/10⟩ < 3.3","mis":"M3-2-u4-X14"},{"t":"⟨34/10⟩ = 3.3","mis":"M3-2-u4-X22"},{"t":"견줄 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["분모가 10인 분수는 소수로 바꿀 수 있어요 — ⟨34/10⟩ = 3.4.","소수로 견주어요 — 자연수 부분부터, 같으면 소수점 오른쪽 수.","⟨34/10⟩ > 3.3."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
