INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L10_challenge#3','math',3,2,'u4','L10','g3_2_math_u4_L10_challenge','lesson_challenge','M3-2-u4-C11',3,'mc','auto','⟨1 □/10⟩가 ⟨1 6/10⟩보다 클 때, □ 안에 들어갈 수 있는 수를 모두 고른 것은 무엇인가요?',ARRAY['M3-2-u4-X21','M3-2-u4-X20']::text[],true,'{"seq":3,"concept":"M3-2-u4-C11","difficulty":3,"kind":"mc","stem":"⟨1 □/10⟩가 ⟨1 6/10⟩보다 클 때, □ 안에 들어갈 수 있는 수를 모두 고른 것은 무엇인가요?","options":[{"t":"7, 8, 9","correct":true},{"t":"6, 7, 8, 9","mis":"M3-2-u4-X21"},{"t":"1, 2, 3, 4, 5","mis":"M3-2-u4-X20"},{"t":"7","mis":"M3-2-u4-X21"}],"explanation":["자연수 부분이 1로 같아요.","분수 부분의 분자 □가 6보다 커야 해요.","□ = 7, 8, 9 — 6은 같아서 넣지 않아요."],"variant_rule":{"alt":[{"stem":"⟨1 □/10⟩가 ⟨1 4/10⟩보다 클 때, □ 안에 들어갈 수 있는 수를 모두 고른 것은 무엇인가요?","options":[{"t":"5, 6, 7, 8, 9","correct":true},{"t":"4, 5, 6, 7, 8, 9","mis":"M3-2-u4-X21"},{"t":"1, 2, 3","mis":"M3-2-u4-X20"},{"t":"5","mis":"M3-2-u4-X21"}],"explanation":["자연수 부분이 1로 같아요.","분수 부분의 분자 □가 4보다 커야 해요.","□ = 5, 6, 7, 8, 9 — 4는 같아서 넣지 않아요."],"asset":null},{"stem":"⟨5 □/10⟩가 ⟨5 5/10⟩보다 클 때, □ 안에 들어갈 수 있는 수를 모두 고른 것은 무엇인가요?","options":[{"t":"6, 7, 8, 9","correct":true},{"t":"5, 6, 7, 8, 9","mis":"M3-2-u4-X21"},{"t":"1, 2, 3, 4","mis":"M3-2-u4-X20"},{"t":"6","mis":"M3-2-u4-X21"}],"explanation":["자연수 부분이 5로 같아요.","분수 부분의 분자 □가 5보다 커야 해요.","□ = 6, 7, 8, 9 — 5는 같아서 넣지 않아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L10_challenge#4','math',3,2,'u4','L10','g3_2_math_u4_L10_challenge','lesson_challenge','M3-2-u4-C11',3,'sa','auto','8.6 < 8.□일 때, □ 안에 들어갈 수 있는 수는 모두 몇 개인가요? (□는 0부터 9까지의 수) 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-2-u4-C11","difficulty":3,"kind":"sa","stem":"8.6 < 8.□일 때, □ 안에 들어갈 수 있는 수는 모두 몇 개인가요? (□는 0부터 9까지의 수) 숫자로 쓰세요.","answer":["3"],"explanation":["자연수 부분이 8로 같아요.","□는 6보다 커야 해요 — 7, 8, 9.","모두 3개 — 6은 같아서 빼요."],"variant_rule":{"alt":[{"stem":"1.5 < 1.□일 때, □ 안에 들어갈 수 있는 수는 모두 몇 개인가요? (□는 0부터 9까지의 수) 숫자로 쓰세요.","answer":["4"],"explanation":["자연수 부분이 1로 같아요.","□는 5보다 커야 해요 — 6, 7, 8, 9.","모두 4개 — 5는 같아서 빼요."],"asset":null},{"stem":"2.2 < 2.□일 때, □ 안에 들어갈 수 있는 수는 모두 몇 개인가요? (□는 0부터 9까지의 수) 숫자로 쓰세요.","answer":["7"],"explanation":["자연수 부분이 2로 같아요.","□는 2보다 커야 해요 — 3, 4, 5, 6, 7, 8, 9.","모두 7개 — 2는 같아서 빼요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
