INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L10_challenge#6','math',3,2,'u4','L10','g3_2_math_u4_L10_challenge','lesson_challenge','M3-2-u4-C11',3,'mc','auto','두 수의 크기를 바르게 견준 것은 무엇인가요?',ARRAY['M3-2-u4-X14','M3-2-u4-X22']::text[],true,'{"seq":6,"concept":"M3-2-u4-C11","difficulty":3,"kind":"mc","stem":"두 수의 크기를 바르게 견준 것은 무엇인가요?","options":[{"t":"⟨32/10⟩ < ⟨3 5/10⟩","correct":true},{"t":"⟨32/10⟩ > ⟨3 5/10⟩","mis":"M3-2-u4-X14"},{"t":"⟨32/10⟩ = ⟨3 5/10⟩","mis":"M3-2-u4-X22"},{"t":"견줄 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["분모가 10인 분수는 소수로 바꿀 수 있어요 — ⟨32/10⟩ = 3.2, ⟨3 5/10⟩ = 3.5.","소수로 견주어요 — 자연수 부분부터, 같으면 소수점 오른쪽 수.","⟨32/10⟩ < ⟨3 5/10⟩."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 두 수의 크기를 바르게 견준 것은 무엇인가요?","options":[{"t":"⟨6 3/10⟩ > 5.5","correct":true},{"t":"⟨6 3/10⟩ < 5.5","mis":"M3-2-u4-X14"},{"t":"⟨6 3/10⟩ = 5.5","mis":"M3-2-u4-X22"},{"t":"견줄 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["분모가 10인 분수는 소수로 바꿀 수 있어요 — ⟨6 3/10⟩ = 6.3.","소수로 견주어요 — 자연수 부분부터, 같으면 소수점 오른쪽 수.","⟨6 3/10⟩ > 5.5."],"asset":null},{"stem":"이번에는 다른 문제예요. 두 수의 크기를 바르게 견준 것은 무엇인가요?","options":[{"t":"⟨92/10⟩ > ⟨8 4/10⟩","correct":true},{"t":"⟨92/10⟩ < ⟨8 4/10⟩","mis":"M3-2-u4-X14"},{"t":"⟨92/10⟩ = ⟨8 4/10⟩","mis":"M3-2-u4-X22"},{"t":"견줄 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["분모가 10인 분수는 소수로 바꿀 수 있어요 — ⟨92/10⟩ = 9.2, ⟨8 4/10⟩ = 8.4.","소수로 견주어요 — 자연수 부분부터, 같으면 소수점 오른쪽 수.","⟨92/10⟩ > ⟨8 4/10⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L10_challenge#7','math',3,2,'u4','L10','g3_2_math_u4_L10_challenge','lesson_challenge','M3-2-u4-C11',3,'mc','auto','네 수 중에서 가장 작은 수는 무엇인가요? 6.8, ⟨7 9/10⟩, ⟨6 3/10⟩, 6.9',ARRAY['M3-2-u4-X14','M3-2-u4-X20']::text[],true,'{"seq":7,"concept":"M3-2-u4-C11","difficulty":3,"kind":"mc","stem":"네 수 중에서 가장 작은 수는 무엇인가요? 6.8, ⟨7 9/10⟩, ⟨6 3/10⟩, 6.9","options":[{"t":"⟨6 3/10⟩","correct":true},{"t":"6.8","mis":"M3-2-u4-X14"},{"t":"⟨7 9/10⟩","mis":"M3-2-u4-X20"},{"t":"6.9","mis":"M3-2-u4-X14"}],"explanation":["분수는 소수로 바꾸어요 — 6.8, 7.9, 6.3, 6.9.","자연수 부분부터, 같으면 소수점 오른쪽 수를 견주어요.","가장 작은 수는 ⟨6 3/10⟩이에요."],"variant_rule":{"alt":[{"stem":"네 수 중에서 가장 작은 수는 무엇인가요? 1.5, ⟨1 1/10⟩, ⟨1 3/10⟩, ⟨12/10⟩","options":[{"t":"⟨1 1/10⟩","correct":true},{"t":"1.5","mis":"M3-2-u4-X20"},{"t":"⟨1 3/10⟩","mis":"M3-2-u4-X14"},{"t":"⟨12/10⟩","mis":"M3-2-u4-X14"}],"explanation":["분수는 소수로 바꾸어요 — 1.5, 1.1, 1.3, 1.2.","자연수 부분부터, 같으면 소수점 오른쪽 수를 견주어요.","가장 작은 수는 ⟨1 1/10⟩이에요."],"asset":null},{"stem":"네 수 중에서 가장 작은 수는 무엇인가요? ⟨3 4/10⟩, 4.2, ⟨3 2/10⟩, 4.1","options":[{"t":"⟨3 2/10⟩","correct":true},{"t":"⟨3 4/10⟩","mis":"M3-2-u4-X14"},{"t":"4.2","mis":"M3-2-u4-X20"},{"t":"4.1","mis":"M3-2-u4-X14"}],"explanation":["분수는 소수로 바꾸어요 — 3.4, 4.2, 3.2, 4.1.","자연수 부분부터, 같으면 소수점 오른쪽 수를 견주어요.","가장 작은 수는 ⟨3 2/10⟩예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L10_challenge#8','math',3,2,'u4','L10','g3_2_math_u4_L10_challenge','lesson_challenge','M3-2-u4-C11',4,'essay','teacher','분수 마을에는 ⟨2 5/10⟩와 ⟨3 1/10⟩, 소수 마을에는 3.6과 2.8이 살아요. 네 수 중에서 가장 큰 수를 찾고, 그 방법을 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-2-u4-C11","difficulty":4,"kind":"essay","stem":"분수 마을에는 ⟨2 5/10⟩와 ⟨3 1/10⟩, 소수 마을에는 3.6과 2.8이 살아요. 네 수 중에서 가장 큰 수를 찾고, 그 방법을 설명해 보세요.","answer_guide":{"answer":"예: 분모가 10인 분수를 소수로 바꾸면 ⟨2 5/10⟩ = 2.5, ⟨3 1/10⟩ = 3.1이다. 네 수 2.5, 3.1, 3.6, 2.8에서 자연수 부분이 3인 3.1과 3.6을 견주면 소수점 오른쪽 수 6이 더 크므로 가장 큰 수는 3.6이다.","scoring_points":["분수를 소수로(또는 소수를 분수로) 바꾸었는가","자연수 부분부터 견주었는가","3.6이 가장 크다고 답했는가"]},"explanation":["⟨2 5/10⟩ = 2.5, ⟨3 1/10⟩ = 3.1.","3.1 < 3.6.","가장 큰 수는 3.6."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L10_challenge#9','math',3,2,'u4','L10','g3_2_math_u4_L10_challenge','lesson_challenge','M3-2-u4-C11',4,'essay','teacher','1.6 < 1.□일 때, □ 안에 들어갈 수 있는 수를 모두 구하고 그렇게 생각한 까닭을 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-2-u4-C11","difficulty":4,"kind":"essay","stem":"1.6 < 1.□일 때, □ 안에 들어갈 수 있는 수를 모두 구하고 그렇게 생각한 까닭을 써 보세요.","answer_guide":{"answer":"예: 7, 8, 9이다. 자연수 부분이 1로 같으므로 소수점 오른쪽 수를 견준다. □가 6보다 커야 하므로 7, 8, 9가 들어갈 수 있다. 6은 두 수가 같아지므로 넣을 수 없다.","scoring_points":["7, 8, 9를 모두 구했는가","자연수 부분이 같아 소수점 오른쪽 수를 견준다고 썼는가","6은 들어갈 수 없다고 썼는가"]},"explanation":["자연수 부분 1로 같아요.","□ > 6.","□ = 7, 8, 9."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_L10_challenge#10','math',3,2,'u4','L10','g3_2_math_u4_L10_challenge','lesson_challenge','M3-2-u4-C11',4,'mc','auto','⟨2 □/10⟩가 ⟨2 2/10⟩보다 클 때, □ 안에 들어갈 수 있는 수를 모두 고른 것은 무엇인가요?',ARRAY['M3-2-u4-X21','M3-2-u4-X20']::text[],true,'{"seq":10,"concept":"M3-2-u4-C11","difficulty":4,"kind":"mc","stem":"⟨2 □/10⟩가 ⟨2 2/10⟩보다 클 때, □ 안에 들어갈 수 있는 수를 모두 고른 것은 무엇인가요?","options":[{"t":"3, 4, 5, 6, 7, 8, 9","correct":true},{"t":"2, 3, 4, 5, 6, 7, 8, 9","mis":"M3-2-u4-X21"},{"t":"1","mis":"M3-2-u4-X20"},{"t":"3","mis":"M3-2-u4-X21"}],"explanation":["자연수 부분이 2로 같아요.","분수 부분의 분자 □가 2보다 커야 해요.","□ = 3, 4, 5, 6, 7, 8, 9 — 2는 같아서 넣지 않아요."],"variant_rule":{"alt":[{"stem":"⟨9 □/10⟩가 ⟨9 4/10⟩보다 클 때, □ 안에 들어갈 수 있는 수를 모두 고른 것은 무엇인가요?","options":[{"t":"5, 6, 7, 8, 9","correct":true},{"t":"4, 5, 6, 7, 8, 9","mis":"M3-2-u4-X21"},{"t":"1, 2, 3","mis":"M3-2-u4-X20"},{"t":"5","mis":"M3-2-u4-X21"}],"explanation":["자연수 부분이 9로 같아요.","분수 부분의 분자 □가 4보다 커야 해요.","□ = 5, 6, 7, 8, 9 — 4는 같아서 넣지 않아요."],"asset":null},{"stem":"⟨7 □/10⟩가 ⟨7 4/10⟩보다 클 때, □ 안에 들어갈 수 있는 수를 모두 고른 것은 무엇인가요?","options":[{"t":"5, 6, 7, 8, 9","correct":true},{"t":"4, 5, 6, 7, 8, 9","mis":"M3-2-u4-X21"},{"t":"1, 2, 3","mis":"M3-2-u4-X20"},{"t":"5","mis":"M3-2-u4-X21"}],"explanation":["자연수 부분이 7로 같아요.","분수 부분의 분자 □가 4보다 커야 해요.","□ = 5, 6, 7, 8, 9 — 4는 같아서 넣지 않아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_a#1','math',3,2,'u4','','g3_2_math_u4_review_a','unit_review','M3-2-u4-C1',1,'mc','auto','2개씩 묶었어요. 색칠한 부분은 전체의 얼마인가요?',ARRAY['M3-2-u4-X01','M3-2-u4-X02','M3-2-u4-X20']::text[],true,'{"seq":1,"concept":"M3-2-u4-C1","difficulty":1,"kind":"mc","stem":"2개씩 묶었어요. 색칠한 부분은 전체의 얼마인가요?","options":[{"t":"⟨1/5⟩","correct":true},{"t":"⟨1/4⟩","mis":"M3-2-u4-X01"},{"t":"⟨2/5⟩","mis":"M3-2-u4-X02"},{"t":"⟨4/5⟩","mis":"M3-2-u4-X20"}],"explanation":["2개씩 묶으니 모두 5묶음 — 분모 5.","색칠한 묶음은 1묶음 — 분자 1.","색칠한 부분은 전체의 ⟨1/5⟩이에요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[2.7,0],[3.7,0],[3.7,1],[2.7,1]]},{"p":[[3.7,0],[4.7,0],[4.7,1],[3.7,1]]},{"p":[[5.4,0],[6.4,0],[6.4,1],[5.4,1]]},{"p":[[6.4,0],[7.4,0],[7.4,1],[6.4,1]]},{"p":[[8.1,0],[9.1,0],[9.1,1],[8.1,1]]},{"p":[[9.1,0],[10.1,0],[10.1,1],[9.1,1]]},{"p":[[10.8,0],[11.8,0],[11.8,1],[10.8,1]]},{"p":[[11.8,0],[12.8,0],[12.8,1],[11.8,1]]}],"u":23},"variant_rule":{"alt":[{"stem":"1개씩 묶었어요. 색칠한 부분은 전체의 얼마인가요?","options":[{"t":"⟨1/4⟩","correct":true},{"t":"⟨1/3⟩","mis":"M3-2-u4-X01"},{"t":"⟨3/4⟩","mis":"M3-2-u4-X20"},{"t":"⟨2/4⟩","mis":"M3-2-u4-X21"}],"explanation":["1개씩 묶으니 모두 4묶음 — 분모 4.","색칠한 묶음은 1묶음 — 분자 1.","색칠한 부분은 전체의 ⟨1/4⟩이에요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1.7,0],[2.7,0],[2.7,1],[1.7,1]]},{"p":[[3.4,0],[4.4,0],[4.4,1],[3.4,1]]},{"p":[[5.1,0],[6.1,0],[6.1,1],[5.1,1]]}],"u":30}},{"stem":"이번에는 다른 문제예요. 2개씩 묶었어요. 색칠한 부분은 전체의 얼마인가요?","options":[{"t":"⟨2/4⟩","correct":true},{"t":"⟨4/2⟩","mis":"M3-2-u4-X03"},{"t":"⟨4/4⟩","mis":"M3-2-u4-X02"},{"t":"⟨3/4⟩","mis":"M3-2-u4-X21"}],"explanation":["2개씩 묶으니 모두 4묶음 — 분모 4.","색칠한 묶음은 2묶음 — 분자 2.","색칠한 부분은 전체의 ⟨2/4⟩예요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[2.7,0],[3.7,0],[3.7,1],[2.7,1]],"hi":true},{"p":[[3.7,0],[4.7,0],[4.7,1],[3.7,1]],"hi":true},{"p":[[5.4,0],[6.4,0],[6.4,1],[5.4,1]]},{"p":[[6.4,0],[7.4,0],[7.4,1],[6.4,1]]},{"p":[[8.1,0],[9.1,0],[9.1,1],[8.1,1]]},{"p":[[9.1,0],[10.1,0],[10.1,1],[9.1,1]]}],"u":29}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_a#2','math',3,2,'u4','','g3_2_math_u4_review_a','unit_review','M3-2-u4-C3',1,'sa','auto','8의 ⟨1/4⟩은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u4-C3","difficulty":1,"kind":"sa","stem":"8의 ⟨1/4⟩은 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["8을 분모만큼 똑같이 4묶음으로 나누면 한 묶음에 2개예요 — 8의 ⟨1/4⟩은 2.","⟨1/4⟩은 그중 1묶음이에요.","8의 ⟨1/4⟩은 2 — 8 ÷ 4와 같아요."],"variant_rule":{"alt":[{"stem":"10의 ⟨1/2⟩은 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["10을 분모만큼 똑같이 2묶음으로 나누면 한 묶음에 5개예요 — 10의 ⟨1/2⟩은 5.","⟨1/2⟩은 그중 1묶음이에요.","10의 ⟨1/2⟩은 5 — 10 ÷ 2와 같아요."],"asset":null},{"stem":"6의 ⟨1/2⟩은 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["6을 분모만큼 똑같이 2묶음으로 나누면 한 묶음에 3개예요 — 6의 ⟨1/2⟩은 3.","⟨1/2⟩은 그중 1묶음이에요.","6의 ⟨1/2⟩은 3 — 6 ÷ 2와 같아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_a#3','math',3,2,'u4','','g3_2_math_u4_review_a','unit_review','M3-2-u4-C4',1,'sa','auto','철사 45 cm의 ⟨1/3⟩은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-2-u4-C4","difficulty":1,"kind":"sa","stem":"철사 45 cm의 ⟨1/3⟩은 몇 cm인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["45 cm를 분모만큼 똑같이 3부분으로 나누면 한 부분이 15 cm예요.","⟨1/3⟩은 한 부분이에요.","45 cm의 ⟨1/3⟩은 15 cm — 나눈 부분의 길이는 모두 같아야 해요."],"asset":{"type":"fbar","bars":[{"den":3,"num":1,"grp":1,"label":"철사 45 cm"}]},"variant_rule":{"alt":[{"stem":"등산로 14 km의 ⟨1/2⟩은 몇 km인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["14 km를 분모만큼 똑같이 2부분으로 나누면 한 부분이 7 km예요.","⟨1/2⟩은 한 부분이에요.","14 km의 ⟨1/2⟩은 7 km — 나눈 부분의 길이는 모두 같아야 해요."],"asset":{"type":"fbar","bars":[{"den":2,"num":1,"grp":1,"label":"등산로 14 km"}]}},{"stem":"리본 60 cm의 ⟨3/4⟩은 몇 cm인가요? 숫자로 쓰세요.","answer":["45"],"explanation":["60 cm를 분모만큼 똑같이 4부분으로 나누면 한 부분이 15 cm예요.","⟨3/4⟩은 그런 부분 3개예요.","60 cm의 ⟨3/4⟩은 45 cm — 나눈 부분의 길이는 모두 같아야 해요."],"asset":{"type":"fbar","bars":[{"den":4,"num":3,"grp":1,"label":"리본 60 cm"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_a#4','math',3,2,'u4','','g3_2_math_u4_review_a','unit_review','M3-2-u4-C5',1,'mc','auto','분수 ⟨7/6⟩은 무엇인가요?',ARRAY['M3-2-u4-X08']::text[],true,'{"seq":4,"concept":"M3-2-u4-C5","difficulty":1,"kind":"mc","stem":"분수 ⟨7/6⟩은 무엇인가요?","options":[{"t":"가분수","correct":true},{"t":"진분수","mis":"M3-2-u4-X08"},{"t":"대분수","mis":"M3-2-u4-X08"},{"t":"자연수","mis":"M3-2-u4-X08"}],"explanation":["분자 7, 분모 6을 견주어요.","분자가 분모보다 커요.","⟨7/6⟩은 가분수 — 분자가 분모와 같거나 큰 분수."],"variant_rule":{"alt":[{"stem":"분수 ⟨1/2⟩은 무엇인가요?","options":[{"t":"진분수","correct":true},{"t":"가분수","mis":"M3-2-u4-X08"},{"t":"대분수","mis":"M3-2-u4-X08"},{"t":"자연수","mis":"M3-2-u4-X08"}],"explanation":["분자 1, 분모 2를 견주어요.","분자가 분모보다 작아요.","⟨1/2⟩은 진분수 — 분자가 분모보다 작은 분수."],"asset":null},{"stem":"분수 ⟨6/9⟩은 무엇인가요?","options":[{"t":"진분수","correct":true},{"t":"가분수","mis":"M3-2-u4-X08"},{"t":"대분수","mis":"M3-2-u4-X08"},{"t":"자연수","mis":"M3-2-u4-X08"}],"explanation":["분자 6, 분모 9를 견주어요.","분자가 분모보다 작아요.","⟨6/9⟩은 진분수 — 분자가 분모보다 작은 분수."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_a#5','math',3,2,'u4','','g3_2_math_u4_review_a','unit_review','M3-2-u4-C6',1,'sa','auto','2를 분모가 9인 분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-2-u4-C6","difficulty":1,"kind":"sa","stem":"2를 분모가 9인 분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["⟨1/9⟩이 9개면 1이에요 — 1 = ⟨9/9⟩.","2는 1이 2개 — ⟨1/9⟩이 9 × 2 = 18개.","2 = ⟨18/9⟩ — 분자는 18."],"variant_rule":{"alt":[{"stem":"1을 분모가 7인 분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["⟨1/7⟩이 7개면 1이에요 — 1 = ⟨7/7⟩.","그래서 1 = ⟨7/7⟩.","1 = ⟨7/7⟩ — 분자는 7."],"asset":null},{"stem":"1을 분모가 6인 분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["⟨1/6⟩이 6개면 1이에요 — 1 = ⟨6/6⟩.","그래서 1 = ⟨6/6⟩.","1 = ⟨6/6⟩ — 분자는 6."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_a#6','math',3,2,'u4','','g3_2_math_u4_review_a','unit_review','M3-2-u4-C7',1,'mc','auto','똑같은 띠 2개에 색칠했어요. 색칠한 부분을 대분수로 나타내면 무엇인가요?',ARRAY['M3-2-u4-X12','M3-2-u4-X21','M3-2-u4-X20']::text[],true,'{"seq":6,"concept":"M3-2-u4-C7","difficulty":1,"kind":"mc","stem":"똑같은 띠 2개에 색칠했어요. 색칠한 부분을 대분수로 나타내면 무엇인가요?","options":[{"t":"⟨1 3/4⟩","correct":true},{"t":"⟨3/4⟩","mis":"M3-2-u4-X12"},{"t":"⟨2 3/4⟩","mis":"M3-2-u4-X21"},{"t":"⟨1 1/4⟩","mis":"M3-2-u4-X20"}],"explanation":["통째로 색칠한 띠가 1개 — 자연수 부분 1.","남은 띠는 4칸 중 3칸 — 진분수 ⟨3/4⟩.","색칠한 부분은 ⟨1 3/4⟩이에요."],"asset":{"type":"fbar","bars":[{"den":4,"num":4},{"den":4,"num":3}]},"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 똑같은 띠 2개에 색칠했어요. 색칠한 부분을 대분수로 나타내면 무엇인가요?","options":[{"t":"⟨1 1/2⟩","correct":true},{"t":"⟨1/2⟩","mis":"M3-2-u4-X12"},{"t":"⟨2 1/2⟩","mis":"M3-2-u4-X21"},{"t":"⟨1 1/3⟩","mis":"M3-2-u4-X21"}],"explanation":["통째로 색칠한 띠가 1개 — 자연수 부분 1.","남은 띠는 2칸 중 1칸 — 진분수 ⟨1/2⟩.","색칠한 부분은 ⟨1 1/2⟩이에요."],"asset":{"type":"fbar","bars":[{"den":2,"num":2},{"den":2,"num":1}]}},{"stem":"똑같은 띠 3개에 색칠했어요. 색칠한 부분을 대분수로 나타내면 무엇인가요?","options":[{"t":"⟨2 1/2⟩","correct":true},{"t":"⟨1/2⟩","mis":"M3-2-u4-X12"},{"t":"⟨3 1/2⟩","mis":"M3-2-u4-X21"},{"t":"⟨1 1/2⟩","mis":"M3-2-u4-X12"}],"explanation":["통째로 색칠한 띠가 2개 — 자연수 부분 2.","남은 띠는 2칸 중 1칸 — 진분수 ⟨1/2⟩.","색칠한 부분은 ⟨2 1/2⟩이에요."],"asset":{"type":"fbar","bars":[{"den":2,"num":2},{"den":2,"num":2},{"den":2,"num":1}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_a#7','math',3,2,'u4','','g3_2_math_u4_review_a','unit_review','M3-2-u4-C9',1,'sa','auto','1.1은 0.1이 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M3-2-u4-C9","difficulty":1,"kind":"sa","stem":"1.1은 0.1이 몇 개인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["1은 0.1이 10개예요 — 1은 0.1이 10개.","0.1은 0.1이 1개예요.","1.1은 0.1이 10 + 1 = 11개."],"variant_rule":{"alt":[{"stem":"7.1은 0.1이 몇 개인가요? 숫자로 쓰세요.","answer":["71"],"explanation":["1은 0.1이 10개예요 — 7은 0.1이 70개.","0.1은 0.1이 1개예요.","7.1은 0.1이 70 + 1 = 71개."],"asset":null},{"stem":"3.5는 0.1이 몇 개인가요? 숫자로 쓰세요.","answer":["35"],"explanation":["1은 0.1이 10개예요 — 3은 0.1이 30개.","0.5는 0.1이 5개예요.","3.5는 0.1이 30 + 5 = 35개."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_a#8','math',3,2,'u4','','g3_2_math_u4_review_a','unit_review','M3-2-u4-C10',1,'mc','auto','두 수의 크기를 바르게 견준 것은 무엇인가요?',ARRAY['M3-2-u4-X18','M3-2-u4-X22']::text[],true,'{"seq":8,"concept":"M3-2-u4-C10","difficulty":1,"kind":"mc","stem":"두 수의 크기를 바르게 견준 것은 무엇인가요?","options":[{"t":"7.8 > 6.2","correct":true},{"t":"7.8 < 6.2","mis":"M3-2-u4-X18"},{"t":"7.8 = 6.2","mis":"M3-2-u4-X22"},{"t":"견줄 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["자연수 부분부터 견주어요 — 7과 6.","자연수 부분이 큰 소수가 더 커요.","7.8 > 6.2 — 0.1이 78개와 62개로 견주어도 같아요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 두 수의 크기를 바르게 견준 것은 무엇인가요?","options":[{"t":"4.8 < 8.2","correct":true},{"t":"4.8 > 8.2","mis":"M3-2-u4-X18"},{"t":"4.8 = 8.2","mis":"M3-2-u4-X22"},{"t":"견줄 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["자연수 부분부터 견주어요 — 4와 8.","자연수 부분이 큰 소수가 더 커요.","4.8 < 8.2 — 0.1이 48개와 82개로 견주어도 같아요."],"asset":null},{"stem":"이번에는 다른 문제예요. 두 수의 크기를 바르게 견준 것은 무엇인가요?","options":[{"t":"8.4 < 9.9","correct":true},{"t":"8.4 > 9.9","mis":"M3-2-u4-X18"},{"t":"8.4 = 9.9","mis":"M3-2-u4-X22"},{"t":"견줄 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["자연수 부분부터 견주어요 — 8과 9.","자연수 부분이 큰 소수가 더 커요.","8.4 < 9.9 — 0.1이 84개와 99개로 견주어도 같아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_a#9','math',3,2,'u4','','g3_2_math_u4_review_a','unit_review','M3-2-u4-C2',2,'mc','auto','검은 돌 4개와 흰 돌 5개가 있어요. 검은 돌은 전체 돌의 얼마인가요?',ARRAY['M3-2-u4-X01','M3-2-u4-X20','M3-2-u4-X03']::text[],true,'{"seq":9,"concept":"M3-2-u4-C2","difficulty":2,"kind":"mc","stem":"검은 돌 4개와 흰 돌 5개가 있어요. 검은 돌은 전체 돌의 얼마인가요?","options":[{"t":"⟨4/9⟩","correct":true},{"t":"⟨4/5⟩","mis":"M3-2-u4-X01"},{"t":"⟨5/9⟩","mis":"M3-2-u4-X20"},{"t":"⟨9/4⟩","mis":"M3-2-u4-X03"}],"explanation":["먼저 전체를 정해요 — 돌은 모두 4 + 5 = 9개.","검은 돌은 흰 돌과 견주는 것이 아니라 전체 9개와 견주어요.","검은 돌은 전체의 ⟨4/9⟩예요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[2,0],[3,0],[3,1],[2,1]],"hi":true},{"p":[[3,0],[4,0],[4,1],[3,1]],"hi":true},{"p":[[4,0],[5,0],[5,1],[4,1]]},{"p":[[0,1],[1,1],[1,2],[0,2]]},{"p":[[1,1],[2,1],[2,2],[1,2]]},{"p":[[2,1],[3,1],[3,2],[2,2]]},{"p":[[3,1],[4,1],[4,2],[3,2]]}],"u":30},"variant_rule":{"alt":[{"stem":"검은 돌 2개와 흰 돌 3개가 있어요. 검은 돌은 전체 돌의 얼마인가요?","options":[{"t":"⟨2/5⟩","correct":true},{"t":"⟨2/3⟩","mis":"M3-2-u4-X01"},{"t":"⟨3/5⟩","mis":"M3-2-u4-X20"},{"t":"⟨5/2⟩","mis":"M3-2-u4-X03"}],"explanation":["먼저 전체를 정해요 — 돌은 모두 2 + 3 = 5개.","검은 돌은 흰 돌과 견주는 것이 아니라 전체 5개와 견주어요.","검은 돌은 전체의 ⟨2/5⟩예요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[2,0],[3,0],[3,1],[2,1]]},{"p":[[3,0],[4,0],[4,1],[3,1]]},{"p":[[4,0],[5,0],[5,1],[4,1]]}],"u":30}},{"stem":"검은 돌 2개와 흰 돌 4개가 있어요. 검은 돌은 전체 돌의 얼마인가요?","options":[{"t":"⟨2/6⟩","correct":true},{"t":"⟨2/4⟩","mis":"M3-2-u4-X01"},{"t":"⟨4/6⟩","mis":"M3-2-u4-X20"},{"t":"⟨6/2⟩","mis":"M3-2-u4-X03"}],"explanation":["먼저 전체를 정해요 — 돌은 모두 2 + 4 = 6개.","검은 돌은 흰 돌과 견주는 것이 아니라 전체 6개와 견주어요.","검은 돌은 전체의 ⟨2/6⟩예요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[2,0],[3,0],[3,1],[2,1]]},{"p":[[3,0],[4,0],[4,1],[3,1]]},{"p":[[4,0],[5,0],[5,1],[4,1]]},{"p":[[0,1],[1,1],[1,2],[0,2]]}],"u":30}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_a#10','math',3,2,'u4','','g3_2_math_u4_review_a','unit_review','M3-2-u4-C3',2,'mc','auto','귤 24개의 ⟨3/6⟩은 몇 개인가요?',ARRAY['M3-2-u4-X04','M3-2-u4-X05','M3-2-u4-X06']::text[],true,'{"seq":10,"concept":"M3-2-u4-C3","difficulty":2,"kind":"mc","stem":"귤 24개의 ⟨3/6⟩은 몇 개인가요?","options":[{"t":"12개","correct":true},{"t":"3개","mis":"M3-2-u4-X04"},{"t":"4개","mis":"M3-2-u4-X05"},{"t":"48개","mis":"M3-2-u4-X06"}],"explanation":["24를 분모만큼 똑같이 6묶음으로 나누면 한 묶음에 4개예요 — 24의 ⟨1/6⟩은 4.","⟨3/6⟩은 ⟨1/6⟩이 3개 — 3묶음이에요.","24의 ⟨3/6⟩은 4 × 3 = 12 — 분자만 보고 답하지 않아요."],"variant_rule":{"alt":[{"stem":"약과 25개의 ⟨3/5⟩은 몇 개인가요?","options":[{"t":"15개","correct":true},{"t":"3개","mis":"M3-2-u4-X04"},{"t":"5개","mis":"M3-2-u4-X05"},{"t":"20개","mis":"M3-2-u4-X21"}],"explanation":["25를 분모만큼 똑같이 5묶음으로 나누면 한 묶음에 5개예요 — 25의 ⟨1/5⟩은 5.","⟨3/5⟩은 ⟨1/5⟩이 3개 — 3묶음이에요.","25의 ⟨3/5⟩은 5 × 3 = 15 — 분자만 보고 답하지 않아요."],"asset":null},{"stem":"와플 12개의 ⟨5/6⟩는 몇 개인가요?","options":[{"t":"10개","correct":true},{"t":"5개","mis":"M3-2-u4-X04"},{"t":"2개","mis":"M3-2-u4-X05"},{"t":"12개","mis":"M3-2-u4-X21"}],"explanation":["12를 분모만큼 똑같이 6묶음으로 나누면 한 묶음에 2개예요 — 12의 ⟨1/6⟩은 2.","⟨5/6⟩는 ⟨1/6⟩이 5개 — 5묶음이에요.","12의 ⟨5/6⟩는 2 × 5 = 10 — 분자만 보고 답하지 않아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_a#11','math',3,2,'u4','','g3_2_math_u4_review_a','unit_review','M3-2-u4-C4',2,'sa','auto','도연이 하루의 ⟨2/6⟩ 동안 학교에 있는 시간은 몇 시간인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":11,"concept":"M3-2-u4-C4","difficulty":2,"kind":"sa","stem":"도연이 하루의 ⟨2/6⟩ 동안 학교에 있는 시간은 몇 시간인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["하루는 24시간이에요.","24를 똑같이 6부분으로 나누면 한 부분이 4시간이에요.","하루의 ⟨2/6⟩는 4 × 2 = 8시간."],"variant_rule":{"alt":[{"stem":"지훈이 하루의 ⟨3/12⟩ 동안 잠을 잔 시간은 몇 시간인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["하루는 24시간이에요.","24를 똑같이 12부분으로 나누면 한 부분이 2시간이에요.","하루의 ⟨3/12⟩은 2 × 3 = 6시간."],"asset":null},{"stem":"서윤이 하루의 ⟨9/24⟩ 동안 학교에 있는 시간은 몇 시간인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["하루는 24시간이에요.","24를 똑같이 24부분으로 나누면 한 부분이 1시간이에요.","하루의 ⟨9/24⟩는 1 × 9 = 9시간."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_a#12','math',3,2,'u4','','g3_2_math_u4_review_a','unit_review','M3-2-u4-C7',2,'sa','auto','⟨11/5⟩을 대분수로 나타내면 자연수 부분은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":12,"concept":"M3-2-u4-C7","difficulty":2,"kind":"sa","stem":"⟨11/5⟩을 대분수로 나타내면 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["⟨11/5⟩은 ⟨1/5⟩이 11개예요.","5개씩 모으면 1 — 11 ÷ 5 = 2 … 1, 통째로 2이고 ⟨1/5⟩이 1개 남아요.","⟨11/5⟩ = ⟨2 1/5⟩ — 분수 부분은 진분수예요."],"variant_rule":{"alt":[{"stem":"⟨7/2⟩을 대분수로 나타내면 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["⟨7/2⟩은 ⟨1/2⟩이 7개예요.","2개씩 모으면 1 — 7 ÷ 2 = 3 … 1, 통째로 3이고 ⟨1/2⟩이 1개 남아요.","⟨7/2⟩ = ⟨3 1/2⟩ — 분수 부분은 진분수예요."],"asset":null},{"stem":"⟨13/6⟩을 대분수로 나타내면 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["⟨13/6⟩은 ⟨1/6⟩이 13개예요.","6개씩 모으면 1 — 13 ÷ 6 = 2 … 1, 통째로 2이고 ⟨1/6⟩이 1개 남아요.","⟨13/6⟩ = ⟨2 1/6⟩ — 분수 부분은 진분수예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_a#13','math',3,2,'u4','','g3_2_math_u4_review_a','unit_review','M3-2-u4-C8',2,'mc','auto','두 수의 크기를 바르게 견준 것은 무엇인가요?',ARRAY['M3-2-u4-X13','M3-2-u4-X22']::text[],true,'{"seq":13,"concept":"M3-2-u4-C8","difficulty":2,"kind":"mc","stem":"두 수의 크기를 바르게 견준 것은 무엇인가요?","options":[{"t":"⟨2 4/6⟩ < ⟨5 1/6⟩","correct":true},{"t":"⟨2 4/6⟩ > ⟨5 1/6⟩","mis":"M3-2-u4-X13"},{"t":"⟨2 4/6⟩ = ⟨5 1/6⟩","mis":"M3-2-u4-X22"},{"t":"견줄 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["대분수는 자연수 부분부터 견주어요.","2 < 5 — 자연수 부분이 큰 쪽이 커요.","분수 부분은 1보다 작아서 뒤집지 못해요 — ⟨2 4/6⟩ < ⟨5 1/6⟩."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 두 수의 크기를 바르게 견준 것은 무엇인가요?","options":[{"t":"⟨4 3/6⟩ > ⟨1 5/6⟩","correct":true},{"t":"⟨4 3/6⟩ < ⟨1 5/6⟩","mis":"M3-2-u4-X13"},{"t":"⟨4 3/6⟩ = ⟨1 5/6⟩","mis":"M3-2-u4-X22"},{"t":"견줄 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["대분수는 자연수 부분부터 견주어요.","4 > 1 — 자연수 부분이 큰 쪽이 커요.","분수 부분은 1보다 작아서 뒤집지 못해요 — ⟨4 3/6⟩ > ⟨1 5/6⟩."],"asset":null},{"stem":"이번에는 다른 문제예요. 두 수의 크기를 바르게 견준 것은 무엇인가요?","options":[{"t":"⟨2 3/8⟩ > ⟨1 7/8⟩","correct":true},{"t":"⟨2 3/8⟩ < ⟨1 7/8⟩","mis":"M3-2-u4-X13"},{"t":"⟨2 3/8⟩ = ⟨1 7/8⟩","mis":"M3-2-u4-X22"},{"t":"견줄 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["대분수는 자연수 부분부터 견주어요.","2 > 1 — 자연수 부분이 큰 쪽이 커요.","분수 부분은 1보다 작아서 뒤집지 못해요 — ⟨2 3/8⟩ > ⟨1 7/8⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_a#14','math',3,2,'u4','','g3_2_math_u4_review_a','unit_review','M3-2-u4-C9',2,'mc','auto','종이 빨대의 길이는 1 cm 1 mm예요. 몇 cm인지 소수로 나타내면 얼마인가요?',ARRAY['M3-2-u4-X17','M3-2-u4-X21']::text[],true,'{"seq":14,"concept":"M3-2-u4-C9","difficulty":2,"kind":"mc","stem":"종이 빨대의 길이는 1 cm 1 mm예요. 몇 cm인지 소수로 나타내면 얼마인가요?","options":[{"t":"1.1 cm","correct":true},{"t":"1.01 cm","mis":"M3-2-u4-X17"},{"t":"11 cm","mis":"M3-2-u4-X17"},{"t":"1.2 cm","mis":"M3-2-u4-X21"}],"explanation":["1 mm = ⟨1/10⟩ cm = 0.1 cm예요.","1 mm는 0.1 cm — 1 cm 1 mm = ⟨1 1/10⟩ cm.","⟨1 1/10⟩ cm = 1.1 cm."],"asset":{"type":"mmruler","len":11,"label":"종이 빨대"},"variant_rule":{"alt":[{"stem":"애벌레의 길이는 9 cm 1 mm예요. 몇 cm인지 소수로 나타내면 얼마인가요?","options":[{"t":"9.1 cm","correct":true},{"t":"9.01 cm","mis":"M3-2-u4-X17"},{"t":"91 cm","mis":"M3-2-u4-X17"},{"t":"1.9 cm","mis":"M3-2-u4-X16"}],"explanation":["1 mm = ⟨1/10⟩ cm = 0.1 cm예요.","1 mm는 0.1 cm — 9 cm 1 mm = ⟨9 1/10⟩ cm.","⟨9 1/10⟩ cm = 9.1 cm."],"asset":{"type":"mmruler","len":91,"label":"애벌레"}},{"stem":"지우개의 길이는 5 cm 9 mm예요. 몇 cm인지 소수로 나타내면 얼마인가요?","options":[{"t":"5.9 cm","correct":true},{"t":"5.09 cm","mis":"M3-2-u4-X17"},{"t":"59 cm","mis":"M3-2-u4-X17"},{"t":"9.5 cm","mis":"M3-2-u4-X16"}],"explanation":["1 mm = ⟨1/10⟩ cm = 0.1 cm예요.","9 mm는 0.9 cm — 5 cm 9 mm = ⟨5 9/10⟩ cm.","⟨5 9/10⟩ cm = 5.9 cm."],"asset":{"type":"mmruler","len":59,"label":"지우개"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_a#15','math',3,2,'u4','','g3_2_math_u4_review_a','unit_review','M3-2-u4-C10',2,'mc','auto','큐브 맞추기 기록이에요. 지훈 10.8초, 도연 9.1초, 서준 9.9초. 가장 빠른 사람은 누구인가요?',ARRAY['M3-2-u4-X19','M3-2-u4-X18','M3-2-u4-X22']::text[],true,'{"seq":15,"concept":"M3-2-u4-C10","difficulty":2,"kind":"mc","stem":"큐브 맞추기 기록이에요. 지훈 10.8초, 도연 9.1초, 서준 9.9초. 가장 빠른 사람은 누구인가요?","options":[{"t":"도연","correct":true},{"t":"지훈","mis":"M3-2-u4-X19"},{"t":"서준","mis":"M3-2-u4-X18"},{"t":"모두 같아요","mis":"M3-2-u4-X22"}],"explanation":["걸린 시간이 짧을수록 빨라요.","10.8, 9.1, 9.9 중 가장 작은 수는 9.1이에요.","가장 빠른 사람은 도연이에요."],"variant_rule":{"alt":[{"stem":"줄넘기 30번 기록이에요. 채원 10.1초, 은비 11.3초, 하윤 10.5초. 가장 빠른 사람은 누구인가요?","options":[{"t":"채원","correct":true},{"t":"은비","mis":"M3-2-u4-X19"},{"t":"하윤","mis":"M3-2-u4-X18"},{"t":"모두 같아요","mis":"M3-2-u4-X22"}],"explanation":["걸린 시간이 짧을수록 빨라요.","10.1, 11.3, 10.5 중 가장 작은 수는 10.1이에요.","가장 빠른 사람은 채원이에요."],"asset":null},{"stem":"100 m 수영 기록이에요. 도연 10.6초, 지훈 11.2초, 서준 10.2초. 가장 빠른 사람은 누구인가요?","options":[{"t":"서준","correct":true},{"t":"지훈","mis":"M3-2-u4-X19"},{"t":"도연","mis":"M3-2-u4-X18"},{"t":"모두 같아요","mis":"M3-2-u4-X22"}],"explanation":["걸린 시간이 짧을수록 빨라요.","10.6, 11.2, 10.2 중 가장 작은 수는 10.2예요.","가장 빠른 사람은 서준이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_a#16','math',3,2,'u4','','g3_2_math_u4_review_a','unit_review','M3-2-u4-C11',2,'mc','auto','두 수의 크기를 바르게 견준 것은 무엇인가요?',ARRAY['M3-2-u4-X14','M3-2-u4-X22']::text[],true,'{"seq":16,"concept":"M3-2-u4-C11","difficulty":2,"kind":"mc","stem":"두 수의 크기를 바르게 견준 것은 무엇인가요?","options":[{"t":"4.3 < ⟨5 1/10⟩","correct":true},{"t":"4.3 > ⟨5 1/10⟩","mis":"M3-2-u4-X14"},{"t":"4.3 = ⟨5 1/10⟩","mis":"M3-2-u4-X22"},{"t":"견줄 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["분모가 10인 분수는 소수로 바꿀 수 있어요 — ⟨5 1/10⟩ = 5.1.","소수로 견주어요 — 자연수 부분부터, 같으면 소수점 오른쪽 수.","4.3 < ⟨5 1/10⟩."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 두 수의 크기를 바르게 견준 것은 무엇인가요?","options":[{"t":"⟨2 4/10⟩ < 3.3","correct":true},{"t":"⟨2 4/10⟩ > 3.3","mis":"M3-2-u4-X14"},{"t":"⟨2 4/10⟩ = 3.3","mis":"M3-2-u4-X22"},{"t":"견줄 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["분모가 10인 분수는 소수로 바꿀 수 있어요 — ⟨2 4/10⟩ = 2.4.","소수로 견주어요 — 자연수 부분부터, 같으면 소수점 오른쪽 수.","⟨2 4/10⟩ < 3.3."],"asset":null},{"stem":"이번에는 다른 문제예요. 두 수의 크기를 바르게 견준 것은 무엇인가요?","options":[{"t":"⟨2 4/10⟩ > 1.5","correct":true},{"t":"⟨2 4/10⟩ < 1.5","mis":"M3-2-u4-X14"},{"t":"⟨2 4/10⟩ = 1.5","mis":"M3-2-u4-X22"},{"t":"견줄 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["분모가 10인 분수는 소수로 바꿀 수 있어요 — ⟨2 4/10⟩ = 2.4.","소수로 견주어요 — 자연수 부분부터, 같으면 소수점 오른쪽 수.","⟨2 4/10⟩ > 1.5."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_a#17','math',3,2,'u4','','g3_2_math_u4_review_a','unit_review','M3-2-u4-C1',3,'mc','auto','10을 2씩 묶었어요. 4는 10의 얼마인가요?',ARRAY['M3-2-u4-X03','M3-2-u4-X01','M3-2-u4-X21']::text[],true,'{"seq":17,"concept":"M3-2-u4-C1","difficulty":3,"kind":"mc","stem":"10을 2씩 묶었어요. 4는 10의 얼마인가요?","options":[{"t":"⟨2/5⟩","correct":true},{"t":"⟨5/2⟩","mis":"M3-2-u4-X03"},{"t":"⟨2/3⟩","mis":"M3-2-u4-X01"},{"t":"⟨3/5⟩","mis":"M3-2-u4-X21"}],"explanation":["10을 2씩 묶으면 5묶음 — 분모 5.","4는 그중 2묶음 — 분자 2.","4는 10의 ⟨2/5⟩ — 낱개 수 4·10으로 쓰지 않아요."],"variant_rule":{"alt":[{"stem":"25를 5씩 묶었어요. 5는 25의 얼마인가요?","options":[{"t":"⟨1/5⟩","correct":true},{"t":"⟨1/4⟩","mis":"M3-2-u4-X01"},{"t":"⟨2/5⟩","mis":"M3-2-u4-X21"},{"t":"⟨1/25⟩","mis":"M3-2-u4-X02"}],"explanation":["25를 5씩 묶으면 5묶음 — 분모 5.","5는 그중 1묶음 — 분자 1.","5는 25의 ⟨1/5⟩ — 낱개 수 5·25로 쓰지 않아요."],"asset":null},{"stem":"35를 5씩 묶었어요. 15는 35의 얼마인가요?","options":[{"t":"⟨3/7⟩","correct":true},{"t":"⟨7/3⟩","mis":"M3-2-u4-X03"},{"t":"⟨3/4⟩","mis":"M3-2-u4-X01"},{"t":"⟨5/7⟩","mis":"M3-2-u4-X07"}],"explanation":["35를 5씩 묶으면 7묶음 — 분모 7.","15는 그중 3묶음 — 분자 3.","15는 35의 ⟨3/7⟩ — 낱개 수 15·35로 쓰지 않아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_a#18','math',3,2,'u4','','g3_2_math_u4_review_a','unit_review','M3-2-u4-C3',3,'sa','auto','사탕 8개 중 서준은 ⟨2/4⟩를, 하윤은 ⟨1/4⟩을 먹었어요. 남은 사탕은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":18,"concept":"M3-2-u4-C3","difficulty":3,"kind":"sa","stem":"사탕 8개 중 서준은 ⟨2/4⟩를, 하윤은 ⟨1/4⟩을 먹었어요. 남은 사탕은 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["8의 ⟨1/4⟩은 2개예요.","서준은 4개, 하윤은 2개 — 모두 6개를 먹었어요.","남은 것은 8 − 6 = 2개."],"variant_rule":{"alt":[{"stem":"귤 16개 중 채원은 ⟨2/4⟩를, 도연은 ⟨1/4⟩을 먹었어요. 남은 귤은 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["16의 ⟨1/4⟩은 4개예요.","채원은 8개, 도연은 4개 — 모두 12개를 먹었어요.","남은 것은 16 − 12 = 4개."],"asset":null},{"stem":"약과 32개 중 채원은 ⟨4/8⟩를, 은비는 ⟨3/8⟩을 먹었어요. 남은 약과는 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["32의 ⟨1/8⟩은 4개예요.","채원은 16개, 은비는 12개 — 모두 28개를 먹었어요.","남은 것은 32 − 28 = 4개."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_a#19','math',3,2,'u4','','g3_2_math_u4_review_a','unit_review','M3-2-u4-C7',3,'sa','auto','⟨2 5/8⟩를 가분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":19,"concept":"M3-2-u4-C7","difficulty":3,"kind":"sa","stem":"⟨2 5/8⟩를 가분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.","answer":["21"],"explanation":["자연수 1은 ⟨1/8⟩이 8개예요 — 2는 2 × 8 = 16개.","⟨5/8⟩는 5개 — 모두 16 + 5 = 21개예요.","⟨2 5/8⟩ = ⟨21/8⟩ — 분모는 그대로 두어요."],"variant_rule":{"alt":[{"stem":"⟨2 4/5⟩를 가분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["자연수 1은 ⟨1/5⟩이 5개예요 — 2는 2 × 5 = 10개.","⟨4/5⟩는 4개 — 모두 10 + 4 = 14개예요.","⟨2 4/5⟩ = ⟨14/5⟩ — 분모는 그대로 두어요."],"asset":null},{"stem":"⟨3 2/4⟩를 가분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["자연수 1은 ⟨1/4⟩이 4개예요 — 3은 3 × 4 = 12개.","⟨2/4⟩는 2개 — 모두 12 + 2 = 14개예요.","⟨3 2/4⟩ = ⟨14/4⟩ — 분모는 그대로 두어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_a#20','math',3,2,'u4','','g3_2_math_u4_review_a','unit_review','M3-2-u4-C8',3,'mc','auto','두 수의 크기를 바르게 견준 것은 무엇인가요?',ARRAY['M3-2-u4-X14','M3-2-u4-X22']::text[],true,'{"seq":20,"concept":"M3-2-u4-C8","difficulty":3,"kind":"mc","stem":"두 수의 크기를 바르게 견준 것은 무엇인가요?","options":[{"t":"⟨13/7⟩ < ⟨3 1/7⟩","correct":true},{"t":"⟨13/7⟩ > ⟨3 1/7⟩","mis":"M3-2-u4-X14"},{"t":"⟨13/7⟩ = ⟨3 1/7⟩","mis":"M3-2-u4-X22"},{"t":"견줄 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["한쪽으로 바꾸어 견주어요.","⟨3 1/7⟩ = ⟨22/7⟩예요.","⟨13/7⟩과 ⟨22/7⟩ — ⟨13/7⟩ < ⟨3 1/7⟩ (⟨13/7⟩ = ⟨1 6/7⟩으로 바꾸어도 같아요)."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 두 수의 크기를 바르게 견준 것은 무엇인가요?","options":[{"t":"⟨23/6⟩ > ⟨1 1/6⟩","correct":true},{"t":"⟨23/6⟩ < ⟨1 1/6⟩","mis":"M3-2-u4-X14"},{"t":"⟨23/6⟩ = ⟨1 1/6⟩","mis":"M3-2-u4-X22"},{"t":"견줄 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["한쪽으로 바꾸어 견주어요.","⟨1 1/6⟩ = ⟨7/6⟩이에요.","⟨23/6⟩과 ⟨7/6⟩ — ⟨23/6⟩ > ⟨1 1/6⟩ (⟨23/6⟩ = ⟨3 5/6⟩로 바꾸어도 같아요)."],"asset":null},{"stem":"이번에는 다른 문제예요. 두 수의 크기를 바르게 견준 것은 무엇인가요?","options":[{"t":"⟨11/4⟩ > ⟨1 1/4⟩","correct":true},{"t":"⟨11/4⟩ < ⟨1 1/4⟩","mis":"M3-2-u4-X14"},{"t":"⟨11/4⟩ = ⟨1 1/4⟩","mis":"M3-2-u4-X22"},{"t":"견줄 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["한쪽으로 바꾸어 견주어요.","⟨1 1/4⟩ = ⟨5/4⟩예요.","⟨11/4⟩과 ⟨5/4⟩ — ⟨11/4⟩ > ⟨1 1/4⟩ (⟨11/4⟩ = ⟨2 3/4⟩으로 바꾸어도 같아요)."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_a#21','math',3,2,'u4','','g3_2_math_u4_review_a','unit_review','M3-2-u4-C9',3,'mc','auto','수직선의 한 칸은 0.1이에요. ?가 나타내는 소수는 무엇인가요?',ARRAY['M3-2-u4-X21','M3-2-u4-X16']::text[],true,'{"seq":21,"concept":"M3-2-u4-C9","difficulty":3,"kind":"mc","stem":"수직선의 한 칸은 0.1이에요. ?가 나타내는 소수는 무엇인가요?","options":[{"t":"5.3","correct":true},{"t":"5.4","mis":"M3-2-u4-X21"},{"t":"5.2","mis":"M3-2-u4-X21"},{"t":"3.5","mis":"M3-2-u4-X16"}],"explanation":["오른쪽으로 한 칸 갈 때마다 0.1씩 커져요.","앞뒤의 수를 보면 5.2 다음 자리예요.","?는 5.3이에요."],"asset":{"type":"number_line","cells":["5.1","5.2","?","5.4","5.5"]},"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 수직선의 한 칸은 0.1이에요. ?가 나타내는 소수는 무엇인가요?","options":[{"t":"2.4","correct":true},{"t":"2.5","mis":"M3-2-u4-X21"},{"t":"2.3","mis":"M3-2-u4-X21"},{"t":"4.2","mis":"M3-2-u4-X16"}],"explanation":["오른쪽으로 한 칸 갈 때마다 0.1씩 커져요.","앞뒤의 수를 보면 왼쪽 다음 자리예요.","?는 2.4예요."],"asset":{"type":"number_line","cells":["?","2.5","2.6","2.7","2.8"]}},{"stem":"이번에는 다른 문제예요. 수직선의 한 칸은 0.1이에요. ?가 나타내는 소수는 무엇인가요?","options":[{"t":"2.2","correct":true},{"t":"2.3","mis":"M3-2-u4-X21"},{"t":"2.1","mis":"M3-2-u4-X21"},{"t":"0.2","mis":"M3-2-u4-X15"}],"explanation":["오른쪽으로 한 칸 갈 때마다 0.1씩 커져요.","앞뒤의 수를 보면 2.1 다음 자리예요.","?는 2.2예요."],"asset":{"type":"number_line","cells":["2","2.1","?","2.3","2.4"]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_a#22','math',3,2,'u4','','g3_2_math_u4_review_a','unit_review','M3-2-u4-C11',3,'mc','auto','⟨6 □/10⟩가 ⟨6 6/10⟩보다 클 때, □ 안에 들어갈 수 있는 수를 모두 고른 것은 무엇인가요?',ARRAY['M3-2-u4-X21','M3-2-u4-X20']::text[],true,'{"seq":22,"concept":"M3-2-u4-C11","difficulty":3,"kind":"mc","stem":"⟨6 □/10⟩가 ⟨6 6/10⟩보다 클 때, □ 안에 들어갈 수 있는 수를 모두 고른 것은 무엇인가요?","options":[{"t":"7, 8, 9","correct":true},{"t":"6, 7, 8, 9","mis":"M3-2-u4-X21"},{"t":"1, 2, 3, 4, 5","mis":"M3-2-u4-X20"},{"t":"7","mis":"M3-2-u4-X21"}],"explanation":["자연수 부분이 6으로 같아요.","분수 부분의 분자 □가 6보다 커야 해요.","□ = 7, 8, 9 — 6은 같아서 넣지 않아요."],"variant_rule":{"alt":[{"stem":"⟨1 □/10⟩가 ⟨1 3/10⟩보다 클 때, □ 안에 들어갈 수 있는 수를 모두 고른 것은 무엇인가요?","options":[{"t":"4, 5, 6, 7, 8, 9","correct":true},{"t":"3, 4, 5, 6, 7, 8, 9","mis":"M3-2-u4-X21"},{"t":"1, 2","mis":"M3-2-u4-X20"},{"t":"4","mis":"M3-2-u4-X21"}],"explanation":["자연수 부분이 1로 같아요.","분수 부분의 분자 □가 3보다 커야 해요.","□ = 4, 5, 6, 7, 8, 9 — 3은 같아서 넣지 않아요."],"asset":null},{"stem":"⟨1 □/10⟩가 ⟨1 5/10⟩보다 클 때, □ 안에 들어갈 수 있는 수를 모두 고른 것은 무엇인가요?","options":[{"t":"6, 7, 8, 9","correct":true},{"t":"5, 6, 7, 8, 9","mis":"M3-2-u4-X21"},{"t":"1, 2, 3, 4","mis":"M3-2-u4-X20"},{"t":"6","mis":"M3-2-u4-X21"}],"explanation":["자연수 부분이 1로 같아요.","분수 부분의 분자 □가 5보다 커야 해요.","□ = 6, 7, 8, 9 — 5는 같아서 넣지 않아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_a#23','math',3,2,'u4','','g3_2_math_u4_review_a','unit_review','M3-2-u4-C5',4,'sa','auto','주사위를 던져 처음 나온 4를 분모로 정했어요. 두 번째로 나온 수를 분자로 할 때, 가분수가 되는 경우는 모두 몇 가지인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":23,"concept":"M3-2-u4-C5","difficulty":4,"kind":"sa","stem":"주사위를 던져 처음 나온 4를 분모로 정했어요. 두 번째로 나온 수를 분자로 할 때, 가분수가 되는 경우는 모두 몇 가지인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["주사위의 수는 1부터 6까지예요.","가분수: 분자가 4와 같거나 커야 해요 — 4, 5, 6.","모두 3가지예요."],"variant_rule":{"alt":[{"stem":"주사위를 던져 처음 나온 3을 분모로 정했어요. 두 번째로 나온 수를 분자로 할 때, 가분수가 되는 경우는 모두 몇 가지인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["주사위의 수는 1부터 6까지예요.","가분수: 분자가 3과 같거나 커야 해요 — 3, 4, 5, 6.","모두 4가지예요."],"asset":null},{"stem":"주사위를 던져 처음 나온 2를 분모로 정했어요. 두 번째로 나온 수를 분자로 할 때, 가분수가 되는 경우는 모두 몇 가지인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["주사위의 수는 1부터 6까지예요.","가분수: 분자가 2와 같거나 커야 해요 — 2, 3, 4, 5, 6.","모두 5가지예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_a#24','math',3,2,'u4','','g3_2_math_u4_review_a','unit_review','M3-2-u4-C11',4,'mc','auto','네 수 중에서 가장 큰 수는 무엇인가요? 7.4, 7.6, 6.4, ⟨7 1/10⟩',ARRAY['M3-2-u4-X14','M3-2-u4-X20']::text[],true,'{"seq":24,"concept":"M3-2-u4-C11","difficulty":4,"kind":"mc","stem":"네 수 중에서 가장 큰 수는 무엇인가요? 7.4, 7.6, 6.4, ⟨7 1/10⟩","options":[{"t":"7.6","correct":true},{"t":"7.4","mis":"M3-2-u4-X14"},{"t":"6.4","mis":"M3-2-u4-X20"},{"t":"⟨7 1/10⟩","mis":"M3-2-u4-X14"}],"explanation":["분수는 소수로 바꾸어요 — 7.4, 7.6, 6.4, 7.1.","자연수 부분부터, 같으면 소수점 오른쪽 수를 견주어요.","가장 큰 수는 7.6이에요."],"variant_rule":{"alt":[{"stem":"네 수 중에서 가장 큰 수는 무엇인가요? 4.7, ⟨4 5/10⟩, 3.7, ⟨49/10⟩","options":[{"t":"⟨49/10⟩","correct":true},{"t":"4.7","mis":"M3-2-u4-X14"},{"t":"⟨4 5/10⟩","mis":"M3-2-u4-X14"},{"t":"3.7","mis":"M3-2-u4-X20"}],"explanation":["분수는 소수로 바꾸어요 — 4.7, 4.5, 3.7, 4.9.","자연수 부분부터, 같으면 소수점 오른쪽 수를 견주어요.","가장 큰 수는 ⟨49/10⟩예요."],"asset":null},{"stem":"네 수 중에서 가장 큰 수는 무엇인가요? ⟨5 5/10⟩, 5.2, 4.3, ⟨5 8/10⟩","options":[{"t":"⟨5 8/10⟩","correct":true},{"t":"⟨5 5/10⟩","mis":"M3-2-u4-X14"},{"t":"5.2","mis":"M3-2-u4-X14"},{"t":"4.3","mis":"M3-2-u4-X20"}],"explanation":["분수는 소수로 바꾸어요 — 5.5, 5.2, 4.3, 5.8.","자연수 부분부터, 같으면 소수점 오른쪽 수를 견주어요.","가장 큰 수는 ⟨5 8/10⟩이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_a#25','math',3,2,'u4','','g3_2_math_u4_review_a','unit_review','M3-2-u4-C3',4,'essay','teacher','연필 24자루의 ⟨5/6⟩는 몇 자루인지 구하고, 그 방법을 묶음으로 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M3-2-u4-C3","difficulty":4,"kind":"essay","stem":"연필 24자루의 ⟨5/6⟩는 몇 자루인지 구하고, 그 방법을 묶음으로 설명해 보세요.","answer_guide":{"answer":"예: 24를 분모 6만큼 똑같이 6묶음으로 나누면 한 묶음에 4자루이다. ⟨5/6⟩는 그런 묶음 5개이므로 4 × 5 = 20자루이다.","scoring_points":["6묶음으로 나누어 한 묶음 4자루를 구했는가","5묶음을 모았는가","20자루라고 답했는가"]},"explanation":["24 ÷ 6 = 4.","4 × 5 = 20.","20자루."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_b#1','math',3,2,'u4','','g3_2_math_u4_review_b','unit_review','M3-2-u4-C1',1,'mc','auto','2개씩 묶었어요. 색칠한 부분은 전체의 얼마인가요?',ARRAY['M3-2-u4-X01','M3-2-u4-X02']::text[],true,'{"seq":1,"concept":"M3-2-u4-C1","difficulty":1,"kind":"mc","stem":"2개씩 묶었어요. 색칠한 부분은 전체의 얼마인가요?","options":[{"t":"⟨1/3⟩","correct":true},{"t":"⟨1/2⟩","mis":"M3-2-u4-X01"},{"t":"⟨2/3⟩","mis":"M3-2-u4-X02"},{"t":"⟨1/6⟩","mis":"M3-2-u4-X02"}],"explanation":["2개씩 묶으니 모두 3묶음 — 분모 3.","색칠한 묶음은 1묶음 — 분자 1.","색칠한 부분은 전체의 ⟨1/3⟩이에요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[2.7,0],[3.7,0],[3.7,1],[2.7,1]]},{"p":[[3.7,0],[4.7,0],[4.7,1],[3.7,1]]},{"p":[[5.4,0],[6.4,0],[6.4,1],[5.4,1]]},{"p":[[6.4,0],[7.4,0],[7.4,1],[6.4,1]]}],"u":30},"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 2개씩 묶었어요. 색칠한 부분은 전체의 얼마인가요?","options":[{"t":"⟨4/5⟩","correct":true},{"t":"⟨5/4⟩","mis":"M3-2-u4-X03"},{"t":"⟨8/5⟩","mis":"M3-2-u4-X02"},{"t":"⟨1/5⟩","mis":"M3-2-u4-X20"}],"explanation":["2개씩 묶으니 모두 5묶음 — 분모 5.","색칠한 묶음은 4묶음 — 분자 4.","색칠한 부분은 전체의 ⟨4/5⟩예요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[2.7,0],[3.7,0],[3.7,1],[2.7,1]],"hi":true},{"p":[[3.7,0],[4.7,0],[4.7,1],[3.7,1]],"hi":true},{"p":[[5.4,0],[6.4,0],[6.4,1],[5.4,1]],"hi":true},{"p":[[6.4,0],[7.4,0],[7.4,1],[6.4,1]],"hi":true},{"p":[[8.1,0],[9.1,0],[9.1,1],[8.1,1]],"hi":true},{"p":[[9.1,0],[10.1,0],[10.1,1],[9.1,1]],"hi":true},{"p":[[10.8,0],[11.8,0],[11.8,1],[10.8,1]]},{"p":[[11.8,0],[12.8,0],[12.8,1],[11.8,1]]}],"u":23}},{"stem":"3개씩 묶었어요. 색칠한 부분은 전체의 얼마인가요?","options":[{"t":"⟨3/5⟩","correct":true},{"t":"⟨3/2⟩","mis":"M3-2-u4-X01"},{"t":"⟨5/3⟩","mis":"M3-2-u4-X03"},{"t":"⟨9/5⟩","mis":"M3-2-u4-X02"}],"explanation":["3개씩 묶으니 모두 5묶음 — 분모 5.","색칠한 묶음은 3묶음 — 분자 3.","색칠한 부분은 전체의 ⟨3/5⟩이에요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[2,0],[3,0],[3,1],[2,1]],"hi":true},{"p":[[3.7,0],[4.7,0],[4.7,1],[3.7,1]],"hi":true},{"p":[[4.7,0],[5.7,0],[5.7,1],[4.7,1]],"hi":true},{"p":[[5.7,0],[6.7,0],[6.7,1],[5.7,1]],"hi":true},{"p":[[7.4,0],[8.4,0],[8.4,1],[7.4,1]],"hi":true},{"p":[[8.4,0],[9.4,0],[9.4,1],[8.4,1]],"hi":true},{"p":[[9.4,0],[10.4,0],[10.4,1],[9.4,1]],"hi":true},{"p":[[11.1,0],[12.1,0],[12.1,1],[11.1,1]]},{"p":[[12.1,0],[13.1,0],[13.1,1],[12.1,1]]},{"p":[[13.1,0],[14.1,0],[14.1,1],[13.1,1]]},{"p":[[14.8,0],[15.8,0],[15.8,1],[14.8,1]]},{"p":[[15.8,0],[16.8,0],[16.8,1],[15.8,1]]},{"p":[[16.8,0],[17.8,0],[17.8,1],[16.8,1]]}],"u":16}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_b#2','math',3,2,'u4','','g3_2_math_u4_review_b','unit_review','M3-2-u4-C3',1,'sa','auto','36의 ⟨1/6⟩은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u4-C3","difficulty":1,"kind":"sa","stem":"36의 ⟨1/6⟩은 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["36을 분모만큼 똑같이 6묶음으로 나누면 한 묶음에 6개예요 — 36의 ⟨1/6⟩은 6.","⟨1/6⟩은 그중 1묶음이에요.","36의 ⟨1/6⟩은 6 — 36 ÷ 6과 같아요."],"variant_rule":{"alt":[{"stem":"8의 ⟨1/4⟩은 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["8을 분모만큼 똑같이 4묶음으로 나누면 한 묶음에 2개예요 — 8의 ⟨1/4⟩은 2.","⟨1/4⟩은 그중 1묶음이에요.","8의 ⟨1/4⟩은 2 — 8 ÷ 4와 같아요."],"asset":null},{"stem":"36의 ⟨3/6⟩은 얼마인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["36을 분모만큼 똑같이 6묶음으로 나누면 한 묶음에 6개예요 — 36의 ⟨1/6⟩은 6.","⟨3/6⟩은 ⟨1/6⟩이 3개 — 3묶음이에요.","36의 ⟨3/6⟩은 6 × 3 = 18 — 분자만 보고 답하지 않아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_b#3','math',3,2,'u4','','g3_2_math_u4_review_b','unit_review','M3-2-u4-C4',1,'sa','auto','끈 80 cm의 ⟨1/2⟩은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-2-u4-C4","difficulty":1,"kind":"sa","stem":"끈 80 cm의 ⟨1/2⟩은 몇 cm인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["80 cm를 분모만큼 똑같이 2부분으로 나누면 한 부분이 40 cm예요.","⟨1/2⟩은 한 부분이에요.","80 cm의 ⟨1/2⟩은 40 cm — 나눈 부분의 길이는 모두 같아야 해요."],"asset":{"type":"fbar","bars":[{"den":2,"num":1,"grp":1,"label":"끈 80 cm"}]},"variant_rule":{"alt":[{"stem":"철사 75 cm의 ⟨1/3⟩은 몇 cm인가요? 숫자로 쓰세요.","answer":["25"],"explanation":["75 cm를 분모만큼 똑같이 3부분으로 나누면 한 부분이 25 cm예요.","⟨1/3⟩은 한 부분이에요.","75 cm의 ⟨1/3⟩은 25 cm — 나눈 부분의 길이는 모두 같아야 해요."],"asset":{"type":"fbar","bars":[{"den":3,"num":1,"grp":1,"label":"철사 75 cm"}]}},{"stem":"색 테이프 30 cm의 ⟨2/3⟩는 몇 cm인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["30 cm를 분모만큼 똑같이 3부분으로 나누면 한 부분이 10 cm예요.","⟨2/3⟩는 그런 부분 2개예요.","30 cm의 ⟨2/3⟩는 20 cm — 나눈 부분의 길이는 모두 같아야 해요."],"asset":{"type":"fbar","bars":[{"den":3,"num":2,"grp":1,"label":"색 테이프 30 cm"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_b#4','math',3,2,'u4','','g3_2_math_u4_review_b','unit_review','M3-2-u4-C5',1,'mc','auto','분수 ⟨2/2⟩는 무엇인가요?',ARRAY['M3-2-u4-X08','M3-2-u4-X09']::text[],true,'{"seq":4,"concept":"M3-2-u4-C5","difficulty":1,"kind":"mc","stem":"분수 ⟨2/2⟩는 무엇인가요?","options":[{"t":"가분수","correct":true},{"t":"진분수","mis":"M3-2-u4-X08"},{"t":"대분수","mis":"M3-2-u4-X08"},{"t":"자연수","mis":"M3-2-u4-X09"}],"explanation":["분자 2, 분모 2를 견주어요.","분자가 분모보다 같아요.","⟨2/2⟩는 가분수 — 분자가 분모와 같거나 큰 분수."],"variant_rule":{"alt":[{"stem":"분수 ⟨2/5⟩는 무엇인가요?","options":[{"t":"진분수","correct":true},{"t":"가분수","mis":"M3-2-u4-X08"},{"t":"대분수","mis":"M3-2-u4-X08"},{"t":"자연수","mis":"M3-2-u4-X08"}],"explanation":["분자 2, 분모 5를 견주어요.","분자가 분모보다 작아요.","⟨2/5⟩는 진분수 — 분자가 분모보다 작은 분수."],"asset":null},{"stem":"분수 ⟨3/6⟩은 무엇인가요?","options":[{"t":"진분수","correct":true},{"t":"가분수","mis":"M3-2-u4-X08"},{"t":"대분수","mis":"M3-2-u4-X08"},{"t":"자연수","mis":"M3-2-u4-X08"}],"explanation":["분자 3, 분모 6을 견주어요.","분자가 분모보다 작아요.","⟨3/6⟩은 진분수 — 분자가 분모보다 작은 분수."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_b#5','math',3,2,'u4','','g3_2_math_u4_review_b','unit_review','M3-2-u4-C6',1,'sa','auto','1을 분모가 4인 분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-2-u4-C6","difficulty":1,"kind":"sa","stem":"1을 분모가 4인 분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["⟨1/4⟩이 4개면 1이에요 — 1 = ⟨4/4⟩.","그래서 1 = ⟨4/4⟩.","1 = ⟨4/4⟩ — 분자는 4."],"variant_rule":{"alt":[{"stem":"3을 분모가 4인 분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["⟨1/4⟩이 4개면 1이에요 — 1 = ⟨4/4⟩.","3은 1이 3개 — ⟨1/4⟩이 4 × 3 = 12개.","3 = ⟨12/4⟩ — 분자는 12."],"asset":null},{"stem":"3을 분모가 5인 분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["⟨1/5⟩이 5개면 1이에요 — 1 = ⟨5/5⟩.","3은 1이 3개 — ⟨1/5⟩이 5 × 3 = 15개.","3 = ⟨15/5⟩ — 분자는 15."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_b#6','math',3,2,'u4','','g3_2_math_u4_review_b','unit_review','M3-2-u4-C7',1,'mc','auto','똑같은 띠 2개에 색칠했어요. 색칠한 부분을 대분수로 나타내면 무엇인가요?',ARRAY['M3-2-u4-X12','M3-2-u4-X21','M3-2-u4-X20']::text[],true,'{"seq":6,"concept":"M3-2-u4-C7","difficulty":1,"kind":"mc","stem":"똑같은 띠 2개에 색칠했어요. 색칠한 부분을 대분수로 나타내면 무엇인가요?","options":[{"t":"⟨1 2/5⟩","correct":true},{"t":"⟨2/5⟩","mis":"M3-2-u4-X12"},{"t":"⟨2 2/5⟩","mis":"M3-2-u4-X21"},{"t":"⟨1 3/5⟩","mis":"M3-2-u4-X20"}],"explanation":["통째로 색칠한 띠가 1개 — 자연수 부분 1.","남은 띠는 5칸 중 2칸 — 진분수 ⟨2/5⟩.","색칠한 부분은 ⟨1 2/5⟩예요."],"asset":{"type":"fbar","bars":[{"den":5,"num":5},{"den":5,"num":2}]},"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 똑같은 띠 2개에 색칠했어요. 색칠한 부분을 대분수로 나타내면 무엇인가요?","options":[{"t":"⟨1 1/6⟩","correct":true},{"t":"⟨1/6⟩","mis":"M3-2-u4-X12"},{"t":"⟨2 1/6⟩","mis":"M3-2-u4-X21"},{"t":"⟨1 5/6⟩","mis":"M3-2-u4-X20"}],"explanation":["통째로 색칠한 띠가 1개 — 자연수 부분 1.","남은 띠는 6칸 중 1칸 — 진분수 ⟨1/6⟩.","색칠한 부분은 ⟨1 1/6⟩이에요."],"asset":{"type":"fbar","bars":[{"den":6,"num":6},{"den":6,"num":1}]}},{"stem":"똑같은 띠 3개에 색칠했어요. 색칠한 부분을 대분수로 나타내면 무엇인가요?","options":[{"t":"⟨2 1/3⟩","correct":true},{"t":"⟨1/3⟩","mis":"M3-2-u4-X12"},{"t":"⟨3 1/3⟩","mis":"M3-2-u4-X21"},{"t":"⟨2 2/3⟩","mis":"M3-2-u4-X20"}],"explanation":["통째로 색칠한 띠가 2개 — 자연수 부분 2.","남은 띠는 3칸 중 1칸 — 진분수 ⟨1/3⟩.","색칠한 부분은 ⟨2 1/3⟩이에요."],"asset":{"type":"fbar","bars":[{"den":3,"num":3},{"den":3,"num":3},{"den":3,"num":1}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_b#7','math',3,2,'u4','','g3_2_math_u4_review_b','unit_review','M3-2-u4-C9',1,'sa','auto','2.6은 0.1이 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M3-2-u4-C9","difficulty":1,"kind":"sa","stem":"2.6은 0.1이 몇 개인가요? 숫자로 쓰세요.","answer":["26"],"explanation":["1은 0.1이 10개예요 — 2는 0.1이 20개.","0.6은 0.1이 6개예요.","2.6은 0.1이 20 + 6 = 26개."],"variant_rule":{"alt":[{"stem":"6.1은 0.1이 몇 개인가요? 숫자로 쓰세요.","answer":["61"],"explanation":["1은 0.1이 10개예요 — 6은 0.1이 60개.","0.1은 0.1이 1개예요.","6.1은 0.1이 60 + 1 = 61개."],"asset":null},{"stem":"1.3은 0.1이 몇 개인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["1은 0.1이 10개예요 — 1은 0.1이 10개.","0.3은 0.1이 3개예요.","1.3은 0.1이 10 + 3 = 13개."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_b#8','math',3,2,'u4','','g3_2_math_u4_review_b','unit_review','M3-2-u4-C10',1,'mc','auto','두 수의 크기를 바르게 견준 것은 무엇인가요?',ARRAY['M3-2-u4-X18','M3-2-u4-X22']::text[],true,'{"seq":8,"concept":"M3-2-u4-C10","difficulty":1,"kind":"mc","stem":"두 수의 크기를 바르게 견준 것은 무엇인가요?","options":[{"t":"4.7 > 3.4","correct":true},{"t":"4.7 < 3.4","mis":"M3-2-u4-X18"},{"t":"4.7 = 3.4","mis":"M3-2-u4-X22"},{"t":"견줄 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["자연수 부분부터 견주어요 — 4와 3.","자연수 부분이 큰 소수가 더 커요.","4.7 > 3.4 — 0.1이 47개와 34개로 견주어도 같아요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 두 수의 크기를 바르게 견준 것은 무엇인가요?","options":[{"t":"7.6 > 3.3","correct":true},{"t":"7.6 < 3.3","mis":"M3-2-u4-X18"},{"t":"7.6 = 3.3","mis":"M3-2-u4-X22"},{"t":"견줄 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["자연수 부분부터 견주어요 — 7과 3.","자연수 부분이 큰 소수가 더 커요.","7.6 > 3.3 — 0.1이 76개와 33개로 견주어도 같아요."],"asset":null},{"stem":"이번에는 다른 문제예요. 두 수의 크기를 바르게 견준 것은 무엇인가요?","options":[{"t":"1.7 < 7.7","correct":true},{"t":"1.7 > 7.7","mis":"M3-2-u4-X18"},{"t":"1.7 = 7.7","mis":"M3-2-u4-X22"},{"t":"견줄 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["자연수 부분부터 견주어요 — 1과 7.","자연수 부분이 큰 소수가 더 커요.","1.7 < 7.7 — 0.1이 17개와 77개로 견주어도 같아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_b#9','math',3,2,'u4','','g3_2_math_u4_review_b','unit_review','M3-2-u4-C2',2,'mc','auto','검은 돌 2개와 흰 돌 5개가 있어요. 검은 돌은 전체 돌의 얼마인가요?',ARRAY['M3-2-u4-X01','M3-2-u4-X20','M3-2-u4-X03']::text[],true,'{"seq":9,"concept":"M3-2-u4-C2","difficulty":2,"kind":"mc","stem":"검은 돌 2개와 흰 돌 5개가 있어요. 검은 돌은 전체 돌의 얼마인가요?","options":[{"t":"⟨2/7⟩","correct":true},{"t":"⟨2/5⟩","mis":"M3-2-u4-X01"},{"t":"⟨5/7⟩","mis":"M3-2-u4-X20"},{"t":"⟨7/2⟩","mis":"M3-2-u4-X03"}],"explanation":["먼저 전체를 정해요 — 돌은 모두 2 + 5 = 7개.","검은 돌은 흰 돌과 견주는 것이 아니라 전체 7개와 견주어요.","검은 돌은 전체의 ⟨2/7⟩예요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[2,0],[3,0],[3,1],[2,1]]},{"p":[[3,0],[4,0],[4,1],[3,1]]},{"p":[[4,0],[5,0],[5,1],[4,1]]},{"p":[[0,1],[1,1],[1,2],[0,2]]},{"p":[[1,1],[2,1],[2,2],[1,2]]}],"u":30},"variant_rule":{"alt":[{"stem":"검은 돌 4개와 흰 돌 5개가 있어요. 검은 돌은 전체 돌의 얼마인가요?","options":[{"t":"⟨4/9⟩","correct":true},{"t":"⟨4/5⟩","mis":"M3-2-u4-X01"},{"t":"⟨5/9⟩","mis":"M3-2-u4-X20"},{"t":"⟨9/4⟩","mis":"M3-2-u4-X03"}],"explanation":["먼저 전체를 정해요 — 돌은 모두 4 + 5 = 9개.","검은 돌은 흰 돌과 견주는 것이 아니라 전체 9개와 견주어요.","검은 돌은 전체의 ⟨4/9⟩예요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[2,0],[3,0],[3,1],[2,1]],"hi":true},{"p":[[3,0],[4,0],[4,1],[3,1]],"hi":true},{"p":[[4,0],[5,0],[5,1],[4,1]]},{"p":[[0,1],[1,1],[1,2],[0,2]]},{"p":[[1,1],[2,1],[2,2],[1,2]]},{"p":[[2,1],[3,1],[3,2],[2,2]]},{"p":[[3,1],[4,1],[4,2],[3,2]]}],"u":30}},{"stem":"검은 돌 4개와 흰 돌 3개가 있어요. 검은 돌은 전체 돌의 얼마인가요?","options":[{"t":"⟨4/7⟩","correct":true},{"t":"⟨4/3⟩","mis":"M3-2-u4-X01"},{"t":"⟨3/7⟩","mis":"M3-2-u4-X20"},{"t":"⟨7/4⟩","mis":"M3-2-u4-X03"}],"explanation":["먼저 전체를 정해요 — 돌은 모두 4 + 3 = 7개.","검은 돌은 흰 돌과 견주는 것이 아니라 전체 7개와 견주어요.","검은 돌은 전체의 ⟨4/7⟩예요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[2,0],[3,0],[3,1],[2,1]],"hi":true},{"p":[[3,0],[4,0],[4,1],[3,1]],"hi":true},{"p":[[4,0],[5,0],[5,1],[4,1]]},{"p":[[0,1],[1,1],[1,2],[0,2]]},{"p":[[1,1],[2,1],[2,2],[1,2]]}],"u":30}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_b#10','math',3,2,'u4','','g3_2_math_u4_review_b','unit_review','M3-2-u4-C3',2,'mc','auto','쿠키 16개의 ⟨2/4⟩는 몇 개인가요?',ARRAY['M3-2-u4-X04','M3-2-u4-X05','M3-2-u4-X06']::text[],true,'{"seq":10,"concept":"M3-2-u4-C3","difficulty":2,"kind":"mc","stem":"쿠키 16개의 ⟨2/4⟩는 몇 개인가요?","options":[{"t":"8개","correct":true},{"t":"2개","mis":"M3-2-u4-X04"},{"t":"4개","mis":"M3-2-u4-X05"},{"t":"32개","mis":"M3-2-u4-X06"}],"explanation":["16을 분모만큼 똑같이 4묶음으로 나누면 한 묶음에 4개예요 — 16의 ⟨1/4⟩은 4.","⟨2/4⟩는 ⟨1/4⟩이 2개 — 2묶음이에요.","16의 ⟨2/4⟩는 4 × 2 = 8 — 분자만 보고 답하지 않아요."],"variant_rule":{"alt":[{"stem":"귤 24개의 ⟨2/6⟩는 몇 개인가요?","options":[{"t":"8개","correct":true},{"t":"2개","mis":"M3-2-u4-X04"},{"t":"4개","mis":"M3-2-u4-X05"},{"t":"72개","mis":"M3-2-u4-X06"}],"explanation":["24를 분모만큼 똑같이 6묶음으로 나누면 한 묶음에 4개예요 — 24의 ⟨1/6⟩은 4.","⟨2/6⟩는 ⟨1/6⟩이 2개 — 2묶음이에요.","24의 ⟨2/6⟩는 4 × 2 = 8 — 분자만 보고 답하지 않아요."],"asset":null},{"stem":"약과 25개의 ⟨2/5⟩는 몇 개인가요?","options":[{"t":"10개","correct":true},{"t":"2개","mis":"M3-2-u4-X04"},{"t":"5개","mis":"M3-2-u4-X05"},{"t":"15개","mis":"M3-2-u4-X21"}],"explanation":["25를 분모만큼 똑같이 5묶음으로 나누면 한 묶음에 5개예요 — 25의 ⟨1/5⟩은 5.","⟨2/5⟩는 ⟨1/5⟩이 2개 — 2묶음이에요.","25의 ⟨2/5⟩는 5 × 2 = 10 — 분자만 보고 답하지 않아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_b#11','math',3,2,'u4','','g3_2_math_u4_review_b','unit_review','M3-2-u4-C4',2,'sa','auto','준우가 하루의 ⟨1/8⟩ 동안 책을 읽은 시간은 몇 시간인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":11,"concept":"M3-2-u4-C4","difficulty":2,"kind":"sa","stem":"준우가 하루의 ⟨1/8⟩ 동안 책을 읽은 시간은 몇 시간인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["하루는 24시간이에요.","24를 똑같이 8부분으로 나누면 한 부분이 3시간이에요.","하루의 ⟨1/8⟩은 3 × 1 = 3시간."],"variant_rule":{"alt":[{"stem":"서준이 하루의 ⟨4/12⟩ 동안 학교에 있는 시간은 몇 시간인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["하루는 24시간이에요.","24를 똑같이 12부분으로 나누면 한 부분이 2시간이에요.","하루의 ⟨4/12⟩는 2 × 4 = 8시간."],"asset":null},{"stem":"준우가 하루의 ⟨1/12⟩ 동안 놀이를 한 시간은 몇 시간인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["하루는 24시간이에요.","24를 똑같이 12부분으로 나누면 한 부분이 2시간이에요.","하루의 ⟨1/12⟩은 2 × 1 = 2시간."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_b#12','math',3,2,'u4','','g3_2_math_u4_review_b','unit_review','M3-2-u4-C7',2,'sa','auto','⟨22/6⟩를 대분수로 나타내면 자연수 부분은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":12,"concept":"M3-2-u4-C7","difficulty":2,"kind":"sa","stem":"⟨22/6⟩를 대분수로 나타내면 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["⟨22/6⟩는 ⟨1/6⟩이 22개예요.","6개씩 모으면 1 — 22 ÷ 6 = 3 … 4, 통째로 3이고 ⟨1/6⟩이 4개 남아요.","⟨22/6⟩ = ⟨3 4/6⟩ — 분수 부분은 진분수예요."],"variant_rule":{"alt":[{"stem":"⟨23/5⟩을 대분수로 나타내면 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["⟨23/5⟩은 ⟨1/5⟩이 23개예요.","5개씩 모으면 1 — 23 ÷ 5 = 4 … 3, 통째로 4이고 ⟨1/5⟩이 3개 남아요.","⟨23/5⟩ = ⟨4 3/5⟩ — 분수 부분은 진분수예요."],"asset":null},{"stem":"⟨19/9⟩를 대분수로 나타내면 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["⟨19/9⟩는 ⟨1/9⟩이 19개예요.","9개씩 모으면 1 — 19 ÷ 9 = 2 … 1, 통째로 2이고 ⟨1/9⟩이 1개 남아요.","⟨19/9⟩ = ⟨2 1/9⟩ — 분수 부분은 진분수예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_b#13','math',3,2,'u4','','g3_2_math_u4_review_b','unit_review','M3-2-u4-C8',2,'mc','auto','두 수의 크기를 바르게 견준 것은 무엇인가요?',ARRAY['M3-2-u4-X13','M3-2-u4-X22']::text[],true,'{"seq":13,"concept":"M3-2-u4-C8","difficulty":2,"kind":"mc","stem":"두 수의 크기를 바르게 견준 것은 무엇인가요?","options":[{"t":"⟨3 1/3⟩ > ⟨1 1/3⟩","correct":true},{"t":"⟨3 1/3⟩ < ⟨1 1/3⟩","mis":"M3-2-u4-X13"},{"t":"⟨3 1/3⟩ = ⟨1 1/3⟩","mis":"M3-2-u4-X22"},{"t":"견줄 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["대분수는 자연수 부분부터 견주어요.","3 > 1 — 자연수 부분이 큰 쪽이 커요.","분수 부분은 1보다 작아서 뒤집지 못해요 — ⟨3 1/3⟩ > ⟨1 1/3⟩."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 두 수의 크기를 바르게 견준 것은 무엇인가요?","options":[{"t":"⟨3 2/4⟩ > ⟨1 3/4⟩","correct":true},{"t":"⟨3 2/4⟩ < ⟨1 3/4⟩","mis":"M3-2-u4-X13"},{"t":"⟨3 2/4⟩ = ⟨1 3/4⟩","mis":"M3-2-u4-X22"},{"t":"견줄 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["대분수는 자연수 부분부터 견주어요.","3 > 1 — 자연수 부분이 큰 쪽이 커요.","분수 부분은 1보다 작아서 뒤집지 못해요 — ⟨3 2/4⟩ > ⟨1 3/4⟩."],"asset":null},{"stem":"이번에는 다른 문제예요. 두 수의 크기를 바르게 견준 것은 무엇인가요?","options":[{"t":"⟨3 5/7⟩ > ⟨2 6/7⟩","correct":true},{"t":"⟨3 5/7⟩ < ⟨2 6/7⟩","mis":"M3-2-u4-X13"},{"t":"⟨3 5/7⟩ = ⟨2 6/7⟩","mis":"M3-2-u4-X22"},{"t":"견줄 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["대분수는 자연수 부분부터 견주어요.","3 > 2 — 자연수 부분이 큰 쪽이 커요.","분수 부분은 1보다 작아서 뒤집지 못해요 — ⟨3 5/7⟩ > ⟨2 6/7⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_b#14','math',3,2,'u4','','g3_2_math_u4_review_b','unit_review','M3-2-u4-C9',2,'mc','auto','나뭇잎의 길이는 3 cm 1 mm예요. 몇 cm인지 소수로 나타내면 얼마인가요?',ARRAY['M3-2-u4-X17','M3-2-u4-X16']::text[],true,'{"seq":14,"concept":"M3-2-u4-C9","difficulty":2,"kind":"mc","stem":"나뭇잎의 길이는 3 cm 1 mm예요. 몇 cm인지 소수로 나타내면 얼마인가요?","options":[{"t":"3.1 cm","correct":true},{"t":"3.01 cm","mis":"M3-2-u4-X17"},{"t":"31 cm","mis":"M3-2-u4-X17"},{"t":"1.3 cm","mis":"M3-2-u4-X16"}],"explanation":["1 mm = ⟨1/10⟩ cm = 0.1 cm예요.","1 mm는 0.1 cm — 3 cm 1 mm = ⟨3 1/10⟩ cm.","⟨3 1/10⟩ cm = 3.1 cm."],"asset":{"type":"mmruler","len":31,"label":"나뭇잎"},"variant_rule":{"alt":[{"stem":"종이 빨대의 길이는 3 cm 2 mm예요. 몇 cm인지 소수로 나타내면 얼마인가요?","options":[{"t":"3.2 cm","correct":true},{"t":"3.02 cm","mis":"M3-2-u4-X17"},{"t":"32 cm","mis":"M3-2-u4-X17"},{"t":"2.3 cm","mis":"M3-2-u4-X16"}],"explanation":["1 mm = ⟨1/10⟩ cm = 0.1 cm예요.","2 mm는 0.2 cm — 3 cm 2 mm = ⟨3 2/10⟩ cm.","⟨3 2/10⟩ cm = 3.2 cm."],"asset":{"type":"mmruler","len":32,"label":"종이 빨대"}},{"stem":"애벌레의 길이는 3 cm 4 mm예요. 몇 cm인지 소수로 나타내면 얼마인가요?","options":[{"t":"3.4 cm","correct":true},{"t":"3.04 cm","mis":"M3-2-u4-X17"},{"t":"34 cm","mis":"M3-2-u4-X17"},{"t":"4.3 cm","mis":"M3-2-u4-X16"}],"explanation":["1 mm = ⟨1/10⟩ cm = 0.1 cm예요.","4 mm는 0.4 cm — 3 cm 4 mm = ⟨3 4/10⟩ cm.","⟨3 4/10⟩ cm = 3.4 cm."],"asset":{"type":"mmruler","len":34,"label":"애벌레"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_b#15','math',3,2,'u4','','g3_2_math_u4_review_b','unit_review','M3-2-u4-C10',2,'mc','auto','50 m 달리기 기록이에요. 건우 8.8초, 채원 8.6초, 서준 9.4초. 가장 빠른 사람은 누구인가요?',ARRAY['M3-2-u4-X19','M3-2-u4-X18','M3-2-u4-X22']::text[],true,'{"seq":15,"concept":"M3-2-u4-C10","difficulty":2,"kind":"mc","stem":"50 m 달리기 기록이에요. 건우 8.8초, 채원 8.6초, 서준 9.4초. 가장 빠른 사람은 누구인가요?","options":[{"t":"채원","correct":true},{"t":"서준","mis":"M3-2-u4-X19"},{"t":"건우","mis":"M3-2-u4-X18"},{"t":"모두 같아요","mis":"M3-2-u4-X22"}],"explanation":["걸린 시간이 짧을수록 빨라요.","8.8, 8.6, 9.4 중 가장 작은 수는 8.6이에요.","가장 빠른 사람은 채원이에요."],"variant_rule":{"alt":[{"stem":"큐브 맞추기 기록이에요. 도연 12.4초, 민서 12.9초, 은비 11.5초. 가장 빠른 사람은 누구인가요?","options":[{"t":"은비","correct":true},{"t":"민서","mis":"M3-2-u4-X19"},{"t":"도연","mis":"M3-2-u4-X18"},{"t":"모두 같아요","mis":"M3-2-u4-X22"}],"explanation":["걸린 시간이 짧을수록 빨라요.","12.4, 12.9, 11.5 중 가장 작은 수는 11.5예요.","가장 빠른 사람은 은비예요."],"asset":null},{"stem":"줄넘기 30번 기록이에요. 건우 10.6초, 서윤 9.7초, 은비 9.4초. 가장 빠른 사람은 누구인가요?","options":[{"t":"은비","correct":true},{"t":"건우","mis":"M3-2-u4-X19"},{"t":"서윤","mis":"M3-2-u4-X18"},{"t":"모두 같아요","mis":"M3-2-u4-X22"}],"explanation":["걸린 시간이 짧을수록 빨라요.","10.6, 9.7, 9.4 중 가장 작은 수는 9.4예요.","가장 빠른 사람은 은비예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_b#16','math',3,2,'u4','','g3_2_math_u4_review_b','unit_review','M3-2-u4-C11',2,'mc','auto','두 수의 크기를 바르게 견준 것은 무엇인가요?',ARRAY['M3-2-u4-X14','M3-2-u4-X22']::text[],true,'{"seq":16,"concept":"M3-2-u4-C11","difficulty":2,"kind":"mc","stem":"두 수의 크기를 바르게 견준 것은 무엇인가요?","options":[{"t":"7.4 < ⟨7 7/10⟩","correct":true},{"t":"7.4 > ⟨7 7/10⟩","mis":"M3-2-u4-X14"},{"t":"7.4 = ⟨7 7/10⟩","mis":"M3-2-u4-X22"},{"t":"견줄 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["분모가 10인 분수는 소수로 바꿀 수 있어요 — ⟨7 7/10⟩ = 7.7.","소수로 견주어요 — 자연수 부분부터, 같으면 소수점 오른쪽 수.","7.4 < ⟨7 7/10⟩."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 두 수의 크기를 바르게 견준 것은 무엇인가요?","options":[{"t":"8.9 < ⟨9 4/10⟩","correct":true},{"t":"8.9 > ⟨9 4/10⟩","mis":"M3-2-u4-X14"},{"t":"8.9 = ⟨9 4/10⟩","mis":"M3-2-u4-X22"},{"t":"견줄 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["분모가 10인 분수는 소수로 바꿀 수 있어요 — ⟨9 4/10⟩ = 9.4.","소수로 견주어요 — 자연수 부분부터, 같으면 소수점 오른쪽 수.","8.9 < ⟨9 4/10⟩."],"asset":null},{"stem":"이번에는 다른 문제예요. 두 수의 크기를 바르게 견준 것은 무엇인가요?","options":[{"t":"5.6 < ⟨6 8/10⟩","correct":true},{"t":"5.6 > ⟨6 8/10⟩","mis":"M3-2-u4-X14"},{"t":"5.6 = ⟨6 8/10⟩","mis":"M3-2-u4-X22"},{"t":"견줄 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["분모가 10인 분수는 소수로 바꿀 수 있어요 — ⟨6 8/10⟩ = 6.8.","소수로 견주어요 — 자연수 부분부터, 같으면 소수점 오른쪽 수.","5.6 < ⟨6 8/10⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_b#17','math',3,2,'u4','','g3_2_math_u4_review_b','unit_review','M3-2-u4-C1',3,'mc','auto','10을 2씩 묶었어요. 4는 10의 얼마인가요?',ARRAY['M3-2-u4-X03','M3-2-u4-X01','M3-2-u4-X21']::text[],true,'{"seq":17,"concept":"M3-2-u4-C1","difficulty":3,"kind":"mc","stem":"10을 2씩 묶었어요. 4는 10의 얼마인가요?","options":[{"t":"⟨2/5⟩","correct":true},{"t":"⟨5/2⟩","mis":"M3-2-u4-X03"},{"t":"⟨2/3⟩","mis":"M3-2-u4-X01"},{"t":"⟨3/5⟩","mis":"M3-2-u4-X21"}],"explanation":["10을 2씩 묶으면 5묶음 — 분모 5.","4는 그중 2묶음 — 분자 2.","4는 10의 ⟨2/5⟩ — 낱개 수 4·10으로 쓰지 않아요."],"variant_rule":{"alt":[{"stem":"28을 4씩 묶었어요. 12는 28의 얼마인가요?","options":[{"t":"⟨3/7⟩","correct":true},{"t":"⟨7/3⟩","mis":"M3-2-u4-X03"},{"t":"⟨3/4⟩","mis":"M3-2-u4-X01"},{"t":"⟨4/7⟩","mis":"M3-2-u4-X07"}],"explanation":["28을 4씩 묶으면 7묶음 — 분모 7.","12는 그중 3묶음 — 분자 3.","12는 28의 ⟨3/7⟩ — 낱개 수 12·28로 쓰지 않아요."],"asset":null},{"stem":"15를 3씩 묶었어요. 3은 15의 얼마인가요?","options":[{"t":"⟨1/5⟩","correct":true},{"t":"⟨1/4⟩","mis":"M3-2-u4-X01"},{"t":"⟨3/5⟩","mis":"M3-2-u4-X07"},{"t":"⟨2/5⟩","mis":"M3-2-u4-X21"}],"explanation":["15를 3씩 묶으면 5묶음 — 분모 5.","3은 그중 1묶음 — 분자 1.","3은 15의 ⟨1/5⟩ — 낱개 수 3·15로 쓰지 않아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_b#18','math',3,2,'u4','','g3_2_math_u4_review_b','unit_review','M3-2-u4-C3',3,'sa','auto','쿠키 16개 중 서윤은 ⟨6/8⟩을, 준우는 ⟨1/8⟩을 먹었어요. 남은 쿠키는 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":18,"concept":"M3-2-u4-C3","difficulty":3,"kind":"sa","stem":"쿠키 16개 중 서윤은 ⟨6/8⟩을, 준우는 ⟨1/8⟩을 먹었어요. 남은 쿠키는 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["16의 ⟨1/8⟩은 2개예요.","서윤은 12개, 준우는 2개 — 모두 14개를 먹었어요.","남은 것은 16 − 14 = 2개."],"variant_rule":{"alt":[{"stem":"사탕 8개 중 건우는 ⟨1/4⟩을, 은비는 ⟨2/4⟩를 먹었어요. 남은 사탕은 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["8의 ⟨1/4⟩은 2개예요.","건우는 2개, 은비는 4개 — 모두 6개를 먹었어요.","남은 것은 8 − 6 = 2개."],"asset":null},{"stem":"귤 20개 중 민서는 ⟨2/5⟩를, 하윤은 ⟨1/5⟩을 먹었어요. 남은 귤은 몇 개인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["20의 ⟨1/5⟩은 4개예요.","민서는 8개, 하윤은 4개 — 모두 12개를 먹었어요.","남은 것은 20 − 12 = 8개."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_b#19','math',3,2,'u4','','g3_2_math_u4_review_b','unit_review','M3-2-u4-C7',3,'sa','auto','⟨4 1/4⟩을 가분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":19,"concept":"M3-2-u4-C7","difficulty":3,"kind":"sa","stem":"⟨4 1/4⟩을 가분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.","answer":["17"],"explanation":["자연수 1은 ⟨1/4⟩이 4개예요 — 4는 4 × 4 = 16개.","⟨1/4⟩은 1개 — 모두 16 + 1 = 17개예요.","⟨4 1/4⟩ = ⟨17/4⟩ — 분모는 그대로 두어요."],"variant_rule":{"alt":[{"stem":"⟨3 1/5⟩을 가분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["자연수 1은 ⟨1/5⟩이 5개예요 — 3은 3 × 5 = 15개.","⟨1/5⟩은 1개 — 모두 15 + 1 = 16개예요.","⟨3 1/5⟩ = ⟨16/5⟩ — 분모는 그대로 두어요."],"asset":null},{"stem":"⟨2 1/9⟩을 가분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.","answer":["19"],"explanation":["자연수 1은 ⟨1/9⟩이 9개예요 — 2는 2 × 9 = 18개.","⟨1/9⟩은 1개 — 모두 18 + 1 = 19개예요.","⟨2 1/9⟩ = ⟨19/9⟩ — 분모는 그대로 두어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_b#20','math',3,2,'u4','','g3_2_math_u4_review_b','unit_review','M3-2-u4-C8',3,'mc','auto','두 수의 크기를 바르게 견준 것은 무엇인가요?',ARRAY['M3-2-u4-X14','M3-2-u4-X22']::text[],true,'{"seq":20,"concept":"M3-2-u4-C8","difficulty":3,"kind":"mc","stem":"두 수의 크기를 바르게 견준 것은 무엇인가요?","options":[{"t":"⟨5/2⟩ < ⟨3 1/2⟩","correct":true},{"t":"⟨5/2⟩ > ⟨3 1/2⟩","mis":"M3-2-u4-X14"},{"t":"⟨5/2⟩ = ⟨3 1/2⟩","mis":"M3-2-u4-X22"},{"t":"견줄 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["한쪽으로 바꾸어 견주어요.","⟨3 1/2⟩ = ⟨7/2⟩이에요.","⟨5/2⟩와 ⟨7/2⟩ — ⟨5/2⟩ < ⟨3 1/2⟩ (⟨5/2⟩ = ⟨2 1/2⟩로 바꾸어도 같아요)."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 두 수의 크기를 바르게 견준 것은 무엇인가요?","options":[{"t":"⟨21/5⟩ > ⟨3 2/5⟩","correct":true},{"t":"⟨21/5⟩ < ⟨3 2/5⟩","mis":"M3-2-u4-X14"},{"t":"⟨21/5⟩ = ⟨3 2/5⟩","mis":"M3-2-u4-X22"},{"t":"견줄 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["한쪽으로 바꾸어 견주어요.","⟨3 2/5⟩ = ⟨17/5⟩이에요.","⟨21/5⟩과 ⟨17/5⟩ — ⟨21/5⟩ > ⟨3 2/5⟩ (⟨21/5⟩ = ⟨4 1/5⟩로 바꾸어도 같아요)."],"asset":null},{"stem":"이번에는 다른 문제예요. 두 수의 크기를 바르게 견준 것은 무엇인가요?","options":[{"t":"⟨16/5⟩ < ⟨3 3/5⟩","correct":true},{"t":"⟨16/5⟩ > ⟨3 3/5⟩","mis":"M3-2-u4-X14"},{"t":"⟨16/5⟩ = ⟨3 3/5⟩","mis":"M3-2-u4-X22"},{"t":"견줄 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["한쪽으로 바꾸어 견주어요.","⟨3 3/5⟩ = ⟨18/5⟩이에요.","⟨16/5⟩과 ⟨18/5⟩ — ⟨16/5⟩ < ⟨3 3/5⟩ (⟨16/5⟩ = ⟨3 1/5⟩로 바꾸어도 같아요)."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_b#21','math',3,2,'u4','','g3_2_math_u4_review_b','unit_review','M3-2-u4-C9',3,'mc','auto','수직선의 한 칸은 0.1이에요. ?가 나타내는 소수는 무엇인가요?',ARRAY['M3-2-u4-X21','M3-2-u4-X16']::text[],true,'{"seq":21,"concept":"M3-2-u4-C9","difficulty":3,"kind":"mc","stem":"수직선의 한 칸은 0.1이에요. ?가 나타내는 소수는 무엇인가요?","options":[{"t":"2.3","correct":true},{"t":"2.4","mis":"M3-2-u4-X21"},{"t":"2.2","mis":"M3-2-u4-X21"},{"t":"3.2","mis":"M3-2-u4-X16"}],"explanation":["오른쪽으로 한 칸 갈 때마다 0.1씩 커져요.","앞뒤의 수를 보면 2.2 다음 자리예요.","?는 2.3이에요."],"asset":{"type":"number_line","cells":["1.9","2","2.1","2.2","?"]},"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 수직선의 한 칸은 0.1이에요. ?가 나타내는 소수는 무엇인가요?","options":[{"t":"5.5","correct":true},{"t":"5.6","mis":"M3-2-u4-X21"},{"t":"5.4","mis":"M3-2-u4-X21"},{"t":"0.5","mis":"M3-2-u4-X15"}],"explanation":["오른쪽으로 한 칸 갈 때마다 0.1씩 커져요.","앞뒤의 수를 보면 5.4 다음 자리예요.","?는 5.5예요."],"asset":{"type":"number_line","cells":["5.2","5.3","5.4","?","5.6"]}},{"stem":"이번에는 다른 문제예요. 수직선의 한 칸은 0.1이에요. ?가 나타내는 소수는 무엇인가요?","options":[{"t":"5.7","correct":true},{"t":"5.8","mis":"M3-2-u4-X21"},{"t":"5.6","mis":"M3-2-u4-X21"},{"t":"7.5","mis":"M3-2-u4-X16"}],"explanation":["오른쪽으로 한 칸 갈 때마다 0.1씩 커져요.","앞뒤의 수를 보면 왼쪽 다음 자리예요.","?는 5.7이에요."],"asset":{"type":"number_line","cells":["?","5.8","5.9","6","6.1"]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_b#22','math',3,2,'u4','','g3_2_math_u4_review_b','unit_review','M3-2-u4-C11',3,'mc','auto','⟨9 □/10⟩가 ⟨9 6/10⟩보다 클 때, □ 안에 들어갈 수 있는 수를 모두 고른 것은 무엇인가요?',ARRAY['M3-2-u4-X21','M3-2-u4-X20']::text[],true,'{"seq":22,"concept":"M3-2-u4-C11","difficulty":3,"kind":"mc","stem":"⟨9 □/10⟩가 ⟨9 6/10⟩보다 클 때, □ 안에 들어갈 수 있는 수를 모두 고른 것은 무엇인가요?","options":[{"t":"7, 8, 9","correct":true},{"t":"6, 7, 8, 9","mis":"M3-2-u4-X21"},{"t":"1, 2, 3, 4, 5","mis":"M3-2-u4-X20"},{"t":"7","mis":"M3-2-u4-X21"}],"explanation":["자연수 부분이 9로 같아요.","분수 부분의 분자 □가 6보다 커야 해요.","□ = 7, 8, 9 — 6은 같아서 넣지 않아요."],"variant_rule":{"alt":[{"stem":"⟨8 □/10⟩가 ⟨8 2/10⟩보다 클 때, □ 안에 들어갈 수 있는 수를 모두 고른 것은 무엇인가요?","options":[{"t":"3, 4, 5, 6, 7, 8, 9","correct":true},{"t":"2, 3, 4, 5, 6, 7, 8, 9","mis":"M3-2-u4-X21"},{"t":"1","mis":"M3-2-u4-X20"},{"t":"3","mis":"M3-2-u4-X21"}],"explanation":["자연수 부분이 8로 같아요.","분수 부분의 분자 □가 2보다 커야 해요.","□ = 3, 4, 5, 6, 7, 8, 9 — 2는 같아서 넣지 않아요."],"asset":null},{"stem":"⟨1 □/10⟩가 ⟨1 3/10⟩보다 클 때, □ 안에 들어갈 수 있는 수를 모두 고른 것은 무엇인가요?","options":[{"t":"4, 5, 6, 7, 8, 9","correct":true},{"t":"3, 4, 5, 6, 7, 8, 9","mis":"M3-2-u4-X21"},{"t":"1, 2","mis":"M3-2-u4-X20"},{"t":"4","mis":"M3-2-u4-X21"}],"explanation":["자연수 부분이 1로 같아요.","분수 부분의 분자 □가 3보다 커야 해요.","□ = 4, 5, 6, 7, 8, 9 — 3은 같아서 넣지 않아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_b#23','math',3,2,'u4','','g3_2_math_u4_review_b','unit_review','M3-2-u4-C5',4,'sa','auto','주사위를 던져 처음 나온 3을 분모로 정했어요. 두 번째로 나온 수를 분자로 할 때, 가분수가 되는 경우는 모두 몇 가지인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":23,"concept":"M3-2-u4-C5","difficulty":4,"kind":"sa","stem":"주사위를 던져 처음 나온 3을 분모로 정했어요. 두 번째로 나온 수를 분자로 할 때, 가분수가 되는 경우는 모두 몇 가지인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["주사위의 수는 1부터 6까지예요.","가분수: 분자가 3과 같거나 커야 해요 — 3, 4, 5, 6.","모두 4가지예요."],"variant_rule":{"alt":[{"stem":"주사위를 던져 처음 나온 6을 분모로 정했어요. 두 번째로 나온 수를 분자로 할 때, 가분수가 되는 경우는 모두 몇 가지인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["주사위의 수는 1부터 6까지예요.","가분수: 분자가 6과 같거나 커야 해요 — 6.","모두 1가지예요."],"asset":null},{"stem":"주사위를 던져 처음 나온 4를 분모로 정했어요. 두 번째로 나온 수를 분자로 할 때, 가분수가 되는 경우는 모두 몇 가지인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["주사위의 수는 1부터 6까지예요.","가분수: 분자가 4와 같거나 커야 해요 — 4, 5, 6.","모두 3가지예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_b#24','math',3,2,'u4','','g3_2_math_u4_review_b','unit_review','M3-2-u4-C11',4,'mc','auto','네 수 중에서 가장 큰 수는 무엇인가요? ⟨1 9/10⟩, 1.6, ⟨1 8/10⟩, ⟨2 8/10⟩',ARRAY['M3-2-u4-X14','M3-2-u4-X20']::text[],true,'{"seq":24,"concept":"M3-2-u4-C11","difficulty":4,"kind":"mc","stem":"네 수 중에서 가장 큰 수는 무엇인가요? ⟨1 9/10⟩, 1.6, ⟨1 8/10⟩, ⟨2 8/10⟩","options":[{"t":"⟨2 8/10⟩","correct":true},{"t":"⟨1 9/10⟩","mis":"M3-2-u4-X14"},{"t":"1.6","mis":"M3-2-u4-X20"},{"t":"⟨1 8/10⟩","mis":"M3-2-u4-X14"}],"explanation":["분수는 소수로 바꾸어요 — 1.9, 1.6, 1.8, 2.8.","자연수 부분부터, 같으면 소수점 오른쪽 수를 견주어요.","가장 큰 수는 ⟨2 8/10⟩이에요."],"variant_rule":{"alt":[{"stem":"네 수 중에서 가장 큰 수는 무엇인가요? 4.6, 5.9, ⟨4 9/10⟩, 4.2","options":[{"t":"5.9","correct":true},{"t":"4.6","mis":"M3-2-u4-X14"},{"t":"⟨4 9/10⟩","mis":"M3-2-u4-X14"},{"t":"4.2","mis":"M3-2-u4-X20"}],"explanation":["분수는 소수로 바꾸어요 — 4.6, 5.9, 4.9, 4.2.","자연수 부분부터, 같으면 소수점 오른쪽 수를 견주어요.","가장 큰 수는 5.9예요."],"asset":null},{"stem":"네 수 중에서 가장 큰 수는 무엇인가요? 7.6, 8.8, ⟨8 9/10⟩, ⟨78/10⟩","options":[{"t":"⟨8 9/10⟩","correct":true},{"t":"7.6","mis":"M3-2-u4-X20"},{"t":"8.8","mis":"M3-2-u4-X14"},{"t":"⟨78/10⟩","mis":"M3-2-u4-X14"}],"explanation":["분수는 소수로 바꾸어요 — 7.6, 8.8, 8.9, 7.8.","자연수 부분부터, 같으면 소수점 오른쪽 수를 견주어요.","가장 큰 수는 ⟨8 9/10⟩예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_b#25','math',3,2,'u4','','g3_2_math_u4_review_b','unit_review','M3-2-u4-C7',4,'essay','teacher','⟨17/5⟩을 대분수로 나타내고, 그 방법을 단위분수를 모으는 말로 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M3-2-u4-C7","difficulty":4,"kind":"essay","stem":"⟨17/5⟩을 대분수로 나타내고, 그 방법을 단위분수를 모으는 말로 설명해 보세요.","answer_guide":{"answer":"예: ⟨17/5⟩은 ⟨1/5⟩이 17개이다. 5개씩 모으면 1이 3번 되고 ⟨1/5⟩이 2개 남으므로 ⟨3 2/5⟩이다.","scoring_points":["⟨1/5⟩이 17개라고 썼는가","5개씩 모아 1이 3번이라고 썼는가","⟨3 2/5⟩라고 답했는가"]},"explanation":["⟨17/5⟩ = ⟨1/5⟩ × 17개.","5개씩 → 1이 3번, 2개 남음.","⟨3 2/5⟩."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_c#1','math',3,2,'u4','','g3_2_math_u4_review_c','unit_review','M3-2-u4-C1',1,'mc','auto','1개씩 묶었어요. 색칠한 부분은 전체의 얼마인가요?',ARRAY['M3-2-u4-X01','M3-2-u4-X03','M3-2-u4-X20']::text[],true,'{"seq":1,"concept":"M3-2-u4-C1","difficulty":1,"kind":"mc","stem":"1개씩 묶었어요. 색칠한 부분은 전체의 얼마인가요?","options":[{"t":"⟨3/5⟩","correct":true},{"t":"⟨3/2⟩","mis":"M3-2-u4-X01"},{"t":"⟨5/3⟩","mis":"M3-2-u4-X03"},{"t":"⟨2/5⟩","mis":"M3-2-u4-X20"}],"explanation":["1개씩 묶으니 모두 5묶음 — 분모 5.","색칠한 묶음은 3묶음 — 분자 3.","색칠한 부분은 전체의 ⟨3/5⟩이에요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1.7,0],[2.7,0],[2.7,1],[1.7,1]],"hi":true},{"p":[[3.4,0],[4.4,0],[4.4,1],[3.4,1]],"hi":true},{"p":[[5.1,0],[6.1,0],[6.1,1],[5.1,1]]},{"p":[[6.8,0],[7.8,0],[7.8,1],[6.8,1]]}],"u":30},"variant_rule":{"alt":[{"stem":"3개씩 묶었어요. 색칠한 부분은 전체의 얼마인가요?","options":[{"t":"⟨1/4⟩","correct":true},{"t":"⟨1/3⟩","mis":"M3-2-u4-X01"},{"t":"⟨3/4⟩","mis":"M3-2-u4-X02"},{"t":"⟨2/4⟩","mis":"M3-2-u4-X21"}],"explanation":["3개씩 묶으니 모두 4묶음 — 분모 4.","색칠한 묶음은 1묶음 — 분자 1.","색칠한 부분은 전체의 ⟨1/4⟩이에요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[2,0],[3,0],[3,1],[2,1]],"hi":true},{"p":[[3.7,0],[4.7,0],[4.7,1],[3.7,1]]},{"p":[[4.7,0],[5.7,0],[5.7,1],[4.7,1]]},{"p":[[5.7,0],[6.7,0],[6.7,1],[5.7,1]]},{"p":[[7.4,0],[8.4,0],[8.4,1],[7.4,1]]},{"p":[[8.4,0],[9.4,0],[9.4,1],[8.4,1]]},{"p":[[9.4,0],[10.4,0],[10.4,1],[9.4,1]]},{"p":[[11.1,0],[12.1,0],[12.1,1],[11.1,1]]},{"p":[[12.1,0],[13.1,0],[13.1,1],[12.1,1]]},{"p":[[13.1,0],[14.1,0],[14.1,1],[13.1,1]]}],"u":21}},{"stem":"4개씩 묶었어요. 색칠한 부분은 전체의 얼마인가요?","options":[{"t":"⟨1/5⟩","correct":true},{"t":"⟨1/4⟩","mis":"M3-2-u4-X01"},{"t":"⟨4/5⟩","mis":"M3-2-u4-X02"},{"t":"⟨2/5⟩","mis":"M3-2-u4-X21"}],"explanation":["4개씩 묶으니 모두 5묶음 — 분모 5.","색칠한 묶음은 1묶음 — 분자 1.","색칠한 부분은 전체의 ⟨1/5⟩이에요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[0,1],[1,1],[1,2],[0,2]],"hi":true},{"p":[[1,1],[2,1],[2,2],[1,2]],"hi":true},{"p":[[2.7,0],[3.7,0],[3.7,1],[2.7,1]]},{"p":[[3.7,0],[4.7,0],[4.7,1],[3.7,1]]},{"p":[[2.7,1],[3.7,1],[3.7,2],[2.7,2]]},{"p":[[3.7,1],[4.7,1],[4.7,2],[3.7,2]]},{"p":[[5.4,0],[6.4,0],[6.4,1],[5.4,1]]},{"p":[[6.4,0],[7.4,0],[7.4,1],[6.4,1]]},{"p":[[5.4,1],[6.4,1],[6.4,2],[5.4,2]]},{"p":[[6.4,1],[7.4,1],[7.4,2],[6.4,2]]},{"p":[[8.1,0],[9.1,0],[9.1,1],[8.1,1]]},{"p":[[9.1,0],[10.1,0],[10.1,1],[9.1,1]]},{"p":[[8.1,1],[9.1,1],[9.1,2],[8.1,2]]},{"p":[[9.1,1],[10.1,1],[10.1,2],[9.1,2]]},{"p":[[10.8,0],[11.8,0],[11.8,1],[10.8,1]]},{"p":[[11.8,0],[12.8,0],[12.8,1],[11.8,1]]},{"p":[[10.8,1],[11.8,1],[11.8,2],[10.8,2]]},{"p":[[11.8,1],[12.8,1],[12.8,2],[11.8,2]]}],"u":23}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_c#2','math',3,2,'u4','','g3_2_math_u4_review_c','unit_review','M3-2-u4-C3',1,'sa','auto','30의 ⟨5/6⟩는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u4-C3","difficulty":1,"kind":"sa","stem":"30의 ⟨5/6⟩는 얼마인가요? 숫자로 쓰세요.","answer":["25"],"explanation":["30을 분모만큼 똑같이 6묶음으로 나누면 한 묶음에 5개예요 — 30의 ⟨1/6⟩은 5.","⟨5/6⟩는 ⟨1/6⟩이 5개 — 5묶음이에요.","30의 ⟨5/6⟩는 5 × 5 = 25 — 분자만 보고 답하지 않아요."],"variant_rule":{"alt":[{"stem":"4의 ⟨1/2⟩은 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["4를 분모만큼 똑같이 2묶음으로 나누면 한 묶음에 2개예요 — 4의 ⟨1/2⟩은 2.","⟨1/2⟩은 그중 1묶음이에요.","4의 ⟨1/2⟩은 2 — 4 ÷ 2와 같아요."],"asset":null},{"stem":"20의 ⟨3/4⟩은 얼마인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["20을 분모만큼 똑같이 4묶음으로 나누면 한 묶음에 5개예요 — 20의 ⟨1/4⟩은 5.","⟨3/4⟩은 ⟨1/4⟩이 3개 — 3묶음이에요.","20의 ⟨3/4⟩은 5 × 3 = 15 — 분자만 보고 답하지 않아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_c#3','math',3,2,'u4','','g3_2_math_u4_review_c','unit_review','M3-2-u4-C4',1,'sa','auto','리본 60 cm의 ⟨3/4⟩은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-2-u4-C4","difficulty":1,"kind":"sa","stem":"리본 60 cm의 ⟨3/4⟩은 몇 cm인가요? 숫자로 쓰세요.","answer":["45"],"explanation":["60 cm를 분모만큼 똑같이 4부분으로 나누면 한 부분이 15 cm예요.","⟨3/4⟩은 그런 부분 3개예요.","60 cm의 ⟨3/4⟩은 45 cm — 나눈 부분의 길이는 모두 같아야 해요."],"asset":{"type":"fbar","bars":[{"den":4,"num":3,"grp":1,"label":"리본 60 cm"}]},"variant_rule":{"alt":[{"stem":"끈 8 m의 ⟨1/2⟩은 몇 m인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["8 m를 분모만큼 똑같이 2부분으로 나누면 한 부분이 4 m예요.","⟨1/2⟩은 한 부분이에요.","8 m의 ⟨1/2⟩은 4 m — 나눈 부분의 길이는 모두 같아야 해요."],"asset":{"type":"fbar","bars":[{"den":2,"num":1,"grp":1,"label":"끈 8 m"}]}},{"stem":"철사 9 m의 ⟨2/3⟩는 몇 m인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["9 m를 분모만큼 똑같이 3부분으로 나누면 한 부분이 3 m예요.","⟨2/3⟩는 그런 부분 2개예요.","9 m의 ⟨2/3⟩는 6 m — 나눈 부분의 길이는 모두 같아야 해요."],"asset":{"type":"fbar","bars":[{"den":3,"num":2,"grp":1,"label":"철사 9 m"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_c#4','math',3,2,'u4','','g3_2_math_u4_review_c','unit_review','M3-2-u4-C5',1,'mc','auto','분수 ⟨9/5⟩는 무엇인가요?',ARRAY['M3-2-u4-X08']::text[],true,'{"seq":4,"concept":"M3-2-u4-C5","difficulty":1,"kind":"mc","stem":"분수 ⟨9/5⟩는 무엇인가요?","options":[{"t":"가분수","correct":true},{"t":"진분수","mis":"M3-2-u4-X08"},{"t":"대분수","mis":"M3-2-u4-X08"},{"t":"자연수","mis":"M3-2-u4-X08"}],"explanation":["분자 9, 분모 5를 견주어요.","분자가 분모보다 커요.","⟨9/5⟩는 가분수 — 분자가 분모와 같거나 큰 분수."],"variant_rule":{"alt":[{"stem":"분수 ⟨2/8⟩는 무엇인가요?","options":[{"t":"진분수","correct":true},{"t":"가분수","mis":"M3-2-u4-X08"},{"t":"대분수","mis":"M3-2-u4-X08"},{"t":"자연수","mis":"M3-2-u4-X08"}],"explanation":["분자 2, 분모 8을 견주어요.","분자가 분모보다 작아요.","⟨2/8⟩는 진분수 — 분자가 분모보다 작은 분수."],"asset":null},{"stem":"분수 ⟨3/3⟩은 무엇인가요?","options":[{"t":"가분수","correct":true},{"t":"진분수","mis":"M3-2-u4-X08"},{"t":"대분수","mis":"M3-2-u4-X08"},{"t":"자연수","mis":"M3-2-u4-X09"}],"explanation":["분자 3, 분모 3을 견주어요.","분자가 분모보다 같아요.","⟨3/3⟩은 가분수 — 분자가 분모와 같거나 큰 분수."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_c#5','math',3,2,'u4','','g3_2_math_u4_review_c','unit_review','M3-2-u4-C6',1,'sa','auto','2를 분모가 3인 분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-2-u4-C6","difficulty":1,"kind":"sa","stem":"2를 분모가 3인 분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["⟨1/3⟩이 3개면 1이에요 — 1 = ⟨3/3⟩.","2는 1이 2개 — ⟨1/3⟩이 3 × 2 = 6개.","2 = ⟨6/3⟩ — 분자는 6."],"variant_rule":{"alt":[{"stem":"2를 분모가 9인 분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["⟨1/9⟩이 9개면 1이에요 — 1 = ⟨9/9⟩.","2는 1이 2개 — ⟨1/9⟩이 9 × 2 = 18개.","2 = ⟨18/9⟩ — 분자는 18."],"asset":null},{"stem":"2를 분모가 6인 분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["⟨1/6⟩이 6개면 1이에요 — 1 = ⟨6/6⟩.","2는 1이 2개 — ⟨1/6⟩이 6 × 2 = 12개.","2 = ⟨12/6⟩ — 분자는 12."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_c#6','math',3,2,'u4','','g3_2_math_u4_review_c','unit_review','M3-2-u4-C7',1,'mc','auto','똑같은 띠 3개에 색칠했어요. 색칠한 부분을 대분수로 나타내면 무엇인가요?',ARRAY['M3-2-u4-X12','M3-2-u4-X21','M3-2-u4-X20']::text[],true,'{"seq":6,"concept":"M3-2-u4-C7","difficulty":1,"kind":"mc","stem":"똑같은 띠 3개에 색칠했어요. 색칠한 부분을 대분수로 나타내면 무엇인가요?","options":[{"t":"⟨2 3/4⟩","correct":true},{"t":"⟨3/4⟩","mis":"M3-2-u4-X12"},{"t":"⟨3 3/4⟩","mis":"M3-2-u4-X21"},{"t":"⟨2 1/4⟩","mis":"M3-2-u4-X20"}],"explanation":["통째로 색칠한 띠가 2개 — 자연수 부분 2.","남은 띠는 4칸 중 3칸 — 진분수 ⟨3/4⟩.","색칠한 부분은 ⟨2 3/4⟩이에요."],"asset":{"type":"fbar","bars":[{"den":4,"num":4},{"den":4,"num":4},{"den":4,"num":3}]},"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 똑같은 띠 3개에 색칠했어요. 색칠한 부분을 대분수로 나타내면 무엇인가요?","options":[{"t":"⟨2 1/6⟩","correct":true},{"t":"⟨1/6⟩","mis":"M3-2-u4-X12"},{"t":"⟨3 1/6⟩","mis":"M3-2-u4-X21"},{"t":"⟨2 5/6⟩","mis":"M3-2-u4-X20"}],"explanation":["통째로 색칠한 띠가 2개 — 자연수 부분 2.","남은 띠는 6칸 중 1칸 — 진분수 ⟨1/6⟩.","색칠한 부분은 ⟨2 1/6⟩이에요."],"asset":{"type":"fbar","bars":[{"den":6,"num":6},{"den":6,"num":6},{"den":6,"num":1}]}},{"stem":"이번에는 다른 문제예요. 똑같은 띠 3개에 색칠했어요. 색칠한 부분을 대분수로 나타내면 무엇인가요?","options":[{"t":"⟨2 1/2⟩","correct":true},{"t":"⟨1/2⟩","mis":"M3-2-u4-X12"},{"t":"⟨3 1/2⟩","mis":"M3-2-u4-X21"},{"t":"⟨1 1/2⟩","mis":"M3-2-u4-X12"}],"explanation":["통째로 색칠한 띠가 2개 — 자연수 부분 2.","남은 띠는 2칸 중 1칸 — 진분수 ⟨1/2⟩.","색칠한 부분은 ⟨2 1/2⟩이에요."],"asset":{"type":"fbar","bars":[{"den":2,"num":2},{"den":2,"num":2},{"den":2,"num":1}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_c#7','math',3,2,'u4','','g3_2_math_u4_review_c','unit_review','M3-2-u4-C9',1,'sa','auto','2.7은 0.1이 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M3-2-u4-C9","difficulty":1,"kind":"sa","stem":"2.7은 0.1이 몇 개인가요? 숫자로 쓰세요.","answer":["27"],"explanation":["1은 0.1이 10개예요 — 2는 0.1이 20개.","0.7은 0.1이 7개예요.","2.7은 0.1이 20 + 7 = 27개."],"variant_rule":{"alt":[{"stem":"6.2는 0.1이 몇 개인가요? 숫자로 쓰세요.","answer":["62"],"explanation":["1은 0.1이 10개예요 — 6은 0.1이 60개.","0.2는 0.1이 2개예요.","6.2는 0.1이 60 + 2 = 62개."],"asset":null},{"stem":"4.5는 0.1이 몇 개인가요? 숫자로 쓰세요.","answer":["45"],"explanation":["1은 0.1이 10개예요 — 4는 0.1이 40개.","0.5는 0.1이 5개예요.","4.5는 0.1이 40 + 5 = 45개."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_c#8','math',3,2,'u4','','g3_2_math_u4_review_c','unit_review','M3-2-u4-C10',1,'mc','auto','두 수의 크기를 바르게 견준 것은 무엇인가요?',ARRAY['M3-2-u4-X18','M3-2-u4-X22']::text[],true,'{"seq":8,"concept":"M3-2-u4-C10","difficulty":1,"kind":"mc","stem":"두 수의 크기를 바르게 견준 것은 무엇인가요?","options":[{"t":"3.4 < 8.7","correct":true},{"t":"3.4 > 8.7","mis":"M3-2-u4-X18"},{"t":"3.4 = 8.7","mis":"M3-2-u4-X22"},{"t":"견줄 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["자연수 부분부터 견주어요 — 3과 8.","자연수 부분이 큰 소수가 더 커요.","3.4 < 8.7 — 0.1이 34개와 87개로 견주어도 같아요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 두 수의 크기를 바르게 견준 것은 무엇인가요?","options":[{"t":"3.8 > 1.6","correct":true},{"t":"3.8 < 1.6","mis":"M3-2-u4-X18"},{"t":"3.8 = 1.6","mis":"M3-2-u4-X22"},{"t":"견줄 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["자연수 부분부터 견주어요 — 3과 1.","자연수 부분이 큰 소수가 더 커요.","3.8 > 1.6 — 0.1이 38개와 16개로 견주어도 같아요."],"asset":null},{"stem":"이번에는 다른 문제예요. 두 수의 크기를 바르게 견준 것은 무엇인가요?","options":[{"t":"9.6 > 2.2","correct":true},{"t":"9.6 < 2.2","mis":"M3-2-u4-X18"},{"t":"9.6 = 2.2","mis":"M3-2-u4-X22"},{"t":"견줄 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["자연수 부분부터 견주어요 — 9와 2.","자연수 부분이 큰 소수가 더 커요.","9.6 > 2.2 — 0.1이 96개와 22개로 견주어도 같아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_c#9','math',3,2,'u4','','g3_2_math_u4_review_c','unit_review','M3-2-u4-C2',2,'mc','auto','검은 돌 3개와 흰 돌 4개가 있어요. 검은 돌은 전체 돌의 얼마인가요?',ARRAY['M3-2-u4-X01','M3-2-u4-X20','M3-2-u4-X03']::text[],true,'{"seq":9,"concept":"M3-2-u4-C2","difficulty":2,"kind":"mc","stem":"검은 돌 3개와 흰 돌 4개가 있어요. 검은 돌은 전체 돌의 얼마인가요?","options":[{"t":"⟨3/7⟩","correct":true},{"t":"⟨3/4⟩","mis":"M3-2-u4-X01"},{"t":"⟨4/7⟩","mis":"M3-2-u4-X20"},{"t":"⟨7/3⟩","mis":"M3-2-u4-X03"}],"explanation":["먼저 전체를 정해요 — 돌은 모두 3 + 4 = 7개.","검은 돌은 흰 돌과 견주는 것이 아니라 전체 7개와 견주어요.","검은 돌은 전체의 ⟨3/7⟩이에요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[2,0],[3,0],[3,1],[2,1]],"hi":true},{"p":[[3,0],[4,0],[4,1],[3,1]]},{"p":[[4,0],[5,0],[5,1],[4,1]]},{"p":[[0,1],[1,1],[1,2],[0,2]]},{"p":[[1,1],[2,1],[2,2],[1,2]]}],"u":30},"variant_rule":{"alt":[{"stem":"검은 돌 2개와 흰 돌 3개가 있어요. 검은 돌은 전체 돌의 얼마인가요?","options":[{"t":"⟨2/5⟩","correct":true},{"t":"⟨2/3⟩","mis":"M3-2-u4-X01"},{"t":"⟨3/5⟩","mis":"M3-2-u4-X20"},{"t":"⟨5/2⟩","mis":"M3-2-u4-X03"}],"explanation":["먼저 전체를 정해요 — 돌은 모두 2 + 3 = 5개.","검은 돌은 흰 돌과 견주는 것이 아니라 전체 5개와 견주어요.","검은 돌은 전체의 ⟨2/5⟩예요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[2,0],[3,0],[3,1],[2,1]]},{"p":[[3,0],[4,0],[4,1],[3,1]]},{"p":[[4,0],[5,0],[5,1],[4,1]]}],"u":30}},{"stem":"검은 돌 4개와 흰 돌 2개가 있어요. 검은 돌은 전체 돌의 얼마인가요?","options":[{"t":"⟨4/6⟩","correct":true},{"t":"⟨4/2⟩","mis":"M3-2-u4-X01"},{"t":"⟨2/6⟩","mis":"M3-2-u4-X20"},{"t":"⟨6/4⟩","mis":"M3-2-u4-X03"}],"explanation":["먼저 전체를 정해요 — 돌은 모두 4 + 2 = 6개.","검은 돌은 흰 돌과 견주는 것이 아니라 전체 6개와 견주어요.","검은 돌은 전체의 ⟨4/6⟩예요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[2,0],[3,0],[3,1],[2,1]],"hi":true},{"p":[[3,0],[4,0],[4,1],[3,1]],"hi":true},{"p":[[4,0],[5,0],[5,1],[4,1]]},{"p":[[0,1],[1,1],[1,2],[0,2]]}],"u":30}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_c#10','math',3,2,'u4','','g3_2_math_u4_review_c','unit_review','M3-2-u4-C3',2,'mc','auto','사탕 12개의 ⟨2/3⟩는 몇 개인가요?',ARRAY['M3-2-u4-X04','M3-2-u4-X05','M3-2-u4-X06']::text[],true,'{"seq":10,"concept":"M3-2-u4-C3","difficulty":2,"kind":"mc","stem":"사탕 12개의 ⟨2/3⟩는 몇 개인가요?","options":[{"t":"8개","correct":true},{"t":"2개","mis":"M3-2-u4-X04"},{"t":"4개","mis":"M3-2-u4-X05"},{"t":"18개","mis":"M3-2-u4-X06"}],"explanation":["12를 분모만큼 똑같이 3묶음으로 나누면 한 묶음에 4개예요 — 12의 ⟨1/3⟩은 4.","⟨2/3⟩는 ⟨1/3⟩이 2개 — 2묶음이에요.","12의 ⟨2/3⟩는 4 × 2 = 8 — 분자만 보고 답하지 않아요."],"variant_rule":{"alt":[{"stem":"쿠키 25개의 ⟨2/5⟩는 몇 개인가요?","options":[{"t":"10개","correct":true},{"t":"2개","mis":"M3-2-u4-X04"},{"t":"5개","mis":"M3-2-u4-X05"},{"t":"15개","mis":"M3-2-u4-X21"}],"explanation":["25를 분모만큼 똑같이 5묶음으로 나누면 한 묶음에 5개예요 — 25의 ⟨1/5⟩은 5.","⟨2/5⟩는 ⟨1/5⟩이 2개 — 2묶음이에요.","25의 ⟨2/5⟩는 5 × 2 = 10 — 분자만 보고 답하지 않아요."],"asset":null},{"stem":"귤 24개의 ⟨2/6⟩는 몇 개인가요?","options":[{"t":"8개","correct":true},{"t":"2개","mis":"M3-2-u4-X04"},{"t":"4개","mis":"M3-2-u4-X05"},{"t":"72개","mis":"M3-2-u4-X06"}],"explanation":["24를 분모만큼 똑같이 6묶음으로 나누면 한 묶음에 4개예요 — 24의 ⟨1/6⟩은 4.","⟨2/6⟩는 ⟨1/6⟩이 2개 — 2묶음이에요.","24의 ⟨2/6⟩는 4 × 2 = 8 — 분자만 보고 답하지 않아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_c#11','math',3,2,'u4','','g3_2_math_u4_review_c','unit_review','M3-2-u4-C4',2,'sa','auto','채원이 하루의 ⟨1/3⟩ 동안 학교에 있는 시간은 몇 시간인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":11,"concept":"M3-2-u4-C4","difficulty":2,"kind":"sa","stem":"채원이 하루의 ⟨1/3⟩ 동안 학교에 있는 시간은 몇 시간인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["하루는 24시간이에요.","24를 똑같이 3부분으로 나누면 한 부분이 8시간이에요.","하루의 ⟨1/3⟩은 8 × 1 = 8시간."],"variant_rule":{"alt":[{"stem":"서윤이 하루의 ⟨9/24⟩ 동안 잠을 잔 시간은 몇 시간인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["하루는 24시간이에요.","24를 똑같이 24부분으로 나누면 한 부분이 1시간이에요.","하루의 ⟨9/24⟩는 1 × 9 = 9시간."],"asset":null},{"stem":"도연이 하루의 ⟨5/12⟩ 동안 학교에 있는 시간은 몇 시간인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["하루는 24시간이에요.","24를 똑같이 12부분으로 나누면 한 부분이 2시간이에요.","하루의 ⟨5/12⟩는 2 × 5 = 10시간."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_c#12','math',3,2,'u4','','g3_2_math_u4_review_c','unit_review','M3-2-u4-C7',2,'sa','auto','⟨18/4⟩을 대분수로 나타내면 자연수 부분은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":12,"concept":"M3-2-u4-C7","difficulty":2,"kind":"sa","stem":"⟨18/4⟩을 대분수로 나타내면 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["⟨18/4⟩은 ⟨1/4⟩이 18개예요.","4개씩 모으면 1 — 18 ÷ 4 = 4 … 2, 통째로 4이고 ⟨1/4⟩이 2개 남아요.","⟨18/4⟩ = ⟨4 2/4⟩ — 분수 부분은 진분수예요."],"variant_rule":{"alt":[{"stem":"⟨20/7⟩을 대분수로 나타내면 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["⟨20/7⟩은 ⟨1/7⟩이 20개예요.","7개씩 모으면 1 — 20 ÷ 7 = 2 … 6, 통째로 2이고 ⟨1/7⟩이 6개 남아요.","⟨20/7⟩ = ⟨2 6/7⟩ — 분수 부분은 진분수예요."],"asset":null},{"stem":"⟨22/6⟩를 대분수로 나타내면 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["⟨22/6⟩는 ⟨1/6⟩이 22개예요.","6개씩 모으면 1 — 22 ÷ 6 = 3 … 4, 통째로 3이고 ⟨1/6⟩이 4개 남아요.","⟨22/6⟩ = ⟨3 4/6⟩ — 분수 부분은 진분수예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_c#13','math',3,2,'u4','','g3_2_math_u4_review_c','unit_review','M3-2-u4-C8',2,'mc','auto','두 수의 크기를 바르게 견준 것은 무엇인가요?',ARRAY['M3-2-u4-X13','M3-2-u4-X22']::text[],true,'{"seq":13,"concept":"M3-2-u4-C8","difficulty":2,"kind":"mc","stem":"두 수의 크기를 바르게 견준 것은 무엇인가요?","options":[{"t":"⟨3 3/5⟩ < ⟨5 1/5⟩","correct":true},{"t":"⟨3 3/5⟩ > ⟨5 1/5⟩","mis":"M3-2-u4-X13"},{"t":"⟨3 3/5⟩ = ⟨5 1/5⟩","mis":"M3-2-u4-X22"},{"t":"견줄 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["대분수는 자연수 부분부터 견주어요.","3 < 5 — 자연수 부분이 큰 쪽이 커요.","분수 부분은 1보다 작아서 뒤집지 못해요 — ⟨3 3/5⟩ < ⟨5 1/5⟩."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 두 수의 크기를 바르게 견준 것은 무엇인가요?","options":[{"t":"⟨1 6/9⟩ < ⟨2 1/9⟩","correct":true},{"t":"⟨1 6/9⟩ > ⟨2 1/9⟩","mis":"M3-2-u4-X13"},{"t":"⟨1 6/9⟩ = ⟨2 1/9⟩","mis":"M3-2-u4-X22"},{"t":"견줄 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["대분수는 자연수 부분부터 견주어요.","1 < 2 — 자연수 부분이 큰 쪽이 커요.","분수 부분은 1보다 작아서 뒤집지 못해요 — ⟨1 6/9⟩ < ⟨2 1/9⟩."],"asset":null},{"stem":"이번에는 다른 문제예요. 두 수의 크기를 바르게 견준 것은 무엇인가요?","options":[{"t":"⟨2 4/8⟩ < ⟨3 3/8⟩","correct":true},{"t":"⟨2 4/8⟩ > ⟨3 3/8⟩","mis":"M3-2-u4-X13"},{"t":"⟨2 4/8⟩ = ⟨3 3/8⟩","mis":"M3-2-u4-X22"},{"t":"견줄 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["대분수는 자연수 부분부터 견주어요.","2 < 3 — 자연수 부분이 큰 쪽이 커요.","분수 부분은 1보다 작아서 뒤집지 못해요 — ⟨2 4/8⟩ < ⟨3 3/8⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_c#14','math',3,2,'u4','','g3_2_math_u4_review_c','unit_review','M3-2-u4-C9',2,'mc','auto','크레파스의 길이는 7 cm 8 mm예요. 몇 cm인지 소수로 나타내면 얼마인가요?',ARRAY['M3-2-u4-X17','M3-2-u4-X16']::text[],true,'{"seq":14,"concept":"M3-2-u4-C9","difficulty":2,"kind":"mc","stem":"크레파스의 길이는 7 cm 8 mm예요. 몇 cm인지 소수로 나타내면 얼마인가요?","options":[{"t":"7.8 cm","correct":true},{"t":"7.08 cm","mis":"M3-2-u4-X17"},{"t":"78 cm","mis":"M3-2-u4-X17"},{"t":"8.7 cm","mis":"M3-2-u4-X16"}],"explanation":["1 mm = ⟨1/10⟩ cm = 0.1 cm예요.","8 mm는 0.8 cm — 7 cm 8 mm = ⟨7 8/10⟩ cm.","⟨7 8/10⟩ cm = 7.8 cm."],"asset":{"type":"mmruler","len":78,"label":"크레파스"},"variant_rule":{"alt":[{"stem":"나뭇잎의 길이는 6 cm 6 mm예요. 몇 cm인지 소수로 나타내면 얼마인가요?","options":[{"t":"6.6 cm","correct":true},{"t":"6.06 cm","mis":"M3-2-u4-X17"},{"t":"66 cm","mis":"M3-2-u4-X17"},{"t":"6.7 cm","mis":"M3-2-u4-X21"}],"explanation":["1 mm = ⟨1/10⟩ cm = 0.1 cm예요.","6 mm는 0.6 cm — 6 cm 6 mm = ⟨6 6/10⟩ cm.","⟨6 6/10⟩ cm = 6.6 cm."],"asset":{"type":"mmruler","len":66,"label":"나뭇잎"}},{"stem":"종이 빨대의 길이는 7 cm 3 mm예요. 몇 cm인지 소수로 나타내면 얼마인가요?","options":[{"t":"7.3 cm","correct":true},{"t":"7.03 cm","mis":"M3-2-u4-X17"},{"t":"73 cm","mis":"M3-2-u4-X17"},{"t":"3.7 cm","mis":"M3-2-u4-X16"}],"explanation":["1 mm = ⟨1/10⟩ cm = 0.1 cm예요.","3 mm는 0.3 cm — 7 cm 3 mm = ⟨7 3/10⟩ cm.","⟨7 3/10⟩ cm = 7.3 cm."],"asset":{"type":"mmruler","len":73,"label":"종이 빨대"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_c#15','math',3,2,'u4','','g3_2_math_u4_review_c','unit_review','M3-2-u4-C10',2,'mc','auto','100 m 수영 기록이에요. 채원 13.5초, 도연 12.5초, 서준 13.2초. 가장 빠른 사람은 누구인가요?',ARRAY['M3-2-u4-X19','M3-2-u4-X18','M3-2-u4-X22']::text[],true,'{"seq":15,"concept":"M3-2-u4-C10","difficulty":2,"kind":"mc","stem":"100 m 수영 기록이에요. 채원 13.5초, 도연 12.5초, 서준 13.2초. 가장 빠른 사람은 누구인가요?","options":[{"t":"도연","correct":true},{"t":"채원","mis":"M3-2-u4-X19"},{"t":"서준","mis":"M3-2-u4-X18"},{"t":"모두 같아요","mis":"M3-2-u4-X22"}],"explanation":["걸린 시간이 짧을수록 빨라요.","13.5, 12.5, 13.2 중 가장 작은 수는 12.5예요.","가장 빠른 사람은 도연이에요."],"variant_rule":{"alt":[{"stem":"50 m 달리기 기록이에요. 하윤 8.1초, 준우 9.9초, 건우 9.1초. 가장 빠른 사람은 누구인가요?","options":[{"t":"하윤","correct":true},{"t":"준우","mis":"M3-2-u4-X19"},{"t":"건우","mis":"M3-2-u4-X18"},{"t":"모두 같아요","mis":"M3-2-u4-X22"}],"explanation":["걸린 시간이 짧을수록 빨라요.","8.1, 9.9, 9.1 중 가장 작은 수는 8.1이에요.","가장 빠른 사람은 하윤이에요."],"asset":null},{"stem":"큐브 맞추기 기록이에요. 지훈 13.7초, 채원 13.4초, 민서 12.2초. 가장 빠른 사람은 누구인가요?","options":[{"t":"민서","correct":true},{"t":"지훈","mis":"M3-2-u4-X19"},{"t":"채원","mis":"M3-2-u4-X18"},{"t":"모두 같아요","mis":"M3-2-u4-X22"}],"explanation":["걸린 시간이 짧을수록 빨라요.","13.7, 13.4, 12.2 중 가장 작은 수는 12.2예요.","가장 빠른 사람은 민서예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_c#16','math',3,2,'u4','','g3_2_math_u4_review_c','unit_review','M3-2-u4-C11',2,'mc','auto','두 수의 크기를 바르게 견준 것은 무엇인가요?',ARRAY['M3-2-u4-X14','M3-2-u4-X22']::text[],true,'{"seq":16,"concept":"M3-2-u4-C11","difficulty":2,"kind":"mc","stem":"두 수의 크기를 바르게 견준 것은 무엇인가요?","options":[{"t":"5.4 < ⟨5 5/10⟩","correct":true},{"t":"5.4 > ⟨5 5/10⟩","mis":"M3-2-u4-X14"},{"t":"5.4 = ⟨5 5/10⟩","mis":"M3-2-u4-X22"},{"t":"견줄 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["분모가 10인 분수는 소수로 바꿀 수 있어요 — ⟨5 5/10⟩ = 5.5.","소수로 견주어요 — 자연수 부분부터, 같으면 소수점 오른쪽 수.","5.4 < ⟨5 5/10⟩."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 두 수의 크기를 바르게 견준 것은 무엇인가요?","options":[{"t":"⟨6 6/10⟩ > 6.1","correct":true},{"t":"⟨6 6/10⟩ < 6.1","mis":"M3-2-u4-X14"},{"t":"⟨6 6/10⟩ = 6.1","mis":"M3-2-u4-X22"},{"t":"견줄 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["분모가 10인 분수는 소수로 바꿀 수 있어요 — ⟨6 6/10⟩ = 6.6.","소수로 견주어요 — 자연수 부분부터, 같으면 소수점 오른쪽 수.","⟨6 6/10⟩ > 6.1."],"asset":null},{"stem":"이번에는 다른 문제예요. 두 수의 크기를 바르게 견준 것은 무엇인가요?","options":[{"t":"8.2 > ⟨7 9/10⟩","correct":true},{"t":"8.2 < ⟨7 9/10⟩","mis":"M3-2-u4-X14"},{"t":"8.2 = ⟨7 9/10⟩","mis":"M3-2-u4-X22"},{"t":"견줄 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["분모가 10인 분수는 소수로 바꿀 수 있어요 — ⟨7 9/10⟩ = 7.9.","소수로 견주어요 — 자연수 부분부터, 같으면 소수점 오른쪽 수.","8.2 > ⟨7 9/10⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_c#17','math',3,2,'u4','','g3_2_math_u4_review_c','unit_review','M3-2-u4-C1',3,'mc','auto','18을 3씩 묶었어요. 15는 18의 얼마인가요?',ARRAY['M3-2-u4-X03','M3-2-u4-X07','M3-2-u4-X02']::text[],true,'{"seq":17,"concept":"M3-2-u4-C1","difficulty":3,"kind":"mc","stem":"18을 3씩 묶었어요. 15는 18의 얼마인가요?","options":[{"t":"⟨5/6⟩","correct":true},{"t":"⟨6/5⟩","mis":"M3-2-u4-X03"},{"t":"⟨3/6⟩","mis":"M3-2-u4-X07"},{"t":"⟨5/18⟩","mis":"M3-2-u4-X02"}],"explanation":["18을 3씩 묶으면 6묶음 — 분모 6.","15는 그중 5묶음 — 분자 5.","15는 18의 ⟨5/6⟩ — 낱개 수 15·18로 쓰지 않아요."],"variant_rule":{"alt":[{"stem":"25를 5씩 묶었어요. 10은 25의 얼마인가요?","options":[{"t":"⟨2/5⟩","correct":true},{"t":"⟨5/2⟩","mis":"M3-2-u4-X03"},{"t":"⟨2/3⟩","mis":"M3-2-u4-X01"},{"t":"⟨3/5⟩","mis":"M3-2-u4-X21"}],"explanation":["25를 5씩 묶으면 5묶음 — 분모 5.","10은 그중 2묶음 — 분자 2.","10은 25의 ⟨2/5⟩ — 낱개 수 10·25로 쓰지 않아요."],"asset":null},{"stem":"30을 5씩 묶었어요. 25는 30의 얼마인가요?","options":[{"t":"⟨5/6⟩","correct":true},{"t":"⟨6/5⟩","mis":"M3-2-u4-X03"},{"t":"⟨5/30⟩","mis":"M3-2-u4-X02"},{"t":"⟨1/6⟩","mis":"M3-2-u4-X20"}],"explanation":["30을 5씩 묶으면 6묶음 — 분모 6.","25는 그중 5묶음 — 분자 5.","25는 30의 ⟨5/6⟩ — 낱개 수 25·30으로 쓰지 않아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_c#18','math',3,2,'u4','','g3_2_math_u4_review_c','unit_review','M3-2-u4-C3',3,'sa','auto','약과 8개 중 민서는 ⟨2/4⟩를, 하윤은 ⟨1/4⟩을 먹었어요. 남은 약과는 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":18,"concept":"M3-2-u4-C3","difficulty":3,"kind":"sa","stem":"약과 8개 중 민서는 ⟨2/4⟩를, 하윤은 ⟨1/4⟩을 먹었어요. 남은 약과는 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["8의 ⟨1/4⟩은 2개예요.","민서는 4개, 하윤은 2개 — 모두 6개를 먹었어요.","남은 것은 8 − 6 = 2개."],"variant_rule":{"alt":[{"stem":"쿠키 24개 중 도연은 ⟨4/6⟩를, 하윤은 ⟨1/6⟩을 먹었어요. 남은 쿠키는 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["24의 ⟨1/6⟩은 4개예요.","도연은 16개, 하윤은 4개 — 모두 20개를 먹었어요.","남은 것은 24 − 20 = 4개."],"asset":null},{"stem":"사탕 10개 중 준우는 ⟨2/5⟩를, 서준은 ⟨2/5⟩를 먹었어요. 남은 사탕은 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["10의 ⟨1/5⟩은 2개예요.","준우는 4개, 서준은 4개 — 모두 8개를 먹었어요.","남은 것은 10 − 8 = 2개."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_c#19','math',3,2,'u4','','g3_2_math_u4_review_c','unit_review','M3-2-u4-C7',3,'sa','auto','⟨3 2/5⟩를 가분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":19,"concept":"M3-2-u4-C7","difficulty":3,"kind":"sa","stem":"⟨3 2/5⟩를 가분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.","answer":["17"],"explanation":["자연수 1은 ⟨1/5⟩이 5개예요 — 3은 3 × 5 = 15개.","⟨2/5⟩는 2개 — 모두 15 + 2 = 17개예요.","⟨3 2/5⟩ = ⟨17/5⟩ — 분모는 그대로 두어요."],"variant_rule":{"alt":[{"stem":"⟨4 1/9⟩을 가분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.","answer":["37"],"explanation":["자연수 1은 ⟨1/9⟩이 9개예요 — 4는 4 × 9 = 36개.","⟨1/9⟩은 1개 — 모두 36 + 1 = 37개예요.","⟨4 1/9⟩ = ⟨37/9⟩ — 분모는 그대로 두어요."],"asset":null},{"stem":"⟨4 4/7⟩를 가분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.","answer":["32"],"explanation":["자연수 1은 ⟨1/7⟩이 7개예요 — 4는 4 × 7 = 28개.","⟨4/7⟩는 4개 — 모두 28 + 4 = 32개예요.","⟨4 4/7⟩ = ⟨32/7⟩ — 분모는 그대로 두어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_c#20','math',3,2,'u4','','g3_2_math_u4_review_c','unit_review','M3-2-u4-C8',3,'mc','auto','두 수의 크기를 바르게 견준 것은 무엇인가요?',ARRAY['M3-2-u4-X14','M3-2-u4-X22']::text[],true,'{"seq":20,"concept":"M3-2-u4-C8","difficulty":3,"kind":"mc","stem":"두 수의 크기를 바르게 견준 것은 무엇인가요?","options":[{"t":"⟨13/7⟩ > ⟨1 1/7⟩","correct":true},{"t":"⟨13/7⟩ < ⟨1 1/7⟩","mis":"M3-2-u4-X14"},{"t":"⟨13/7⟩ = ⟨1 1/7⟩","mis":"M3-2-u4-X22"},{"t":"견줄 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["한쪽으로 바꾸어 견주어요.","⟨1 1/7⟩ = ⟨8/7⟩이에요.","⟨13/7⟩과 ⟨8/7⟩ — ⟨13/7⟩ > ⟨1 1/7⟩ (⟨13/7⟩ = ⟨1 6/7⟩으로 바꾸어도 같아요)."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 두 수의 크기를 바르게 견준 것은 무엇인가요?","options":[{"t":"⟨14/3⟩ > ⟨2 1/3⟩","correct":true},{"t":"⟨14/3⟩ < ⟨2 1/3⟩","mis":"M3-2-u4-X14"},{"t":"⟨14/3⟩ = ⟨2 1/3⟩","mis":"M3-2-u4-X22"},{"t":"견줄 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["한쪽으로 바꾸어 견주어요.","⟨2 1/3⟩ = ⟨7/3⟩이에요.","⟨14/3⟩와 ⟨7/3⟩ — ⟨14/3⟩ > ⟨2 1/3⟩ (⟨14/3⟩ = ⟨4 2/3⟩로 바꾸어도 같아요)."],"asset":null},{"stem":"이번에는 다른 문제예요. 두 수의 크기를 바르게 견준 것은 무엇인가요?","options":[{"t":"⟨14/5⟩ > ⟨2 2/5⟩","correct":true},{"t":"⟨14/5⟩ < ⟨2 2/5⟩","mis":"M3-2-u4-X14"},{"t":"⟨14/5⟩ = ⟨2 2/5⟩","mis":"M3-2-u4-X22"},{"t":"견줄 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["한쪽으로 바꾸어 견주어요.","⟨2 2/5⟩ = ⟨12/5⟩예요.","⟨14/5⟩와 ⟨12/5⟩ — ⟨14/5⟩ > ⟨2 2/5⟩ (⟨14/5⟩ = ⟨2 4/5⟩로 바꾸어도 같아요)."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_c#21','math',3,2,'u4','','g3_2_math_u4_review_c','unit_review','M3-2-u4-C9',3,'mc','auto','수직선의 한 칸은 0.1이에요. ?가 나타내는 소수는 무엇인가요?',ARRAY['M3-2-u4-X21','M3-2-u4-X16']::text[],true,'{"seq":21,"concept":"M3-2-u4-C9","difficulty":3,"kind":"mc","stem":"수직선의 한 칸은 0.1이에요. ?가 나타내는 소수는 무엇인가요?","options":[{"t":"8.9","correct":true},{"t":"9","mis":"M3-2-u4-X21"},{"t":"8.8","mis":"M3-2-u4-X21"},{"t":"9.8","mis":"M3-2-u4-X16"}],"explanation":["오른쪽으로 한 칸 갈 때마다 0.1씩 커져요.","앞뒤의 수를 보면 8.8 다음 자리예요.","?는 8.9예요."],"asset":{"type":"number_line","cells":["8.5","8.6","8.7","8.8","?"]},"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 수직선의 한 칸은 0.1이에요. ?가 나타내는 소수는 무엇인가요?","options":[{"t":"1.3","correct":true},{"t":"1.4","mis":"M3-2-u4-X21"},{"t":"1.2","mis":"M3-2-u4-X21"},{"t":"3.1","mis":"M3-2-u4-X16"}],"explanation":["오른쪽으로 한 칸 갈 때마다 0.1씩 커져요.","앞뒤의 수를 보면 1.2 다음 자리예요.","?는 1.3이에요."],"asset":{"type":"number_line","cells":["0.9","1","1.1","1.2","?"]}},{"stem":"이번에는 다른 문제예요. 수직선의 한 칸은 0.1이에요. ?가 나타내는 소수는 무엇인가요?","options":[{"t":"8.2","correct":true},{"t":"8.3","mis":"M3-2-u4-X21"},{"t":"8.1","mis":"M3-2-u4-X21"},{"t":"2.8","mis":"M3-2-u4-X16"}],"explanation":["오른쪽으로 한 칸 갈 때마다 0.1씩 커져요.","앞뒤의 수를 보면 8.1 다음 자리예요.","?는 8.2예요."],"asset":{"type":"number_line","cells":["8.1","?","8.3","8.4","8.5"]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_c#22','math',3,2,'u4','','g3_2_math_u4_review_c','unit_review','M3-2-u4-C11',3,'mc','auto','⟨9 □/10⟩가 ⟨9 3/10⟩보다 클 때, □ 안에 들어갈 수 있는 수를 모두 고른 것은 무엇인가요?',ARRAY['M3-2-u4-X21','M3-2-u4-X20']::text[],true,'{"seq":22,"concept":"M3-2-u4-C11","difficulty":3,"kind":"mc","stem":"⟨9 □/10⟩가 ⟨9 3/10⟩보다 클 때, □ 안에 들어갈 수 있는 수를 모두 고른 것은 무엇인가요?","options":[{"t":"4, 5, 6, 7, 8, 9","correct":true},{"t":"3, 4, 5, 6, 7, 8, 9","mis":"M3-2-u4-X21"},{"t":"1, 2","mis":"M3-2-u4-X20"},{"t":"4","mis":"M3-2-u4-X21"}],"explanation":["자연수 부분이 9로 같아요.","분수 부분의 분자 □가 3보다 커야 해요.","□ = 4, 5, 6, 7, 8, 9 — 3은 같아서 넣지 않아요."],"variant_rule":{"alt":[{"stem":"⟨6 □/10⟩가 ⟨6 5/10⟩보다 클 때, □ 안에 들어갈 수 있는 수를 모두 고른 것은 무엇인가요?","options":[{"t":"6, 7, 8, 9","correct":true},{"t":"5, 6, 7, 8, 9","mis":"M3-2-u4-X21"},{"t":"1, 2, 3, 4","mis":"M3-2-u4-X20"},{"t":"6","mis":"M3-2-u4-X21"}],"explanation":["자연수 부분이 6으로 같아요.","분수 부분의 분자 □가 5보다 커야 해요.","□ = 6, 7, 8, 9 — 5는 같아서 넣지 않아요."],"asset":null},{"stem":"⟨9 □/10⟩가 ⟨9 6/10⟩보다 클 때, □ 안에 들어갈 수 있는 수를 모두 고른 것은 무엇인가요?","options":[{"t":"7, 8, 9","correct":true},{"t":"6, 7, 8, 9","mis":"M3-2-u4-X21"},{"t":"1, 2, 3, 4, 5","mis":"M3-2-u4-X20"},{"t":"7","mis":"M3-2-u4-X21"}],"explanation":["자연수 부분이 9로 같아요.","분수 부분의 분자 □가 6보다 커야 해요.","□ = 7, 8, 9 — 6은 같아서 넣지 않아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_c#23','math',3,2,'u4','','g3_2_math_u4_review_c','unit_review','M3-2-u4-C5',4,'sa','auto','주사위를 던져 처음 나온 5를 분모로 정했어요. 두 번째로 나온 수를 분자로 할 때, 가분수가 되는 경우는 모두 몇 가지인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":23,"concept":"M3-2-u4-C5","difficulty":4,"kind":"sa","stem":"주사위를 던져 처음 나온 5를 분모로 정했어요. 두 번째로 나온 수를 분자로 할 때, 가분수가 되는 경우는 모두 몇 가지인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["주사위의 수는 1부터 6까지예요.","가분수: 분자가 5와 같거나 커야 해요 — 5, 6.","모두 2가지예요."],"variant_rule":{"alt":[{"stem":"주사위를 던져 처음 나온 3을 분모로 정했어요. 두 번째로 나온 수를 분자로 할 때, 가분수가 되는 경우는 모두 몇 가지인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["주사위의 수는 1부터 6까지예요.","가분수: 분자가 3과 같거나 커야 해요 — 3, 4, 5, 6.","모두 4가지예요."],"asset":null},{"stem":"주사위를 던져 처음 나온 6을 분모로 정했어요. 두 번째로 나온 수를 분자로 할 때, 가분수가 되는 경우는 모두 몇 가지인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["주사위의 수는 1부터 6까지예요.","가분수: 분자가 6과 같거나 커야 해요 — 6.","모두 1가지예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_c#24','math',3,2,'u4','','g3_2_math_u4_review_c','unit_review','M3-2-u4-C11',4,'mc','auto','네 수 중에서 가장 큰 수는 무엇인가요? 3.7, 4.4, ⟨4 2/10⟩, ⟨47/10⟩',ARRAY['M3-2-u4-X20','M3-2-u4-X14']::text[],true,'{"seq":24,"concept":"M3-2-u4-C11","difficulty":4,"kind":"mc","stem":"네 수 중에서 가장 큰 수는 무엇인가요? 3.7, 4.4, ⟨4 2/10⟩, ⟨47/10⟩","options":[{"t":"⟨47/10⟩","correct":true},{"t":"3.7","mis":"M3-2-u4-X20"},{"t":"4.4","mis":"M3-2-u4-X14"},{"t":"⟨4 2/10⟩","mis":"M3-2-u4-X14"}],"explanation":["분수는 소수로 바꾸어요 — 3.7, 4.4, 4.2, 4.7.","자연수 부분부터, 같으면 소수점 오른쪽 수를 견주어요.","가장 큰 수는 ⟨47/10⟩이에요."],"variant_rule":{"alt":[{"stem":"네 수 중에서 가장 큰 수는 무엇인가요? ⟨6 8/10⟩, 6.7, ⟨71/10⟩, ⟨6 6/10⟩","options":[{"t":"⟨71/10⟩","correct":true},{"t":"⟨6 8/10⟩","mis":"M3-2-u4-X14"},{"t":"6.7","mis":"M3-2-u4-X14"},{"t":"⟨6 6/10⟩","mis":"M3-2-u4-X20"}],"explanation":["분수는 소수로 바꾸어요 — 6.8, 6.7, 7.1, 6.6.","자연수 부분부터, 같으면 소수점 오른쪽 수를 견주어요.","가장 큰 수는 ⟨71/10⟩이에요."],"asset":null},{"stem":"네 수 중에서 가장 큰 수는 무엇인가요? 5.3, ⟨5 4/10⟩, ⟨5 6/10⟩, 5.5","options":[{"t":"⟨5 6/10⟩","correct":true},{"t":"5.3","mis":"M3-2-u4-X20"},{"t":"⟨5 4/10⟩","mis":"M3-2-u4-X14"},{"t":"5.5","mis":"M3-2-u4-X14"}],"explanation":["분수는 소수로 바꾸어요 — 5.3, 5.4, 5.6, 5.5.","자연수 부분부터, 같으면 소수점 오른쪽 수를 견주어요.","가장 큰 수는 ⟨5 6/10⟩이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_c#25','math',3,2,'u4','','g3_2_math_u4_review_c','unit_review','M3-2-u4-C9',4,'essay','teacher','3 cm 5 mm를 분수와 소수로 각각 나타내고, 0.1 cm가 몇 개인 길이인지 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M3-2-u4-C9","difficulty":4,"kind":"essay","stem":"3 cm 5 mm를 분수와 소수로 각각 나타내고, 0.1 cm가 몇 개인 길이인지 설명해 보세요.","answer_guide":{"answer":"예: 5 mm = ⟨5/10⟩ cm이므로 3 cm 5 mm = ⟨3 5/10⟩ cm = 3.5 cm이다. 3 cm는 0.1 cm가 30개, 5 mm는 5개이므로 모두 35개인 길이이다.","scoring_points":["⟨3 5/10⟩ cm를 썼는가","3.5 cm를 썼는가","0.1 cm가 35개라고 설명했는가"]},"explanation":["5 mm = 0.5 cm.","3 cm 5 mm = 3.5 cm.","0.1 cm × 35개."],"asset":{"type":"mmruler","len":35,"label":"색 테이프"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_d#1','math',3,2,'u4','','g3_2_math_u4_review_d','unit_review','M3-2-u4-C1',1,'mc','auto','4개씩 묶었어요. 색칠한 부분은 전체의 얼마인가요?',ARRAY['M3-2-u4-X03','M3-2-u4-X02','M3-2-u4-X20']::text[],true,'{"seq":1,"concept":"M3-2-u4-C1","difficulty":1,"kind":"mc","stem":"4개씩 묶었어요. 색칠한 부분은 전체의 얼마인가요?","options":[{"t":"⟨3/4⟩","correct":true},{"t":"⟨4/3⟩","mis":"M3-2-u4-X03"},{"t":"⟨12/4⟩","mis":"M3-2-u4-X02"},{"t":"⟨1/4⟩","mis":"M3-2-u4-X20"}],"explanation":["4개씩 묶으니 모두 4묶음 — 분모 4.","색칠한 묶음은 3묶음 — 분자 3.","색칠한 부분은 전체의 ⟨3/4⟩이에요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[0,1],[1,1],[1,2],[0,2]],"hi":true},{"p":[[1,1],[2,1],[2,2],[1,2]],"hi":true},{"p":[[2.7,0],[3.7,0],[3.7,1],[2.7,1]],"hi":true},{"p":[[3.7,0],[4.7,0],[4.7,1],[3.7,1]],"hi":true},{"p":[[2.7,1],[3.7,1],[3.7,2],[2.7,2]],"hi":true},{"p":[[3.7,1],[4.7,1],[4.7,2],[3.7,2]],"hi":true},{"p":[[5.4,0],[6.4,0],[6.4,1],[5.4,1]],"hi":true},{"p":[[6.4,0],[7.4,0],[7.4,1],[6.4,1]],"hi":true},{"p":[[5.4,1],[6.4,1],[6.4,2],[5.4,2]],"hi":true},{"p":[[6.4,1],[7.4,1],[7.4,2],[6.4,2]],"hi":true},{"p":[[8.1,0],[9.1,0],[9.1,1],[8.1,1]]},{"p":[[9.1,0],[10.1,0],[10.1,1],[9.1,1]]},{"p":[[8.1,1],[9.1,1],[9.1,2],[8.1,2]]},{"p":[[9.1,1],[10.1,1],[10.1,2],[9.1,2]]}],"u":29},"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 4개씩 묶었어요. 색칠한 부분은 전체의 얼마인가요?","options":[{"t":"⟨1/3⟩","correct":true},{"t":"⟨1/2⟩","mis":"M3-2-u4-X01"},{"t":"⟨4/3⟩","mis":"M3-2-u4-X02"},{"t":"⟨2/3⟩","mis":"M3-2-u4-X20"}],"explanation":["4개씩 묶으니 모두 3묶음 — 분모 3.","색칠한 묶음은 1묶음 — 분자 1.","색칠한 부분은 전체의 ⟨1/3⟩이에요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[0,1],[1,1],[1,2],[0,2]],"hi":true},{"p":[[1,1],[2,1],[2,2],[1,2]],"hi":true},{"p":[[2.7,0],[3.7,0],[3.7,1],[2.7,1]]},{"p":[[3.7,0],[4.7,0],[4.7,1],[3.7,1]]},{"p":[[2.7,1],[3.7,1],[3.7,2],[2.7,2]]},{"p":[[3.7,1],[4.7,1],[4.7,2],[3.7,2]]},{"p":[[5.4,0],[6.4,0],[6.4,1],[5.4,1]]},{"p":[[6.4,0],[7.4,0],[7.4,1],[6.4,1]]},{"p":[[5.4,1],[6.4,1],[6.4,2],[5.4,2]]},{"p":[[6.4,1],[7.4,1],[7.4,2],[6.4,2]]}],"u":30}},{"stem":"2개씩 묶었어요. 색칠한 부분은 전체의 얼마인가요?","options":[{"t":"⟨1/6⟩","correct":true},{"t":"⟨1/5⟩","mis":"M3-2-u4-X01"},{"t":"⟨2/6⟩","mis":"M3-2-u4-X02"},{"t":"⟨5/6⟩","mis":"M3-2-u4-X20"}],"explanation":["2개씩 묶으니 모두 6묶음 — 분모 6.","색칠한 묶음은 1묶음 — 분자 1.","색칠한 부분은 전체의 ⟨1/6⟩이에요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[2.7,0],[3.7,0],[3.7,1],[2.7,1]]},{"p":[[3.7,0],[4.7,0],[4.7,1],[3.7,1]]},{"p":[[5.4,0],[6.4,0],[6.4,1],[5.4,1]]},{"p":[[6.4,0],[7.4,0],[7.4,1],[6.4,1]]},{"p":[[8.1,0],[9.1,0],[9.1,1],[8.1,1]]},{"p":[[9.1,0],[10.1,0],[10.1,1],[9.1,1]]},{"p":[[10.8,0],[11.8,0],[11.8,1],[10.8,1]]},{"p":[[11.8,0],[12.8,0],[12.8,1],[11.8,1]]},{"p":[[13.5,0],[14.5,0],[14.5,1],[13.5,1]]},{"p":[[14.5,0],[15.5,0],[15.5,1],[14.5,1]]}],"u":19}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_d#2','math',3,2,'u4','','g3_2_math_u4_review_d','unit_review','M3-2-u4-C3',1,'sa','auto','10의 ⟨4/5⟩는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u4-C3","difficulty":1,"kind":"sa","stem":"10의 ⟨4/5⟩는 얼마인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["10을 분모만큼 똑같이 5묶음으로 나누면 한 묶음에 2개예요 — 10의 ⟨1/5⟩은 2.","⟨4/5⟩는 ⟨1/5⟩이 4개 — 4묶음이에요.","10의 ⟨4/5⟩는 2 × 4 = 8 — 분자만 보고 답하지 않아요."],"variant_rule":{"alt":[{"stem":"12의 ⟨2/3⟩는 얼마인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["12를 분모만큼 똑같이 3묶음으로 나누면 한 묶음에 4개예요 — 12의 ⟨1/3⟩은 4.","⟨2/3⟩는 ⟨1/3⟩이 2개 — 2묶음이에요.","12의 ⟨2/3⟩는 4 × 2 = 8 — 분자만 보고 답하지 않아요."],"asset":null},{"stem":"12의 ⟨4/6⟩는 얼마인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["12를 분모만큼 똑같이 6묶음으로 나누면 한 묶음에 2개예요 — 12의 ⟨1/6⟩은 2.","⟨4/6⟩는 ⟨1/6⟩이 4개 — 4묶음이에요.","12의 ⟨4/6⟩는 2 × 4 = 8 — 분자만 보고 답하지 않아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_d#3','math',3,2,'u4','','g3_2_math_u4_review_d','unit_review','M3-2-u4-C4',1,'sa','auto','색 테이프 20 m의 ⟨1/4⟩은 몇 m인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-2-u4-C4","difficulty":1,"kind":"sa","stem":"색 테이프 20 m의 ⟨1/4⟩은 몇 m인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["20 m를 분모만큼 똑같이 4부분으로 나누면 한 부분이 5 m예요.","⟨1/4⟩은 한 부분이에요.","20 m의 ⟨1/4⟩은 5 m — 나눈 부분의 길이는 모두 같아야 해요."],"asset":{"type":"fbar","bars":[{"den":4,"num":1,"grp":1,"label":"색 테이프 20 m"}]},"variant_rule":{"alt":[{"stem":"리본 40 cm의 ⟨1/2⟩은 몇 cm인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["40 cm를 분모만큼 똑같이 2부분으로 나누면 한 부분이 20 cm예요.","⟨1/2⟩은 한 부분이에요.","40 cm의 ⟨1/2⟩은 20 cm — 나눈 부분의 길이는 모두 같아야 해요."],"asset":{"type":"fbar","bars":[{"den":2,"num":1,"grp":1,"label":"리본 40 cm"}]}},{"stem":"끈 90 cm의 ⟨1/3⟩은 몇 cm인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["90 cm를 분모만큼 똑같이 3부분으로 나누면 한 부분이 30 cm예요.","⟨1/3⟩은 한 부분이에요.","90 cm의 ⟨1/3⟩은 30 cm — 나눈 부분의 길이는 모두 같아야 해요."],"asset":{"type":"fbar","bars":[{"den":3,"num":1,"grp":1,"label":"끈 90 cm"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_d#4','math',3,2,'u4','','g3_2_math_u4_review_d','unit_review','M3-2-u4-C5',1,'mc','auto','분수 ⟨1/2⟩은 무엇인가요?',ARRAY['M3-2-u4-X08']::text[],true,'{"seq":4,"concept":"M3-2-u4-C5","difficulty":1,"kind":"mc","stem":"분수 ⟨1/2⟩은 무엇인가요?","options":[{"t":"진분수","correct":true},{"t":"가분수","mis":"M3-2-u4-X08"},{"t":"대분수","mis":"M3-2-u4-X08"},{"t":"자연수","mis":"M3-2-u4-X08"}],"explanation":["분자 1, 분모 2를 견주어요.","분자가 분모보다 작아요.","⟨1/2⟩은 진분수 — 분자가 분모보다 작은 분수."],"variant_rule":{"alt":[{"stem":"분수 ⟨3/4⟩은 무엇인가요?","options":[{"t":"진분수","correct":true},{"t":"가분수","mis":"M3-2-u4-X08"},{"t":"대분수","mis":"M3-2-u4-X08"},{"t":"자연수","mis":"M3-2-u4-X08"}],"explanation":["분자 3, 분모 4를 견주어요.","분자가 분모보다 작아요.","⟨3/4⟩은 진분수 — 분자가 분모보다 작은 분수."],"asset":null},{"stem":"분수 ⟨5/8⟩는 무엇인가요?","options":[{"t":"진분수","correct":true},{"t":"가분수","mis":"M3-2-u4-X08"},{"t":"대분수","mis":"M3-2-u4-X08"},{"t":"자연수","mis":"M3-2-u4-X08"}],"explanation":["분자 5, 분모 8을 견주어요.","분자가 분모보다 작아요.","⟨5/8⟩는 진분수 — 분자가 분모보다 작은 분수."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_d#5','math',3,2,'u4','','g3_2_math_u4_review_d','unit_review','M3-2-u4-C6',1,'sa','auto','2를 분모가 4인 분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-2-u4-C6","difficulty":1,"kind":"sa","stem":"2를 분모가 4인 분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["⟨1/4⟩이 4개면 1이에요 — 1 = ⟨4/4⟩.","2는 1이 2개 — ⟨1/4⟩이 4 × 2 = 8개.","2 = ⟨8/4⟩ — 분자는 8."],"variant_rule":{"alt":[{"stem":"3을 분모가 3인 분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["⟨1/3⟩이 3개면 1이에요 — 1 = ⟨3/3⟩.","3은 1이 3개 — ⟨1/3⟩이 3 × 3 = 9개.","3 = ⟨9/3⟩ — 분자는 9."],"asset":null},{"stem":"2를 분모가 2인 분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["⟨1/2⟩이 2개면 1이에요 — 1 = ⟨2/2⟩.","2는 1이 2개 — ⟨1/2⟩이 2 × 2 = 4개.","2 = ⟨4/2⟩ — 분자는 4."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_d#6','math',3,2,'u4','','g3_2_math_u4_review_d','unit_review','M3-2-u4-C7',1,'mc','auto','똑같은 띠 2개에 색칠했어요. 색칠한 부분을 대분수로 나타내면 무엇인가요?',ARRAY['M3-2-u4-X12','M3-2-u4-X21','M3-2-u4-X20']::text[],true,'{"seq":6,"concept":"M3-2-u4-C7","difficulty":1,"kind":"mc","stem":"똑같은 띠 2개에 색칠했어요. 색칠한 부분을 대분수로 나타내면 무엇인가요?","options":[{"t":"⟨1 2/3⟩","correct":true},{"t":"⟨2/3⟩","mis":"M3-2-u4-X12"},{"t":"⟨2 2/3⟩","mis":"M3-2-u4-X21"},{"t":"⟨1 1/3⟩","mis":"M3-2-u4-X20"}],"explanation":["통째로 색칠한 띠가 1개 — 자연수 부분 1.","남은 띠는 3칸 중 2칸 — 진분수 ⟨2/3⟩.","색칠한 부분은 ⟨1 2/3⟩예요."],"asset":{"type":"fbar","bars":[{"den":3,"num":3},{"den":3,"num":2}]},"variant_rule":{"alt":[{"stem":"똑같은 띠 3개에 색칠했어요. 색칠한 부분을 대분수로 나타내면 무엇인가요?","options":[{"t":"⟨2 2/5⟩","correct":true},{"t":"⟨2/5⟩","mis":"M3-2-u4-X12"},{"t":"⟨3 2/5⟩","mis":"M3-2-u4-X21"},{"t":"⟨2 3/5⟩","mis":"M3-2-u4-X20"}],"explanation":["통째로 색칠한 띠가 2개 — 자연수 부분 2.","남은 띠는 5칸 중 2칸 — 진분수 ⟨2/5⟩.","색칠한 부분은 ⟨2 2/5⟩예요."],"asset":{"type":"fbar","bars":[{"den":5,"num":5},{"den":5,"num":5},{"den":5,"num":2}]}},{"stem":"똑같은 띠 3개에 색칠했어요. 색칠한 부분을 대분수로 나타내면 무엇인가요?","options":[{"t":"⟨2 1/2⟩","correct":true},{"t":"⟨1/2⟩","mis":"M3-2-u4-X12"},{"t":"⟨3 1/2⟩","mis":"M3-2-u4-X21"},{"t":"⟨1 1/2⟩","mis":"M3-2-u4-X12"}],"explanation":["통째로 색칠한 띠가 2개 — 자연수 부분 2.","남은 띠는 2칸 중 1칸 — 진분수 ⟨1/2⟩.","색칠한 부분은 ⟨2 1/2⟩이에요."],"asset":{"type":"fbar","bars":[{"den":2,"num":2},{"den":2,"num":2},{"den":2,"num":1}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_d#7','math',3,2,'u4','','g3_2_math_u4_review_d','unit_review','M3-2-u4-C9',1,'sa','auto','4.1은 0.1이 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M3-2-u4-C9","difficulty":1,"kind":"sa","stem":"4.1은 0.1이 몇 개인가요? 숫자로 쓰세요.","answer":["41"],"explanation":["1은 0.1이 10개예요 — 4는 0.1이 40개.","0.1은 0.1이 1개예요.","4.1은 0.1이 40 + 1 = 41개."],"variant_rule":{"alt":[{"stem":"8.3은 0.1이 몇 개인가요? 숫자로 쓰세요.","answer":["83"],"explanation":["1은 0.1이 10개예요 — 8은 0.1이 80개.","0.3은 0.1이 3개예요.","8.3은 0.1이 80 + 3 = 83개."],"asset":null},{"stem":"5.2는 0.1이 몇 개인가요? 숫자로 쓰세요.","answer":["52"],"explanation":["1은 0.1이 10개예요 — 5는 0.1이 50개.","0.2는 0.1이 2개예요.","5.2는 0.1이 50 + 2 = 52개."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_d#8','math',3,2,'u4','','g3_2_math_u4_review_d','unit_review','M3-2-u4-C10',1,'mc','auto','두 수의 크기를 바르게 견준 것은 무엇인가요?',ARRAY['M3-2-u4-X18','M3-2-u4-X22']::text[],true,'{"seq":8,"concept":"M3-2-u4-C10","difficulty":1,"kind":"mc","stem":"두 수의 크기를 바르게 견준 것은 무엇인가요?","options":[{"t":"7.7 > 5.9","correct":true},{"t":"7.7 < 5.9","mis":"M3-2-u4-X18"},{"t":"7.7 = 5.9","mis":"M3-2-u4-X22"},{"t":"견줄 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["자연수 부분부터 견주어요 — 7과 5.","자연수 부분이 큰 소수가 더 커요.","7.7 > 5.9 — 0.1이 77개와 59개로 견주어도 같아요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 두 수의 크기를 바르게 견준 것은 무엇인가요?","options":[{"t":"7.8 > 6.1","correct":true},{"t":"7.8 < 6.1","mis":"M3-2-u4-X18"},{"t":"7.8 = 6.1","mis":"M3-2-u4-X22"},{"t":"견줄 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["자연수 부분부터 견주어요 — 7과 6.","자연수 부분이 큰 소수가 더 커요.","7.8 > 6.1 — 0.1이 78개와 61개로 견주어도 같아요."],"asset":null},{"stem":"이번에는 다른 문제예요. 두 수의 크기를 바르게 견준 것은 무엇인가요?","options":[{"t":"3.5 > 2.2","correct":true},{"t":"3.5 < 2.2","mis":"M3-2-u4-X18"},{"t":"3.5 = 2.2","mis":"M3-2-u4-X22"},{"t":"견줄 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["자연수 부분부터 견주어요 — 3과 2.","자연수 부분이 큰 소수가 더 커요.","3.5 > 2.2 — 0.1이 35개와 22개로 견주어도 같아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_d#9','math',3,2,'u4','','g3_2_math_u4_review_d','unit_review','M3-2-u4-C2',2,'mc','auto','검은 돌 5개와 흰 돌 2개가 있어요. 검은 돌은 전체 돌의 얼마인가요?',ARRAY['M3-2-u4-X01','M3-2-u4-X20','M3-2-u4-X03']::text[],true,'{"seq":9,"concept":"M3-2-u4-C2","difficulty":2,"kind":"mc","stem":"검은 돌 5개와 흰 돌 2개가 있어요. 검은 돌은 전체 돌의 얼마인가요?","options":[{"t":"⟨5/7⟩","correct":true},{"t":"⟨5/2⟩","mis":"M3-2-u4-X01"},{"t":"⟨2/7⟩","mis":"M3-2-u4-X20"},{"t":"⟨7/5⟩","mis":"M3-2-u4-X03"}],"explanation":["먼저 전체를 정해요 — 돌은 모두 5 + 2 = 7개.","검은 돌은 흰 돌과 견주는 것이 아니라 전체 7개와 견주어요.","검은 돌은 전체의 ⟨5/7⟩예요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[2,0],[3,0],[3,1],[2,1]],"hi":true},{"p":[[3,0],[4,0],[4,1],[3,1]],"hi":true},{"p":[[4,0],[5,0],[5,1],[4,1]],"hi":true},{"p":[[0,1],[1,1],[1,2],[0,2]]},{"p":[[1,1],[2,1],[2,2],[1,2]]}],"u":30},"variant_rule":{"alt":[{"stem":"검은 돌 5개와 흰 돌 4개가 있어요. 검은 돌은 전체 돌의 얼마인가요?","options":[{"t":"⟨5/9⟩","correct":true},{"t":"⟨5/4⟩","mis":"M3-2-u4-X01"},{"t":"⟨4/9⟩","mis":"M3-2-u4-X20"},{"t":"⟨9/5⟩","mis":"M3-2-u4-X03"}],"explanation":["먼저 전체를 정해요 — 돌은 모두 5 + 4 = 9개.","검은 돌은 흰 돌과 견주는 것이 아니라 전체 9개와 견주어요.","검은 돌은 전체의 ⟨5/9⟩예요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[2,0],[3,0],[3,1],[2,1]],"hi":true},{"p":[[3,0],[4,0],[4,1],[3,1]],"hi":true},{"p":[[4,0],[5,0],[5,1],[4,1]],"hi":true},{"p":[[0,1],[1,1],[1,2],[0,2]]},{"p":[[1,1],[2,1],[2,2],[1,2]]},{"p":[[2,1],[3,1],[3,2],[2,2]]},{"p":[[3,1],[4,1],[4,2],[3,2]]}],"u":30}},{"stem":"검은 돌 3개와 흰 돌 4개가 있어요. 검은 돌은 전체 돌의 얼마인가요?","options":[{"t":"⟨3/7⟩","correct":true},{"t":"⟨3/4⟩","mis":"M3-2-u4-X01"},{"t":"⟨4/7⟩","mis":"M3-2-u4-X20"},{"t":"⟨7/3⟩","mis":"M3-2-u4-X03"}],"explanation":["먼저 전체를 정해요 — 돌은 모두 3 + 4 = 7개.","검은 돌은 흰 돌과 견주는 것이 아니라 전체 7개와 견주어요.","검은 돌은 전체의 ⟨3/7⟩이에요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[2,0],[3,0],[3,1],[2,1]],"hi":true},{"p":[[3,0],[4,0],[4,1],[3,1]]},{"p":[[4,0],[5,0],[5,1],[4,1]]},{"p":[[0,1],[1,1],[1,2],[0,2]]},{"p":[[1,1],[2,1],[2,2],[1,2]]}],"u":30}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_d#10','math',3,2,'u4','','g3_2_math_u4_review_d','unit_review','M3-2-u4-C3',2,'mc','auto','딸기 9개의 ⟨2/3⟩는 몇 개인가요?',ARRAY['M3-2-u4-X04','M3-2-u4-X05','M3-2-u4-X21']::text[],true,'{"seq":10,"concept":"M3-2-u4-C3","difficulty":2,"kind":"mc","stem":"딸기 9개의 ⟨2/3⟩는 몇 개인가요?","options":[{"t":"6개","correct":true},{"t":"2개","mis":"M3-2-u4-X04"},{"t":"3개","mis":"M3-2-u4-X05"},{"t":"9개","mis":"M3-2-u4-X21"}],"explanation":["9를 분모만큼 똑같이 3묶음으로 나누면 한 묶음에 3개예요 — 9의 ⟨1/3⟩은 3.","⟨2/3⟩는 ⟨1/3⟩이 2개 — 2묶음이에요.","9의 ⟨2/3⟩는 3 × 2 = 6 — 분자만 보고 답하지 않아요."],"variant_rule":{"alt":[{"stem":"사탕 20개의 ⟨3/4⟩은 몇 개인가요?","options":[{"t":"15개","correct":true},{"t":"3개","mis":"M3-2-u4-X04"},{"t":"5개","mis":"M3-2-u4-X05"},{"t":"20개","mis":"M3-2-u4-X21"}],"explanation":["20을 분모만큼 똑같이 4묶음으로 나누면 한 묶음에 5개예요 — 20의 ⟨1/4⟩은 5.","⟨3/4⟩은 ⟨1/4⟩이 3개 — 3묶음이에요.","20의 ⟨3/4⟩은 5 × 3 = 15 — 분자만 보고 답하지 않아요."],"asset":null},{"stem":"쿠키 12개의 ⟨2/4⟩는 몇 개인가요?","options":[{"t":"6개","correct":true},{"t":"2개","mis":"M3-2-u4-X04"},{"t":"3개","mis":"M3-2-u4-X05"},{"t":"24개","mis":"M3-2-u4-X06"}],"explanation":["12를 분모만큼 똑같이 4묶음으로 나누면 한 묶음에 3개예요 — 12의 ⟨1/4⟩은 3.","⟨2/4⟩는 ⟨1/4⟩이 2개 — 2묶음이에요.","12의 ⟨2/4⟩는 3 × 2 = 6 — 분자만 보고 답하지 않아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_d#11','math',3,2,'u4','','g3_2_math_u4_review_d','unit_review','M3-2-u4-C4',2,'sa','auto','서준이 하루의 ⟨1/6⟩ 동안 운동을 한 시간은 몇 시간인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":11,"concept":"M3-2-u4-C4","difficulty":2,"kind":"sa","stem":"서준이 하루의 ⟨1/6⟩ 동안 운동을 한 시간은 몇 시간인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["하루는 24시간이에요.","24를 똑같이 6부분으로 나누면 한 부분이 4시간이에요.","하루의 ⟨1/6⟩은 4 × 1 = 4시간."],"variant_rule":{"alt":[{"stem":"건우가 하루의 ⟨2/8⟩ 동안 학교에 있는 시간은 몇 시간인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["하루는 24시간이에요.","24를 똑같이 8부분으로 나누면 한 부분이 3시간이에요.","하루의 ⟨2/8⟩는 3 × 2 = 6시간."],"asset":null},{"stem":"채원이 하루의 ⟨9/24⟩ 동안 잠을 잔 시간은 몇 시간인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["하루는 24시간이에요.","24를 똑같이 24부분으로 나누면 한 부분이 1시간이에요.","하루의 ⟨9/24⟩는 1 × 9 = 9시간."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_d#12','math',3,2,'u4','','g3_2_math_u4_review_d','unit_review','M3-2-u4-C7',2,'sa','auto','⟨21/6⟩을 대분수로 나타내면 자연수 부분은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":12,"concept":"M3-2-u4-C7","difficulty":2,"kind":"sa","stem":"⟨21/6⟩을 대분수로 나타내면 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["⟨21/6⟩은 ⟨1/6⟩이 21개예요.","6개씩 모으면 1 — 21 ÷ 6 = 3 … 3, 통째로 3이고 ⟨1/6⟩이 3개 남아요.","⟨21/6⟩ = ⟨3 3/6⟩ — 분수 부분은 진분수예요."],"variant_rule":{"alt":[{"stem":"⟨5/2⟩를 대분수로 나타내면 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["⟨5/2⟩는 ⟨1/2⟩이 5개예요.","2개씩 모으면 1 — 5 ÷ 2 = 2 … 1, 통째로 2이고 ⟨1/2⟩이 1개 남아요.","⟨5/2⟩ = ⟨2 1/2⟩ — 분수 부분은 진분수예요."],"asset":null},{"stem":"⟨3/2⟩을 대분수로 나타내면 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["⟨3/2⟩은 ⟨1/2⟩이 3개예요.","2개씩 모으면 1 — 3 ÷ 2 = 1 … 1, 통째로 1이고 ⟨1/2⟩이 1개 남아요.","⟨3/2⟩ = ⟨1 1/2⟩ — 분수 부분은 진분수예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_d#13','math',3,2,'u4','','g3_2_math_u4_review_d','unit_review','M3-2-u4-C8',2,'mc','auto','두 수의 크기를 바르게 견준 것은 무엇인가요?',ARRAY['M3-2-u4-X13','M3-2-u4-X22']::text[],true,'{"seq":13,"concept":"M3-2-u4-C8","difficulty":2,"kind":"mc","stem":"두 수의 크기를 바르게 견준 것은 무엇인가요?","options":[{"t":"⟨2 1/3⟩ > ⟨1 1/3⟩","correct":true},{"t":"⟨2 1/3⟩ < ⟨1 1/3⟩","mis":"M3-2-u4-X13"},{"t":"⟨2 1/3⟩ = ⟨1 1/3⟩","mis":"M3-2-u4-X22"},{"t":"견줄 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["대분수는 자연수 부분부터 견주어요.","2 > 1 — 자연수 부분이 큰 쪽이 커요.","분수 부분은 1보다 작아서 뒤집지 못해요 — ⟨2 1/3⟩ > ⟨1 1/3⟩."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 두 수의 크기를 바르게 견준 것은 무엇인가요?","options":[{"t":"⟨4 1/9⟩ > ⟨1 3/9⟩","correct":true},{"t":"⟨4 1/9⟩ < ⟨1 3/9⟩","mis":"M3-2-u4-X13"},{"t":"⟨4 1/9⟩ = ⟨1 3/9⟩","mis":"M3-2-u4-X22"},{"t":"견줄 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["대분수는 자연수 부분부터 견주어요.","4 > 1 — 자연수 부분이 큰 쪽이 커요.","분수 부분은 1보다 작아서 뒤집지 못해요 — ⟨4 1/9⟩ > ⟨1 3/9⟩."],"asset":null},{"stem":"이번에는 다른 문제예요. 두 수의 크기를 바르게 견준 것은 무엇인가요?","options":[{"t":"⟨5 2/9⟩ > ⟨4 5/9⟩","correct":true},{"t":"⟨5 2/9⟩ < ⟨4 5/9⟩","mis":"M3-2-u4-X13"},{"t":"⟨5 2/9⟩ = ⟨4 5/9⟩","mis":"M3-2-u4-X22"},{"t":"견줄 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["대분수는 자연수 부분부터 견주어요.","5 > 4 — 자연수 부분이 큰 쪽이 커요.","분수 부분은 1보다 작아서 뒤집지 못해요 — ⟨5 2/9⟩ > ⟨4 5/9⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_d#14','math',3,2,'u4','','g3_2_math_u4_review_d','unit_review','M3-2-u4-C9',2,'mc','auto','머리핀의 길이는 8 cm 1 mm예요. 몇 cm인지 소수로 나타내면 얼마인가요?',ARRAY['M3-2-u4-X17','M3-2-u4-X16']::text[],true,'{"seq":14,"concept":"M3-2-u4-C9","difficulty":2,"kind":"mc","stem":"머리핀의 길이는 8 cm 1 mm예요. 몇 cm인지 소수로 나타내면 얼마인가요?","options":[{"t":"8.1 cm","correct":true},{"t":"8.01 cm","mis":"M3-2-u4-X17"},{"t":"81 cm","mis":"M3-2-u4-X17"},{"t":"1.8 cm","mis":"M3-2-u4-X16"}],"explanation":["1 mm = ⟨1/10⟩ cm = 0.1 cm예요.","1 mm는 0.1 cm — 8 cm 1 mm = ⟨8 1/10⟩ cm.","⟨8 1/10⟩ cm = 8.1 cm."],"asset":{"type":"mmruler","len":81,"label":"머리핀"},"variant_rule":{"alt":[{"stem":"크레파스의 길이는 2 cm 2 mm예요. 몇 cm인지 소수로 나타내면 얼마인가요?","options":[{"t":"2.2 cm","correct":true},{"t":"2.02 cm","mis":"M3-2-u4-X17"},{"t":"22 cm","mis":"M3-2-u4-X17"},{"t":"2.3 cm","mis":"M3-2-u4-X21"}],"explanation":["1 mm = ⟨1/10⟩ cm = 0.1 cm예요.","2 mm는 0.2 cm — 2 cm 2 mm = ⟨2 2/10⟩ cm.","⟨2 2/10⟩ cm = 2.2 cm."],"asset":{"type":"mmruler","len":22,"label":"크레파스"}},{"stem":"나뭇잎의 길이는 9 cm 3 mm예요. 몇 cm인지 소수로 나타내면 얼마인가요?","options":[{"t":"9.3 cm","correct":true},{"t":"9.03 cm","mis":"M3-2-u4-X17"},{"t":"93 cm","mis":"M3-2-u4-X17"},{"t":"3.9 cm","mis":"M3-2-u4-X16"}],"explanation":["1 mm = ⟨1/10⟩ cm = 0.1 cm예요.","3 mm는 0.3 cm — 9 cm 3 mm = ⟨9 3/10⟩ cm.","⟨9 3/10⟩ cm = 9.3 cm."],"asset":{"type":"mmruler","len":93,"label":"나뭇잎"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_d#15','math',3,2,'u4','','g3_2_math_u4_review_d','unit_review','M3-2-u4-C10',2,'mc','auto','줄넘기 30번 기록이에요. 하윤 9.2초, 서준 10.9초, 은비 9.4초. 가장 빠른 사람은 누구인가요?',ARRAY['M3-2-u4-X19','M3-2-u4-X18','M3-2-u4-X22']::text[],true,'{"seq":15,"concept":"M3-2-u4-C10","difficulty":2,"kind":"mc","stem":"줄넘기 30번 기록이에요. 하윤 9.2초, 서준 10.9초, 은비 9.4초. 가장 빠른 사람은 누구인가요?","options":[{"t":"하윤","correct":true},{"t":"서준","mis":"M3-2-u4-X19"},{"t":"은비","mis":"M3-2-u4-X18"},{"t":"모두 같아요","mis":"M3-2-u4-X22"}],"explanation":["걸린 시간이 짧을수록 빨라요.","9.2, 10.9, 9.4 중 가장 작은 수는 9.2예요.","가장 빠른 사람은 하윤이에요."],"variant_rule":{"alt":[{"stem":"100 m 수영 기록이에요. 서준 12.9초, 채원 11.4초, 준우 12.8초. 가장 빠른 사람은 누구인가요?","options":[{"t":"채원","correct":true},{"t":"서준","mis":"M3-2-u4-X19"},{"t":"준우","mis":"M3-2-u4-X18"},{"t":"모두 같아요","mis":"M3-2-u4-X22"}],"explanation":["걸린 시간이 짧을수록 빨라요.","12.9, 11.4, 12.8 중 가장 작은 수는 11.4예요.","가장 빠른 사람은 채원이에요."],"asset":null},{"stem":"50 m 달리기 기록이에요. 은비 11.3초, 서준 11.2초, 건우 12.4초. 가장 빠른 사람은 누구인가요?","options":[{"t":"서준","correct":true},{"t":"건우","mis":"M3-2-u4-X19"},{"t":"은비","mis":"M3-2-u4-X18"},{"t":"모두 같아요","mis":"M3-2-u4-X22"}],"explanation":["걸린 시간이 짧을수록 빨라요.","11.3, 11.2, 12.4 중 가장 작은 수는 11.2예요.","가장 빠른 사람은 서준이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_d#16','math',3,2,'u4','','g3_2_math_u4_review_d','unit_review','M3-2-u4-C11',2,'mc','auto','두 수의 크기를 바르게 견준 것은 무엇인가요?',ARRAY['M3-2-u4-X14','M3-2-u4-X22']::text[],true,'{"seq":16,"concept":"M3-2-u4-C11","difficulty":2,"kind":"mc","stem":"두 수의 크기를 바르게 견준 것은 무엇인가요?","options":[{"t":"3.2 > ⟨2 3/10⟩","correct":true},{"t":"3.2 < ⟨2 3/10⟩","mis":"M3-2-u4-X14"},{"t":"3.2 = ⟨2 3/10⟩","mis":"M3-2-u4-X22"},{"t":"견줄 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["분모가 10인 분수는 소수로 바꿀 수 있어요 — ⟨2 3/10⟩ = 2.3.","소수로 견주어요 — 자연수 부분부터, 같으면 소수점 오른쪽 수.","3.2 > ⟨2 3/10⟩."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 두 수의 크기를 바르게 견준 것은 무엇인가요?","options":[{"t":"7.4 < ⟨8 2/10⟩","correct":true},{"t":"7.4 > ⟨8 2/10⟩","mis":"M3-2-u4-X14"},{"t":"7.4 = ⟨8 2/10⟩","mis":"M3-2-u4-X22"},{"t":"견줄 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["분모가 10인 분수는 소수로 바꿀 수 있어요 — ⟨8 2/10⟩ = 8.2.","소수로 견주어요 — 자연수 부분부터, 같으면 소수점 오른쪽 수.","7.4 < ⟨8 2/10⟩."],"asset":null},{"stem":"이번에는 다른 문제예요. 두 수의 크기를 바르게 견준 것은 무엇인가요?","options":[{"t":"⟨2 1/10⟩ < 2.6","correct":true},{"t":"⟨2 1/10⟩ > 2.6","mis":"M3-2-u4-X14"},{"t":"⟨2 1/10⟩ = 2.6","mis":"M3-2-u4-X22"},{"t":"견줄 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["분모가 10인 분수는 소수로 바꿀 수 있어요 — ⟨2 1/10⟩ = 2.1.","소수로 견주어요 — 자연수 부분부터, 같으면 소수점 오른쪽 수.","⟨2 1/10⟩ < 2.6."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_d#17','math',3,2,'u4','','g3_2_math_u4_review_d','unit_review','M3-2-u4-C1',3,'mc','auto','16을 4씩 묶었어요. 8은 16의 얼마인가요?',ARRAY['M3-2-u4-X03','M3-2-u4-X21','M3-2-u4-X02']::text[],true,'{"seq":17,"concept":"M3-2-u4-C1","difficulty":3,"kind":"mc","stem":"16을 4씩 묶었어요. 8은 16의 얼마인가요?","options":[{"t":"⟨2/4⟩","correct":true},{"t":"⟨4/2⟩","mis":"M3-2-u4-X03"},{"t":"⟨3/4⟩","mis":"M3-2-u4-X21"},{"t":"⟨2/16⟩","mis":"M3-2-u4-X02"}],"explanation":["16을 4씩 묶으면 4묶음 — 분모 4.","8은 그중 2묶음 — 분자 2.","8은 16의 ⟨2/4⟩ — 낱개 수 8·16으로 쓰지 않아요."],"variant_rule":{"alt":[{"stem":"16을 2씩 묶었어요. 6은 16의 얼마인가요?","options":[{"t":"⟨3/8⟩","correct":true},{"t":"⟨8/3⟩","mis":"M3-2-u4-X03"},{"t":"⟨3/5⟩","mis":"M3-2-u4-X01"},{"t":"⟨2/8⟩","mis":"M3-2-u4-X07"}],"explanation":["16을 2씩 묶으면 8묶음 — 분모 8.","6은 그중 3묶음 — 분자 3.","6은 16의 ⟨3/8⟩ — 낱개 수 6·16으로 쓰지 않아요."],"asset":null},{"stem":"10을 2씩 묶었어요. 4는 10의 얼마인가요?","options":[{"t":"⟨2/5⟩","correct":true},{"t":"⟨5/2⟩","mis":"M3-2-u4-X03"},{"t":"⟨2/3⟩","mis":"M3-2-u4-X01"},{"t":"⟨3/5⟩","mis":"M3-2-u4-X21"}],"explanation":["10을 2씩 묶으면 5묶음 — 분모 5.","4는 그중 2묶음 — 분자 2.","4는 10의 ⟨2/5⟩ — 낱개 수 4·10으로 쓰지 않아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_d#18','math',3,2,'u4','','g3_2_math_u4_review_d','unit_review','M3-2-u4-C3',3,'sa','auto','귤 12개 중 은비는 ⟨3/6⟩을, 서윤은 ⟨1/6⟩을 먹었어요. 남은 귤은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":18,"concept":"M3-2-u4-C3","difficulty":3,"kind":"sa","stem":"귤 12개 중 은비는 ⟨3/6⟩을, 서윤은 ⟨1/6⟩을 먹었어요. 남은 귤은 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["12의 ⟨1/6⟩은 2개예요.","은비는 6개, 서윤은 2개 — 모두 8개를 먹었어요.","남은 것은 12 − 8 = 4개."],"variant_rule":{"alt":[{"stem":"약과 20개 중 서준은 ⟨1/5⟩을, 도연은 ⟨2/5⟩를 먹었어요. 남은 약과는 몇 개인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["20의 ⟨1/5⟩은 4개예요.","서준은 4개, 도연은 8개 — 모두 12개를 먹었어요.","남은 것은 20 − 12 = 8개."],"asset":null},{"stem":"쿠키 12개 중 채원은 ⟨1/6⟩을, 서준은 ⟨4/6⟩를 먹었어요. 남은 쿠키는 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["12의 ⟨1/6⟩은 2개예요.","채원은 2개, 서준은 8개 — 모두 10개를 먹었어요.","남은 것은 12 − 10 = 2개."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_d#19','math',3,2,'u4','','g3_2_math_u4_review_d','unit_review','M3-2-u4-C7',3,'sa','auto','⟨3 5/7⟩를 가분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":19,"concept":"M3-2-u4-C7","difficulty":3,"kind":"sa","stem":"⟨3 5/7⟩를 가분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.","answer":["26"],"explanation":["자연수 1은 ⟨1/7⟩이 7개예요 — 3은 3 × 7 = 21개.","⟨5/7⟩는 5개 — 모두 21 + 5 = 26개예요.","⟨3 5/7⟩ = ⟨26/7⟩ — 분모는 그대로 두어요."],"variant_rule":{"alt":[{"stem":"⟨3 1/4⟩을 가분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["자연수 1은 ⟨1/4⟩이 4개예요 — 3은 3 × 4 = 12개.","⟨1/4⟩은 1개 — 모두 12 + 1 = 13개예요.","⟨3 1/4⟩ = ⟨13/4⟩ — 분모는 그대로 두어요."],"asset":null},{"stem":"⟨1 3/4⟩을 가분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["자연수 1은 ⟨1/4⟩이 4개예요.","⟨3/4⟩은 3개 — 모두 4 + 3 = 7개예요.","⟨1 3/4⟩ = ⟨7/4⟩ — 분모는 그대로 두어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_d#20','math',3,2,'u4','','g3_2_math_u4_review_d','unit_review','M3-2-u4-C8',3,'mc','auto','두 수의 크기를 바르게 견준 것은 무엇인가요?',ARRAY['M3-2-u4-X14','M3-2-u4-X22']::text[],true,'{"seq":20,"concept":"M3-2-u4-C8","difficulty":3,"kind":"mc","stem":"두 수의 크기를 바르게 견준 것은 무엇인가요?","options":[{"t":"⟨22/6⟩ > ⟨2 1/6⟩","correct":true},{"t":"⟨22/6⟩ < ⟨2 1/6⟩","mis":"M3-2-u4-X14"},{"t":"⟨22/6⟩ = ⟨2 1/6⟩","mis":"M3-2-u4-X22"},{"t":"견줄 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["한쪽으로 바꾸어 견주어요.","⟨2 1/6⟩ = ⟨13/6⟩이에요.","⟨22/6⟩와 ⟨13/6⟩ — ⟨22/6⟩ > ⟨2 1/6⟩ (⟨22/6⟩ = ⟨3 4/6⟩로 바꾸어도 같아요)."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 두 수의 크기를 바르게 견준 것은 무엇인가요?","options":[{"t":"⟨28/6⟩ > ⟨2 2/6⟩","correct":true},{"t":"⟨28/6⟩ < ⟨2 2/6⟩","mis":"M3-2-u4-X14"},{"t":"⟨28/6⟩ = ⟨2 2/6⟩","mis":"M3-2-u4-X22"},{"t":"견줄 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["한쪽으로 바꾸어 견주어요.","⟨2 2/6⟩ = ⟨14/6⟩예요.","⟨28/6⟩과 ⟨14/6⟩ — ⟨28/6⟩ > ⟨2 2/6⟩ (⟨28/6⟩ = ⟨4 4/6⟩로 바꾸어도 같아요)."],"asset":null},{"stem":"이번에는 다른 문제예요. 두 수의 크기를 바르게 견준 것은 무엇인가요?","options":[{"t":"⟨8/3⟩ < ⟨4 1/3⟩","correct":true},{"t":"⟨8/3⟩ > ⟨4 1/3⟩","mis":"M3-2-u4-X14"},{"t":"⟨8/3⟩ = ⟨4 1/3⟩","mis":"M3-2-u4-X22"},{"t":"견줄 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["한쪽으로 바꾸어 견주어요.","⟨4 1/3⟩ = ⟨13/3⟩이에요.","⟨8/3⟩과 ⟨13/3⟩ — ⟨8/3⟩ < ⟨4 1/3⟩ (⟨8/3⟩ = ⟨2 2/3⟩로 바꾸어도 같아요)."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_d#21','math',3,2,'u4','','g3_2_math_u4_review_d','unit_review','M3-2-u4-C9',3,'mc','auto','수직선의 한 칸은 0.1이에요. ?가 나타내는 소수는 무엇인가요?',ARRAY['M3-2-u4-X21','M3-2-u4-X16']::text[],true,'{"seq":21,"concept":"M3-2-u4-C9","difficulty":3,"kind":"mc","stem":"수직선의 한 칸은 0.1이에요. ?가 나타내는 소수는 무엇인가요?","options":[{"t":"2.4","correct":true},{"t":"2.5","mis":"M3-2-u4-X21"},{"t":"2.3","mis":"M3-2-u4-X21"},{"t":"4.2","mis":"M3-2-u4-X16"}],"explanation":["오른쪽으로 한 칸 갈 때마다 0.1씩 커져요.","앞뒤의 수를 보면 2.3 다음 자리예요.","?는 2.4예요."],"asset":{"type":"number_line","cells":["2.1","2.2","2.3","?","2.5"]},"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 수직선의 한 칸은 0.1이에요. ?가 나타내는 소수는 무엇인가요?","options":[{"t":"3.9","correct":true},{"t":"4","mis":"M3-2-u4-X21"},{"t":"3.8","mis":"M3-2-u4-X21"},{"t":"9.3","mis":"M3-2-u4-X16"}],"explanation":["오른쪽으로 한 칸 갈 때마다 0.1씩 커져요.","앞뒤의 수를 보면 왼쪽 다음 자리예요.","?는 3.9예요."],"asset":{"type":"number_line","cells":["?","4","4.1","4.2","4.3"]}},{"stem":"이번에는 다른 문제예요. 수직선의 한 칸은 0.1이에요. ?가 나타내는 소수는 무엇인가요?","options":[{"t":"8.6","correct":true},{"t":"8.7","mis":"M3-2-u4-X21"},{"t":"8.5","mis":"M3-2-u4-X21"},{"t":"6.8","mis":"M3-2-u4-X16"}],"explanation":["오른쪽으로 한 칸 갈 때마다 0.1씩 커져요.","앞뒤의 수를 보면 8.5 다음 자리예요.","?는 8.6이에요."],"asset":{"type":"number_line","cells":["8.5","?","8.7","8.8","8.9"]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_d#22','math',3,2,'u4','','g3_2_math_u4_review_d','unit_review','M3-2-u4-C11',3,'mc','auto','⟨7 □/10⟩가 ⟨7 5/10⟩보다 클 때, □ 안에 들어갈 수 있는 수를 모두 고른 것은 무엇인가요?',ARRAY['M3-2-u4-X21','M3-2-u4-X20']::text[],true,'{"seq":22,"concept":"M3-2-u4-C11","difficulty":3,"kind":"mc","stem":"⟨7 □/10⟩가 ⟨7 5/10⟩보다 클 때, □ 안에 들어갈 수 있는 수를 모두 고른 것은 무엇인가요?","options":[{"t":"6, 7, 8, 9","correct":true},{"t":"5, 6, 7, 8, 9","mis":"M3-2-u4-X21"},{"t":"1, 2, 3, 4","mis":"M3-2-u4-X20"},{"t":"6","mis":"M3-2-u4-X21"}],"explanation":["자연수 부분이 7로 같아요.","분수 부분의 분자 □가 5보다 커야 해요.","□ = 6, 7, 8, 9 — 5는 같아서 넣지 않아요."],"variant_rule":{"alt":[{"stem":"⟨7 □/10⟩가 ⟨7 6/10⟩보다 클 때, □ 안에 들어갈 수 있는 수를 모두 고른 것은 무엇인가요?","options":[{"t":"7, 8, 9","correct":true},{"t":"6, 7, 8, 9","mis":"M3-2-u4-X21"},{"t":"1, 2, 3, 4, 5","mis":"M3-2-u4-X20"},{"t":"7","mis":"M3-2-u4-X21"}],"explanation":["자연수 부분이 7로 같아요.","분수 부분의 분자 □가 6보다 커야 해요.","□ = 7, 8, 9 — 6은 같아서 넣지 않아요."],"asset":null},{"stem":"⟨9 □/10⟩가 ⟨9 3/10⟩보다 클 때, □ 안에 들어갈 수 있는 수를 모두 고른 것은 무엇인가요?","options":[{"t":"4, 5, 6, 7, 8, 9","correct":true},{"t":"3, 4, 5, 6, 7, 8, 9","mis":"M3-2-u4-X21"},{"t":"1, 2","mis":"M3-2-u4-X20"},{"t":"4","mis":"M3-2-u4-X21"}],"explanation":["자연수 부분이 9로 같아요.","분수 부분의 분자 □가 3보다 커야 해요.","□ = 4, 5, 6, 7, 8, 9 — 3은 같아서 넣지 않아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_d#23','math',3,2,'u4','','g3_2_math_u4_review_d','unit_review','M3-2-u4-C5',4,'sa','auto','주사위를 던져 처음 나온 2를 분모로 정했어요. 두 번째로 나온 수를 분자로 할 때, 가분수가 되는 경우는 모두 몇 가지인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":23,"concept":"M3-2-u4-C5","difficulty":4,"kind":"sa","stem":"주사위를 던져 처음 나온 2를 분모로 정했어요. 두 번째로 나온 수를 분자로 할 때, 가분수가 되는 경우는 모두 몇 가지인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["주사위의 수는 1부터 6까지예요.","가분수: 분자가 2와 같거나 커야 해요 — 2, 3, 4, 5, 6.","모두 5가지예요."],"variant_rule":{"alt":[{"stem":"주사위를 던져 처음 나온 6을 분모로 정했어요. 두 번째로 나온 수를 분자로 할 때, 가분수가 되는 경우는 모두 몇 가지인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["주사위의 수는 1부터 6까지예요.","가분수: 분자가 6과 같거나 커야 해요 — 6.","모두 1가지예요."],"asset":null},{"stem":"주사위를 던져 처음 나온 4를 분모로 정했어요. 두 번째로 나온 수를 분자로 할 때, 가분수가 되는 경우는 모두 몇 가지인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["주사위의 수는 1부터 6까지예요.","가분수: 분자가 4와 같거나 커야 해요 — 4, 5, 6.","모두 3가지예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_d#24','math',3,2,'u4','','g3_2_math_u4_review_d','unit_review','M3-2-u4-C11',4,'mc','auto','네 수 중에서 가장 큰 수는 무엇인가요? ⟨2 4/10⟩, ⟨2 9/10⟩, 2.1, 2.8',ARRAY['M3-2-u4-X14','M3-2-u4-X20']::text[],true,'{"seq":24,"concept":"M3-2-u4-C11","difficulty":4,"kind":"mc","stem":"네 수 중에서 가장 큰 수는 무엇인가요? ⟨2 4/10⟩, ⟨2 9/10⟩, 2.1, 2.8","options":[{"t":"⟨2 9/10⟩","correct":true},{"t":"⟨2 4/10⟩","mis":"M3-2-u4-X14"},{"t":"2.1","mis":"M3-2-u4-X20"},{"t":"2.8","mis":"M3-2-u4-X14"}],"explanation":["분수는 소수로 바꾸어요 — 2.4, 2.9, 2.1, 2.8.","자연수 부분부터, 같으면 소수점 오른쪽 수를 견주어요.","가장 큰 수는 ⟨2 9/10⟩예요."],"variant_rule":{"alt":[{"stem":"네 수 중에서 가장 큰 수는 무엇인가요? 3.8, 3.1, ⟨36/10⟩, ⟨3 2/10⟩","options":[{"t":"3.8","correct":true},{"t":"3.1","mis":"M3-2-u4-X20"},{"t":"⟨36/10⟩","mis":"M3-2-u4-X14"},{"t":"⟨3 2/10⟩","mis":"M3-2-u4-X14"}],"explanation":["분수는 소수로 바꾸어요 — 3.8, 3.1, 3.6, 3.2.","자연수 부분부터, 같으면 소수점 오른쪽 수를 견주어요.","가장 큰 수는 3.8이에요."],"asset":null},{"stem":"네 수 중에서 가장 큰 수는 무엇인가요? 7.7, ⟨6 3/10⟩, ⟨6 5/10⟩, 7.6","options":[{"t":"7.7","correct":true},{"t":"⟨6 3/10⟩","mis":"M3-2-u4-X20"},{"t":"⟨6 5/10⟩","mis":"M3-2-u4-X14"},{"t":"7.6","mis":"M3-2-u4-X14"}],"explanation":["분수는 소수로 바꾸어요 — 7.7, 6.3, 6.5, 7.6.","자연수 부분부터, 같으면 소수점 오른쪽 수를 견주어요.","가장 큰 수는 7.7이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u4_review_d#25','math',3,2,'u4','','g3_2_math_u4_review_d','unit_review','M3-2-u4-C11',4,'essay','teacher','사슴벌레 수컷은 ⟨5 3/10⟩ cm, 암컷은 ⟨44/10⟩ cm예요. 어느 쪽이 더 긴지 쓰고, 한쪽으로 바꾸어 견주는 방법으로 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M3-2-u4-C11","difficulty":4,"kind":"essay","stem":"사슴벌레 수컷은 ⟨5 3/10⟩ cm, 암컷은 ⟨44/10⟩ cm예요. 어느 쪽이 더 긴지 쓰고, 한쪽으로 바꾸어 견주는 방법으로 설명해 보세요.","answer_guide":{"answer":"예: 수컷이 더 길다. ⟨5 3/10⟩ = 5.3, ⟨44/10⟩ = 4.4로 바꾸면 자연수 부분 5 > 4이므로 5.3이 크다. ⟨5 3/10⟩ = ⟨53/10⟩으로 바꾸어 53 > 44로 견주어도 된다.","scoring_points":["수컷이 더 길다고 답했는가","소수(또는 가분수)로 바꾸어 견주었는가","바꾼 수의 크기 비교가 맞는가"]},"explanation":["⟨5 3/10⟩ = 5.3, ⟨44/10⟩ = 4.4.","5.3 > 4.4.","수컷이 더 길어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
